INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('einja-inc/einja-management-template/einja-infra-maintenance', 'community', 'einja-inc', 'einja-management-template', 'einja-inc/einja-management-template', 'einja-infra-maintenance', 1, 0, 60, '2026-03-07T12:03:06Z', '2026-03-07T12:51:18.383Z', '55ba1463877ff99abc4ef7f9eaff6dc3a5c70f594c74a0a3c6897f02a56e9e17', '{"id":"einja-inc/einja-management-template/einja-infra-maintenance","name":"einja-infra-maintenance","description":{"en":"The einja-infra-maintenance skill enables interactive infrastructure setup and maintenance for developers, covering local development environments, Vercel, Neon, GitHub Actions, and environment variable management.","zh":"einja-infra-maintenance Skill是用于对话式执行环境变量管理和部署的工具，支持Vercel和Neon等","ja":"einja-infra-maintenance Skillは、インフラ環境のセットアップとメンテナンスを対話的に実行するためのツールです","ko":"einja-infra-maintenance Skill은 대화형으로 환경 변수 관리와 배포를 수행하는 도구입니다","es":"einja-infra-maintenance es una habilidad que permite la configuración y el mantenimiento de entornos de infraestructura de manera interactiva, cubriendo temas como variables de entorno y despliegue","fr":"einja-infra-maintenance est une compétence qui permet la configuration et la maintenance des environnements d''infrastructure de manière interactive, couvrant des sujets tels que les variables d''environnement et le déploiement","de":"einja-infra-maintenance ist eine Fähigkeit, die die Konfiguration und Wartung von Infrastruktur-Umgebungen in interaktiver Weise ermöglicht, einschließlich Themen wie Umgebungsvariablen und Bereitstellung","pt":"O einja-infra-maintenance é uma ferramenta de manutenção de infraestrutura que executa tarefas de setup e manutenção de forma interativa, cobrindo ambientes locais, Vercel, Neon e GitHub Actions.","ru":"ИИ Агент einja-infra-maintenance - это инструмент для поддержки инфраструктуры, который выполняет задачи настройки и обслуживания в интерактивном режиме, покрывая локальные среды, Vercel, Neon и GitHub Actions.","ar":"وحدة einja-infra-maintenance هي أداة لصيانة البنية التحتية التي تنفذ مهام الإعداد والصيانة بطريقة تفاعلية، وتغطي بيئات محلية، Vercel، Neon و GitHub Actions."},"seo":{"title":{"en":"einja-infra-maintenance: Infrastructure Setup Guide | AI ...","zh":"einja-infra-maintenance Setup Guide: AIエージェント环境变量管理","ja":"einja-infra-maintenance セットアップガイド: インフラ環境メンテナンスを対話的に実行","ko":"einja-infra-maintenance 설정 가이드: 인프라 환경 유지 관리를 위한 AI 에이전트","es":"Guía de Configuración de einja-infra-maintenance para Des...","fr":"Configurer einja-infra-maintenance : Guide de Mise en Place","de":"Einja-infra-maintenance Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do einja-infra-maintenance: Setup de...","ru":"Настройка инфраструктуры с помощью ИИ Агента einja-infra-...","ar":"دليل إعداد einja-infra-maintenance: إعداد البيئة التحتية"},"description":{"en":"Discover how einja-infra-maintenance simplifies infrastructure management. Learn to set up and maintain your environment with ease. Get started now!","zh":"了解einja-infra-maintenance Skill的功能和特点，包括环境变量管理、Vercel和Neon部署等","ja":"einja-infra-maintenance Skillの機能と特徴について学びます。ローカル開発環境、Vercel、Neon、GitHub Actionsなどをカバー","ko":"einja-infra-maintenance Skill의 기능과 특징을 알아보세요. 로컬 개발 환경, Vercel, Neon, GitHub Actions 등을 포함","es":"Aprende a configurar einja-infra-maintenance para tu entorno de desarrollo con esta guía paso a paso que cubre Vercel, Neon y GitHub Actions","fr":"Découvrez comment configurer einja-infra-maintenance pour votre environnement de développement avec ce guide étape par étape sur Vercel, Neon et GitHub Actions","de":"Erfahren Sie, wie Sie einja-infra-maintenance für Ihre Entwicklungsumgebung mit diesem Schritt-für-Schritt-Leitfaden konfigurieren, der Vercel, Neon und GitH...","pt":"Aprenda a configurar e manter sua infraestrutura com o einja-infra-maintenance, incluindo setup de ambiente, deploy e gerenciamento de variáveis","ru":"Узнайте, как настроить и поддерживать инфраструктуру с помощью ИИ Агента einja-infra-maintenance, включая настройку окружения, deploy и управление переменными","ar":"تعلم كيفية إعداد وتنظيم البنية التحتية باستخدام einja-infra-maintenance، بما في ذلك إعداد البيئة وتوزيع البرامج وإدارة المتغيرات"},"definition":{"en":"einja-infra-maintenance is a skill that facilitates interactive infrastructure environment setup and maintenance, supporting various platforms and tools.","zh":"einja-infra-maintenance Skill是用于环境变量管理和部署的AIエージェント","ja":"einja-infra-maintenance Skillは、インフラ環境メンテナンスを対話的に実行するためのAIエージェントです","ko":"einja-infra-maintenance Skill은 인프라 환경 유지 관리를 위한 AI 에이전트입니다","es":"einja-infra-maintenance es una herramienta de AI que ayuda a los desarrolladores a configurar y mantener entornos de infraestructura de manera eficiente","fr":"einja-infra-maintenance est un outil d''IA qui aide les développeurs à configurer et maintenir des environnements d''infrastructure de manière efficace","de":"einja-infra-maintenance ist ein AI-Tool, das Entwicklern hilft, Infrastruktur-Umgebungen effizient zu konfigurieren und zu warten","pt":"O einja-infra-maintenance é uma ferramenta de manutenção de infraestrutura que automatiza tarefas de setup e manutenção","ru":"ИИ Агент einja-infra-maintenance - это инструмент для автоматизации задач настройки и обслуживания инфраструктуры","ar":"وحدة einja-infra-maintenance هي أداة لصيانة البنية التحتية التي ت自動 hóa مهام الإعداد والصيانة"},"features":{"en":["Supports local development environment setup","Integrates with Vercel for streamlined deployment","Manages environment variables for Neon and GitHub Actions","Provides documentation for environment setup and deployment","Allows for selective reading of reference documents based on category"],"zh":["环境变量管理","Vercel和Neon部署","GitHub Actions集成","对话式执行","支持多种开发环境"],"ja":["環境変数管理","VercelとNeonのデプロイ","GitHub Actionsの統合","対話式の実行","複数の開発環境のサポート"],"ko":["환경 변수 관리","Vercel과 Neon 배포","GitHub Actions 통합","대화형 실행","다중 개발 환경 지원"],"es":["Configuración interactiva de entornos de infraestructura","Gestión de variables de entorno para desarrollo local y producción","Despliegue en plataformas como Vercel, Neon y GitHub Actions","Compatibilidad con archivos de configuración para cada categoría","Documentación integrada para cada paso del proceso"],"fr":["Configuration interactive des environnements d''infrastructure","Gestion des variables d''environnement pour le développement local et la production","Déploiement sur des plateformes telles que Vercel, Neon et GitHub Actions","Compatibilité avec des fichiers de configuration pour chaque catégorie","Documentation intégrée pour chaque étape du processus"],"de":["Interaktive Konfiguration von Infrastruktur-Umgebungen","Verwaltung von Umgebungsvariablen für lokale Entwicklung und Produktion","Bereitstellung auf Plattformen wie Vercel, Neon und GitHub Actions","Kompatibilität mit Konfigurationsdateien für jede Kategorie","Integrierte Dokumentation für jeden Schritt des Prozesses"],"pt":["Setup de ambiente local","Deploy em Vercel, Neon e GitHub Actions","Gerenciamento de variáveis de ambiente","Suporte a desenvolvimento interativo","Integração com ferramentas de deploy"],"ru":["Настройка локальной среды","Deploy в Vercel, Neon и GitHub Actions","Управление переменными окружения","Поддержка интерактивного разработки","Интеграция с инструментами deploy"],"ar":["إعداد البيئة المحلية","توزيع في Vercel، Neon و GitHub Actions","إدارة متغيرات البيئة","دعم التطوير التفاعلي","تكامل مع أدوات التوزيع"]},"keywords":{"en":["einja-infra-maintenance setup guide","infrastructure management for developers","Vercel deployment tutorial","GitHub Actions environment variables","what is einja-infra-maintenance","einja-infra-maintenance vs traditional infrastructure management"],"zh":["AIエージェント","环境变量管理","Vercel部署","Neon部署","GitHub Actions","对话式执行","开发环境管理"],"ja":["AIエージェント","インフラ環境メンテナンス","環境変数管理","Vercelデプロイ","Neonデプロイ","GitHub Actions","対話式の実行"],"ko":["AI 에이전트","인프라 환경 유지 관리","환경 변수 관리","Vercel 배포","Neon 배포","GitHub Actions","대화형 실행"],"es":["einja-infra-maintenance","configuración de infraestructura","variables de entorno","despliegue en Vercel","despliegue en Neon","despliegue en GitHub Actions","herramientas de AI para desarrolladores","Infrastruktur als Code"],"fr":["einja-infra-maintenance","configuration d''infrastructure","variables d''environnement","déploiement sur Vercel","déploiement sur Neon","déploiement sur GitHub Actions","outils d''IA pour développeurs","Infrastructure comme Code"],"de":["einja-infra-maintenance","Infrastruktur-Konfiguration","Umgebungsvariablen","Bereitstellung auf Vercel","Bereitstellung auf Neon","Bereitstellung auf GitHub Actions","AI-Tools für Entwickler","Infrastruktur als Code"],"pt":["einja-infra-maintenance","manutenção de infraestrutura","setup de ambiente","deploy em Vercel","gerenciamento de variáveis","desenvolvimento interativo","ferramentas de deploy"],"ru":["ИИ Агент einja-infra-maintenance","поддержка инфраструктуры","настройка окружения","deploy в Vercel","управление переменными","интерактивное разработка","инструменты deploy"],"ar":["وحدة einja-infra-maintenance","صيانة البنية التحتية","إعداد البيئة","توزيع في Vercel","إدارة المتغيرات","التطوير التفاعلي","أدوات التوزيع"]}},"owner":"einja-inc","repo":"einja-management-template","repoPath":"einja-inc/einja-management-template","stars":1,"forks":0,"updatedAt":"2026-03-07T12:03:06Z","topics":[],"category":"community","skillMd":{"name":"einja-infra-maintenance","description":"インフラ環境のセットアップ・メンテナンスを対話的に実行するSkill。ローカル環境、Vercel、Neon、GitHub Actions、環境変数管理をカバー","bodyPreview":"# インフラ環境メンテナンス Skill\n\n## 概要\n\nインフラ環境のセットアップ・メンテナンスを**対話的に**実行するSkillです。ローカル開発環境、Vercel、Neon、GitHub Actions、環境変数管理をカバーします。\n\n## 参照ドキュメント\n\n> **重要**: ドキュメントは**起動時に全て読まない**。選択されたカテゴリの実行時に、該当する参照ドキュメントのみを読むこと。各カテゴリの「参照ドキュメント」セクションに記載されたファイルが対象。\n\n### 設計方針\n- `docs/einja/steering/infrastructure/environment-variables.md`\n- `docs/einja/steering/infrastructure/deployment.md`\n\n### 手順書\n- `docs/einja/instructions/environment-setup.md`\n- `docs/einja/instructions/deployment-setup.md`\n- `docs/einja/instructions/ve","body":"# インフラ環境メンテナンス Skill\n\n## 概要\n\nインフラ環境のセットアップ・メンテナンスを**対話的に**実行するSkillです。ローカル開発環境、Vercel、Neon、GitHub Actions、環境変数管理をカバーします。\n\n## 参照ドキュメント\n\n> **重要**: ドキュメントは**起動時に全て読まない**。選択されたカテゴリの実行時に、該当する参照ドキュメントのみを読むこと。各カテゴリの「参照ドキュメント」セクションに記載されたファイルが対象。\n\n### 設計方針\n- `docs/einja/steering/infrastructure/environment-variables.md`\n- `docs/einja/steering/infrastructure/deployment.md`\n\n### 手順書\n- `docs/einja/instructions/environment-setup.md`\n- `docs/einja/instructions/deployment-setup.md`\n- `docs/einja/instructions/vercel-cli-reference.md`\n- `docs/einja/instructions/neon-cli-reference.md`\n- `docs/einja/instructions/local-server-environment-and-worktree.md`\n\n> **Single Source of Truth**: このSkillは対話フローの定義であり、具体的なコマンド手順は各カテゴリの参照ドキュメントが正。\n\n---\n\n## 実行フロー\n\n```mermaid\ngraph TB\n    Start[Skill起動] --> Detect[Phase 1: 環境状態の自動検出]\n    Detect --> Judge[Phase 2: 意図判定]\n    Judge -->|意図が明確| Direct[該当カテゴリへ直接遷移]\n    Judge -->|意図が不明確| Menu[AskUserQuestion: メインメニュー]\n    Menu --> Cat[カテゴリ 1-7 選択]\n    Direct --> Exec[実行]\n    Cat --> Exec\n    Exec --> Result[結果報告]\n```\n\n---\n\n## Phase 1: 環境状態の自動検出\n\nSkill起動時に以下を自動検出し、結果をユーザーに表示する。\n\n```bash\n# === ファイル存在確認 ===\nfor f in .env .env.local .env.keys .env.personal .env.develop .env.staging .env.production .env.preview; do\n  [ -f \"$f\" ] && echo \"✅ $f\" || echo \"❌ $f\"\ndone\n\n# === CLI存在確認 ===\nfor cmd in vercel neonctl gh dotenvx docker; do\n  command -v \"$cmd\" >/dev/null 2>&1 && echo \"✅ $cmd\" || echo \"❌ $cmd\"\ndone\n\n# === Docker/PostgreSQL状態 ===\ndocker compose ps 2>/dev/null | grep postgres\n\n# === 開発サーバー状態 ===\npnpm dev:status 2>/dev/null || echo \"停止中\"\n\n# === デフォルトトークン設定状況 ===\nDEFAULTS_FILE=\"${XDG_CONFIG_HOME:-$HOME/.config}/einja/defaults.json\"\nif [ -f \"$DEFAULTS_FILE\" ]; then\n  echo \"✅ デフォルトトークン設定ファイル\"\n  # jqがある場合はキーの有無を表示\n  if command -v jq >/dev/null 2>&1; then\n    for key in VERCEL_TOKEN NEON_API_KEY GITHUB_TOKEN VERCEL_ORG_ID; do\n      val=$(jq -r \".tokens.${key} // empty\" \"$DEFAULTS_FILE\")\n      [ -n \"$val\" ] && echo \"  ✅ $key\" || echo \"  ❌ $key\"\n    done\n  fi\nelse\n  echo \"❌ デフォルトトークン未設定\"\nfi\n\n# === トークン有効性検証（.env.personal 存在時のみ） ===\nif [ -f \".env.personal\" ]; then\n  # 並行実行で高速化（各コマンドにタイムアウト設定）\n  timeout 5 gh auth status 2>/dev/null && echo \"✅ GITHUB_TOKEN 有効\" || echo \"⚠️ GITHUB_TOKEN 無効/未設定\" &\n  timeout 5 vercel whoami 2>/dev/null && echo \"✅ VERCEL_TOKEN 有効\" || echo \"⚠️ VERCEL_TOKEN 無効/未設定\" &\n  if [ -n \"$NEON_API_KEY\" ]; then\n    timeout 5 neonctl projects list --api-key \"$NEON_API_KEY\" >/dev/null 2>&1 && echo \"✅ NEON_API_KEY 有効\" || echo \"⚠️ NEON_API_KEY 無効/期限切れ\" &\n  else\n    echo \"⚠️ NEON_API_KEY 未設定\"\n  fi\n  wait\nfi\n```\n\n検出結果をサマリー表示した上で、AskUserQuestionでメインメニューを表示する。\n\n---\n\n## Phase 2: 意図判定とメインメニュー\n\n### 意図が明確な場合（質問せずに直接実行）\n\nSkill起動時の引数やユーザーの指示から意図が読み取れる場合は、AskUserQuestionを使わずに該当カテゴリに直接進む。\n\n**直接実行の例:**\n- `/infra-maintenance Vercel初期設定` → カテゴリ3: Vercel管理へ直接遷移\n- `/infra-maintenance ヘルスチェック` → カテゴリ6: 環境状態確認へ直接遷移\n- `Neonのブランチを作成したい` → カテゴリ4: Neon管理へ直接遷移\n- `GitHub Secretsを一括設定して` → カテゴリ5: GitHub Secrets管理へ直接遷移\n- `環境変数を追加したい` → カテゴリ2: 環境変数管理へ直接遷移\n- `CIが失敗してる` → カテゴリ7: GitHub Actions CI/CD管理へ直接遷移\n- `ワークフローの実行状況を見たい` → カテゴリ7: GitHub Actions CI/CD管理へ直接遷移\n- `デフォルトトークンを設定したい` → カテゴリ8: デフォルトトークン管理へ直接遷移\n- `共通トークンをプロジェクトに適用したい` → カテゴリ8: デフォルトトークン管理へ直接遷移\n\n### 意図が不明確な場合のみメニューを表示\n\n引数がない、または意図が曖昧な場合のみ、AskUserQuestionで以下の選択肢を提示する。検出結果に基づいて推奨を表示する。\n\n#### 検出結果に基づく推奨ロジック\n\nPhase 1の検出結果から、推奨カテゴリにマーク（推奨）を付与してAskUserQuestionの選択肢に表示する。\n\n| 検出結果 | 推奨カテゴリ |\n|---------|------------|\n| `.env.keys`不在 | ローカル環境セットアップ |\n| 開発サーバー停止中 + `.env.keys`存在 | ローカル環境セットアップ |\n| vercel CLI未インストール or 未リンク | Vercel管理 |\n| neonctl未インストール | Neon管理 |\n| `.env.personal`不在 | 環境変数管理 |\n| トークン無効/期限切れ | 環境変数管理（個人トークン再設定） |\n| デフォルトトークン未設定 | デフォルトトークン管理 |\n| 上記に該当しない | 環境状態確認（デフォルト） |\n\n| 選択肢 | 説明 |\n|--------|------|\n| ローカル環境セットアップ | 初回セットアップ、開発サーバー起動 |\n| 環境変数管理 | 個人トークン設定、チーム共有設定変更、新規変数追加 |\n| Vercel管理 | 初期設定、環境変数同期、デプロイ状態確認 |\n| Neon管理 | 初期設定、ブランチ管理、接続文字列取得 |\n| GitHub Secrets管理 | 一覧表示、個別設定、一括設定 |\n| 環境状態確認 | 包括的ヘルスチェック |\n| GitHub Actions CI/CD管理 | ワークフロー状態確認、失敗調査、手動トリガー |\n| デフォルトトークン管理 | 組織共通トークン（dev@einja.net）の設定・確認・検証・プロジェクト適用 |\n\n---\n\n## カテゴリ1: ローカル環境セットアップ\n\n### サブメニュー\n- **初回セットアップ**: `pnpm dev:setup` 実行\n- **開発サーバー起動**: `pnpm dev:bg` 実行\n- **サーバー停止**: `pnpm dev:stop` 実行\n- **ログ確認**: `pnpm dev:logs` 実行\n\n### 実行手順\n\n#### ゼロ状態判定\nPhase 1の検出結果で `.env*` ファイルが**全て不在**の場合、「初回プロジェクトセットアップ」モードとして以下の順序で案内する:\n1. 必須CLIツールの確認・インストール案内（Docker含む）\n2. `pnpm install` → `pnpm dev:setup` の実行\n3. 完了後、カテゴリ2（環境変数管理）への誘導\n\n#### 初回セットアップ\n1. `pnpm install` で依存関係インストール\n2. `pnpm dev:setup` で環境セットアップ\n3. エラー時: エラー内容を分析し、対話的にトラブルシュート\n\n#### エラー時の対処\n\n| エラー | 対処 |\n|--------|------|\n| `.env.keys`不在 | `git worktree list` でメインworktreeを検出し、`.env.keys` が存在すれば自動コピー。不在の場合は「チームメンバーから `.env.keys` ファイルを受け取り、プロジェクトルートに配置してください」と案内 |\n| Docker未インストール | [OrbStack](https://orbstack.dev/) のインストールを案内。`brew install orbstack` または公式サイトからダウンロード |\n| PostgreSQL接続エラー | `docker compose up -d postgres` → ヘルスチェック |\n| Node.jsバージョン不一致 | `volta install node@22` 提案 |\n| pnpmバージョン不一致 | `volta install pnpm@10` 提案 |\n\n### 参照ドキュメント\n- `docs/einja/instructions/local-server-environment-and-worktree.md`\n- `docs/einja/instructions/environment-setup.md`\n\n---\n\n## カテゴリ2: 環境変数管理\n\n### サブメニュー\n- **個人トークン設定**: `.env.personal`にトークンを保存\n- **チーム共有設定変更**: `.env.local`等の復号→編集→再暗号化\n- **新規環境変数追加**: プロジェクト全体への変数追加フロー\n- **環境変数の状態表示**: 現在の設定状態を表示\n\n> **クイック操作**: `pnpm env:update` を実行すると、個人トークン設定・チーム共有設定変更を対話式ウィザードで実行できます。\n\n### 実行手順\n\n#### 個人トークン設定\n1. 必要なトークンをAskUserQuestionで確認:\n   - `GITHUB_TOKEN`: https://github.com/settings/tokens/new\n   - `VERCEL_TOKEN`: https://vercel.com/account/tokens\n   - `NEON_API_KEY`: https://console.neon.tech/app/settings/api-keys\n2. AskUserQuestionでトークン値を入力してもらう\n3. `.env.personal`に保存\n4. `chmod 600 .env.personal` 実行\n5. API検証（可能な場合）:\n   - GitHub: `gh auth status`\n   - Vercel: `vercel whoami`\n   - Neon: `neonctl projects list --api-key $NEON_API_KEY`\n\n#### チーム共有設定変更\n1. AskUserQuestionで対象ファイルを選択（.env.local / .env.develop / .env.production / .env.preview）\n2. `dotenvx decrypt -f <file> --stdout > <file>.tmp`\n3. 変更内容をAskUserQuestionで確認\n4. 編集実行\n5. `rm <file> && mv <file>.tmp <file>`\n6. `dotenvx encrypt -f <file>`\n7. コミット案内\n\n#### 新規環境変数追加\n1. AskUserQuestionで変数名・用途・対象環境（local/develop/production/preview）を確認\n2. 対象環境に応じた`.env.*`ファイルを特定\n3. 暗号化ファイルの場合: チーム共有設定変更と同じフロー（decrypt→編集→encrypt）\n4. 非暗号化ファイルの場合（.env/.env.personal）: 直接編集\n5. AskUserQuestion: 他環境への展開が必要か確認\n6. コミット案内（チーム共有設定の場合）\n\n> **詳細手順**: `docs/einja/instructions/environment-setup.md`の「新規環境変数を追加するとき」を参照\n\n### 参照ドキュメント\n- `docs/einja/instructions/environment-setup.md`\n\n---\n\n## カテゴリ3: Vercel管理\n\n### サブメニュー\n- **新規プロジェクト作成**: Vercelプロジェクトの新規作成（初回のみ）\n- **初期設定**: プロジェクトリンク・Root Directory設定\n- **環境変数同期**: dotenvx鍵のVercel同期\n- **デプロイ状態確認**: 最新デプロイ情報表示\n\n### 実行手順\n\n#### 新規プロジェクト作成（初回のみ）\n> Vercelにプロジェクトが存在しない場合（ゼロ状態）のみ実行。VERCEL_TOKEN 取得済みが前提。\n\n1. **プロジェクト名の推定・確認**:\n   package.jsonのnameフィールドからプロジェクト名を推定（`@scope/name` → `name`、`-monorepo`/`-template`サフィックス除去）。\n   フォールバック: Gitリポジトリ名から推定。\n   ```bash\n   BASE_NAME=$(cat package.json | jq -r ''.name // empty'' | sed ''s/@[^/]*\\///'' | sed ''s/-monorepo$//'' | sed ''s/-template$//'')\n   if [ -z \"$BASE_NAME\" ]; then\n     BASE_NAME=$(basename \"$(git remote get-url origin 2>/dev/null)\" .git | sed ''s/-template$//'')\n   fi\n   # jq未インストール時のフォールバック\n   if [ -z \"$BASE_NAME\" ]; then\n     BASE_NAME=$(grep ''\"name\"'' package.json | head -1 | sed ''s/.*\"name\"[[:space:]]*:[[:space:]]*\"\\([^\"]*\\)\".*/\\1/'' | sed ''s/@[^/]*\\///'' | sed ''s/-monorepo$//'' | sed ''s/-template$//'')\n   fi\n   ```\n   推定した `${BASE_NAME}-web`, `${BASE_NAME}-admin` をAskUserQuestionでプロジェクト名と作成対象アプリ（web / admin / 両方）を確認。\n\n2. **既存プロジェクトの確認**:\n   ```bash\n   vercel project ls\n   ```\n   既にプロジェクトが存在する場合は「既にVercelに存在します。スキップしますか？」と確認。\n\n3. **CLIでプロジェクト作成・Git接続**:\n   ```bash\n   # チーム切り替え（必要な場合）\n   vercel switch <team-slug>\n\n   # apps/ 配下のディレクトリを動的取得\n   APP_DIRS=$(ls -d apps/*/  2>/dev/null | xargs -I{} basename {})\n   for APP_NAME in $APP_DIRS; do\n     cd \"apps/$APP_NAME\"\n     vercel link --project=\"${BASE_NAME}-${APP_NAME}\" --yes\n     vercel git connect \"https://github.com/${GH_ORG}/${GH_REPO}\" --yes\n     cd ../..\n   done\n   ```\n   > `vercel link` はプロジェクトが存在しない場合に自動作成する（`vercel-cli-reference.md` L287）\n\n4. **APIでRoot Directory設定**（CLIでは不可: `vercel-cli-reference.md` L112）:\n   ```bash\n   # apps/ 配下のディレクトリを動的取得\n   APP_DIRS=$(ls -d apps/*/  2>/dev/null | xargs -I{} basename {})\n   for APP_NAME in $APP_DIRS; do\n     PROJECT_ID=$(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.projectId'')\n     VERCEL_ORG_ID=$(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.orgId'')\n     curl -X PATCH \"https://api.vercel.com/v9/projects/$PROJECT_ID?teamId=$VERCEL_ORG_ID\" \\\n       -H \"Authorization: Bearer $VERCEL_TOKEN\" \\\n       -H \"Content-Type: application/json\" \\\n       -d \"{\\\"rootDirectory\\\": \\\"apps/$APP_NAME\\\"}\"\n   done\n   ```\n\n5. **プロジェクトID/ORG IDを自動取得・表示**:\n   ```bash\n   # apps/ 配下のディレクトリを動的取得\n   APP_DIRS=$(ls -d apps/*/  2>/dev/null | xargs -I{} basename {})\n   for APP_NAME in $APP_DIRS; do\n     echo \"$(echo $APP_NAME | tr ''[:lower:]'' ''[:upper:]''):\"\n     echo \"  PROJECT_ID: $(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.projectId'')\"\n     echo \"  ORG_ID: $(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.orgId'')\"\n   done\n   ```\n   GitHub Secretsへの登録を提案（→ カテゴリ5: 一括設定 Step 2）\n\n#### 初期設定\n1. VERCEL_TOKEN確認 → 未設定時はURL案内 + `.env.personal`保存\n2. AskUserQuestionでアプリ選択（web / admin）\n3. `vercel link --project=$NAME --yes` で接続\n4. Root Directory設定:\n   ```bash\n   curl -X PATCH \"https://api.vercel.com/v9/projects/$PROJECT_ID?teamId=$VERCEL_ORG_ID\" \\\n     -H \"Authorization: Bearer $VERCEL_TOKEN\" \\\n     -H \"Content-Type: application/json\" \\\n     -d ''{\"rootDirectory\": \"apps/$APP_NAME\"}''\n   ```\n5. `.vercel/project.json` からプロジェクトIDとORG IDを自動取得:\n   ```bash\n   VERCEL_PROJECT_ID=$(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.projectId'')\n   VERCEL_ORG_ID=$(cat \"apps/$APP_NAME/.vercel/project.json\" | jq -r ''.orgId'')\n   ```\n6. 取得結果を表示し、GitHub Secretsへの登録を提案（→ カテゴリ5）\n\n#### 環境変数同期\n> **注意**: CI/CDではmainブランチのみ`vercel env add`で自動同期。develop/staging/PRは`--env`実行時注入。\n> 以下の手動同期は**初回セットアップ時のみ**実行。\n\n1. `.env.keys`からDOTENV_PRIVATE_KEY_*を抽出\n2. AskUserQuestionで同期対象を確認（値はマスク表示）\n3. 承認後、`vercel env rm` + `vercel env add` でVercelに同期\n4. 設定結果を `vercel env ls` で確認\n\n> **詳細手順**: `docs/einja/instructions/vercel-cli-reference.md`の「環境変数同期自動化」を参照\n\n#### デプロイ状態確認\n```bash\nvercel ls\n```\n\n### 参照ドキュメント\n- `docs/einja/instructions/vercel-cli-reference.md`\n- `docs/einja/instructions/deployment-setup.md`\n\n---\n\n## カテゴリ4: Neon管理\n\n### サブメニュー\n- **初期設定**: プロジェクト作成・ブランチ戦略初期化\n- **ブランチ管理**: 一覧表示・作成・削除\n- **接続文字列取得**: 特定ブランチの接続URLを取得\n- **プロジェクトID取得**: 既存プロジェクトのIDを `neonctl projects list` で自動取得\n\n### 実行手順\n\n#### 初期設定\n1. NEON_API_KEY確認 → 未設定時はURL案内 + `.env.personal`保存\n   - 取得URL: https://console.neon.tech/app/settings/api-keys\n   - **`neonctl auth`は使用しない**（理由: `docs/einja/instructions/neon-cli-reference.md`「認証方式」参照）→ `--api-key`フラグまたは`NEON_API_KEY`環境変数で認証\n\n2. **既存プロジェクトの確認**:\n   ```bash\n   neonctl projects list --api-key $NEON_API_KEY\n   ```\n   既存プロジェクトがあれば一覧表示し、使用するプロジェクトをAskUserQuestionで確認。\n   既存プロジェクトを使用する場合 → `neonctl projects get $PROJECT_ID` でIDを取得してステップ4へ。\n\n3. **プロジェクト名の推定・確認・作成**:\n   共通推定ロジック（カテゴリ3と同様）で `$BASE_NAME` を取得。AskUserQuestionで確認（デフォルト値として提示）。\n   ```bash\n   neonctl projects create --name \"$NEON_PROJECT_NAME\" --region-id aws-ap-northeast-1 --api-key $NEON_API_KEY\n   ```\n   作成後、`neonctl projects list` でプロジェクトIDを取得:\n   ```bash\n   NEON_PROJECT_ID=$(neonctl projects list --api-key $NEON_API_KEY --output json | jq -r \".[] | select(.name==\\\"$NEON_PROJECT_NAME\\\") | .id\")\n   ```\n\n4. **`.env.preview` に自動設定** → dotenvx暗号化:\n   ```bash\n   dotenvx decrypt -f .env.preview --stdout > .env.preview.tmp\n   # 既存の同名変数を削除してから追加（重複防止）\n   grep -v \"^NEON_PROJECT_ID=\" .env.preview.tmp | grep -v \"^NEON_API_KEY=\" > .env.preview.clean\n   echo \"NEON_PROJECT_ID=$NEON_PROJECT_ID\" >> .env.preview.clean\n   echo \"NEON_API_KEY=$NEON_API_KEY\" >> .env.preview.clean\n   rm .env.preview && mv .env.preview.clean .env.preview\n   dotenvx encrypt -f .env.preview\n   ```\n\n5. ブランチ戦略初期設定:\n   - production（main）ブランチ確認\n   - developmentブランチ作成\n\n#### ブランチ管理\n```bash\n# 一覧\nneonctl branches list --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY\n\n# 作成\nneonctl branches create --project-id $NEON_PROJECT_ID --name $NAME --api-key $NEON_API_KEY\n\n# 削除\nneonctl branches delete $BRANCH_ID --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY\n```\n\n#### 接続文字列取得\n```bash\n# CLI（単一ブランチ）\nneonctl connection-string <branch-name> --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY\n\n# API（複数ブランチ一括取得時）\ncurl -s \"https://console.neon.tech/api/v2/projects/$NEON_PROJECT_ID/connection_uri?branch_id=$BRANCH_ID&database_name=neondb&role_name=$ROLE_NAME\" \\\n  -H \"Authorization: Bearer $NEON_API_KEY\"\n```\n\n> **pooled/unpooled接続の使い分け**:\n> - **マイグレーション用（unpooled）**: `neonctl connection-string <branch> --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY`（デフォルトはpooled=false）\n> - **アプリruntime用（pooled）**: `neonctl connection-string <branch> --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY --pooled`\n> - CI/CDワークフローではマイグレーション時にunpooled、アプリビルド時にpooled接続を使い分けている\n\n> **注意**: 孤立ブランチのクリーンアップは`cleanup-pr-preview-db.yml`ワークフローが自動実行するため、このSkillでは手動クリーンアップを提供しない。\n\n### 参照ドキュメント\n- `docs/einja/instructions/neon-cli-reference.md`\n- `docs/einja/instructions/deployment-setup.md`\n\n---\n\n## カテゴリ5: GitHub Secrets管理\n\n### サブメニュー\n- **一覧表示**: 現在のSecrets一覧\n- **個別設定**: 指定したSecretを設定\n- **一括設定**: `.env.keys`からdotenvx秘密鍵を一括設定\n\n### 実行手順\n\n#### 一覧表示\n```bash\ngh secret list\n```\n\n#### 個別設定\n1. AskUserQuestionでSecret名と値を入力\n2. `gh secret set $NAME --body \"<value>\"`\n3. 設定確認: `gh secret list`\n\n#### 一括設定（全Secrets）\n> **参照**: `docs/einja/instructions/deployment-setup.md`（セクション6）に全Secretsの取得手順あり\n\n**Step 1: dotenvx秘密鍵を自動抽出**\n```bash\nfor key_name in PREVIEW PRODUCTION DEVELOP STAGING; do\n  value=$(grep \"DOTENV_PRIVATE_KEY_${key_name}\" .env.keys | cut -d''='' -f2 | tr -d \"\\\"''\")\n  if [ -n \"$value\" ]; then\n    gh secret set \"DOTENV_PRIVATE_KEY_${key_name}\" --body \"$value\"\n    echo \"✅ DOTENV_PRIVATE_KEY_${key_name} を設定しました\"\n  else\n    echo \"⚠️ DOTENV_PRIVATE_KEY_${key_name} が .env.keys に見つかりません\"\n  fi\ndone\n```\n\n**Step 2: Vercel関連Secrets**\n\n2-a. `VERCEL_TOKEN`（人間入力が必須）:\nAskUserQuestionで値を入力してもらう。取得手順:\n- Vercel Dashboard（https://vercel.com/account/tokens）> 「Create Token」\n- Scope: Full Account を選択\n- 入力後、`vercel whoami --token $TOKEN` で有効性を自動検証\n\n2-b. `VERCEL_ORG_ID`（自動取得）:\n```bash\n# apps/web/.vercel/project.json から取得（vercel link 実行済みの場合）\nVERCEL_ORG_ID=$(cat apps/web/.vercel/project.json 2>/dev/null | jq -r ''.orgId'')\n# 未取得の場合はAPI経由\nif [ -z \"$VERCEL_ORG_ID\" ] || [ \"$VERCEL_ORG_ID\" = \"null\" ]; then\n  VERCEL_ORG_ID=$(curl -s \"https://api.vercel.com/v2/teams\" \\\n    -H \"Authorization: Bearer $VERCEL_TOKEN\" | jq -r ''.teams[0].id'')\nfi\ngh secret set VERCEL_ORG_ID --body \"$VERCEL_ORG_ID\"\necho \"✅ VERCEL_ORG_ID = $VERCEL_ORG_ID を設定しました\"\n```\n\n2-c. `VERCEL_PROJECT_ID_*`（自動取得）:\n```bash\n# apps/ 配下のディレクトリを動的取得（.vercelが存在するもの）\nfor APP_NAME in $(for d in apps/*/; do [ -d \"$d/.vercel\" ] && basename \"$d\"; done); do\n  # apps/<app>/.vercel/project.json から取得（vercel link 実行済みの場合）\n  PROJECT_ID=$(cat \"apps/$APP_NAME/.vercel/project.json\" 2>/dev/null | jq -r ''.projectId'')\n  if [ -z \"$PROJECT_ID\" ] || [ \"$PROJECT_ID\" = \"null\" ]; then\n    # vercel link 未実行の場合: カテゴリ3（新規プロジェクト作成 or 初期設定）を先に実行するよう案内\n    echo \"⚠️ apps/$APP_NAME/.vercel/project.json が見つかりません。先にカテゴリ3でVercelプロジェクトをリンクしてください\"\n    continue\n  fi\n  SECRET_NAME=\"VERCEL_PROJECT_ID_$(echo $APP_NAME | tr ''[:lower:]'' ''[:upper:]'')\"\n  gh secret set \"$SECRET_NAME\" --body \"$PROJECT_ID\"\n  echo \"✅ $SECRET_NAME = $PROJECT_ID を設定しました\"\ndone\n```\n\n**Step 3: Turborepo Remote Cache**\n\n3-a. `TURBO_TOKEN`:\nVERCEL_TOKEN（Step 2-a で取得済み）と同じ値を使用（別トークンを使う場合のみAskUserQuestionで入力）:\n```bash\ngh secret set TURBO_TOKEN --body \"$VERCEL_TOKEN\"\necho \"✅ TURBO_TOKEN を設定しました（VERCEL_TOKENと同一値）\"\n```\n\n3-b. `TURBO_TEAM`（自動取得）:\n```bash\nTURBO_TEAM=$(cat .turbo/config.json 2>/dev/null | jq -r ''.teamId // empty'')\nif [ -z \"$TURBO_TEAM\" ]; then\n  echo \"⚠️ .turbo/config.json 未生成。先に npx turbo login && npx turbo link を実行します\"\n  npx turbo login && npx turbo link\n  TURBO_TEAM=$(cat .turbo/config.json | jq -r ''.teamId'')\nfi\ngh secret set TURBO_TEAM --body \"$TURBO_TEAM\"\necho \"✅ TURBO_TEAM = $TURBO_TEAM を設定しました\"\n```\n\n### 参照ドキュメント\n- `docs/einja/instructions/deployment-setup.md`（セクション6: GitHub Secrets登録）\n\n---\n\n## カテゴリ6: 環境状態確認（ヘルスチェック）\n\n### チェック対象\n\n#### ローカル環境\n```bash\n# ランタイム\nnode --version\npnpm --version\n\n# 環境変数ファイル\nfor f in .env .env.local .env.keys .env.personal; do\n  [ -f \"$f\" ] && echo \"✅ $f\" || echo \"❌ $f\"\ndone\n\n# Docker/PostgreSQL\ndocker compose ps\ndocker compose exec postgres pg_isready -U postgres\n\n# 開発サーバー\npnpm dev:status\n\n# CLIツール\nfor cmd in gh vercel neonctl dotenvx; do\n  command -v \"$cmd\" >/dev/null 2>&1 && echo \"✅ $cmd\" || echo \"❌ $cmd\"\ndone\n\n# === デフォルトトークン ===\nDEFAULTS_FILE=\"${XDG_CONFIG_HOME:-$HOME/.config}/einja/defaults.json\"\nif [ -f \"$DEFAULTS_FILE\" ]; then\n  echo \"✅ デフォルトトークン設定済み\"\nelse\n  echo \"❌ デフォルトトークン未設定\"\nfi\n\n# === トークン有効性検証（.env.personal 存在時のみ） ===\nif [ -f \".env.personal\" ]; then\n  # 並行実行で高速化（各コマンドにタイムアウト設定）\n  timeout 5 gh auth status 2>/dev/null && echo \"✅ GITHUB_TOKEN 有効\" || echo \"⚠️ GITHUB_TOKEN 無効/未設定\" &\n  timeout 5 vercel whoami 2>/dev/null && echo \"✅ VERCEL_TOKEN 有効\" || echo \"⚠️ VERCEL_TOKEN 無効/未設定\" &\n  if [ -n \"$NEON_API_KEY\" ]; then\n    timeout 5 neonctl projects list --api-key \"$NEON_API_KEY\" >/dev/null 2>&1 && echo \"✅ NEON_API_KEY 有効\" || echo \"⚠️ NEON_API_KEY 無効/期限切れ\" &\n  else\n    echo \"⚠️ NEON_API_KEY 未設定\"\n  fi\n  wait\nfi\n```\n\n#### Vercel\n```bash\nvercel ls\n```\n\n#### Neon\n```bash\nneonctl branches list --project-id $NEON_PROJECT_ID --api-key $NEON_API_KEY\n```\n\n#### GitHub\n```bash\ngh secret list\ngh run list --limit 5\n```\n\n### 結果表示\n\nチェック結果を以下の形式でサマリー表示する:\n\n```\n=== 環境ヘルスチェック結果 ===\n\n📦 ローカル環境\n  ✅ Node.js 22.16.0\n  ✅ pnpm 10.14.0\n  ✅ PostgreSQL 起動中\n  ✅ 開発サーバー 起動中 (port 3195)\n  ❌ .env.personal 不在\n\n🔧 CLI ツール\n  ✅ gh 2.x\n  ✅ vercel 37.x\n  ❌ neonctl 未インストール\n  ✅ dotenvx 1.x\n\n🔑 デフォルトトークン\n  ✅ VERCEL_TOKEN 設定済み\n  ✅ NEON_API_KEY 設定済み\n  ✅ GITHUB_TOKEN 設定済み\n  ❌ VERCEL_ORG_ID 未設定\n\n🔑 トークン有効性\n  ✅ GITHUB_TOKEN 有効\n  ✅ VERCEL_TOKEN 有効\n  ⚠️ NEON_API_KEY 未設定\n\n☁️ Vercel\n  ✅ 最新デプロイ: 2h ago (Ready)\n\n🗄️ Neon\n  ✅ ブランチ: 3個 (main, development, preview/feature-auth)\n\n🔐 GitHub Secrets\n  ✅ 10個のSecrets設定済み\n  ✅ 最新CI: 成功 (2h ago)\n```\n\n### 推奨アクション提案\n\nヘルスチェック結果に❌がある場合、以下のルールで推奨アクションを提示する:\n\n| 検出結果 | 推奨アクション |\n|---------|--------------|\n| `.env.keys`不在 / CLI未インストール | → カテゴリ1（ローカル環境セットアップ） |\n| `.env.personal`不在 / トークン未設定 | → カテゴリ2（環境変数管理 > 個人トークン設定） |\n| トークン無効/期限切れ | → カテゴリ2（環境変数管理 > 個人トークン再設定） |\n| Vercel未リンク / デプロイエラー | → カテゴリ3（Vercel管理） |\n| Neonブランチ取得失敗 | → カテゴリ4（Neon管理） |\n| GitHub Secrets不足 | → カテゴリ5（GitHub Secrets管理） |\n| CI失敗 | → カテゴリ7（GitHub Actions CI/CD管理 > 失敗調査） |\n| デフォルトトークン未設定 | → カテゴリ8（デフォルトトークン管理） |\n\n❌が3個以上の場合は「初期セットアップが必要です。カテゴリ1を実行してください」と表示。\n\n### 参照ドキュメント\n- `docs/einja/instructions/local-server-environment-and-worktree.md`（包括的ヘルスチェック）\n\n---\n\n## カテゴリ7: GitHub Actions CI/CD管理\n\n### サブメニュー\n- **ワークフロー状態確認**: 最新の実行結果一覧\n- **失敗調査**: 失敗したワークフローのログ分析\n- **手動トリガー**: ワークフローの手動実行\n- **ワークフロー一覧**: 利用可能なワークフロー確認\n\n### プロジェクトのワークフロー\n\n| ワークフロー | ファイル | トリガー | 用途 | 備考 |\n|------------|---------|---------|------|------|\n| デプロイ（安定ブランチ） | `deploy-stable-branches.yml` | push to main/develop/staging | 動的マトリクス → 変更アプリのみデプロイ | mainのみenv sync、他は`--env`実行時注入 |\n| PRプレビューデプロイ | `deploy-pr-preview.yml` | PR open/sync | PR毎のプレビュー環境作成 | `--env`実行時注入（env sync廃止） |\n| PRプレビューDB削除 | `cleanup-pr-preview-db.yml` | schedule/manual | 孤立Neonブランチのクリーンアップ | PR未存在のブランチを自動削除 |\n| PRクローズ時クリーンアップ | `cleanup-pr-preview-on-close.yml` | PR close | PR関連リソース削除 | Neonブランチ + Vercel Preview削除 |\n| CLIリリース | `release-cli.yml` | manual | @einja/cli NPM公開 | workflow_dispatch対応 |\n| create-einja-appリリース | `release-create-einja-app.yml` | manual | create-einja-app NPM公開 | workflow_dispatch対応 |\n| Claude Code | `claude.yml` | issue comment | Claude Codeによる自動対応 | `/claude`コメントでトリガー |\n\n### 実行手順\n\n#### ワークフロー状態確認\n```bash\n# 最新の実行結果一覧\ngh run list --limit 10\n\n# 特定ワークフローの実行一覧\ngh run list --workflow=deploy-stable-branches.yml --limit 5\n\n# 実行中のワークフロー\ngh run list --status=in_progress\n```\n\n#### 失敗調査\n1. 失敗したワークフローの一覧を取得:\n   ```bash\n   gh run list --status=failure --limit 5\n   ```\n2. AskUserQuestionで調査対象のrun-idを選択\n3. 失敗したジョブのログを表示:\n   ```bash\n   gh run view <run-id> --log-failed\n   ```\n4. **ログ分析→アクション提案**: エラーパターンに基づいてカテゴリ遷移を提案\n\n| エラーパターン | 推奨アクション |\n|---------------|---------------|\n| `Secret not found: DOTENV_PRIVATE_KEY_*` | → カテゴリ5（GitHub Secrets管理）で一括設定 |\n| `vercel deploy failed` | → カテゴリ3（Vercel管理）で状態確認 |\n| `neonctl: authentication failed` | → カテゴリ5でNEON_API_KEY更新 |\n| `Permission denied` | → `.github/workflows/`のpermissions設定確認を案内 |\n| その他 | エラーログ全文を表示し、対処方法をAskUserQuestionで相談 |\n\n#### 手動トリガー\n```bash\n# workflow_dispatch対応ワークフローを手動実行\ngh workflow run <workflow-file> --ref <branch>\n\n# 入力パラメータ付き\ngh workflow run <workflow-file> --ref <branch> -f param1=value1\n\n# PRプレビューDBクリーンアップの手動実行\ngh workflow run cleanup-pr-preview-db.yml --ref main\n```\n\n#### ワークフロー一覧\n```bash\n# 利用可能なワークフロー一覧\ngh workflow list\n\n# 特定ワークフローの詳細\ngh workflow view <workflow-file>\n```\n\n### エラー時の対処\n\n| エラー | 対処 |\n|--------|------|\n| デプロイ失敗 | `gh run view <id> --log-failed` でログ確認 → 原因特定 |\n| Secrets不足 | カテゴリ5（GitHub Secrets管理）で設定 |\n| 環境変数同期失敗 | dotenvx秘密鍵のSecret設定を確認 |\n| Neonブランチ作成失敗 | NEON_API_KEY のSecret設定・有効期限を確認 |\n| Permission denied | ワークフローのpermissions設定を確認 |\n\n### 参照ドキュメント\n- `.github/workflows/` 内の各ワークフローファイル\n- `docs/einja/instructions/deployment-setup.md`\n- `docs/einja/steering/infrastructure/deployment.md`\n\n---\n\n## カテゴリ8: デフォルトトークン管理\n\n### 概要\n\n組織共通のトークン（`dev@einja.net` アカウント）をグローバルデフォルトとして `~/.config/einja/defaults.json` に保存し、複数プロジェクトで再利用する機能。\n\n> **クイック操作**: `pnpm env` → 「デフォルトトークン管理」を選択\n\n### サブメニュー\n- **トークンを設定/更新**: 個別にデフォルトトークンを入力\n- **プロジェクトに適用**: デフォルトを `.env.personal` にコピー\n- **トークンを検証**: API接続テスト\n\n### 管理対象トークン\n\n| キー | 用途 | 取得先 |\n|------|------|--------|\n| `VERCEL_TOKEN` | Vercel CLI認証 | https://vercel.com/account/tokens |\n| `NEON_API_KEY` | Neon CLI認証 | https://console.neon.tech/app/settings/api-keys |\n| `GITHUB_TOKEN` | GitHub API認証 | https://github.com/settings/tokens/new |\n| `VERCEL_ORG_ID` | Vercel組織ID | `apps/web/.vercel/project.json` の `orgId` |\n\n### 実行手順\n\n#### トークンを設定/更新\n1. `pnpm env` → 「デフォルトトークン管理」→「トークンを設定/更新」\n2. 各トークンについて設定するか確認（現在値をマスク表示）\n3. 入力されたトークンを `~/.config/einja/defaults.json` に保存\n\n#### プロジェクトに適用\n1. 「プロジェクトに適用」を選択\n2. 各トークンについて `.env.personal` への適用を確認\n3. 承認されたトークンのみ `.env.personal` に書き込み\n\n#### トークンを検証\n各トークンのAPIエンドポイントに接続テスト:\n- `GITHUB_TOKEN`: `https://api.github.com/user`\n- `VERCEL_TOKEN`: `https://api.vercel.com/v2/user`\n- `NEON_API_KEY`: `https://console.neon.tech/api/v2/projects`\n\n### トークン参照の優先順位\n\n```\nプロジェクト .env.personal  >  グローバルデフォルト (~/.config/einja/defaults.json)\n```\n\n### セキュリティ\n\n| 項目 | 詳細 |\n|------|------|\n| 保存形式 | プレーンテキスト JSON（`.env.personal` と同等のリスクレベル） |\n| ディレクトリ権限 | `~/.config/einja/` を `0700` で作成 |\n| ファイル権限 | `defaults.json` を `0600` で作成 |\n| CI環境 | `process.env.CI` が truthy の場合、読み書きともにスキップ |\n\n### 参照ドキュメント\n- `docs/einja/instructions/environment-setup.md`\n- `docs/einja/steering/infrastructure/environment-variables.md`\n\n---\n\n## セキュリティ考慮事項\n\n### トークン・API Keyの管理\n\n| トークン | 保存先 | セキュリティ |\n|---------|--------|------------|\n| VERCEL_TOKEN | `.env.personal` | gitignore対象、`chmod 600`設定 |\n| NEON_API_KEY | `.env.personal` | gitignore対象、`chmod 600`設定 |\n| GITHUB_TOKEN | `.env.personal` | gitignore対象、`chmod 600`設定 |\n| DOTENV_PRIVATE_KEY_* | `.env.keys` | gitignore対象、1Password等で共有 |\n| NEON_PROJECT_ID | `.env.preview`（暗号化） | dotenvx暗号化、Git管理 |\n\n**必須**: トークン保存後は `chmod 600 .env.personal` を実行すること。\n\n### CLI vs REST API 使い分け\n\n| 操作 | 方式 | 理由 |\n|------|------|------|\n| Vercel プロジェクト操作 | CLI (`vercel link --yes`) | 認証簡単、非対話モード対応 |\n| Vercel Root Directory設定 | API (`PATCH /v9/projects/{id}`) | CLIでは不可 |\n| Vercel 標準環境変数 | CLI (`vercel env add/rm`) | バッチ対応 |\n| Neon ブランチ操作 | CLI (`neonctl --api-key`) | 環境変数認証で非対話実行可 |\n| Neon 接続URL取得 | CLI + API | CLI: 単一ブランチ、API: 一括取得 |\n| GitHub Secrets | CLI (`gh secret set`) | API暗号化が複雑 |\n| GitHub Actions監視 | CLI (`gh run list/view`) | フォーマット良好 |\n\n---\n\n## エラーハンドリング\n\n| エラー種別 | 対処 |\n|-----------|------|\n| CLI未インストール | 自動インストール実行: `brew install <cli>` または `npm i -g <cli>`。Docker のみ OrbStack インストール案内（GUI必須のため） |\n| トークン未設定 | 取得URL案内 → AskUserQuestionで値入力 → `.env.personal`に保存 → API検証（`vercel whoami` / `gh auth status` / `neonctl projects list`）で有効性確認 |\n| トークン無効/期限切れ | 再取得URL案内 → AskUserQuestionで新しい値入力 → `.env.personal`を更新 → API検証で有効性確認 |\n| API呼び出し失敗 | エラー内容表示 → リトライ or 代替手段提示 |\n| dotenvx復号失敗 | `.env.keys`確認 → 秘密鍵再設定ガイド |\n| ネットワークエラー | 3回リトライ → 失敗時は手動手順提示 |\n\n---\n\n## 既存ワークフローとの整合性\n\n### 競合回避ルール\n\n- **環境変数同期**: `vercel env add`によるVercel環境変数ストアへの書き込みはmainブランチのみ。develop/staging/PRは`vercel deploy --env`で実行時注入（並行デプロイ間の競合防止）\n- **初回セットアップ**: Skillでは初回セットアップ時のみ手動同期。以降はGitHub Actionsが自動管理\n- **Neonブランチクリーンアップ**: `cleanup-pr-preview-db.yml`が定期実行。Skillでは手動クリーンアップは提供しない\n- **GitHub Secrets更新**: Skillで設定した値はワークフローでそのまま使用される（同じdotenvxコマンド体系）\n\n---\n\n## 初版で除外する機能\n\n以下の機能は将来版で対応予定:\n\n| 機能 | 除外理由 | 対応方針 |\n|------|---------|---------|\n| トークンローテーション | 手順書にドキュメント化のみで十分 | `environment-setup.md`を参照 |\n| Vercelカスタム環境操作 | API仕様の安定性要調査 | 安定確認後に追加 |\n| Neon孤立ブランチ手動クリーンアップ | 既存ワークフローに任せる | `cleanup-pr-preview-db.yml`が担当 |\n\n<!-- @einja:project-private:start id=\"einja-infra-maintenance-project\" -->\n<!-- プロジェクト固有の情報を記入 -->\n<!-- @einja:project-private:end -->\n"},"lastSynced":"2026-03-07T12:51:18.383Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined infrastructure setup and maintenance for local development environments, Vercel, Neon, and GitHub Actions.","zh":"适用于需要简化基础设施设置和维护的本地开发环境的DevOps代理，例如Vercel、Neon和GitHub Actions。","ja":"ローカル開発環境のインフラストラクチャ設定とメンテナンスを簡素化する必要があるDevOpsエージェントに適しています。例えば、Vercel、Neon、GitHub Actionsです。","ko":"로컬 개발 환경의 인프라 설정 및 유지 보수를 간소화해야 하는 DevOps 에이전트에 적합합니다. 예를 들어 Vercel, Neon, GitHub Actions와 같은 경우입니다.","es":"Ideal para agentes de DevOps que requieren una configuración y mantenimiento de infraestructura simplificados para entornos de desarrollo locales, Vercel, Neon y GitHub Actions.","fr":"Idéal pour les agents DevOps nécessitant une configuration et une maintenance d''infrastructure simplifiées pour les environnements de développement locaux, Vercel, Neon et GitHub Actions.","de":"Ideal für DevOps-Agents, die eine vereinfachte Infrastrukturkonfiguration und -wartung für lokale Entwicklungsumgebungen benötigen, Vercel, Neon und GitHub Actions.","pt":"Ideal para Agentes DevOps que requerem configuração e manutenção de infraestrutura simplificadas para ambientes de desenvolvimento local, Vercel, Neon e GitHub Actions.","ru":"Идеально подходит для агентов DevOps, требующих упрощенной настройки и обслуживания инфраструктуры для локальных сред разработки, Vercel, Neon и GitHub Actions.","ar":"مثالي لعميل DevOps الذين يتطلبون إعداد البنية التحتية وبصيانة مبسطة للبيئات المحلية للتطوير، Vercel، Neon، و GitHub Actions."},"recommendation":{"en":"Empowers agents to manage environment variables, automate deployment setups, and interact with infrastructure services like Vercel and Neon, utilizing documentation from categories such as environment-variables.md and deployment.md.","zh":"赋予代理管理环境变量、自动化部署设置以及与Vercel和Neon等基础设施服务交互的能力，利用environment-variables.md和deployment.md等类别的文档。","ja":"エージェントが環境変数を管理し、デプロイ設定を自動化し、VercelやNeonなどのインフラストラクチャサービスとやり取りする能力を提供します。environment-variables.mdやdeployment.mdなどのカテゴリのドキュメントを利用します。","ko":"에이전트가 환경 변수를 관리하고 배포 설정을 자동화하며 Vercel 및 Neon과 같은 인프라 서비스와 상호 작용할 수 있는 기능을 제공합니다. environment-variables.md 및 deployment.md와 같은 카테고리의 문서를 사용합니다.","es":"Permite a los agentes gestionar variables de entorno, automatizar la configuración de despliegues y interactuar con servicios de infraestructura como Vercel y Neon, utilizando la documentación de categorías como environment-variables.md y deployment.md.","fr":"Permet aux agents de gérer les variables d''environnement, d''automatiser les configurations de déploiement et d''interagir avec les services d''infrastructure tels que Vercel et Neon, en utilisant la documentation de catégories telles que environment-variables.md et deployment.md.","de":"Ermöglicht es den Agents, Umgebungsvariablen zu verwalten, Deployment-Konfigurationen zu automatisieren und mit Infrastrukturdiensten wie Vercel und Neon zu interagieren, indem sie die Dokumentation von Kategorien wie environment-variables.md und deployment.md verwenden.","pt":"Habilita os agentes a gerenciar variáveis de ambiente, automatizar configurações de implantação e interagir com serviços de infraestrutura como Vercel e Neon, utilizando documentação de categorias como environment-variables.md e deployment.md.","ru":"Наделяет агентов возможностью управлять переменными среды, автоматизировать настройки развертывания и взаимодействовать с сервисами инфраструктуры, такими как Vercel и Neon, используя документацию из категорий, таких как environment-variables.md и deployment.md.","ar":"يتمكّن الوكلاء من إدارة متغيرات البيئة، وتوفير الإعدادات التلقائية للنشر، والتفاعل مع خدمات البنية التحتية مثل Vercel و Neon، باستخدام الوثائق من الفئات مثل environment-variables.md و deployment.md."},"useCases":{"en":["Automating local development environment configurations","Deploying applications to Vercel and Neon platforms","Managing environment variables across different infrastructure setups"],"zh":["自动化本地开发环境配置","将应用程序部署到Vercel和Neon平台","跨不同基础设施设置管理环境变量"],"ja":["ローカル開発環境の設定を自動化する","アプリケーションをVercelおよびNeonプラットフォームにデプロイする","異なるインフラストラクチャ設定間で環境変数を管理する"],"ko":["로컬 개발 환경 설정 자동화","Vercel 및 Neon 플랫폼에 애플리케이션 배포","다양한 인프라 설정 간 환경 변수 관리"],"es":["Automatizar las configuraciones de entornos de desarrollo locales","Desplegar aplicaciones en las plataformas Vercel y Neon","Gestionar variables de entorno en diferentes configuraciones de infraestructura"],"fr":["Automatiser les configurations d''environnements de développement locaux","Déployer des applications sur les plateformes Vercel et Neon","Gérer les variables d''environnement dans différentes configurations d''infrastructure"],"de":["Automatisieren von Konfigurationen für lokale Entwicklungsumgebungen","Bereitstellen von Anwendungen auf den Plattformen Vercel und Neon","Verwalten von Umgebungsvariablen in verschiedenen Infrastrukturkonfigurationen"],"pt":["Automatizar configurações de ambiente de desenvolvimento local","Implantar aplicações em plataformas Vercel e Neon","Gerenciar variáveis de ambiente em diferentes configurações de infraestrutura"],"ru":["Автоматизировать настройки локальной среды разработки","Развертывать приложения на платформах Vercel и Neon","Управлять переменными среды в разных конфигурациях инфраструктуры"],"ar":["تحسين تلقائي لconfigurations بيئة التطوير المحلية","نشر التطبيقات على منصات Vercel و Neon","إدارة متغيرات البيئة عبر إعدادات البنية التحتية المختلفة"]},"limitations":{"en":["Requires access to specific documentation files at runtime","Limited to the services explicitly mentioned, such as Vercel, Neon, and GitHub Actions"],"zh":["需要在运行时访问特定的文档文件","仅限于明确提到的服务，例如Vercel、Neon和GitHub Actions"],"ja":["特定のドキュメントファイルに実行時にアクセスする必要がある","明示的に記載されているサービスに限定されます。例えば、Vercel、Neon、GitHub Actions"],"ko":["특정 문서 파일에 런타임 시 액세스해야 함","명시적으로 언급된 서비스에만 제한됩니다. 예를 들어 Vercel, Neon, GitHub Actions"],"es":["Requiere acceso a archivos de documentación específicos en tiempo de ejecución","Limitado a los servicios explícitamente mencionados, como Vercel, Neon y GitHub Actions"],"fr":["Requiert un accès à des fichiers de documentation spécifiques au moment de l''exécution","Limité aux services explicitement mentionnés, tels que Vercel, Neon et GitHub Actions"],"de":["Benötigt Zugriff auf bestimmte Dokumentationsdateien zur Laufzeit","Begrenzt auf die explizit genannten Dienste, wie Vercel, Neon und GitHub Actions"],"pt":["Requer acesso a arquivos de documentação específicos em tempo de execução","Limitado aos serviços mencionados explicitamente, como Vercel, Neon e GitHub Actions"],"ru":["Требует доступа к конкретным файлам документации во время выполнения","Ограничен только явно упомянутыми сервисами, такими как Vercel, Neon и GitHub Actions"],"ar":["يتطلب الوصول إلى ملفات توثيقية محددة في وقت التشغيل","محدود بالخدمات المذكورة صراحة، مثل Vercel و Neon و GitHub Actions"]},"version":4},"contentHash":"55ba1463877ff99abc4ef7f9eaff6dc3a5c70f594c74a0a3c6897f02a56e9e17","qualityScore":60}');
