INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('juanjaragavi/social-media-genius/authentication', 'authentication', 'juanjaragavi', 'social-media-genius', 'community', 'authentication juanjaragavi social-media-genius community The authentication skill governs login flows, session management, and protected route middleware for AI agents, leveraging technologies like Google OAuth and Supabase sessions. 身份验证技能用于管理登录流、会话和OAuth集成，支持Google OAuth和Supabase会话 認証スキルは、ログインフロー、セッション、OAuth統合を管理し、Google OAuthとSupabaseセッションをサポートします 인증 스킬은 로그인 흐름, 세션 및 OAuth 통합을 관리하며 Google OAuth 및 Supabase 세션을 지원합니다 La autenticación es un conjunto de habilidades que gobierna el trabajo de autenticación y autorización, incluyendo flujos de inicio de sesión y gestión de sesiones con OAuth y Supabase L''authentification est un ensemble de compétences qui régit le travail d''authentification et d''autorisation, y compris les flux de connexion et la gestion de sessions avec OAuth et Supabase Die Authentifizierung ist ein Satz von Fähigkeiten, der die Arbeit der Authentifizierung und Autorisierung regelt, einschließlich Login-Flows und Sitzungsmanagement mit OAuth und Supabase Autenticação é um skill que governa todo o trabalho de autenticação e autorização, incluindo login, sessões e OAuth. Saiba mais sobre como implementá-lo em suas aplicações Аутентификация - это навык, который управляет всей работой по аутентификации и авторизации, включая вход, сессии и OAuth для ИИ Агентов المصادقة هي مهارة تحكم جميع الأعمال المتعلقة بالمصادقة والتفويض، بما في ذلك عمليات التسجيل والجلسات وOAuth how to use authentication in AI agents what is authentication in software development authentication vs authorization in AI authentication setup guide for developers Google OAuth integration for AI agents Supabase sessions for secure login flows protected route middleware for AI authentication authentication alternative for AI developers installing authentication for AI agents authentication best practices for software development AIエージェント身份验证 登录流管理 会话管理 OAuth集成 Google OAuth Supabase会话 保护路由中间件 域限制访问 Manages login flows and session management using Supabase sessions Integrates Google OAuth for secure authentication and authorization Supports protected route middleware for restricted access control Enables domain-restricted access for secure data exchange Provides secondary Google Drive OAuth integration for expanded functionality Handles access control patterns for fine-grained permission management Authentication is a skill that manages access control, authorization, and secure data exchange for AI agents, enabling protected route middleware and domain-restricted access.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fabioeducacross/DesignSystem-Vuexy/scientific-schematics', 'community', 'fabioeducacross', 'DesignSystem-Vuexy', 'fabioeducacross/DesignSystem-Vuexy', 'scientific-schematics', 0, 0, 60, '2026-03-03T12:56:07Z', '2026-03-07T03:40:54.274Z', '0ffbbb6c89e2a58b5d7fee718ab10db7ac663243eac22adb441722b278bd7da0', '{"id":"fabioeducacross/DesignSystem-Vuexy/scientific-schematics","name":"scientific-schematics","description":{"en":"Scientific-schematics transforms complex concepts into clear visual representations using Nano Banana Pro AI for diagram generation and Gemini 3 Pro for quality review, benefiting developers and researchers.","zh":"科学图表生成使用Nano Banana Pro AI和Gemini 3 Pro，实现自动化的图表生成和质量审查","ja":"科学図表の自動生成は、Nano Banana Pro AIとGemini 3 Proを使用して実現します。図表生成と品質レビューを自動化します","ko":"과학 도면 생성은 Nano Banana Pro AI와 Gemini 3 Pro를 사용하여 자동으로 생성하고 품질을 검토합니다","es":"El esquemático científico utiliza Nano Banana Pro AI para generar imágenes de publicación de alta calidad. La revisión de calidad se realiza con Gemini 3 Pro.","fr":"Le schéma scientifique utilise Nano Banana Pro AI pour générer des images de publication de haute qualité. La révision de la qualité est effectuée avec Gemini 3 Pro.","de":"Das wissenschaftliche Schema verwendet Nano Banana Pro AI, um Publikationsbilder in hoher Qualität zu generieren. Die Qualitätsprüfung wird mit Gemini 3 Pro durchgeführt.","pt":"O esquema científico é uma representação visual de conceitos complexos, gerado automaticamente pelo Nano Banana Pro com revisão de qualidade do Gemini 3 Pro.","ru":"Научная схема - это визуальное представление сложных концепций, автоматически генерируемое с помощью Nano Banana Pro и проверяемое на качество с помощью Gemini 3 Pro.","ar":"المخطط العلمي هو تمثيل مرئي للمفاهيم المعقدة، يتم إنشاؤه تلقائيًا بواسطة Nano Banana Pro مع مراجعة الجودة من Gemini 3 Pro."}