INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fabioeducacross/DesignSystem-Vuexy/scientific-schematics', 'scientific-schematics', 'fabioeducacross', 'DesignSystem-Vuexy', 'community', 'scientific-schematics fabioeducacross DesignSystem-Vuexy community Scientific-schematics transforms complex concepts into clear visual representations using Nano Banana Pro AI for diagram generation and Gemini 3 Pro for quality review, benefiting developers and researchers. 科学图表生成使用Nano Banana Pro AI和Gemini 3 Pro，实现自动化的图表生成和质量审查 科学図表の自動生成は、Nano Banana Pro AIとGemini 3 Proを使用して実現します。図表生成と品質レビューを自動化します 과학 도면 생성은 Nano Banana Pro AI와 Gemini 3 Pro를 사용하여 자동으로 생성하고 품질을 검토합니다 El esquemático científico utiliza Nano Banana Pro AI para generar imágenes de publicación de alta calidad. La revisión de calidad se realiza con Gemini 3 Pro. Le schéma scientifique utilise Nano Banana Pro AI pour générer des images de publication de haute qualité. La révision de la qualité est effectuée avec Gemini 3 Pro. Das wissenschaftliche Schema verwendet Nano Banana Pro AI, um Publikationsbilder in hoher Qualität zu generieren. Die Qualitätsprüfung wird mit Gemini 3 Pro durchgeführt. O esquema científico é uma representação visual de conceitos complexos, gerado automaticamente pelo Nano Banana Pro com revisão de qualidade do Gemini 3 Pro. Научная схема - это визуальное представление сложных концепций, автоматически генерируемое с помощью Nano Banana Pro и проверяемое на качество с помощью Gemini 3 Pro. المخطط العلمي هو تمثيل مرئي للمفاهيم المعقدة، يتم إنشاؤه تلقائيًا بواسطة Nano Banana Pro مع مراجعة الجودة من Gemini 3 Pro. how to use scientific-schematics what is scientific-schematics scientific-schematics alternative scientific-schematics vs manual diagram generation scientific-schematics install scientific-schematics setup guide Nano Banana Pro AI tutorials Gemini 3 Pro quality review 科学图表生成 Nano Banana Pro AI Gemini 3 Pro 图表生成 自动化出版 科学图纸 图表质量审查 Generates publication-quality images automatically using Nano Banana Pro AI Utilizes Gemini 3 Pro for quality review against document-type thresholds Supports smart iteration, regenerating only as needed Accepts natural language descriptions for diagram generation Produces high-quality diagrams for scientific publications and research Scientific-schematics is a skill that uses AI to generate publication-quality diagrams and schematics for scientific publications and research.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dreamineering/meme-times/meme-launcher', 'community', 'dreamineering', 'meme-times', 'dreamineering/meme-times', 'meme-launcher', 0, 0, 60, '2026-01-14T07:48:21Z', '2026-03-07T03:41:13.104Z', 'c1a07788b888ce1f2c04735d1e5c27467a4e2e653b141b0f5e1e66adb1916c1f', '{"id":"dreamineering/meme-times/meme-launcher","name":"meme-launcher","description":{"en":"The meme-launcher skill provides end-to-end memecoin launch planning and execution for Solana, benefiting developers and project creators. It offers features like launch strategy and tokenomics planning.","zh":"Meme Launcher 是一个用于 Solana 的 Memecoin 发布系统，提供从概念到部署的端到端解决方案。它包括 Tokenomics、Pump.fun 发布策略和 Bonding Curve 设置等功能。","ja":"Meme Launcher は、Solana 向けの Memecoin 発売システムで、コンセプトからデプロイまでを網羅したエンドツーエンドのソリューションを提供します。トークノミクス、Pump.fun 発売戦略、ボンディングカーブ設定などを含みます - AIエージェント","ko":"Meme Launcher는 Solana 용 Memecoin 출시 시스템으로, 개념에서 배포까지 종단에서 종단까지 솔루션을 제공합니다. 토큰 경제학, Pump.fun 출시 전략, Bonding Curve 설정 등을 포함합니다 - AI 도구","es":"Meme Launcher es un sistema de lanzamiento de memecoin para Solana que cubre desde la planificación hasta la ejecución. Ofrece funcionalidades como tokenomics y configuración de curvas de vinculación.","fr":"Meme Launcher est un système de lancement de memecoin pour Solana qui couvre la planification à l''exécution. Il offre des fonctionnalités telles que la tokenomique et la configuration des courbes de liaison.","de":"Meme Launcher ist ein Memecoin-Startsystem für Solana, das von der Planung bis zur Ausführung reicht. Es bietet Funktionalitäten wie Tokenomics und Bonding-Kurven-Konfiguration.","pt":"O Meme Launcher é um sistema de lançamento de memecoins na Solana, oferecendo planejamento e execução de lançamento de conceito a implantação.","ru":"Meme Launcher - это система запуска мемекойнов на Solana, предоставляющая планирование и выполнение запуска от концепции до развертывания.","ar":"Meme Launcher هو نظام لإطلاق العملات الرمزية على Solana، يقدم التخطيط والتنفيذ لإطلاق العملات الرمزية من концепتها إلى نشرها."},"seo":{"title":{"en":"meme-launcher: Solana Memecoin Launch System Setup Guide ...","zh":"Meme Launcher 设置指南 - Solana Memecoin 发布系统","ja":"Meme Launcher Setup Guide - Solana Memecoin 発売システム - AIエー...","ko":"Meme Launcher 설정 가이드 - Solana Memecoin 출시 시스템 - AI 도구","es":"Guía de configuración de Meme Launcher para Solana","fr":"Mise en place de Meme Launcher pour Solana : Meilleures p...","de":"Meme Launcher für Solana: Einrichtungsanleitung und Tools","pt":"Guia de Configuração do Meme Launcher - Lançamento de Mem...","ru":"Настройка Meme Launcher - Система запуска мемекойнов на S...","ar":"دليل إعداد Meme Launcher - إطلاق العملات الرمزية على Solana"},"description":{"en":"Discover how to launch a memecoin on Solana with meme-launcher. Learn tokenomics, pump.fun launch strategies, and bonding curve setup. Get started now!","zh":"了解 Meme Launcher，一个用于 Solana 的端到端 Memecoin 发布规划和执行系统，包括概念、部署和 Tokenomics。","ja":"Solana 向けの Memecoin 発売計画と実行を端から端まで行う Meme Launcher を紹介します。コンセプト、デプロイ、トークノミクスなどを網羅しています - AIエージェント","ko":"Solana 용 Memecoin 출시 계획 및 실행을 종단에서 종단까지 처리하는 Meme Launcher에 대해 알아보세요. 개념, 배포, 토큰 경제학 등을 포함합니다 - AI 도구","es":"Descubre cómo lanzar un memecoin en Solana con Meme Launcher, desde la conceptualización hasta el despliegue y la estrategia de lanzamiento","fr":"Découvrez comment lancer un memecoin sur Solana avec Meme Launcher, de la conceptualisation au déploiement et à la stratégie de lancement","de":"Erfahren Sie, wie Sie mit Meme Launcher ein Memecoin auf Solana starten, von der Konzeption bis zum Deployment und Launch-Strategie","pt":"Aprenda a lançar memecoins na Solana com o Meme Launcher, incluindo planejamento, execução e estratégias de lançamento","ru":"Узнайте, как запустить мемекойны на Solana с помощью Meme Launcher, включая планирование, выполнение и стратегии запуска","ar":"تعلم كيفية إطلاق العملات الرمزية على Solana باستخدام Meme Launcher، بما في ذلك التخطيط والتنفيذ واستراتيجيات الإطلاق"},"definition":{"en":"meme-launcher is a Solana memecoin launch system that enables end-to-end planning and execution for memecoin projects, covering concept to deployment and beyond.","zh":"Meme Launcher 是一个用于 Solana 的 Memecoin 发布系统，提供端到端的发布规划和执行解决方案。","ja":"Meme Launcher は、Solana 向けの Memecoin 発売システムで、端から端までの発売計画と実行を提供します - AIエージェント","ko":"Meme Launcher는 Solana 용 Memecoin 출시 시스템으로, 종단에서 종단까지 출시 계획 및 실행을 제공하는 솔루션입니다 - AI 도구","es":"Meme Launcher es un sistema integral para el lanzamiento de memecoins en la blockchain de Solana","fr":"Meme Launcher est un système intégral pour le lancement de memecoins sur la blockchain Solana","de":"Meme Launcher ist ein integrales System für den Start von Memecoins in der Solana-Blockchain","pt":"O Meme Launcher é um sistema de lançamento de memecoins na Solana que fornece planejamento e execução de lançamento","ru":"Meme Launcher - это система запуска мемекойнов на Solana, обеспечивающая планирование и выполнение запуска","ar":"Meme Launcher هو نظام إطلاق العملات الرمزية على Solana يوفر التخطيط والتنفيذ لإطلاق العملات الرمزية"},"features":{"en":["Launches memecoins on the Solana platform","Provides tokenomics planning and execution","Supports pump.fun launch strategies","Enables bonding curve setup for memecoins","Offers pre-launch checklist and deployment planning","Builds hype for memecoins with targeted marketing strategies"],"zh":["端到端的 Memecoin 发布规划和执行","Tokenomics 和 Pump.fun 发布策略支持","Bonding Curve 设置和配置","从概念到部署的完整解决方案","Solana 平台集成","创建和管理 Memecoin 代币"],"ja":["端から端までの Memecoin 発売計画と実行","トークノミクスと Pump.fun 発売戦略のサポート","ボンディングカーブ設定と構成","コンセプトからデプロイまでの完全なソリューション","Solana プラットフォームの統合","Memecoin トークンの作成と管理 - AIエージェント"],"ko":["종단에서 종단까지의 Memecoin 출시 계획 및 실행","토큰 경제학 및 Pump.fun 출시 전략 지원","Bonding Curve 설정 및 구성","개념에서 배포까지의 완전한 솔루션","Solana 플랫폼 통합","Memecoin 토큰의 생성 및 관리 - AI 도구"],"es":["Planificación y ejecución de lanzamiento de memecoin","Tokenomics y configuración de curvas de vinculación","Estrategia de lanzamiento en Solana","Lista de verificación prelanzamiento","Creación de tokens y configuración de tokenomics","Configuración de curvas de vinculación para la estrategia de lanzamiento"],"fr":["Planification et exécution de lancement de memecoin","Tokenomique et configuration des courbes de liaison","Stratégie de lancement sur Solana","Liste de vérification pré-lancement","Création de tokens et configuration de tokenomique","Configuration des courbes de liaison pour la stratégie de lancement"],"de":["Planung und Ausführung von Memecoin-Starts","Tokenomics und Bonding-Kurven-Konfiguration","Startstrategie auf Solana","Vorstart-Checkliste","Token-Erstellung und Tokenomics-Konfiguration","Bonding-Kurven-Konfiguration für die Startstrategie"],"pt":["Planejamento de lançamento de memecoins","Estratégias de lançamento com Pump.fun","Configuração de curva de vinculação","Criação de token e minting","Lista de verificação pré-lançamento","Integração com a plataforma Solana"],"ru":["Планирование запуска мемекойнов","Стратегии запуска с Pump.fun","Настройка кривой привязки","Создание токена и майнинг","Предварительный чек-лист","Интеграция с платформой Solana"],"ar":["تخطيط إطلاق العملات الرمزية","استراتيجيات الإطلاق مع Pump.fun","إعداد منحنى الارتباط","إنشاء رمز و صك العملة","قائمة مراجعة قبل الإطلاق","التكامل مع منصة Solana"]},"keywords":{"en":["how to use meme-launcher","meme-launcher setup guide","Solana memecoin launch","tokenomics for memecoins","pump.fun launch strategy","meme-launcher alternative","meme-launcher vs other launch systems","meme-launcher install","meme-launcher documentation"],"zh":["Meme Launcher","Solana Memecoin","Tokenomics","Pump.fun","Bonding Curve","Memecoin 发布","Solana 平台","AI 工具","Memecoin 代币创建"],"ja":["Meme Launcher","Solana Memecoin","トークノミクス","Pump.fun","ボンディングカーブ","Memecoin 発売","Solana プラットフォーム","AIエージェント","Memecoin トークンの作成"],"ko":["Meme Launcher","Solana Memecoin","토큰 경제학","Pump.fun","Bonding Curve","Memecoin 출시","Solana 플랫폼","AI 도구","Memecoin 토큰 생성"],"es":["lanzamiento de memecoin","Solana","tokenomics","curvas de vinculación","estrategia de lanzamiento","lista de verificación prelanzamiento","creación de tokens","configuración de tokenomics","Meme Launcher","herramientas de Solana"],"fr":["lancement de memecoin","Solana","tokenomique","courbes de liaison","stratégie de lancement","liste de vérification pré-lancement","création de tokens","configuration de tokenomique","Meme Launcher","outils Solana"],"de":["Memecoin-Start","Solana","Tokenomics","Bonding-Kurven","Startstrategie","Vorstart-Checkliste","Token-Erstellung","Tokenomics-Konfiguration","Meme Launcher","Solana-Tools"],"pt":["lançamento de memecoins","Meme Launcher","Solana","Pump.fun","criação de token","minting","curva de vinculação","lista de verificação pré-lançamento","plataforma de lançamento de criptomoedas"],"ru":["запуск мемекойнов","Meme Launcher","Solana","Pump.fun","создание токена","майнинг","кривая привязки","предварительный чек-лист","платформа запуска криптовалют"],"ar":["إطلاق العملات الرمزية","Meme Launcher","Solana","Pump.fun","إنشاء رمز","صك العملة","منحنى الارتباط","قائمة مراجعة قبل الإطلاق","منصة إطلاق العملات الرقمية"]}},"owner":"dreamineering","repo":"meme-times","repoPath":"dreamineering/meme-times","stars":0,"forks":0,"updatedAt":"2026-01-14T07:48:21Z","topics":[],"category":"community","skillMd":{"name":"meme-launcher","description":"|","bodyPreview":"# Meme Launcher - Solana Memecoin Launch System\n\nEnd-to-end memecoin launch planning and execution for Solana. From concept to deployment to moon.\n\n## Activation Triggers\n\n<triggers>\n- \"Launch a memecoin\"\n- \"Create token for [concept]\"\n- \"Pump.fun launch strategy\"\n- \"Tokenomics for [project]\"\n- \"Pre-launch checklist\"\n- \"How to launch on [platform]\"\n- \"Bonding curve setup\"\n- \"Build hype for [token]\"\n- Keywords: launch, deploy, tokenomics, pump.fun launch, create token, mint token, bonding curve,","body":"# Meme Launcher - Solana Memecoin Launch System\n\nEnd-to-end memecoin launch planning and execution for Solana. From concept to deployment to moon.\n\n## Activation Triggers\n\n<triggers>\n- \"Launch a memecoin\"\n- \"Create token for [concept]\"\n- \"Pump.fun launch strategy\"\n- \"Tokenomics for [project]\"\n- \"Pre-launch checklist\"\n- \"How to launch on [platform]\"\n- \"Bonding curve setup\"\n- \"Build hype for [token]\"\n- Keywords: launch, deploy, tokenomics, pump.fun launch, create token, mint token, bonding curve, pre-launch, liquidity add\n</triggers>\n\n## Core Capabilities\n\n### 1. Token Concept Development\n- Name/ticker optimization (memorability, searchability)\n- Narrative construction (why this token, why now)\n- Visual identity guidelines (logo, banner, meme templates)\n- Community angle (target demographic, culture fit)\n\n### 2. Tokenomics Design\n- Supply architecture (total supply, decimals)\n- Distribution strategy (fair launch vs. presale)\n- Tax structure (if any) - buy/sell fees\n- Burn mechanics and deflationary options\n- LP allocation and lock parameters\n\n### 3. Platform Selection\n- **Pump.fun**: Bonding curve launches, low barrier, viral potential\n- **Raydium**: AMM pools, deeper liquidity, established traders\n- **Jupiter**: Launch pad features, routing optimization\n- **Custom SPL**: Full control, requires more setup\n\n### 4. Launch Execution\n- Contract deployment checklist\n- Liquidity provisioning strategy\n- Initial price setting\n- Sniper protection tactics\n- First-hour playbook\n\n### 5. Anti-Rug Implementation\n- Mint authority renouncement\n- Freeze authority removal\n- LP lock procedures\n- Transparent team allocation\n- Trust signals for buyers\n\n## Launch Platforms Deep Dive\n\n<platforms>\n### Pump.fun\n- **Best for**: Viral memes, low-effort launches, quick validation\n- **Bonding curve**: Auto-AMM, graduates to Raydium at threshold\n- **Cost**: ~0.02 SOL creation fee\n- **Time to launch**: < 5 minutes\n- **Graduation**: 69 SOL collected triggers Raydium migration\n\n### Raydium\n- **Best for**: Serious projects, larger liquidity, established presence\n- **Pool type**: Concentrated liquidity or standard AMM\n- **Cost**: ~2-3 SOL for pool creation\n- **Time to launch**: 15-30 minutes\n- **Requirements**: Pre-minted token, initial liquidity\n\n### Jupiter LFG\n- **Best for**: Curated launches, built-in audience\n- **Features**: Voting mechanism, established credibility\n- **Cost**: Application-based\n- **Time to launch**: Days (approval required)\n</platforms>\n\n## Implementation Workflow\n\n### Step 1: Parse Launch Intent\n```typescript\ninterface LaunchConfig {\n  concept: string;\n  name?: string;\n  ticker?: string;\n  platform: ''pump.fun'' | ''raydium'' | ''jupiter'' | ''custom'';\n  supply: number;\n  initialLiquidity: number; // in SOL\n  launchType: ''fair'' | ''presale'' | ''stealth'';\n  antiRugFeatures: string[];\n}\n```\n\n### Step 2: Concept Validation\n1. **Name Check**: Search existing tokens for conflicts\n2. **Trend Analysis**: Validate narrative timing\n3. **Competition Scan**: Similar tokens, market saturation\n4. **Virality Score**: Meme potential assessment\n\n### Step 3: Tokenomics Builder\n```\nRECOMMENDED TOKENOMICS:\n\nFair Launch (Pump.fun):\n- Supply: 1,000,000,000 (1B)\n- Decimals: 6\n- Dev allocation: 0% (buy from curve like everyone)\n- Tax: 0% (standard for pump.fun)\n- LP: Auto-managed by bonding curve\n\nRaydium Launch:\n- Supply: 1,000,000,000 (1B)\n- Decimals: 9\n- Dev/Team: 5-10% (vested/locked)\n- Marketing: 5%\n- LP: 80-90% of supply\n- Initial LP: 10-50 SOL recommended\n```\n\n### Step 4: Pre-Launch Checklist\nExecute validation before any deployment:\n```bash\nnpx tsx .claude/skills/meme-launcher/scripts/pre-launch-check.ts \\\n  --name \"MOONCAT\" \\\n  --ticker \"$MCAT\" \\\n  --platform pump.fun \\\n  --supply 1000000000\n```\n\n### Step 5: Launch Execution\nPlatform-specific deployment guides in `references/`\n\n## Output Formats\n\n### Launch Plan (Default)\n```\nTOKEN: $MCAT (MoonCat)\nPLATFORM: Pump.fun\nSTATUS: Ready to Deploy\n\nTOKENOMICS:\n- Supply: 1,000,000,000\n- Decimals: 6\n- Tax: 0%\n- LP Lock: Auto (pump.fun)\n\nPRE-LAUNCH CHECKLIST:\n[x] Name available (no conflicts)\n[x] Ticker unique\n[x] Logo prepared (400x400 PNG)\n[x] Description written\n[x] Social links ready\n[ ] Community seeded (min 50 members)\n[ ] KOL outreach complete\n\nANTI-RUG SIGNALS:\n[x] Fair launch (no presale)\n[x] Dev buys from curve\n[x] Mint renounced at creation\n[x] No freeze authority\n\nLAUNCH STRATEGY:\n1. Deploy at low-activity hour (2-4 AM UTC)\n2. Seed initial buys (0.5-1 SOL each x 5 wallets)\n3. Post to CT immediately after\n4. Telegram announcement at 10 holders\n5. Push for graduation at momentum peak\n\nESTIMATED COSTS:\n- Creation: 0.02 SOL\n- Initial seed buys: 2.5-5 SOL\n- Total: ~3-5 SOL\n```\n\n### Quick Deploy (--format quick)\n```\n$MCAT | Pump.fun | 1B supply | Fair launch\nDeploy: pump.fun/create → paste details → confirm\nPost-deploy: Announce → Seed → Shill\n```\n\n### Full Strategy (--format full)\nComplete go-to-market plan including:\n- 7-day pre-launch timeline\n- Community building playbook\n- Influencer outreach templates\n- Post-launch maintenance guide\n\n## Tokenomics Templates\n\n<tokenomics_templates>\n### Fair Launch (Maximum Trust)\n```\nSupply: 1B | Tax: 0% | Dev: 0%\nEveryone buys equally, dev buys from market\nBest for: Viral memes, community-driven\n```\n\n### Team Allocation (Project-Focused)\n```\nSupply: 1B | Tax: 0-1% | Team: 5-10% (locked 3mo)\nTeam tokens vested, transparent allocation\nBest for: Utility roadmap, long-term projects\n```\n\n### Marketing-Heavy\n```\nSupply: 1B | Tax: 2% (1% burn, 1% marketing) | Marketing wallet: 5%\nBuilt-in marketing fund from trading\nBest for: KOL campaigns, aggressive growth\n```\n\n### Deflationary\n```\nSupply: 1B | Burn: 1% per tx | LP burn: 50% at launch\nDecreasing supply over time\nBest for: \"Number go up\" narrative\n```\n</tokenomics_templates>\n\n## Platform Deployment Guides\n\n### Pump.fun Launch Steps\n```\n1. Go to pump.fun/create\n2. Upload logo (400x400 recommended)\n3. Enter name and ticker\n4. Write description (max 500 chars, include narrative)\n5. Add social links (Twitter, Telegram, Website)\n6. Pay creation fee (~0.02 SOL)\n7. IMMEDIATELY after creation:\n   - Copy contract address\n   - Make first buy (establishes you''re in)\n   - Post to Twitter with CA\n   - Share in Telegram\n```\n\n### Raydium Launch Steps\n```\n1. Create SPL token via spl-token CLI or Solana Tools\n2. Renounce mint authority\n3. Go to raydium.io/liquidity\n4. Create new pool (select token + SOL pair)\n5. Set initial price (supply in pool / SOL in pool)\n6. Add liquidity (recommend 80%+ of supply)\n7. Lock LP tokens (raydium.io/burn or third-party)\n8. Announce with LP lock proof\n```\n\n## Pre-Launch Validation\n\n<validation_checklist>\n**REQUIRED:**\n- [ ] Token name doesn''t conflict with established projects\n- [ ] Ticker is available and memorable (3-5 chars)\n- [ ] Logo is original or properly licensed\n- [ ] Description is clear and compelling\n- [ ] At least one social channel exists\n\n**RECOMMENDED:**\n- [ ] Community of 50+ members pre-launch\n- [ ] 2-3 KOLs aware/interested\n- [ ] Meme templates prepared\n- [ ] Website or landing page\n- [ ] Launch timing analyzed (avoid major events)\n\n**ANTI-RUG (Non-negotiable for credibility):**\n- [ ] Mint authority will be renounced\n- [ ] No freeze authority\n- [ ] LP will be locked or burned\n- [ ] Team allocation (if any) is transparent and locked\n- [ ] No hidden functions in contract\n</validation_checklist>\n\n## Launch Timing Strategy\n\n<timing>\n### Best Times (UTC)\n- **Monday-Wednesday 14:00-18:00**: US afternoon, peak CT activity\n- **Friday 12:00-16:00**: Weekend anticipation, FOMO builds\n- **Sunday 20:00-24:00**: Fresh week positioning\n\n### Avoid\n- **Saturday night**: Low attention\n- **Major crypto events**: Competition for attention\n- **Market dumps**: Fear overrides degen impulses\n- **US holidays**: Reduced volume\n\n### Coordination\n1. Soft announce 24h before (build anticipation)\n2. Final countdown 1h before (urgency)\n3. Deploy and immediately post CA\n4. First 10 minutes critical (seed momentum)\n</timing>\n\n## Post-Launch Checklist\n\n<post_launch>\n**First Hour:**\n- [ ] Verify contract on Solscan\n- [ ] Post CA to all channels\n- [ ] Monitor for snipers/bots\n- [ ] Engage with early buyers\n- [ ] Update Dexscreener info (if Raydium)\n\n**First Day:**\n- [ ] Track holder growth\n- [ ] Respond to community questions\n- [ ] Share milestone updates (holders, MCAP)\n- [ ] KOL follow-ups\n\n**First Week:**\n- [ ] Daily community engagement\n- [ ] Meme contests/airdrops\n- [ ] Partnership outreach\n- [ ] Roadmap updates (if applicable)\n</post_launch>\n\n## Risk Framework\n\n### Launch Risk Assessment\n```\nLOW RISK (Green light):\n- Unique concept, good timing\n- Community pre-built\n- Clean contract, all anti-rug features\n- Multiple social channels active\n\nMEDIUM RISK (Proceed carefully):\n- Similar tokens exist\n- Small initial community\n- Launch timing suboptimal\n- Limited marketing budget\n\nHIGH RISK (Reconsider):\n- Saturated narrative\n- No community traction\n- Poor timing (bear market)\n- No differentiator\n```\n\n## Error Handling\n\n<error_recovery>\n- **Name taken**: Generate alternatives, check availability\n- **Low initial traction**: Increase seed buys, delay major push\n- **Sniper attack**: Document, communicate to community\n- **Pump.fun graduation stall**: Rally community for final push\n- **FUD spreading**: Address transparently, show proof of anti-rug\n</error_recovery>\n\n## Security Considerations\n\n<security>\n- Never share deployer wallet private keys\n- Use fresh wallet for launches (operational security)\n- Verify all contract interactions before signing\n- Document everything for transparency\n- Prepare proof of LP lock/burn before launch\n</security>\n\n## Quality Gates\n\n<validation_rules>\n- Never recommend launch without anti-rug features\n- Always include LP strategy\n- Verify name/ticker availability before finalizing\n- Include cost estimates\n- Provide post-launch support checklist\n</validation_rules>\n\n<see_also>\n- references/pump-fun-guide.md - Detailed pump.fun walkthrough\n- references/tokenomics-templates.md - Supply/distribution models\n- references/launch-marketing-playbook.md - Go-to-market strategies\n- scripts/pre-launch-check.ts - Validation CLI\n</see_also>\n"},"lastSynced":"2026-03-07T03:41:13.104Z","agentAnalysis":{"suitability":{"en":"Perfect for Crypto Agents needing end-to-end memecoin launch planning and execution on Solana.","zh":"非常适合需要在Solana上进行端到端的memecoin发行规划和执行的Crypto Agents。","ja":"Solana上でのメームコインのエンドツーエンドの立ち上げ計画と実行が必要なCrypto Agentsに最適。","ko":"솔라나에서 엔드투엔드 메임코인 런치 계획 및 실행이 필요한 크립토 에이전트에게 완벽함","es":"Perfecto para agentes de Crypto que necesitan planificación y ejecución de lanzamiento de memecoin de extremo a extremo en Solana.","fr":"Parfait pour les agents Crypto ayant besoin d''une planification et d''une exécution de lancement de memecoin de bout en bout sur Solana.","de":"Perfekt für Crypto-Agents, die eine umfassende Planung und Ausführung von Memecoin-Starts auf Solana benötigen.","pt":"Perfeito para Agentes de Criptomoedas que precisam de planejamento e execução de lançamento de memecoin de ponta a ponta no Solana.","ru":"Идеально подходит для криптоагентов, которым необходим полный план запуска и реализации мемкоинов на Solana.","ar":" مثالي للوكلاء المشفرة الذين يحتاجون إلى تخطيط وإطلاق ميمكوين من النهاية إلى النهاية على سولانا."},"recommendation":{"en":"Empowers agents to plan and deploy memecoins using tokenomics planning, launch strategy, and bonding curve setup, leveraging Solana''s blockchain protocol and Pump.fun launch strategy.","zh":"赋予代理商使用代币经济学规划、启动策略和债券曲线设置来规划和部署memecoins的能力，利用Solana的区块链协议和Pump.fun启动策略。","ja":"エージェントがメームコインを計画して展開するためのトークノミクス計画、立ち上げ戦略、ボンディング曲線設定を使用できるようにすることで、SolanaのブロックチェーンプロトコルとPump.funの立ち上げ戦略を活用します。","ko":"토큰 경제학 계획, 런치 전략, 본딩 곡선 설정을 사용하여 메임코인을 계획하고 배포할 수 있는 능력을 에이전트에게 부여함으로써 솔라나의 블록체인 프로토콜과 펌프.펀의 런치 전략을 활용합니다.","es":"Habilita a los agentes a planificar y desplegar memecoins utilizando la planificación de tokenomics, la estrategia de lanzamiento y la configuración de la curva de vinculación, aprovechando el protocolo de blockchain de Solana y la estrategia de lanzamiento de Pump.fun.","fr":"Permet aux agents de planifier et de déployer des memecoins en utilisant la planification de la tokenomique, la stratégie de lancement et la configuration de la courbe de liaison, en exploitant le protocole de blockchain de Solana et la stratégie de lancement de Pump.fun.","de":"Ermöglicht es Agents, Memecoins zu planen und bereitzustellen, indem sie die Tokenomics-Planung, die Startstrategie und die Bonding-Kurven-Konfiguration nutzen und das Solana-Blockchain-Protokoll und die Pump.fun-Startstrategie ausschöpfen.","pt":"Habilita os agentes a planejarem e implantarem memecoins usando planejamento de tokenômica, estratégia de lançamento e configuração de curva de ligação, aproveitando o protocolo de blockchain do Solana e a estratégia de lançamento Pump.fun.","ru":"Наделяет агентов возможностью планировать и развертывать мемкоины, используя планирование токеномики, стратегию запуска и настройку кривой связывания, используя протокол блокчейна Solana и стратегию запуска Pump.fun.","ar":"يمنح الوكلاء القدرة على تخطيط و نشر ميمكوين باستخدام تخطيط التوكينومكس و استراتيجية الإطلاق و إعداد منحنى الربط، مستفيدا من بروتوكول سولانا للبلوكتشين و استراتيجية إطلاق بامب.فان."},"useCases":{"en":["Automating memecoin launch preparation with pre-launch checklists","Generating tokenomics plans for Solana-based projects","Deploying memecoins with optimized bonding curve configurations"],"zh":["使用预启动清单自动化memecoin启动准备","为Solana基于项目生成代币经济学计划","使用优化的债券曲线配置部署memecoins"],"ja":["立ち上げ前チェックリストを使用してメームコインの立ち上げ準備を自動化する","ソラナベースのプロジェクトのためのトークノミクス計画を生成する","最適化されたボンディング曲線設定を使用してメームコインを展開する"],"ko":["프리런치 체크리스트를 사용하여 메임코인 런치 준비를 자동화","솔라나 기반 프로젝트를 위한 토큰 эконом학 계획 생성","최적화된 본딩 곡선 구성으로 메임코인 배포"],"es":["Automatización de la preparación del lanzamiento de memecoin con listas de verificación previas al lanzamiento","Generación de planes de tokenomics para proyectos basados en Solana","Implementación de memecoins con configuraciones de curvas de vinculación optimizadas"],"fr":["Automatisation de la préparation du lancement de memecoin avec des listes de vérification préalables au lancement","Génération de plans de tokenomique pour les projets basés sur Solana","Déploiement de memecoins avec des configurations de courbes de liaison optimisées"],"de":["Automatisierung der Vorbereitung von Memecoin-Starts mit Checklisten vor dem Start","Erstellung von Tokenomics-Plänen für auf Solana basierende Projekte","Bereitstellung von Memecoins mit optimierten Bonding-Kurven-Konfigurationen"],"pt":["Automatizar a preparação para o lançamento de memecoin com listas de verificação pré-lançamento","Gerar planos de tokenômica para projetos baseados em Solana","Implantar memecoins com configurações de curva de ligação otimizadas"],"ru":["Автоматизировать подготовку к запуску мемкоинов с помощью предварительных чек-листов","Генерировать планы токеномики для проектов на основе Solana","Развертывать мемкоины с оптимизированными настройками кривой связывания"],"ar":["تأتمتة استعداد إطلاق ميمكوين مع قوائم التحقق قبل الإطلاق","توليد خطط التوكينومكس للمشاريع المبنية على سولانا","نشر ميمكوين مع إعدادات منحنى الربط المُختزلة"]},"limitations":{"en":["Limited to Solana blockchain","Requires knowledge of tokenomics and launch strategies","Dependent on Pump.fun launch strategy and bonding curve setup"],"zh":["仅限于Solana区块链","需要代币经济学和启动策略的知识","依赖于Pump.fun启动策略和债券曲线设置"],"ja":["ソラナのブロックチェーンに限定される","トークノミクスと立ち上げ戦略の知識が必要","Pump.funの立ち上げ戦略とボンディング曲線設定に依存する"],"ko":["솔라나 블록체인에만 제한됨","토큰 경제학 및 런치 전략에 대한 지식이 필요","펌프.펀의 런치 전략 및 본딩 곡선 설정에 의존"],"es":["Limitado a la blockchain de Solana","Requiere conocimiento de tokenomics y estrategias de lanzamiento","Dependiente de la estrategia de lanzamiento de Pump.fun y la configuración de la curva de vinculación"],"fr":["Limité au blockchain de Solana","Nécessite des connaissances en tokenomique et en stratégies de lancement","Dépendant de la stratégie de lancement de Pump.fun et de la configuration de la courbe de liaison"],"de":["Begrenzt auf die Solana-Blockchain","Benötigt Kenntnisse über Tokenomics und Startstrategien","Abhängig von der Startstrategie von Pump.fun und der Bonding-Kurven-Konfiguration"],"pt":["Limitado à blockchain do Solana","Exige conhecimento de tokenômica e estratégias de lançamento","Dependente da estratégia de lançamento Pump.fun e configuração da curva de ligação"],"ru":["Ограничен блокчейном Solana","Требует знания токеномики и стратегий запуска","Зависит от стратегии запуска Pump.fun и настройки кривой связывания"],"ar":["محدود ببلوكتشين سولانا","يتطلب معرفة بالتوقنومكس و استراتيجيات الإطلاق","يعتمد على استراتيجية إطلاق بامب.فان و إعداد منحنى الربط"]},"version":4},"contentHash":"c1a07788b888ce1f2c04735d1e5c27467a4e2e653b141b0f5e1e66adb1916c1f","qualityScore":60}');
