INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dreamineering/meme-times/meme-launcher', 'meme-launcher', 'dreamineering', 'meme-times', 'community', 'meme-launcher dreamineering meme-times community The meme-launcher skill provides end-to-end memecoin launch planning and execution for Solana, benefiting developers and project creators. It offers features like launch strategy and tokenomics planning. Meme Launcher 是一个用于 Solana 的 Memecoin 发布系统，提供从概念到部署的端到端解决方案。它包括 Tokenomics、Pump.fun 发布策略和 Bonding Curve 设置等功能。 Meme Launcher は、Solana 向けの Memecoin 発売システムで、コンセプトからデプロイまでを網羅したエンドツーエンドのソリューションを提供します。トークノミクス、Pump.fun 発売戦略、ボンディングカーブ設定などを含みます - AIエージェント Meme Launcher는 Solana 용 Memecoin 출시 시스템으로, 개념에서 배포까지 종단에서 종단까지 솔루션을 제공합니다. 토큰 경제학, Pump.fun 출시 전략, Bonding Curve 설정 등을 포함합니다 - AI 도구 Meme Launcher es un sistema de lanzamiento de memecoin para Solana que cubre desde la planificación hasta la ejecución. Ofrece funcionalidades como tokenomics y configuración de curvas de vinculación. Meme Launcher est un système de lancement de memecoin pour Solana qui couvre la planification à l''exécution. Il offre des fonctionnalités telles que la tokenomique et la configuration des courbes de liaison. Meme Launcher ist ein Memecoin-Startsystem für Solana, das von der Planung bis zur Ausführung reicht. Es bietet Funktionalitäten wie Tokenomics und Bonding-Kurven-Konfiguration. O Meme Launcher é um sistema de lançamento de memecoins na Solana, oferecendo planejamento e execução de lançamento de conceito a implantação. Meme Launcher - это система запуска мемекойнов на Solana, предоставляющая планирование и выполнение запуска от концепции до развертывания. Meme Launcher هو نظام لإطلاق العملات الرمزية على Solana، يقدم التخطيط والتنفيذ لإطلاق العملات الرمزية من концепتها إلى نشرها. how to use meme-launcher meme-launcher setup guide Solana memecoin launch tokenomics for memecoins pump.fun launch strategy meme-launcher alternative meme-launcher vs other launch systems meme-launcher install meme-launcher documentation Meme Launcher Solana Memecoin Tokenomics Pump.fun Bonding Curve Memecoin 发布 Solana 平台 AI 工具 Memecoin 代币创建 Launches memecoins on the Solana platform Provides tokenomics planning and execution Supports pump.fun launch strategies Enables bonding curve setup for memecoins Offers pre-launch checklist and deployment planning Builds hype for memecoins with targeted marketing strategies meme-launcher is a Solana memecoin launch system that enables end-to-end planning and execution for memecoin projects, covering concept to deployment and beyond.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brenordv/rust-pad/rust', 'community', 'brenordv', 'rust-pad', 'brenordv/rust-pad', 'rust', 0, 0, 60, '2026-03-01T06:29:36Z', '2026-03-07T03:42:00.011Z', '41978aba0c2aee8024cd61d0e035bc0f4ff7f661a0f966772d154428608b04cb', '{"id":"brenordv/rust-pad/rust","name":"rust","description":{"en":"Rust is a cross-platform Notepad inspired by Notepad++, designed for developers to efficiently manage notes and code. It benefits developers seeking a unified note-taking experience across platforms","zh":"Rust 跨平台记事本开发框架，提供 GUI 设计和开发指南","ja":"Rust を使用した AIエージェントの GUI 設計と開発","ko":"Rust 개발을 위한 노트패드++ 연동 도구의 기능과 사용법","es":"Rust es un lenguaje de programación que permite crear aplicaciones de escritorio cross-plataforma con una interfaz gráfica de usuario inspirada en Notepad++","fr":"Rust est un langage de programmation qui permet de créer des applications de bureau cross-plateforme avec une interface graphique utilisateur inspirée de Notepad++","de":"Rust ist eine Programmiersprache, die die Erstellung von cross-plattformfähigen Desktop-Anwendungen mit einer grafischen Benutzeroberfläche ermöglicht, die von Notepad++ inspiriert ist","pt":"O Rust é uma linguagem de programação que permite desenvolver aplicações de notas cross-plataforma inspiradas no Notepad++","ru":"Rust - язык программирования, который позволяет разработчикам создавать кроссплатформенные приложения для заметок, вдохновленные Notepad++","ar":"الرست هي لغة برمجة تمكن المطورين من إنشاء تطبيقات ملاحظات متعددة المنصات مستوحاة من Notepad++"},"seo":{"title":{"en":"Rust: Cross-Platform Notepad Setup Guide | AI Agent Skill","zh":"Rust Setup Guide: 跨平台记事本开发","ja":"Rust を使用した AIエージェントの GUI 設計","ko":"Rust 개발 가이드: 노트패드++ 연동 도구","es":"Guía de configuración de Rust para desarrolladores","fr":"Guide de mise en route de Rust pour les développeurs","de":"Rust-Setup-Anleitung