INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brenordv/rust-pad/rust', 'rust', 'brenordv', 'rust-pad', 'community', 'rust brenordv rust-pad community gui notebook notepad notepad-plus-plus notes tools Rust is a cross-platform Notepad inspired by Notepad++, designed for developers to efficiently manage notes and code. It benefits developers seeking a unified note-taking experience across platforms Rust 跨平台记事本开发框架，提供 GUI 设计和开发指南 Rust を使用した AIエージェントの GUI 設計と開発 Rust 개발을 위한 노트패드++ 연동 도구의 기능과 사용법 Rust es un lenguaje de programación que permite crear aplicaciones de escritorio cross-plataforma con una interfaz gráfica de usuario inspirada en Notepad++ Rust est un langage de programmation qui permet de créer des applications de bureau cross-plateforme avec une interface graphique utilisateur inspirée de Notepad++ Rust ist eine Programmiersprache, die die Erstellung von cross-plattformfähigen Desktop-Anwendungen mit einer grafischen Benutzeroberfläche ermöglicht, die von Notepad++ inspiriert ist O Rust é uma linguagem de programação que permite desenvolver aplicações de notas cross-plataforma inspiradas no Notepad++ Rust - язык программирования, который позволяет разработчикам создавать кроссплатформенные приложения для заметок, вдохновленные Notepad++ الرست هي لغة برمجة تمكن المطورين من إنشاء تطبيقات ملاحظات متعددة المنصات مستوحاة من Notepad++ how to use rust for notepad rust alternative to notepad++ rust vs notepad++ rust setup guide for developers what is rust programming language rust install for cross-platform development rust gui development best practices rust notepad inspired application rust cross-platform notepad setup Rust 跨平台开发 GUI 设计 Notepad++ 功能 AIエージェント开发 Rust 编程 跨平台记事本 Utilizes GUI design principles for cross-platform compatibility Follows Rust-specific design principles for efficient development Performs planning and analysis before code implementation Reviews existing codebase for conventions and utilities Identifies platform-specific constraints for targeted GUI work Considers edge cases within reason for robust application development Rust is a cross-platform Notepad application inspired by Notepad++, designed for efficient note management and development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NikGor/image-prompt-optimizer/openrouter-research', 'community', 'NikGor', 'image-prompt-optimizer', 'NikGor/image-prompt-optimizer', 'openrouter-research', 0, 0, 60, '2026-02-25T18:39:05Z', '2026-03-07T03:43:04.503Z', 'bf4c05c7f57402aafad31fe5e1b5fbed139f6f58114fdbbe9c67725f76ec816f', '{"id":"NikGor/image-prompt-optimizer/openrouter-research","name":"openrouter-research","description":{"en":"openrouter-research analyzes OpenRouter API specifications and Grok model availability for SFUMATO, benefiting developers who use text LLM calls through app/tools/openrouter_tool.py.","zh":"OpenRouter Research 是一个基于 AI 的研究工具，用于研究 OpenRouter API 和 Grok 模型的可用性","ja":"OpenRouter Research は、OpenRouter API と Grok モデルの可用性を研究するための AI エージェントです","ko":"OpenRouter Research는 OpenRouter API 및 Grok 모델의 가용성을 연구하기 위한 AI 도구입니다","es":"openrouter-research es una habilidad para investigar las especificaciones de la API de OpenRouter y la disponibilidad del modelo Grok para SFUMATO","fr":"openrouter-research est une compétence pour rechercher les spécifications de l''API OpenRouter et la disponibilité du modèle Grok pour SFUMATO","de":"openrouter-research ist eine Fähigkeit, um die Spezifikationen der OpenRouter-API und die Verfügbarkeit des Grok-Modells für SFUMATO zu untersuchen","pt":"O OpenRouter Research é uma ferramenta para pesquisa de especificações da API OpenRouter e disponibilidade do modelo Grok para SFUMATO","ru":"OpenRouter Research - это инструмент для изучения спецификаций API OpenRouter и доступности модели Grok для SFUMATO и разработки ИИ Агентов","ar":"OpenRouter Research هو أداة لبحث مواصفات واجهة برمجة التطبيقات OpenRouter وتوفر نموذج Grok لمنصة SFUMATO وتطوير أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"openrouter-research: API Research Setup Guide | AI Agent ...","zh":"OpenRouter Research 设置指南 - 基于 AI 的 API 研究","j