INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NikGor/image-prompt-optimizer/openrouter-research', 'openrouter-research', 'NikGor', 'image-prompt-optimizer', 'community', 'openrouter-research NikGor image-prompt-optimizer community openrouter-research analyzes OpenRouter API specifications and Grok model availability for SFUMATO, benefiting developers who use text LLM calls through app/tools/openrouter_tool.py. OpenRouter Research 是一个基于 AI 的研究工具，用于研究 OpenRouter API 和 Grok 模型的可用性 OpenRouter Research は、OpenRouter API と Grok モデルの可用性を研究するための AI エージェントです OpenRouter Research는 OpenRouter API 및 Grok 모델의 가용성을 연구하기 위한 AI 도구입니다 openrouter-research es una habilidad para investigar las especificaciones de la API de OpenRouter y la disponibilidad del modelo Grok para SFUMATO openrouter-research est une compétence pour rechercher les spécifications de l''API OpenRouter et la disponibilité du modèle Grok pour SFUMATO openrouter-research ist eine Fähigkeit, um die Spezifikationen der OpenRouter-API und die Verfügbarkeit des Grok-Modells für SFUMATO zu untersuchen O OpenRouter Research é uma ferramenta para pesquisa de especificações da API OpenRouter e disponibilidade do modelo Grok para SFUMATO OpenRouter Research - это инструмент для изучения спецификаций API OpenRouter и доступности модели Grok для SFUMATO и разработки ИИ Агентов OpenRouter Research هو أداة لبحث مواصفات واجهة برمجة التطبيقات OpenRouter وتوفر نموذج Grok لمنصة SFUMATO وتطوير أدوات الذكاء الاصطناعي how to use openrouter-research openrouter-research setup guide openrouter-research alternative openrouter-research vs api.ai openrouter-research install what is openrouter-research openrouter-research api specifications openrouter-research grok model availability OpenRouter Research AI 研究工具 OpenRouter API Grok 模型 httpx.A ENV vars 文本分析 视觉分析 Researches OpenRouter API specifications for SFUMATO Analyzes Grok model availability through app/tools/openrouter_tool.py Utilizes ENV vars: OPENROUTER_API_KEY and OPENROUTER_BASE_URL Employs httpx.A client for API interactions Supports text-only input through prompt_service.generate_prompt() and prompt_service.revise_prompt() Enables Grok with vision through judge_service.evaluate() for image analysis openrouter-research is a skill that researches current OpenRouter API specifications and Grok model availability for SFUMATO.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kslhunter/simplysm/sd-review', 'community', 'kslhunter', 'simplysm', 'kslhunter/simplysm', 'sd-review', 0, 0, 60, '2026-03-06T06:23:00.208Z', '2026-03-06T08:18:17.358Z', 'f3b02d9addf9c7944adf601db5be8d333be58fbc8d9c2bfd0db1e436fb6155a2', '{"id":"kslhunter/simplysm/sd-review","name":"sd-review","description":{"en":"The sd-review skill provides comprehensive code analysis for developers, combining defect review and refactoring analysis. It dispatches up to 5 reviewer agents in parallel for efficient code verification","zh":"sd-review是一种代码分析工具，提供正确性、安全性和结构简化的检查和优化建议。它可以并行运行多个代码检查代理，并生成统一的报告。","ja":"sd-reviewは、コードレビューとリファクタリング分析を組み合わせたコード分析ツールです。並列処理により、複数のコードチェックエージェントを実行し、統一されたレポートを生成します。","ko":"sd-review는 코드의 오류를 검사하고 구조를 개선하는 코드 분석 도구입니다. 여러 코드 검사 에이전트를 병렬로 실행하여 통합 보고서를 생성합니다.","es":"sd-review es una herramienta de análisis de código que combina revisión de defectos y análisis de refactorización para mejorar la calidad del código","fr":"sd-review est un outil d''analyse de code qui combine la révision des défauts et l''analyse de refactorisation pour améliorer la qualité du code","de":"sd-review ist ein Code-Analyse-Tool, das Defekt- und Refactoring-Analysen kombiniert, um die Code-Qualität zu verbessern","pt":"O sd-review é uma ferramenta de análise de código que combina revisão de defeitos e refatoração, fornecendo um relatório unificado","ru":"ИИ Агент sd-review - это инструмент комплексного обзора кода, объединяющий проверку дефектов и рефакторинг, и предоставляющий единый отчет","ar":"وحدة sd-review هي أداة لتحليل الكود التي تجمع بين استعراض العيوب وإعادة الهيكلة، وتقدم تقريرًا موحدًا"},"seo":{"title":{"en":"sd-review: Comprehensive Code Analysis Setup Guide | AI A...","zh":"sd-review 代码分析工具：正确性和结构优化指南","ja":"sd-review AIエージェント：コードレビューとリファクタリング分析のベストプラクティス","ko":"sd-review 코드 분석 도구: 오류 검사 및 리팩토링 가이드","es":"Guía de Configuración de sd-review: Análisis de Código In...","fr":"Guide de Configuration de sd-review : Analyse de Code Com...","de":"Einrichtungsleitfaden für sd-review: Umfassende Code-Analyse","pt":"Guia de Configuração do sd-review: Análise de Código Avan...","ru":"Настройка ИИ Агента sd-review: Комплексный Обзор Код","ar":"دليل إعداد sd-review: تحليل شاملة للكود"},"description":{"en":"Unlock the full potential of sd-review with our expert guide. Discover how to harness parallel code review and refactoring analysis for streamlined development","zh":"sd-review 代码分析工具提供了综合的代码检查和优化建议，包括正确性、安全性和结构简化。了解如何使用sd-review提高代码质量。","ja":"sd-review AIエージェントは、コードレビューとリファクタリング分析を組み合わせたコード分析ツールです。コード品質の向上に役立つsd-reviewの使い方を学びましょう。","ko":"sd-review 코드 분석 도구는 코드의 오류를 검사하고 구조를 개선하여 코드 품질을 향상시킵니다. sd-review를 사용하여 코드를 최적화하는 방법을 알아보세요.","es":"Descubre cómo sd-review realiza un análisis de código integral, combinando revisión de defectos y análisis de refactorización para mejorar la calidad del código","fr":"Découvrez comment sd-review effectue une analyse de code complète, combinant la révision des défauts et l''analyse de refactorisation pour améliorer la qualit...","de":"Erfahren Sie, wie sd-review eine umfassende Code-Analyse durchführt, indem es Defekt- und Refactoring-Analysen kombiniert, um die Code-Qualität zu verbessern","pt":"Aprenda a configurar o sd-review para análise de código avançada, incluindo revisão de defeitos e refatoração","ru":"Узнайте, как настроить ИИ Агент sd-review для комплексного обзора кода, включая проверку дефектов и рефакторинг","ar":"تعلم كيفية إعداد sd-review لتحليل الكود الشامل، بما في ذلك استعراض العيوب وإعادة الهيكلة"},"definition":{"en":"sd-review is a code analysis skill that combines defect review and refactoring analysis for comprehensive code evaluation","zh":"sd-review是一种代码分析工具，用于检查代码的正确性、安全性和结构，并提供优化建议。","ja":"sd-reviewは、コードの正しさ、安全性、構造を分析し、最適化提案を提供するコード分析ツールです。","ko":"sd-review는 코드의 오류를 검사하고 구조를 개선하여 코드 품질을 향상시키는 코드 분석 도구입니다.","es":"sd-review es una herramienta de análisis de código que realiza una revisión integral de defectos y estructura del código","fr":"sd-review est un outil d''analyse de code qui effectue une révision complète des défauts et de la structure du code","de":"sd-review ist ein Code-Analyse-Tool, das eine umfassende Überprüfung von Fehlern und Code-Struktur durchführt","pt":"O sd-review é uma ferramenta de análise de código que executa revisão de defeitos e refatoração","ru":"ИИ Агент sd-review - это инструмент обзора кода, выполняющий проверку дефектов и рефакторинг","ar":"وحدة sd-review هي أداة لتحليل الكود التي تنفذ استعراض العيوب وإعادة الهيكلة"},"features":{"en":["Combines defect review and refactoring analysis for comprehensive code evaluation","Dispatches up to 5 reviewer agents in parallel for efficient code verification","Verifies findings against actual code for accurate results","Compiles a unified report for streamlined code review","Performs analysis only, with no code modifications"],"zh":["并行运行多个代码检查代理","代码正确性、安全性和结构简化的检查","统一的代码分析报告","支持多种代码检查和优化建议","无代码修改的分析"],"ja":["複数のコードチェックエージェントの並列処理","コードの正しさ、安全性、構造の分析","統一されたコード分析レポート","複数のコードチェックと最適化提案のサポート","コード修正不要の分析"],"ko":["여러 코드 검사 에이전트의 병렬 실행","코드의 오류 검사와 구조 개선","통합된 코드 분석 보고서","다양한 코드 검사와 최적화 제안의 지원","코드 수정 없이 분석"],"es":["Análisis de defectos y refactorización en paralelo","Verificación de resultados contra el código real","Informes unificados y detallados","Análisis de la estructura y simplificación del código","Revisión de API y convenciones de código"],"fr":["Analyse des défauts et de la refactorisation en parallèle","Vérification des résultats contre le code réel","Rapports unifiés et détaillés","Analyse de la structure et de la simplification du code","Révision de l''API et des conventions de code"],"de":["Fehler- und Refactoring-Analyse in Parallelschritten","Überprüfung der Ergebnisse gegen den tatsächlichen Code","Einheitliche und detaillierte Berichte","Analyse der Code-Struktur und -Vereinfachung","Überprüfung von API und Code-Konventionen"],"pt":["Revisão de defeitos e segurança","Análise de API e convenções","Refatoração de estrutura e simplificação","Dispatch de até 5 agentes de revisão em paralelo","Verificação de achados contra código real"],"ru":["Проверка дефектов и безопасности","Анализ API и конвенций","Рефакторинг структуры и упрощение","Запуск до 5 агентов проверки в параллели","Проверка результатов против реального кода"],"ar":["استعراض العيوب والأمان","تحليل واجهة برمجة التطبيقات والاتفاقيات","إعادة هيكلة البنية وتبسيطها","إرسال ما يصل إلى 5 وكلاء استعراض بالتوازي","التحقق من النتائج مقابل الكود الفعلي"]},"keywords":{"en":["how to use sd-review","sd-review alternative","sd-review setup guide","what is sd-review","sd-review vs code review tools","sd-review install","comprehensive code analysis","parallel code review","refactoring analysis"],"zh":["代码分析工具","代码检查","代码优化","代码安全性","代码结构简化","sd-review","代码质量","代码 review","代码 refactor"],"ja":["コード分析ツール","コードチェック","コード最適化","コードセキュリティ","コード構造最適化","sd-review","コード品質","コードレビュー","コードリファクタリング"],"ko":["코드 분석 도구","코드 검사","코드 최적화","코드 보안","코드 구조 개선","sd-review","코드 품질","코드 리뷰","코드 리팩토링"],"es":["herramientas de análisis de código","sd-review","análisis de defectos","refactorización de código","mejora de la calidad del código","informes de análisis de código","análisis de código integral"],"fr":["outils d''analyse de code","sd-review","analyse des défauts","refactorisation de code","amélioration de la qualité du code","rapports d''analyse de code","analyse de code complète"],"de":["Code-Analyse-Tools","sd-review","Fehler-Analyse","Code-Refactoring","Code-Qualitätsverbesserung","Code-Analyse-Berichte","umfassende Code-Analyse"],"pt":["sd-review","análise de código","revisão de defeitos","refatoração","ferramenta de análise de código","desenvolvimento de software","qualidade de código"],"ru":["ИИ Агент sd-review","обзор кода","проверка дефектов","рефакторинг","инструмент обзора кода","разработка программного обеспечения","качество кода"],"ar":["وحدة sd-review","تحليل الكود","استعراض العيوب","إعادة الهيكلة","أداة تحليل الكود","تطوير البرمجيات","جودة الكود"]}},"owner":"kslhunter","repo":"simplysm","repoPath":"kslhunter/simplysm","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.208Z","topics":[],"category":"community","skillMd":{"name":"sd-review","description":"Use when the user explicitly requests code review, refactoring analysis, or structural improvement. Covers correctness, safety, API design, conventions, complexity, duplication, and code structure. Explicit invocation only.","bodyPreview":"# sd-review\n\n## Overview\n\nComprehensive code analysis combining **defect review** (correctness, safety, API, conventions) and **refactoring analysis** (structure, simplification). Dispatches up to 5 reviewer agents in parallel, verifies findings against actual code, and compiles a unified report.\n\n**Analysis only — no code modifications.**\n\n## Principles\n\n- **Breaking changes are irrelevant**: Reviewers must NOT dismiss, soften, or deprioritize findings because the suggested fix would cause a br","body":"# sd-review\n\n## Overview\n\nComprehensive code analysis combining **defect review** (correctness, safety, API, conventions) and **refactoring analysis** (structure, simplification). Dispatches up to 5 reviewer agents in parallel, verifies findings against actual code, and compiles a unified report.\n\n**Analysis only — no code modifications.**\n\n## Principles\n\n- **Breaking changes are irrelevant**: Reviewers must NOT dismiss, soften, or deprioritize findings because the suggested fix would cause a breaking change. Correctness, safety, usability, architecture, and maintainability always take priority over API stability. If something is wrong, report it — regardless of breaking change impact.\n\n## Usage\n\n- `/sd-review packages/solid` — full review (all perspectives)\n- `/sd-review packages/solid focus on bugs` — selective review based on request\n- `/sd-review packages/solid focus on refactoring` — structural analysis only\n- `/sd-review` — if no argument, ask the user for the target path\n\n## Target Selection\n\n- With argument: review source code at the given path\n- Without argument: ask the user for the target path\n\n**Important:** Review ALL source files under the target path. Do not use git status or git diff to limit scope.\n\n## Reviewer Perspectives\n\n| Reviewer | Prompt Template | Perspective |\n|----------|----------------|-------------|\n| **Code Reviewer** | `code-reviewer-prompt.md` | Correctness & Safety — bugs, security, logic errors, architectural defects (circular deps, boundary violations) |\n| **API Reviewer** | `api-reviewer-prompt.md` | Usability & DX — naming, types, consistency |\n| **Convention Checker** | `convention-checker-prompt.md` | Project rules — Grep-based systematic check against convention files (prohibited patterns, naming rules, export rules) |\n| **Code Simplifier** | `code-simplifier-prompt.md` | Simplification — complexity, duplication, readability |\n| **Structure Analyzer** | `structure-analyzer-prompt.md` | Organization — responsibility separation, abstraction levels, module structure |\n\n## Reviewer Selection\n\nBy default, run **all 5 reviewers**. If the user specifies a focus in natural language, select only the relevant reviewer(s):\n\n| User says | Run |\n|-----------|-----|\n| \"bugs\", \"security\", \"safety\", \"architecture\", \"dependencies\", \"boundaries\" | Code Reviewer only |\n| \"API\", \"naming\", \"types\", \"DX\" | API Reviewer only |\n| \"conventions\", \"rules\", \"patterns\" | Convention Checker only |\n| \"simplify\", \"complexity\", \"duplication\", \"readability\" | Code Simplifier only |\n| \"structure\", \"responsibility\", \"module\", \"organization\", \"abstraction\" | Structure Analyzer only |\n| \"defects\", \"correctness\" | Code + API + Convention |\n| \"refactoring\", \"refactor\", \"maintainability\" | Simplifier + Structure |\n| (no specific focus) | All 5 |\n\nUse judgment for ambiguous requests.\n\n## Workflow\n\n### Step 1: Dispatch Reviewers\n\nRead the prompt template files from this skill''s directory. Replace `[TARGET_PATH]` with the actual target path. Then dispatch using `Agent(general-purpose)`:\n\n```\nAgent(subagent_type=general-purpose, prompt=<filled template>)\n```\n\nRun selected reviewers **in parallel** (multiple Agent calls in a single message).\n\n### Step 2: Verify Findings\n\nAfter collecting results from all reviewers, **Read the actual code** for each finding and verify.\n\n**For defect findings (Code, API, Convention reviewers):**\n\n- **Valid**: the issue is real AND within scope → include in the report\n- **Invalid — self-contradicted**: the reviewer''s own analysis shows the issue is mitigated (e.g., \"exploitability is limited because...\"). Drop it.\n- **Invalid — type-only**: reports a type definition as a runtime issue without showing actual runtime code that triggers it. Drop it.\n- **Invalid — out of scope**: the issue is about code outside the target path (e.g., how other packages use this code). Drop it.\n- **Invalid — duplicate**: another reviewer already reported the same issue. Keep only the one from the correct domain.\n- **Invalid — bikeshedding**: minor style preference on stable, well-commented code (magic numbers with clear comments, small interface field duplication, naming when used consistently). Drop it.\n- **Invalid — severity inflated**: downgrade or drop findings where the stated severity doesn''t match the actual impact.\n- **Invalid — already handled**: handled elsewhere in the codebase (provide evidence)\n- **Invalid — intentional pattern**: by-design architectural decision\n- **Invalid — misread**: the reviewer misinterpreted the code\n\n**For refactoring findings (Simplifier, Structure reviewers):**\n\n**Check 1 — Scope**:\n- Is this about code structure? Not bugs, conventions, documentation, or performance → if not, drop (out of scope)\n- Is the issue within the target path? → if not, drop (out of target)\n- Already reported by another reviewer? → keep the better-scoped one (duplicate)\n- Minor style preference with no real structural impact? → drop (bikeshedding)\n\n**Check 2 — Duplication reality** (for duplication findings):\n- Count actual duplicated lines. If < 30 lines total, drop — not worth extracting.\n- Compare side by side. If the \"duplicates\" have meaningful behavioral differences (different guards, parameters, error handling), drop — not true duplication.\n- Check if \"similar types\" are an intentional Input/Normalized pattern (optional props → required internal def with defaults applied, `children` → `cell` rename). If yes, drop — by design.\n\n**Check 3 — Separation benefit** (for \"too big\", \"mixed responsibilities\", \"mixed abstraction\" findings):\n- Is the piece proposed for extraction < ~150 lines AND directly depends on the rest of the file (renders, calls, or shares state)? If yes, drop — splitting adds overhead without benefit.\n- Do all the abstractions serve a single cohesive domain concept (all functions called from one entry point, all types used together)? If yes, drop — it''s cohesion, not mixing.\n- Would a realistic consumer reuse the extracted piece independently? If no, drop.\n\n**Check 4 — Not by design**: Is this an established pattern used consistently across the codebase? (Provider+Component, Factory+Product, Input/Output types) If yes, drop.\n\n### Step 3: Invalid Findings Report\n\nPresent only the **filtered findings** to the user:\n\n```\n## Review: <target-path>\n\n### Invalid Findings\n[findings filtered out — grouped by rejection reason]\n```\n\nIf there are **no valid findings**, report that the review found no actionable issues and end.\n\n### Step 4: User Confirmation\n\nPresent each verified finding to the user **one at a time**, ordered by severity (CRITICAL → WARNING → INFO → HIGH → MEDIUM → LOW).\n\nFor each finding, explain:\n1. **What the problem is** — the current code behavior and why it''s an issue\n2. **How it could be fixed** — possible solution approaches (if multiple exist, list them briefly)\n3. **Ask**: address this or skip?\n\nCollect only findings the user confirms. If the user skips all findings, report that and end.\n\n### Step 5: Brainstorm Handoff\n\nPass only the **user-confirmed findings** to **sd-brainstorm**.\n\nEach finding includes: **source reviewer**, **file:line**, **evidence**, **issue**, and **suggestion**.\n\nsd-brainstorm will handle prioritization, grouping, approach exploration, and design.\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Using git diff to limit review scope | Review ALL source files under target path |\n| Skipping verification step | Always verify reviewer findings against actual code |\n| Reporting unverified issues | Only include verified findings in final report |\n| Running all reviewers for focused requests | Match reviewer selection to user''s request |\n| Reporting bugs as refactoring | Ask: \"Is the behavior wrong?\" If yes → defect, not refactoring |\n| Reporting style as refactoring | Ask: \"Is this structural?\" If no → lint, not refactoring |\n| Presenting valid findings as final report | Valid findings must be confirmed by user, then handed off to sd-brainstorm |\n| Dumping all findings at once for user confirmation | Present findings one at a time with problem explanation and solution approaches |\n\n## Completion Criteria\n\nReport invalid findings, then hand off all valid findings to sd-brainstorm. No code modifications during review.\n"},"lastSynced":"2026-03-06T08:18:17.358Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing comprehensive defect and refactoring analysis capabilities.","zh":"非常适合需要全面缺陷和重构分析能力的代码审查代理。","ja":"コードレビュー代理が包括的な欠陥およびリファクタリング分析機能を必要とする場合に最適です。","ko":"전면적인 결함 및 리팩토링 분석 기능이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de análisis de defectos y refactorización comprehensivos.","fr":"Parfait pour les Agents de Révision de Code nécessitant des capacités d''analyse de défauts et de réorganisation complètes.","de":"Perfekt für Code-Review-Agents, die umfassende Defekt- und Refactoring-Analysefunktionen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades de análise de defeitos e refatoração abrangentes.","ru":"Идеально подходит для Агентов Обзора Кодов, которым необходимы комплексные возможности анализа дефектов и рефакторинга.","ar":"مثالي للوكلاء المراجعين للكود الذين يحتاجون إلى قدرات تحليل شاملة للعيوب وإعادة الهيكلة."},"recommendation":{"en":"Empowers agents to perform parallel code verification using up to 5 reviewer agents, analyzing correctness, safety, API conventions, and structure, while compiling unified reports in defect review and refactoring analysis, all without modifying the code.","zh":"使代理能够使用多达5个审查代理并行验证代码，分析正确性、安全性、API约定和结构，同时编译统一的缺陷审查和重构分析报告，而无需修改代码。","ja":"エージェントが最大5つのレビューエージェントを使用してコードの並列検証を実行できるようにし、正しさ、安全性、API規約、構造を分析し、コードを変更せずに統一された報告書をコンパイルします。","ko":"에이전트가 최대 5개의 리뷰 에이전트를 사용하여 코드의 병렬 검증을 수행할 수 있도록 하며, 올바름, 안전성, API 규약, 구조를 분석하고 코드를 수정하지 않고 통일된 보고서를 컴파일합니다.","es":"Habilita a los agentes a realizar una verificación de código paralela utilizando hasta 5 agentes revisores, analizando la corrección, la seguridad, las convenciones de API y la estructura, mientras compila informes unificados en revisión de defectos y análisis de refactorización, todo sin modificar el código.","fr":"Permet aux agents d''effectuer une vérification de code parallèle en utilisant jusqu''à 5 agents réviseurs, analysant la correction, la sécurité, les conventions d''API et la structure, tout en compilant des rapports unifiés en revue de défauts et en analyse de réorganisation, le tout sans modifier le code.","de":"Ermächtigt die Agenten, eine parallele Code-Verifizierung mit bis zu 5 Überprüfungsagenten durchzuführen, wobei die Richtigkeit, Sicherheit, API-Konventionen und Struktur analysiert werden, während einheitliche Berichte zur Defektüberprüfung und Refactoring-Analyse erstellt werden, alles ohne den Code zu modifizieren.","pt":"Habilita os agentes a realizar verificação de código paralela usando até 5 agentes revisores, analisando a correção, a segurança, as convenções da API e a estrutura, enquanto compila relatórios unificados em revisão de defeitos e análise de refatoração, tudo sem modificar o código.","ru":"Наделяет агентов возможностью выполнять параллельную верификацию кода с использованием до 5 агентов-ревьюеров, анализируя правильность, безопасность, соглашения API и структуру, при этом составляя объединенные отчеты по проверке дефектов и анализу рефакторинга, все это без изменения кода.","ar":"يتمكّن الوكلاء من أداء التحقق الموازي للكود باستخدام ما يصل إلى 5 وكلاء مراجعة، وتحليل الصحة والأمان وأعراف API والهيكل، أثناء تجميع تقارير موحدة في مراجعة العيوب وتحليل إعادة الهيكلة، كل ذلك دون تعديل الكود."},"useCases":{"en":["Automating code defect reviews","Generating refactoring suggestions","Verifying API conventions","Analyzing code structure for simplification"],"zh":["自动化代码缺陷审查","生成重构建议","验证API约定","分析代码结构以简化"],"ja":["コード欠陥レビューの自動化","リファクタリングの提案の生成","API規約の検証","コード構造の分析による簡素化"],"ko":["코드 결함 리뷰의 자동화","리팩토링 제안의 생성","API 규약의 검증","코드 구조의 분석을 통한 단순화"],"es":["Automatización de revisiones de defectos de código","Generación de sugerencias de refactorización","Verificación de convenciones de API","Análisis de la estructura del código para simplificación"],"fr":["Automatisation des revues de défauts de code","Génération de suggestions de réorganisation","Vérification des conventions d''API","Analyse de la structure du code pour simplification"],"de":["Automatisierung von Code-Defekt-Überprüfungen","Generierung von Refactoring-Vorschlägen","Überprüfung von API-Konventionen","Analyse der Code-Struktur für Vereinfachung"],"pt":["Automizar revisões de defeitos de código","Gerar sugestões de refatoração","Verificar convenções de API","Analizar estrutura de código para simplificação"],"ru":["Автоматизировать обзор дефектов кода","Генерировать предложения по рефакторингу","Проверять соглашения API","Анализировать структуру кода для упрощения"],"ar":["تأتميم مراجعة عيوب الكود","توليد اقتراحات لإعادة الهيكلة","التحقق من أعراف API","تحليل هيكل الكود من أجل التبسيط"]},"limitations":{"en":["Analysis only, no code modifications","Requires multiple reviewer agents for parallel verification"],"zh":["仅分析，不修改代码","需要多个审查代理进行并行验证"],"ja":["分析のみ、コードの変更はなし","並列検証には複数のレビューエージェントが必要"],"ko":["분석만 수행하고 코드를 수정하지 않음","병렬 검증을 위해서는 여러 리뷰 에이전트가 필요"],"es":["Análisis solo, sin modificaciones de código","Requiere varios agentes revisores para verificación paralela"],"fr":["Analyse uniquement, sans modification de code","Nécessite plusieurs agents réviseurs pour vérification parallèle"],"de":["Nur Analyse, keine Code-Modifikationen","Benötigt mehrere Überprüfungsagenten für parallele Verifizierung"],"pt":["Análise apenas, sem modificações de código","Requer vários agentes revisores para verificação paralela"],"ru":["Только анализ, без изменений кода","Требует нескольких агентов-ревьюеров для параллельной верификации"],"ar":["تحليل فقط، بدون تعديلات على الكود","يتطلب وكلاء مراجعة متعددين للتحقق الموازي"]},"version":4},"contentHash":"f3b02d9addf9c7944adf601db5be8d333be58fbc8d9c2bfd0db1e436fb6155a2","qualityScore":60}');
