INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kslhunter/simplysm/sd-review', 'sd-review', 'kslhunter', 'simplysm', 'community', 'sd-review kslhunter simplysm community The sd-review skill provides comprehensive code analysis for developers, combining defect review and refactoring analysis. It dispatches up to 5 reviewer agents in parallel for efficient code verification sd-review是一种代码分析工具，提供正确性、安全性和结构简化的检查和优化建议。它可以并行运行多个代码检查代理，并生成统一的报告。 sd-reviewは、コードレビューとリファクタリング分析を組み合わせたコード分析ツールです。並列処理により、複数のコードチェックエージェントを実行し、統一されたレポートを生成します。 sd-review는 코드의 오류를 검사하고 구조를 개선하는 코드 분석 도구입니다. 여러 코드 검사 에이전트를 병렬로 실행하여 통합 보고서를 생성합니다. sd-review es una herramienta de análisis de código que combina revisión de defectos y análisis de refactorización para mejorar la calidad del código sd-review est un outil d''analyse de code qui combine la révision des défauts et l''analyse de refactorisation pour améliorer la qualité du code sd-review ist ein Code-Analyse-Tool, das Defekt- und Refactoring-Analysen kombiniert, um die Code-Qualität zu verbessern O sd-review é uma ferramenta de análise de código que combina revisão de defeitos e refatoração, fornecendo um relatório unificado ИИ Агент sd-review - это инструмент комплексного обзора кода, объединяющий проверку дефектов и рефакторинг, и предоставляющий единый отчет وحدة sd-review هي أداة لتحليل الكود التي تجمع بين استعراض العيوب وإعادة الهيكلة، وتقدم تقريرًا موحدًا how to use sd-review sd-review alternative sd-review setup guide what is sd-review sd-review vs code review tools sd-review install comprehensive code analysis parallel code review refactoring analysis 代码分析工具 代码检查 代码优化 代码安全性 代码结构简化 sd-review 代码质量 代码 review 代码 refactor Combines defect review and refactoring analysis for comprehensive code evaluation Dispatches up to 5 reviewer agents in parallel for efficient code verification Verifies findings against actual code for accurate results Compiles a unified report for streamlined code review Performs analysis only, with no code modifications sd-review is a code analysis skill that combines defect review and refactoring analysis for comprehensive code evaluation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ColdstartLabs-ca/myimageupscaler.com/seo-manager', 'community', 'ColdstartLabs-ca', 'myimageupscaler.com', 'ColdstartLabs-ca/myimageupscaler.com', 'seo-manager', 0, 0, 60, '2026-03-06T17:50:19Z', '2026-03-07T03:46:24.191Z', '0311b2df994dfe7c49387b9523f81faaa8f676a0d56d3286c4d7df0b51eadfbd', '{"id":"ColdstartLabs-ca/myimageupscaler.com/seo-manager","name":"seo-manager","description":{"en":"The seo-manager skill orchestrates SEO audits in parallel waves, collecting results and producing a unified health report based on real Google Search Console (GSC) data, benefiting developers and SEO specialists.","zh":"SEO Manager是一种使用GSC数据优化网站的工具，能够实时监测网站性能和搜索引擎排名","ja":"SEO Managerは、AIエージェントとGSCデータを使用して検索エンジン最適化を実現するツールです","ko":"SEO Manager는 GSC 데이터를 사용하여 웹사이트를 최적화하고 검색 엔진 순위를 향상시키는 도구입니다","es":"El SEO Manager es un orquestador de auditorías que recopila resultados y produce informes de salud unificados con datos de GSC","fr":"Le SEO Manager est un orchestrateur d''audits qui collecte les résultats et produit des rapports de santé unifiés avec des données de GSC","de":"Der SEO Manager ist ein Orchestrierer von Audits, der Ergebnisse sammelt und einheitliche Gesundheitsberichte mit GSC-Daten erstellt","pt":"O seo-manager é um orquestrador de auditoria de SEO que coleta resultados de auditorias paralelas e produz relatórios de saúde unificados com base em dados reais do GSC.","ru":"ИИ Агент seo-manager оркестрирует аудит SEO, собирает результаты и производит единый отчет о здоровье на основе реальных данных GSC.","ar":"seo-manager هو منسق لتحليل أداء محركات البحث الذي يجمع نتائج التحليلات المتوازية ويصدّر تقارير صحية موحدة مستندة إلى بيانات حقيقية من GSC."},"seo":{"title":{"en":"seo-manager: Unified SEO Audit Orchestration | AI Agent S...","zh":"SEO Manager Setup Guide: 使用GSC数据优化网站","ja":"SEO Managerの設定方法: AIエージェントを使用した検索エンジン最適化","ko":"SEO Manager 설정 가이드: GSC 데이터를 활용한 웹사이트 최적화","es":"Guía de configuración de SEO Manager: Orquestación de aud...","fr":"Guide de mise en place de SEO Manager : Orchestration des...","de":"Einrichtungsleitfaden für SEO Manager: Orchestrierung von...","pt":"Guia de Configuração do seo-manager: Orquestrador de Audi...","ru":"ИИ Агенты: Руководство по настройке seo-manager для оркес...","ar":"دليل إعداد seo-manager: منسق تحليل أداء محركات البحث"},"description":{"en":"Discover how seo-manager streamlines SEO audits with parallel waves and real GSC data - get started with setup guide and best practices","zh":"了解SEO Manager的功能和设置方法，使用GSC数据优化您的网站，提高搜索引擎排名","ja":"SEO Managerを使用して、AIエージェントとGSCデータを活用した検索エンジン最適化を実現します","ko":"SEO Manager를 사용하여 GSC 데이터를 활용한 웹사이트 최적화와 검색 엔진 순위 향상을 실현하세요","es":"Aprende a configurar el SEO Manager para orquestar auditorías en paralelo y generar informes de salud unificados con datos de GSC","fr":"Découvrez comment configurer le SEO Manager pour orchestrer des audits en parallèle et générer des rapports de santé unifiés avec des données de GSC","de":"Erfahren Sie, wie Sie den SEO Manager einrichten, um Audits parallel zu orchestrieren und einheitliche Gesundheitsberichte mit GSC-Daten zu erstellen","pt":"Aprenda a configurar o seo-manager para orquestrar auditorias de SEO em paralelo e obter relatórios de saúde unificados com base em dados reais do GSC.","ru":"Узнайте, как настроить seo-manager для оркестровки аудита SEO и получения единого отчета о здоровье на основе реальных данных GSC.","ar":"تعلم كيفية إعداد seo-manager لتنسيق تحليلات أداء محركات البحث وتحصل على تقارير صحية موحدة مستندة إلى بيانات حقيقية من GSC."},"definition":{"en":"seo-manager is a skill that automates SEO audit orchestration, leveraging GSC data to provide actionable insights and recommendations","zh":"SEO Manager是一种使用GSC数据优化网站的工具","ja":"SEO Managerは、検索エンジン最適化を実現するAIエージェントの一種です","ko":"SEO Manager는 웹사이트를 최적화하는 도구로 GSC 데이터를 사용합니다","es":"El SEO Manager es una herramienta de Inteligencia Artificial que orquesta auditorías de SEO en paralelo","fr":"Le SEO Manager est un outil d''Intelligence Artificielle qui orchestre des audits de SEO en parallèle","de":"Der SEO Manager ist ein Tool für künstliche Intelligenz, das SEO-Audits parallel orchestriert","pt":"O seo-manager é um agente de IA que orquestra auditorias de SEO em paralelo para produzir relatórios de saúde unificados.","ru":"ИИ Агент seo-manager - это оркестратор аудита SEO, который производит единый отчет о здоровье на основе реальных данных GSC.","ar":"seo-manager هو एजنت ذكاء اصطناعي ينسق تحليلات أداء محركات البحث بشكل موازي لإنتاج تقارير صحية موحدة."},"features":{"en":["Orchestrates SEO audits in parallel waves for efficient analysis","Collects results and produces a unified health report grounded in real GSC data","References real search data from Google Search Console (GSC) for accurate recommendations","Stops audit if GSC fetch fails to ensure data integrity","Supports audit-only mode, never invoking action skills like blog-edit or blog-publish"],"zh":["使用GSC数据优化网站","实时监测网站性能和搜索引擎排名","支持并行波式审计","能够停止无效的审计任务","提供统一的健康报告","支持多种技术如React和Python"],"ja":["GSCデータを使用した検索エンジン最適化","リアルタイムのウェブサイト性能と検索エンジンランキングの監視","並行波式の監査をサポート","無効な監査タスクを停止","統一されたヘルスリポートを提供","ReactやPythonなどの複数の技術をサポート"],"ko":["GSC 데이터를 사용한 웹사이트 최적화","실시간 웹사이트 성능과 검색 엔진 순위 모니터링","병렬波식 감사를 지원","무효한 감사 작업을 중지","통합된 헬스 리포트를 제공","React와 Python 등의 여러 기술을 지원"],"es":["Orquestación de auditorías en paralelo","Recopilación de resultados de auditorías","Generación de informes de salud unificados con datos de GSC","Integración con datos de búsqueda en tiempo real","Compatibilidad con tecnologías de desarrollo como React y Python"],"fr":["Orchestration d''audits en parallèle","Collecte de résultats d''audits","Génération de rapports de santé unifiés avec des données de GSC","Intégration avec des données de recherche en temps réel","Compatibilité avec des technologies de développement comme React et Python"],"de":["Orchestrierung von Audits in Parallelverarbeitung","Sammeln von Audit-Ergebnissen","Erstellung einheitlicher Gesundheitsberichte mit GSC-Daten","Integration mit Echtzeit-Suchdaten","Kompatibilität mit Entwicklungstechnologien wie React und Python"],"pt":["Orquestração de auditorias de SEO em paralelo","Coleta de resultados de auditorias","Produção de relatórios de saúde unificados com base em dados reais do GSC","Integração com o Google Search Console (GSC)","Paralisação em caso de falha no fetch do GSC"],"ru":["Оркестровка аудита SEO в параллельном режиме","Сбор результатов аудита","Производство единого отчета о здоровье на основе реальных данных GSC","Интеграция с Google Search Console (GSC)","Остановка в случае неудачи при получении данных GSC"],"ar":["تنسيق تحليلات أداء محركات البحث بشكل موازي","جمع نتائج التحليلات","إصدار تقارير صحية موحدة مستندة إلى بيانات حقيقية من GSC","التكامل مع واجهة بحث جوجل (GSC)","التوقف في حالة فشل الحصول على بيانات GSC"]},"keywords":{"en":["how to use seo-manager","seo-manager setup guide","seo-manager vs ahrefs","seo-manager alternative to semrush","what is seo-manager","seo-manager install","seo-manager best practices","seo-manager for AI agents","seo-manager GSC integration"],"zh":["SEO Manager","GSC数据","网站优化","搜索引擎排名","AIエージェント","React","Python","并行波式审计","网站性能监测"],"ja":["SEO Manager","GSCデータ","検索エンジン最適化","ウェブサイト性能","AIエージェント","React","Python","並行波式の監査","検索エンジンランキング"],"ko":["SEO Manager","GSC 데이터","웹사이트 최적화","검색 엔진 순위","AI 에이전트","React","Python","병렬波식 감사","웹사이트 성능 모니터링"],"es":["SEO Manager","orquestación de auditorías","informes de salud unificados","GSC","Inteligencia Artificial","herramientas de SEO","auditorías de SEO","desarrollo web","React","Python"],"fr":["SEO Manager","orchestration d''audits","rapports de santé unifiés","GSC","Intelligence Artificielle","outils de SEO","audits de SEO","développement web","React","Python"],"de":["SEO Manager","Orchestrierung von Audits","einheitliche Gesundheitsberichte","GSC","künstliche Intelligenz","SEO-Tools","SEO-Audits","Webentwicklung","React","Python"],"pt":["seo-manager","orquestrador de auditoria de SEO","relatórios de saúde unificados","dados reais do GSC","Google Search Console","auditoria de SEO em paralelo","otimização de SEO","ferramentas de SEO"],"ru":["ИИ Агенты","seo-manager","оркестратор аудита SEO","единый отчет о здоровье","реальные данные GSC","Google Search Console","аудит SEO в параллельном режиме","оптимизация SEO","инструменты SEO"],"ar":["إجنتات الذكاء الاصطناعي","seo-manager","منسق تحليل أداء محركات البحث","تقارير صحية موحدة","بيانات حقيقية من GSC","واجهة بحث جوجل","تحليل أداء محركات البحث بشكل موازي","تحسين أداء محركات البحث","أدوات تحسين أداء محركات البحث"]}},"owner":"ColdstartLabs-ca","repo":"myimageupscaler.com","repoPath":"ColdstartLabs-ca/myimageupscaler.com","stars":0,"forks":0,"updatedAt":"2026-03-06T17:50:19Z","topics":[],"category":"community","skillMd":{"name":"seo-manager","description":"Orchestrate all SEO audit skills in parallel waves and produce a unified health report. Use when asked for full SEO audit, SEO health check, comprehensive SEO report, SEO manager, run all SEO checks, or SEO status.","bodyPreview":"# SEO Manager Orchestrator\n\nYou are the **SEO Manager** for convertbanktoexcel.com. Your job: orchestrate all SEO audit skills in parallel waves, collect results, and produce a unified health report grounded in real GSC data.\n\nWhen this skill activates: `SEO Manager: Initializing audit orchestration...`\n\n---\n\n## Principles\n\n1. **GSC is ground truth** - All recommendations must reference real search data. If GSC fetch fails, STOP.\n2. **Audit only** - NEVER invoke action skills (blog-edit, blog-pu","body":"# SEO Manager Orchestrator\n\nYou are the **SEO Manager** for convertbanktoexcel.com. Your job: orchestrate all SEO audit skills in parallel waves, collect results, and produce a unified health report grounded in real GSC data.\n\nWhen this skill activates: `SEO Manager: Initializing audit orchestration...`\n\n---\n\n## Principles\n\n1. **GSC is ground truth** - All recommendations must reference real search data. If GSC fetch fails, STOP.\n2. **Audit only** - NEVER invoke action skills (blog-edit, blog-publish, ai-image-generation). Report findings, don''t fix them.\n3. **Maximize parallelism** - Launch independent tasks in the SAME message using multiple Task tool calls.\n4. **Each skill = unique angle** - No redundant re-checks across skills.\n5. **Graceful degradation** - If a non-GSC skill fails, mark as \"N/A\" and continue. Only GSC failure is a hard stop.\n\n---\n\n## Input / Arguments\n\nParse optional arguments from user input:\n\n| Argument                | Default                          | Description                                                           |\n| ----------------------- | -------------------------------- | --------------------------------------------------------------------- |\n| `--competitor=<domain>` | _(not run)_                      | Enable competitor sitemap analysis for this domain                    |\n| `--url=<url>`           | `https://convertbanktoexcel.com` | URL for PageSpeed and SquirrelScan audits                             |\n| `--skip=<skills>`       | _(none)_                         | Comma-separated skills to skip (e.g., `blog-audit,backlink-analyzer`) |\n| `--include-strategy`    | _(not run)_                      | Include keyword research & content strategy analysis                  |\n\n---\n\n## Execution Pipeline\n\n### Step 1: Initialize\n\n1. Parse arguments\n2. Check for prior reports: `ls docs/SEO/reports/seo-report-*.md` - read the most recent one for trend comparison\n3. Create the output directory if needed: `mkdir -p docs/SEO/reports`\n4. Display the execution plan to the user:\n\n```\nSEO Manager: Audit Plan\n========================\nTarget: <url>\nCompetitor: <domain or \"skipped\">\nSkipping: <skills or \"none\">\nStrategy: <\"included\" if --include-strategy, otherwise \"skipped\">\n\nWave 1 (Data Collection):  GSC fetch, PageSpeed, SquirrelScan\nWave 2 (Analysis):         SEO review, Blog audit, Schema, AI Search, Internal Linking, Backlinks [, Competitor] [, Keyword Strategy]\nWave 3 (Synthesis):        Score, merge, write report\n\nEstimated time: 10-20 minutes (add +5min if --include-strategy)\n```\n\n5. Use TaskCreate to create tracking tasks for each wave.\n\n---\n\n### Step 2: Wave 1 - Data Collection\n\nLaunch **3 parallel Task tool calls in a single message** (skip any in `--skip` list):\n\n#### Task 1: GSC Data Fetch\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Fetch Google Search Console data for convertbanktoexcel.com.\n\n  Run this command:\n  npx tsx scripts/gsc-direct-fetch.ts\n\n  Then read the output JSON from docs/SEO/gsc-exports/ (most recent file).\n\n  Return a structured summary with EXACTLY these sections:\n  - Indexing: submitted count, indexed count, index rate percentage\n  - Performance (90d): total clicks, total impressions, avg CTR, avg position\n  - Top 20 queries: query, position, impressions, clicks, CTR (as a table)\n  - Low-hanging fruit: keywords with position 4-20 and impressions > 10\n  - Top 10 pages by clicks\n  - Device breakdown\n  - Country breakdown (top 5)\n\n  If the script fails, report the exact error message.\n```\n\n#### Task 2: PageSpeed Audit\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Run a Lighthouse PageSpeed audit on <URL>.\n\n  Invoke the /pagespeed skill with URL: <URL>\n\n  Return a structured summary with:\n  - Scores table: Performance, SEO, Accessibility, Best Practices (mobile + desktop)\n  - Lab data: FCP, LCP, TBT, CLS, Speed Index, TTI, TTFB (mobile + desktop)\n  - Top 5 performance opportunities with estimated savings\n  - Any SEO-specific failures\n  - Any accessibility failures\n\n  Save the full report to docs/SEO/audits/pagespeed-report-YYYY-MM-DD.md\n```\n\n#### Task 3: SquirrelScan Audit\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Run a SquirrelScan website audit on <URL>.\n\n  Execute:\n  squirrel audit <URL> --format llm -C surface\n\n  Return a structured summary with:\n  - Overall health score (0-100)\n  - Issues by severity: critical count, high count, medium count, low count\n  - Top issues by category (SEO, technical, content, security, schema, links)\n  - Broken links found (if any)\n  - Schema markup findings\n\n  If squirrel is not installed, report this and skip.\n```\n\n---\n\n### Step 3: Wave 1 Checkpoint\n\nAfter all Wave 1 tasks return:\n\n1. **Check GSC result** - If GSC failed, STOP and display the error. Help the user troubleshoot:\n   - Check credentials: `ls -la ./cloud/keys/coldstart-labs-service-account-key.json`\n   - Check script: `npx tsx scripts/gsc-direct-fetch.ts --help`\n   - Do NOT proceed without GSC data.\n\n2. **Parse GSC data** - Extract the key metrics to inject into Wave 2 prompts:\n   - `GSC_SUMMARY`: indexing status + performance summary (5-8 lines)\n   - `GSC_TOP_QUERIES`: top 20 queries table\n   - `GSC_LOW_HANGING_FRUIT`: low-hanging fruit keywords\n   - `GSC_TOP_PAGES`: top 10 pages by clicks\n\n3. **Note PageSpeed/SquirrelScan status** - If either failed, mark as \"N/A\" but continue.\n\n4. Update task statuses.\n\n---\n\n### Step 4: Wave 2 - Domain Analysis\n\nLaunch **5-7 parallel Task tool calls in a single message** (skip any in `--skip` list).\n\nEvery Wave 2 prompt MUST include the GSC context block:\n\n```\n## GSC Ground Truth (use this to ground your analysis)\n<paste GSC_SUMMARY>\n<paste GSC_TOP_QUERIES>\n<paste GSC_LOW_HANGING_FRUIT>\n<paste GSC_TOP_PAGES>\n```\n\n#### Task A: SEO Expert Review\n\n```\nsubagent_type: seo-auditor\nprompt: |\n  You are an SEO expert reviewing convertbanktoexcel.com (SaaS tool for converting bank statements to Excel/CSV).\n\n  <GSC context block>\n\n  <SquirrelScan summary if available, otherwise \"SquirrelScan: N/A\">\n\n  Your job: Review on-page SEO and content quality for the TOP 10 PAGES from GSC data.\n  Focus ONLY on what SquirrelScan does NOT cover:\n  - Content depth and search intent match\n  - E-E-A-T signals (expertise, experience, authority, trust)\n  - Keyword targeting effectiveness (are titles/H1s aligned with GSC queries?)\n  - Content gaps (GSC shows impressions but poor CTR - why?)\n  - User experience signals\n\n  For each page reviewed, reference its GSC metrics (position, impressions, CTR).\n\n  Return a structured summary:\n  - Pages reviewed (count)\n  - Key on-page findings (table: page, issue, severity, GSC context)\n  - E-E-A-T assessment (1 paragraph)\n  - Content gap opportunities (list with GSC data citations)\n  - Score: 0-100 for on-page SEO quality\n```\n\n#### Task B: Blog Audit\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Audit all published blog posts on convertbanktoexcel.com for quality and SEO compliance.\n  This is REPORT-ONLY mode - do NOT fix anything, do NOT invoke blog-edit.\n\n  <GSC context block>\n\n  Step 1: Authenticate\n  PASSWORD=$(gcloud secrets versions access latest --secret=convertbanktoexcel-blog-admin-password --project=coldstartlabs-auth)\n  TOKEN=$(curl -s -X POST \"https://api.convertbanktoexcel.com/auth/login\" \\\n    -H \"Content-Type: application/json\" \\\n    -d \"{\\\"email\\\":\\\"motherai@opus.com\\\",\\\"password\\\":\\\"$PASSWORD\\\"}\" \\\n    | jq -r ''.session.access_token'')\n\n  Step 2: Fetch all posts\n  ALL_POSTS=$(curl -s \"https://api.convertbanktoexcel.com/blog/admin/posts?limit=200\" \\\n    -H \"Authorization: Bearer $TOKEN\")\n\n  Step 3: For each post, check:\n  - Thin content (< 300 words = CRITICAL)\n  - Title length (30-60 chars required)\n  - Excerpt length (100-160 chars required)\n  - H1 count (exactly 1 required)\n  - CTA presence (must have hyperlinked CTAs to https://convertbanktoexcel.com)\n  - AI vocabulary (delve, tapestry, nuanced, multifaceted, pivotal, landscape, testament, myriad)\n  - Keyword cannibalization across posts\n\n  Step 4: Cross-reference with GSC low-hanging fruit - are blog posts targeting these keywords?\n\n  Return a structured summary:\n  - Total posts audited\n  - Issues by severity: critical, high, medium, low (counts)\n  - Top 10 worst posts (table: slug, word count, issues found, severity)\n  - Cannibalization pairs (if any)\n  - AI writing detection results\n  - Blog posts targeting GSC low-hanging fruit keywords (or gaps)\n  - Score: 0-100 for blog health\n\n  If authentication fails, report the error and return score as \"N/A\".\n```\n\n#### Task C: Schema Markup Review\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Review structured data / schema markup on convertbanktoexcel.com.\n\n  <GSC context block>\n\n  <SquirrelScan schema findings if available>\n\n  Check the following pages for JSON-LD schema:\n  1. Homepage (https://convertbanktoexcel.com) - expect: Organization, SoftwareApplication, WebSite\n  2. Pricing page (/pricing) - expect: Product or Offer\n  3. Blog posts (check 3 posts) - expect: Article, BreadcrumbList\n  4. Bank-specific pages (check 2 from GSC top pages) - expect: FAQPage, BreadcrumbList, SoftwareApplication\n  5. Format pages (check 2) - expect: HowTo or FAQPage\n\n  For each page, use WebFetch to check the HTML source for JSON-LD scripts.\n\n  Return a structured summary:\n  - Pages checked (count)\n  - Schema types found (table: page, schemas present, schemas missing)\n  - Validation issues (malformed JSON-LD, missing required fields)\n  - Rich result eligibility (which pages qualify for which rich results)\n  - Priority additions (which schemas would have highest impact)\n  - Score: 0-100 for structured data coverage\n```\n\n#### Task D: AI Search Optimization Review\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Review convertbanktoexcel.com for AI search engine visibility (AEO/GEO).\n\n  <GSC context block>\n\n  Check the following:\n\n  1. robots.txt AI bot access - fetch https://convertbanktoexcel.com/robots.txt\n     - Is GPTBot blocked or allowed?\n     - Is ClaudeBot blocked or allowed?\n     - Is PerplexityBot blocked or allowed?\n     - Is Google-Extended blocked or allowed?\n\n  2. llms.txt presence - check https://convertbanktoexcel.com/llms.txt and /llms-full.txt\n     - Does it exist?\n     - Is it well-structured?\n\n  3. Content citability - check 3 key pages from GSC top queries:\n     - Does content use inverted pyramid (answer first)?\n     - Are there clear definitions/explanations AI can extract?\n     - Is content structured with semantic HTML (lists, tables, headings)?\n     - Are there FAQ sections?\n\n  4. E-E-A-T signals for AI\n     - Author credentials visible?\n     - Dates and freshness signals?\n     - Authoritative sources cited?\n\n  Return a structured summary:\n  - AI bot access status (table: bot, status)\n  - llms.txt status\n  - Content citability score per page checked\n  - AEO readiness checklist (items checked vs passed)\n  - Priority recommendations\n  - Score: 0-100 for AI search readiness\n```\n\n#### Task E: Internal Linking Analysis\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Analyze internal linking structure of convertbanktoexcel.com.\n\n  <GSC context block>\n\n  Step 1: Fetch the sitemap\n  Use WebFetch to get https://convertbanktoexcel.com/sitemap.xml\n  Parse the URL list.\n\n  Step 2: Categorize pages by type:\n  - Homepage, Tool/App pages, Bank-specific pSEO pages, Format pSEO pages, Blog posts, Static pages\n\n  Step 3: Check 5 high-value pages from GSC top pages:\n  - How many internal links point TO this page? (check from homepage, nav, footer, blog posts)\n  - How many internal links does this page have going OUT?\n  - Is the anchor text descriptive and keyword-relevant?\n\n  Step 4: Check for orphan pages:\n  - Are there sitemap URLs that might have zero or minimal internal links?\n\n  Step 5: Topic cluster assessment:\n  - Do bank pages link to related format pages and vice versa?\n  - Do blog posts link to relevant tool/pSEO pages?\n  - Is there a hub-and-spoke linking pattern?\n\n  Return a structured summary:\n  - Total pages in sitemap\n  - Pages checked in detail (count)\n  - Internal link distribution (table: page, inbound links, outbound links)\n  - Orphan page candidates\n  - Topic cluster gaps\n  - Anchor text quality assessment\n  - Priority linking opportunities (with GSC data: \"Link to /banks/chase from blog - it has 450 impressions at position 12\")\n  - Score: 0-100 for internal linking health\n```\n\n#### Task F: Backlink Analysis\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Analyze the backlink profile of convertbanktoexcel.com.\n\n  <GSC context block>\n\n  Since we may not have Ahrefs/Semrush API access, use available data:\n\n  1. Check if docs/SEO/ contains any Ahrefs or backlink export files (CSV/JSON)\n  2. Use WebFetch to check common backlink checker tools if available\n  3. Reference any domain authority metrics from prior reports in docs/SEO/audits/\n\n  Based on available data, assess:\n  - Total known backlinks and referring domains\n  - Domain authority / Domain Rating\n  - Link quality distribution (editorial vs directory vs social vs spam)\n  - Anchor text distribution\n  - Top referring domains\n\n  Cross-reference with GSC data:\n  - Pages with high impressions but low CTR might benefit from backlink authority boost\n  - Pages ranking 4-20 that need link equity to push into top 3\n\n  Return a structured summary:\n  - Profile overview (backlinks, referring domains, DR/DA)\n  - Link quality assessment\n  - Competitor link gap (if prior competitor reports exist in docs/SEO/)\n  - High-priority pages needing backlinks (from GSC low-hanging fruit)\n  - Link building opportunity types\n  - Score: 0-100 for backlink profile health (or \"N/A - Limited data\" if no backlink data found)\n```\n\n#### Task G: Competitor Sitemap Spy (ONLY if --competitor provided)\n\n```\nsubagent_type: seo-competitor-analyzer\nprompt: |\n  Analyze competitor <COMPETITOR_DOMAIN> SEO strategy via their sitemap.\n\n  <GSC context block>\n\n  Invoke the /competitor-sitemap-spy skill for domain: <COMPETITOR_DOMAIN>\n\n  Return a structured summary:\n  - Total pages found\n  - Page categories (table: category, count, percentage)\n  - pSEO patterns identified\n  - Content gaps (they have, we don''t)\n  - Our advantages (we have, they don''t)\n  - Top 5 quick-win opportunities\n  - Score: 0-100 for competitive position\n```\n\n#### Task H: Keyword Research & Strategy (ONLY if --include-strategy provided)\n\n```\nsubagent_type: general-purpose\nprompt: |\n  Generate a keyword research strategy and content roadmap for convertbanktoexcel.com.\n\n  <GSC context block>\n\n  Invoke the /keyword-research-strategy skill with focus on easy wins:\n  /keyword-research-strategy --focus=easy-wins --competition=low --limit=15\n\n  The skill will:\n  1. Analyze GSC data + Ahrefs snapshots (if available)\n  2. Classify search intent for all keywords\n  3. Map keywords to existing/proposed pages\n  4. Identify content gaps and intent mismatches\n  5. Generate prioritized content roadmap\n\n  Return a structured summary with EXACTLY these sections:\n  - Total keywords analyzed\n  - Opportunity breakdown by segment:\n    - Quick Wins (position 4-20, easy push)\n    - Content Gaps (high potential, no page)\n    - Long-Tail Clusters (group related keywords)\n    - Intent Mismatches (wrong page ranks)\n  - Top 5 immediate priorities (keyword, segment, impact, effort)\n  - Total potential monthly clicks if roadmap implemented\n  - Link to full roadmap file in docs/SEO/keyword-strategy-roadmap-YYYY-MM-DD.md\n\n  Cross-reference with GSC low-hanging fruit to ensure alignment.\n\n  If the skill fails or no Ahrefs data found, note limitation but include GSC-only analysis.\n```\n\n---\n\n### Step 5: Wave 2 Checkpoint\n\nAfter all Wave 2 tasks return:\n\n1. Collect all structured summaries\n2. Note which skills succeeded and which returned \"N/A\"\n3. Update task statuses\n\n---\n\n### Step 6: Wave 3 - Synthesis\n\nThis runs in the main thread (no subagents).\n\n#### 6a: Compute Health Scores\n\nExtract the score from each skill''s summary. Calculate weighted overall score:\n\n| Dimension                | Weight | Source                                                                                |\n| ------------------------ | ------ | ------------------------------------------------------------------------------------- |\n| Technical SEO            | 20%    | SquirrelScan health score                                                             |\n| Core Web Vitals          | 15%    | PageSpeed performance score (mobile 60% + desktop 40%)                                |\n| On-Page SEO              | 15%    | SEO expert review score                                                               |\n| Content / Blog           | 10%    | Blog audit score                                                                      |\n| Schema / Structured Data | 5%     | Schema markup review score                                                            |\n| Internal Linking         | 10%    | Internal linking analysis score                                                       |\n| Backlinks                | 10%    | Backlink analysis score                                                               |\n| AI Search Readiness      | 5%     | AI search optimization score                                                          |\n| GSC Performance          | 10%    | Composite: (index_rate _ 0.3) + (normalized_position _ 0.4) + (normalized_ctr \\* 0.3) |\n\nFor N/A dimensions: redistribute their weight proportionally across available dimensions.\n\nPosition normalization: `score = max(0, 100 - (avg_position - 1) * 1.5)`\nCTR normalization: `score = min(100, avg_ctr * 1000)`\n\n#### 6b: Trend Comparison\n\nIf a prior report exists in `docs/SEO/reports/`:\n\n- Compare overall score: up/down/stable\n- Compare each dimension score\n- Note significant changes (> 5 point swing)\n\nUse arrows: `[+5]` for improvement, `[-3]` for decline, `[=]` for stable\n\n#### 6c: Assemble Report\n\nWrite the unified report to `docs/SEO/reports/seo-report-YYYY-MM-DD.md` using this template:\n\n```markdown\n# SEO Health Report - convertbanktoexcel.com\n\n**Date:** YYYY-MM-DD\n**Auditor:** SEO Manager Orchestrator\n**URL:** <url>\n**Skills Used:** <list of skills that ran successfully>\n**Skills Skipped/Failed:** <list with reasons>\n**Duration:** ~XX minutes\n\n---\n\n## Executive Summary\n\n### Overall SEO Health Score: XX/100 [trend]\n\n| Dimension           | Score  | Weight | Trend   | Key Finding |\n| ------------------- | ------ | ------ | ------- | ----------- |\n| Technical SEO       | XX/100 | 20%    | [trend] | ...         |\n| Core Web Vitals     | XX/100 | 15%    | [trend] | ...         |\n| On-Page SEO         | XX/100 | 15%    | [trend] | ...         |\n| Content / Blog      | XX/100 | 10%    | [trend] | ...         |\n| Schema              | XX/100 | 5%     | [trend] | ...         |\n| Internal Linking    | XX/100 | 10%    | [trend] | ...         |\n| Backlinks           | XX/100 | 10%    | [trend] | ...         |\n| AI Search Readiness | XX/100 | 5%     | [trend] | ...         |\n| GSC Performance     | XX/100 | 10%    | [trend] | ...         |\n\n### Top 5 Priority Issues\n\n1. **[CRITICAL]** ... (GSC data: ...)\n2. **[HIGH]** ... (GSC data: ...)\n3. ...\n4. ...\n5. ...\n\n### Quick Wins (Impact vs Effort)\n\n1. ... (GSC: keyword X at position Y with Z impressions)\n2. ...\n3. ...\n\n---\n\n## 1. Google Search Console Performance\n\n[Paste GSC summary from Wave 1]\n\n---\n\n## 2. Core Web Vitals & Performance\n\n[Paste PageSpeed summary from Wave 1, or \"N/A - PageSpeed audit was skipped/failed\"]\n\n---\n\n## 3. Technical SEO\n\n[Paste SquirrelScan summary from Wave 1, or \"N/A\"]\n\n---\n\n## 4. On-Page SEO & Content Quality\n\n[Paste SEO expert review from Wave 2]\n\n---\n\n## 5. Blog Content Health\n\n[Paste blog audit summary from Wave 2, or \"N/A\"]\n\n---\n\n## 6. Structured Data & Schema Markup\n\n[Paste schema review from Wave 2, or \"N/A\"]\n\n---\n\n## 7. Internal Link Structure\n\n[Paste internal linking analysis from Wave 2, or \"N/A\"]\n\n---\n\n## 8. Backlink Profile\n\n[Paste backlink analysis from Wave 2, or \"N/A\"]\n\n---\n\n## 9. AI Search Readiness (AEO/GEO)\n\n[Paste AI search review from Wave 2, or \"N/A\"]\n\n---\n\n## 10. Competitive Intelligence\n\n[Paste competitor analysis from Wave 2, or \"Skipped - run with --competitor=<domain> to include\"]\n\n---\n\n## 11. Keyword Research & Content Strategy\n\n[Paste keyword strategy summary from Wave 2, or \"Skipped - run with --include-strategy to include\"]\n\n**Note:** For full keyword roadmap with detailed action plans, see: `docs/SEO/keyword-strategy-roadmap-YYYY-MM-DD.md`\n\n---\n\n## Prioritized Action Plan\n\n### Critical - This Week\n\n[Items referencing GSC data for each recommendation]\n\n### High Impact - This Month\n\n[Items referencing GSC data]\n\n### Medium - This Quarter\n\n[Items]\n\n### Ongoing Maintenance\n\n[Items]\n\n---\n\n## Methodology\n\n- **Data collection:** GSC API, Lighthouse (local), SquirrelScan CLI\n- **Analysis:** Expert review, blog API audit, schema validation, AI search checks, link analysis, backlink assessment\n- **Scoring:** Weighted average across 9 dimensions (weights reflect impact on organic growth)\n- **GSC grounding:** All recommendations cite specific keywords, pages, and metrics from Google Search Console\n```\n\n---\n\n### Step 7: Output Summary\n\nDisplay to the user:\n\n```\nSEO Manager: Audit Complete\n============================\nOverall Health Score: XX/100 [trend]\n\nDimension Scores:\n  Technical SEO:      XX/100\n  Core Web Vitals:    XX/100\n  On-Page SEO:        XX/100\n  Blog Health:        XX/100\n  Schema:             XX/100\n  Internal Linking:   XX/100\n  Backlinks:          XX/100\n  AI Search:          XX/100\n  GSC Performance:    XX/100\n\nTop 3 Issues:\n  1. [CRITICAL] ...\n  2. [HIGH] ...\n  3. [HIGH] ...\n\nReport saved to: docs/SEO/reports/seo-report-YYYY-MM-DD.md\n```\n\n---\n\n## Error Handling\n\n| Error                              | Action                                                              |\n| ---------------------------------- | ------------------------------------------------------------------- |\n| GSC script fails                   | **HARD STOP** - Display error, help troubleshoot credentials/script |\n| PageSpeed fails (Chrome not found) | Mark as N/A, note in report, continue                               |\n| SquirrelScan not installed         | Mark as N/A, note in report, continue                               |\n| Blog audit auth fails              | Mark as N/A, note in report, continue                               |\n| Any Wave 2 task fails              | Mark dimension as N/A, redistribute weight, continue                |\n| No prior report for trends         | Skip trend comparison, note \"First report\"                          |\n| Competitor domain invalid          | Skip competitor analysis, note in report                            |\n"},"lastSynced":"2026-03-07T03:46:24.191Z","agentAnalysis":{"suitability":{"en":"Perfect for SEO Specialist Agents needing comprehensive Google Search Console data analysis and unified health reporting.","zh":"非常适合需要对 Google Search Console 数据进行全面分析和统一健康报告的 SEO Specialist Agents。","ja":"Google Search Console のデータ分析と統一されたヘルスレポートが必要な SEO Specialist エージェントに最適です。","ko":"Google Search Console 데이터 분석과 통합 건강 보고서가 필요한 SEO Specialist 에이전트에게 적합합니다.","es":"Perfecto para Agentes Especialistas en SEO que necesitan un análisis de datos de Google Search Console integral y un informe de salud unificado.","fr":"Parfait pour les agents spécialistes en SEO ayant besoin d''une analyse de données de Google Search Console complète et d''un rapport de santé unifié.","de":"Perfekt für SEO-Spezialisten-Agenten, die eine umfassende Google Search Console-Datenanalyse und ein einheitliches Gesundheitsbericht benötigen.","pt":"Perfeito para Agentes Especialistas em SEO que necessitam de análise de dados abrangente do Google Search Console e relatórios de saúde unificados.","ru":"Идеально подходит для агентов-специалистов по SEO, которые нуждаются в комплексном анализе данных Google Search Console и унифицированных отчетах о состоянии здоровья.","ar":"مثالي لعمال الإختصاص في تحسين محركات البحث الذين يحتاجون إلى تحليل بيانات شامل لمكتب تحكم بحث جوجل وتقارير صحية موحدة."},"recommendation":{"en":"Empowers agents to orchestrate SEO audits in parallel waves, leveraging real Google Search Console (GSC) data for accurate health reports, and providing actionable recommendations grounded in actual search data, utilizing protocols like GSC API for data fetch.","zh":"赋予代理商能够同时进行 SEO 审计，利用实际的 Google Search Console (GSC) 数据来生成准确的健康报告，并提供基于实际搜索数据的可执行建议，使用诸如 GSC API 的协议来获取数据。","ja":"エージェントが SEO 監査を同時に実行できるようにし、実際の Google Search Console (GSC) データを使用して正確なヘルスレポートを生成し、実際の検索データに基づいた実行可能な推奨事項を提供し、GSC API などのプロトコルを使用してデータを取得します。","ko":"에이전트가 SEO 감사를 병렬로 수행할 수 있도록 하며 실제 Google Search Console (GSC) 데이터를 사용하여 정확한 건강 보고서를 생성하고 실제 검색 데이터에 기반한 실행 가능한 권장 사항을 제공하며 GSC API와 같은 프로토콜을 사용하여 데이터를 가져옵니다.","es":"Habilita a los agentes a orquestar auditorías de SEO en oleadas paralelas, aprovechando los datos reales de Google Search Console (GSC) para informes de salud precisos, y proporcionando recomendaciones accionables basadas en datos de búsqueda reales, utilizando protocolos como la API de GSC para la recuperación de datos.","fr":"Permet aux agents d''orchestrer des audits SEO en vagues parallèles, en exploitant les données réelles de Google Search Console (GSC) pour des rapports de santé précis, et en fournissant des recommandations actionnables ancrées dans les données de recherche réelles, en utilisant des protocoles comme l''API GSC pour la récupération de données.","de":"Ermächtigt Agenten, SEO-Audits in parallelen Wellen zu orchestrieren, indem sie echte Google Search Console (GSC)-Daten für genaue Gesundheitsberichte nutzen und handhabbare Empfehlungen bereitstellen, die auf tatsächlichen Suchdaten basieren, unter Verwendung von Protokollen wie der GSC-API für die Datenerfassung.","pt":"Permite que os agentes orquestram auditorias de SEO em ondas paralelas, utilizando dados reais do Google Search Console (GSC) para relatórios de saúde precisos e fornecendo recomendações viáveis baseadas em dados de busca reais, utilizando protocolos como a GSC API para buscar dados.","ru":"Позволяет агентам организовывать аудиты SEO параллельными волнами, используя реальные данные Google Search Console (GSC) для точных отчетов о состоянии здоровья и предоставляя действенные рекомендации, основанные на фактических данных поиска, используя протоколы, такие как GSC API, для извлечения данных.","ar":"تمكن العمال من تنسيق عمليات فحص لتحسين محركات البحث في موجات متوازية، مستخدمين بيانات مكتب تحكم بحث جوجل (GSC) الفعلية لتقارير صحية دقيقة، وتقديم توصيات قابلة للتنفيذ التي تستند إلى بيانات بحث حقيقية، باستخدام بروتوكولات مثل GSC API لاسترجاع البيانات."},"useCases":{"en":["Orchestrating parallel SEO audits","Generating unified health reports based on GSC data","Analyzing search data for optimization opportunities"],"zh":["同时进行 SEO 审计","基于 GSC 数据生成统一的健康报告","分析搜索数据以寻找优化机会"],"ja":["SEO 監査を同時に実行する","GSC データに基づいて統一されたヘルスレポートを生成する","検索データを分析して最適化の機会を探す"],"ko":["SEO 감사를 병렬로 수행한다","GSC 데이터를 기반으로 통합 건강 보고서를 생성한다","검색 데이터를 분석하여 최적화 기회를 찾는다"],"es":["Orquestar auditorías de SEO paralelas","Generar informes de salud unificados en función de los datos de GSC","Analizar datos de búsqueda para oportunidades de optimización"],"fr":["Orchestrer des audits SEO parallèles","Générer des rapports de santé unifiés basés sur les données de GSC","Analyser les données de recherche pour des opportunités d''optimisation"],"de":["Parallele SEO-Audits orchestrieren","Einheitliche Gesundheitsberichte auf Grundlage von GSC-Daten generieren","Suchdaten für Optimierungsmöglichkeiten analysieren"],"pt":["Orquestração de auditorias de SEO paralelas","Geração de relatórios de saúde unificados com base em dados do GSC","Análise de dados de busca para oportunidades de otimização"],"ru":["Организация параллельных аудитов SEO","Генерация унифицированных отчетов о состоянии здоровья на основе данных GSC","Анализ данных поиска для выявления возможностей оптимизации"],"ar":["تنسيق عمليات فحص لتحسين محركات البحث المتوازية","إنتاج تقارير صحية موحدة بالاعتماد على بيانات مكتب تحكم بحث جوجل","تحليل بيانات البحث لفرص تحسين"]},"limitations":{"en":["Requires successful GSC data fetch","Audit-only functionality, excluding action skills invocation"],"zh":["需要成功获取 GSC 数据","仅限审计功能，不包括操作技能的调用"],"ja":["GSC データの取得が成功する必要がある","監査のみの機能であり、操作スキルの呼び出しは除外される"],"ko":["GSC 데이터를 성공적으로 가져올 필요가 있다","감사 전용 기능으로 작업 스킬 호출은 제외된다"],"es":["Requiere una recuperación de datos de GSC exitosa","Funcionalidad de solo auditoría, excluyendo la invocación de habilidades de acción"],"fr":["Nécessite une récupération de données GSC réussie","Fonctionnalité d''audit uniquement, excluant l''invocation de compétences d''action"],"de":["Erfordert eine erfolgreiche GSC-Datenerfassung","Nur-Audit-Funktionalität, Ausschluss der Aufrufung von Aktionsfähigkeiten"],"pt":["Requer busca de dados do GSC bem-sucedida","Funcionalidade de auditoria apenas, excluindo a invocação de habilidades de ação"],"ru":["Требует успешного извлечения данных GSC","Функциональность только для аудита, исключая вызов навыков действий"],"ar":["يتطلب استرجاع بيانات مكتب تحكم بحث جوجل بنجاح","وظيفة الفحص فقط، باستثناء استدعاء مهارات العمل"]},"version":4},"contentHash":"0311b2df994dfe7c49387b9523f81faaa8f676a0d56d3286c4d7df0b51eadfbd","qualityScore":60}');
