INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ColdstartLabs-ca/myimageupscaler.com/seo-manager', 'seo-manager', 'ColdstartLabs-ca', 'myimageupscaler.com', 'community', 'seo-manager ColdstartLabs-ca myimageupscaler.com community The seo-manager skill orchestrates SEO audits in parallel waves, collecting results and producing a unified health report based on real Google Search Console (GSC) data, benefiting developers and SEO specialists. SEO Manager是一种使用GSC数据优化网站的工具，能够实时监测网站性能和搜索引擎排名 SEO Managerは、AIエージェントとGSCデータを使用して検索エンジン最適化を実現するツールです SEO Manager는 GSC 데이터를 사용하여 웹사이트를 최적화하고 검색 엔진 순위를 향상시키는 도구입니다 El SEO Manager es un orquestador de auditorías que recopila resultados y produce informes de salud unificados con datos de GSC Le SEO Manager est un orchestrateur d''audits qui collecte les résultats et produit des rapports de santé unifiés avec des données de GSC Der SEO Manager ist ein Orchestrierer von Audits, der Ergebnisse sammelt und einheitliche Gesundheitsberichte mit GSC-Daten erstellt O seo-manager é um orquestrador de auditoria de SEO que coleta resultados de auditorias paralelas e produz relatórios de saúde unificados com base em dados reais do GSC. ИИ Агент seo-manager оркестрирует аудит SEO, собирает результаты и производит единый отчет о здоровье на основе реальных данных GSC. seo-manager هو منسق لتحليل أداء محركات البحث الذي يجمع نتائج التحليلات المتوازية ويصدّر تقارير صحية موحدة مستندة إلى بيانات حقيقية من GSC. how to use seo-manager seo-manager setup guide seo-manager vs ahrefs seo-manager alternative to semrush what is seo-manager seo-manager install seo-manager best practices seo-manager for AI agents seo-manager GSC integration SEO Manager GSC数据 网站优化 搜索引擎排名 AIエージェント React Python 并行波式审计 网站性能监测 Orchestrates SEO audits in parallel waves for efficient analysis Collects results and produces a unified health report grounded in real GSC data References real search data from Google Search Console (GSC) for accurate recommendations Stops audit if GSC fetch fails to ensure data integrity Supports audit-only mode, never invoking action skills like blog-edit or blog-publish seo-manager is a skill that automates SEO audit orchestration, leveraging GSC data to provide actionable insights and recommendations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GaitanS/AI-Mancare/bats-testing-patterns', 'community', 'GaitanS', 'AI-Mancare', 'GaitanS/AI-Mancare', 'bats-testing-patterns', 0, 0, 60, '2026-02-22T11:51:59Z', '2026-03-07T03:48:27.758Z', 'bbf2ab75641bf998873c2a25e408a7a800a8e727d876ce1c56b20b889772ac78', '{"id":"GaitanS/AI-Mancare/bats-testing-patterns","name":"bats-testing-patterns","description":{"en":"bats-testing-patterns provides comprehensive guidance for writing unit tests for shell scripts using Bats. It benefits developers implementing test-driven development and automating testing in CI/CD pipelines.","zh":"Bats 测试模式提供了编写 Shell 脚本单元测试的综合指南，包括测试模式、fixture 和生产级测试的最佳实践","ja":"Bats テスト パターンは、シェル スクリプトのユニット テストを書くための包括的なガイドを提供し、テスト パターン、fixture、生産レベルのテストのベスト プラクティスを含む","ko":"Bats 테스트 패턴은 셸 스크립트의 단위 테스트를 작성하는ための 포괄적인 가이드를 제공하며, 테스트 패턴, fixture 및 생산급 테스트의最佳实践을 포함","es":"Bats Testing Patterns ofrece una guía completa para escribir pruebas unitarias para scripts de shell con Bats, incluyendo patrones de prueba, fixtures y mejores prácticas","fr":"Les modèles de test Bats proposent un guide complet pour écrire des tests unitaires pour les scripts shell avec Bats, y compris des modèles de test, des fixtures et des bonnes pratiques","de":"Bats-Testmuster bieten eine umfassende Anleitung zum Schreiben von Einheitstests für Shell-Skripte mit Bats, einschließlich Testmustern, Fixtures und Best Practices","pt":"Bats Testing Patterns fornece orientação abrangente para testes unitários de shell scripts. Inclui padrões de teste, fixtures e melhores práticas","ru":"Bats Testing Patterns предоставляет комплексное руководство для написания юнит-тестов для скриптов shell. Включает в себя тестовые паттерны, фикстуры и лучшие практики","ar":"نماذج اختبار Bats توفر إرشادات شاملة لاختبارات وحدة لسكريبتات Shell. تشمل أنماط الاختبار و أفضل الممارسات"},"seo":{"title":{"en"