INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('synqing/K1.node1/bats-testing-patterns', 'bats-testing-patterns', 'synqing', 'K1.node1', 'community', 'bats-testing-patterns synqing K1.node1 community The bats-testing-patterns skill provides comprehensive guidance for writing unit tests for shell scripts using Bats, benefiting developers and DevOps teams. Bats 测试模式提供了编写 shell 脚本单元测试的综合指南，包括测试模式、fixtures 和生产级测试的最佳实践 Bats テスト パターンは、シェル スクリプトの単体テストを書くための包括的なガイドを提供します Bats 테스팅 패턴은 쉘 脚本의 단위 테스트를 작성하기 위한 포괄적인 가이드를 제공합니다 Bats Testing Patterns ofrece orientación completa para escribir pruebas unitarias para scripts de shell, incluyendo patrones de prueba, fixtures y mejores prácticas Bats Testing Patterns fournit une guidance complète pour écrire des tests unitaires pour les scripts shell, y compris des modèles de test, des fixtures et des meilleures pratiques Bats-Testing-Patterns bietet umfassende Anleitung für das Schreiben von Einheitstests für Shell-Skripte, einschließlich Testmustern, Fixtures und Best Practices Bats Testing Patterns fornece orientação abrangente para testes unitários de scripts de shell, incluindo padrões de teste e melhores práticas Шаблоны тестирования Bats предоставляют комплексное руководство для написания юнит-тестов для скриптов shell, включая тест-драйвен разработку и настройку автоматизированного тестирования توفر أنماط الاختبار Bats إرشادات شاملة لكتابة الاختبارات الوحدوية للبرامج النصية، بما في ذلك أنماط الاختبار والإعدادات وأفضل الممارسات how to use bats-testing-patterns bats-testing-patterns setup guide bats-testing-patterns vs bash unit testing bats-testing-patterns install what is bats-testing-patterns bats-testing-patterns tutorial bats-testing-patterns best practices bats-testing-patterns for CI/CD pipelines bats-testing-patterns for shell script testing Bats 测试模式 shell 脚本测试 单元测试 TDD 测试驱动开发 CI/CD 生产级测试 边缘情况测试 错误条件测试 Provides test patterns and fixtures for shell scripts Supports test-driven development (TDD) for scripts Enables automated testing in CI/CD pipelines Allows testing of edge cases and error conditions Validates behavior across different shell environments bats-testing-patterns is a comprehensive testing framework for shell scripts, utilizing Bats for automated testing and validation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getkawai/kawai-code/babysit-pr', 'community', 'getkawai', 'kawai-code', 'getkawai/kawai-code', 'babysit-pr', 0, 0, 60, '2026-02-25T16:49:46Z', '2026-03-07T13:06:21.935Z', '165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5', '{"id":"getkawai/kawai-code/babysit-pr","name":"babysit-pr","description":{"en":"The babysit-pr skill automates PR monitoring, ensuring persistent tracking until a PR is merged, closed, or requires user help, benefiting developers and GitHub users. It handles CI success, review comments, and merge conflicts.","zh":"babysit-pr 是一个自动化 PR 审核和合并的工具，帮助开发者提高效率","ja":"babysit-pr は PR の自動化とマージを実現するツールで、開発者の効率を向上させます","ko":"babysit-pr은 PR 자동화 및 병합을 도와주는 도구로 개발자 효율성을 높여줍니다","es":"babysit-pr es una herramienta de automatización que supervisa las solicitudes de extracción en GitHub hasta que se cumple una de las condiciones de finalización. Permite a los desarrolladores ahorrar tiempo y aumentar la productividad.","fr":"babysit-pr est un outil d''automatisation qui surveille les demandes de tirage sur GitHub jusqu''à ce que l''une des conditions de fin soit remplie. Il permet aux développeurs de gagner du temps et d''augmenter la productivité.","de":"babysit-pr ist ein Automatisierungstool, das Pull-Requests auf GitHub überwacht, bis eine der Beendigungsbedingungen erfüllt ist. Es ermöglicht Entwicklern, Zeit zu sparen und die Produktivität zu steigern.","pt":"O babysit-pr é uma ferramenta que automatiza a vigilância de pull requests até que seja mesclado ou fechado, melhorando a eficiência do fluxo de trabalho de desenvolvimento","ru":"babysit-pr - это инструмент, который автоматизирует надзор за pull request до тех пор, пока он не будет слит или закрыт, улучшая эффективность рабочего процесса разработки","ar":"babysit-pr هو أداة تلقيم مراقبة الطلبات السحب حتى يتم دمجها أو إغلاقها، مما يحسن كفاءة سير عمل التطوير"},"seo":{"title":{"en":"babysit-pr: Automated PR Monitoring Setup Guide | AI Agen...","zh":"babysit-pr 设置指南：自动化 PR 审核和合并","ja":"babysit-pr のベストプラクティス：PR の自動化とマージ","ko":"babysit-pr 설정 가이드: PR 자동화 및 병합","es":"Guía de configuración de babysit-pr para desarrolladores","fr":"Configurer babysit-pr: Le guide des meilleures pratiques","de":"Einrichten von babysit-pr: Eine Anleitung für Entwickler","pt":"Guia de Configuração do babysit-pr: Automatize a Vigilânc...","ru":"Настройка babysit-pr: Автоматизация Надзора за Pull Reque...","ar":"دليل إعداد babysit-pr: تلقيم مراقبة الطلبات السحب مع أدوا..."},"description":{"en":"Discover how babysit-pr streamlines your GitHub workflow by persistently monitoring PRs until merge, closure, or user intervention is required - learn how to...","zh":"了解 babysit-pr 的功能和优点，自动化 PR 审核和合并，提高开发效率","ja":"babysit-pr の機能と利点を紹介します。PR の自動化とマージを実現し、開発効率を向上させます","ko":"babysit-pr의 기능과 이점을 알아보세요. PR 자동화 및 병합을 통해 개발 효율성을 높여보세요","es":"Aprende a configurar babysit-pr para automatizar el proceso de revisión de solicitudes de extracción en GitHub con herramientas de IA","fr":"Découvrez comment configurer babysit-pr pour automatiser le processus d''examen des demandes de tirage sur GitHub avec des outils d''IA","de":"Erfahren Sie, wie Sie babysit-pr einrichten, um den Prozess der Überprüfung von Pull-Requests auf GitHub mit KI-Tools zu automatisieren","pt":"Aprenda a configurar o babysit-pr para automatizar a vigilância de pull requests e melhorar a eficiência do seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить babysit-pr для автоматизации надзора за pull request и улучшения эффективности вашего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد babysit-pr لتلقيم مراقبة الطلبات السحب وتحسين كفاءة سير عمل التطوير الخاص بك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"babysit-pr is a GitHub PR monitoring tool that persistently tracks pull requests until terminal outcomes occur, such as merge, closure, or the need for user intervention.","zh":"babysit-pr 是一个自动化工具，用于监控和管理 PR 的生命周期","ja":"babysit-pr は PR のライフサイクルを監視と管理する自動化ツールです","ko":"babysit-pr은 PR의 라이프사이클을 모니터링하고 관리하는 자동화 도구입니다","es":"babysit-pr es una herramienta de IA que automatiza la supervisión de solicitudes de extracción en GitHub","fr":"babysit-pr est un outil d''IA qui automatise la surveillance des demandes de tirage sur GitHub","de":"babysit-pr ist ein KI-Tool, das die Überwachung von Pull-Requests auf GitHub automatisiert","pt":"O que é babysit-pr? É uma ferramenta de automação que vigia pull requests até que seja mesclado ou fechado","ru":"Что такое babysit-pr? Это инструмент автоматизации, который наблюдает за pull request до тех пор, пока он не будет слит или закрыт","ar":"ما هو babysit-pr؟ هو أداة تلقيم تتابع الطلبات السحب حتى يتم دمجها أو إغلاقها"},"features":{"en":["Monitors PRs until merge or closure","Checks for CI success and addresses unmet review comments","Verifies required review approval and potential merge conflicts","Identifies situations requiring user help, such as CI infrastructure issues","Ensures PRs are mergeable and do not report conflict risks","Handles repeated flaky failures after retry budget exhaustion"],"zh":["自动化 PR 审核和合并","监控 CI 结果和代码审查评论","检测潜在的合并冲突","支持 required review approval","提供 retry 机制以处理 flaky 失败"],"ja":["PR の自動化とマージ","CI 結果とコードレビューのコメントを監視","潜在的なマージコンフリクトを検出","required review approval をサポート","リトライ機構を提供してフラッキー失敗を処理"],"ko":["PR 자동화 및 병합","CI 결과와 코드 리뷰 코멘트 모니터링","潜在적인 병합 충돌 감지","필수 리뷰 승인을 지원","재시도 메커니즘을 제공하여 플래키 실패를 처리"],"es":["Supervisión persistente de solicitudes de extracción","Detención de problemas de infraestructura de CI","Detección de comentarios de revisión no abordados","Verificación de aprobación de revisión requerida","Detección de posibles conflictos de fusión"],"fr":["Surveillance persistante des demandes de tirage","Détection de problèmes d''infrastructure de CI","Détectection de commentaires de révision non abordés","Vérification de l''approbation de révision requise","Détection de conflits de fusion potentiels"],"de":["Persistente Überwachung von Pull-Requests","Erkennung von CI-Infrastrukturproblemen","Erkennung von nicht behandelten Review-Kommentaren","Überprüfung der erforderlichen Review-Genehmigung","Erkennung von potenziellen Merge-Konflikten"],"pt":["Vigilância persistente de pull requests","Verificação de CI e comentários de revisão","Detecção de conflitos de mesclagem potenciais","Notificação de situações que requerem ajuda do usuário","Integração com fluxos de trabalho de desenvolvimento"],"ru":["Персистентный надзор за pull request","Проверка CI и комментариев к ревью","Обнаружение потенциальных конфликтов слияния","Уведомление о ситуациях, требующих помощи пользователя","Интеграция с рабочими процессами разработки"],"ar":["مراقبة مستمرة للطلبات السحب","التحقق من البنية التحتية و التعليقات على المراجعة","اكتشاف التعارضات المحتملة للدمج","الإشعار بالحالات التي تتطلب مساعدة المستخدم","التكامل مع سير عمل التطوير"]},"keywords":{"en":["how to use babysit-pr","babysit-pr setup guide","what is babysit-pr","babysit-pr alternative","babysit-pr vs github actions","babysit-pr install","automated pr monitoring","github pr workflow","ci/cd pipeline optimization"],"zh":["babysit-pr","AIエージェント","PR 自动化","代码审查","CI/CD","自动化工具","开发效率","代码管理"],"ja":["babysit-pr","AIエージェント","PR 自動化","コードレビュー","CI/CD","自動化ツール","開発効率","コード管理"],"ko":["babysit-pr","AI 에이전트","PR 자동화","코드 리뷰","CI/CD","자동화 도구","개발 효율성","코드 관리"],"es":["herramientas de IA para desarrolladores","automatización de solicitudes de extracción","supervisión de GitHub","CI/CD","desarrollo de software","productividad de desarrolladores"],"fr":["outils d''IA pour développeurs","automatisation des demandes de tirage","surveillance de GitHub","CI/CD","développement de logiciels","productivité des développeurs"],"de":["KI-Tools für Entwickler","Automatisierung von Pull-Requests","Überwachung von GitHub","CI/CD","Softwareentwicklung","Produktivität von Entwicklern"],"pt":["babysit-pr","automatização de pull requests","ferramentas de desenvolvimento","fluxo de trabalho de desenvolvimento","CI/CD","revisão de código","mergência de código"],"ru":["babysit-pr","автоматизация pull request","инструменты разработки","рабочий процесс разработки","CI/CD","ревью кода","слияние кода","ИИ Агенты"],"ar":["babysit-pr","تلقيم الطلبات السحب","أدوات التطوير","سير عمل التطوير","CI/CD","مراجعة الكود","دمج الكود","أدوات الذكاء الاصطناعي"]}},"owner":"getkawai","repo":"kawai-code","repoPath":"getkawai/kawai-code","stars":0,"forks":0,"updatedAt":"2026-02-25T16:49:46Z","topics":[],"category":"community","skillMd":{"name":"babysit-pr","description":"Babysit a GitHub pull request after creation by continuously polling CI checks/workflow runs, new review comments, and mergeability state until the PR is ready to merge (or merged/closed). Diagnose failures, retry likely flaky failures up to 3 times, auto-fix/push branch-related issues when appropriate, and stop only when user help is required (for example CI infrastructure issues, exhausted flaky retries, or ambiguous/blocking situations). Use when the user asks Codex to monitor a PR, watch CI, handle review comments, or keep an eye on failures and feedback on an open PR.","bodyPreview":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission pr","body":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission problems, or ambiguity that cannot be resolved safely).\n\nDo not stop merely because a single snapshot returns `idle` while checks are still pending.\n\n## Inputs\nAccept any of the following:\n\n- No PR argument: infer the PR from the current branch (`--pr auto`)\n- PR number\n- PR URL\n\n## Core Workflow\n\n1. When the user asks to \"monitor\"/\"watch\"/\"babysit\" a PR, start with the watcher''s continuous mode (`--watch`) unless you are intentionally doing a one-shot diagnostic snapshot.\n2. Run the watcher script to snapshot PR/CI/review state (or consume each streamed snapshot from `--watch`).\n3. Inspect the `actions` list in the JSON response.\n4. If `diagnose_ci_failure` is present, inspect failed run logs and classify the failure.\n5. If the failure is likely caused by the current branch, patch code locally, commit, and push.\n6. If `process_review_comment` is present, inspect surfaced review items and decide whether to address them.\n7. If a review item is actionable and correct, patch code locally, commit, and push.\n8. If the failure is likely flaky/unrelated and `retry_failed_checks` is present, rerun failed jobs with `--retry-failed-now`.\n9. If both actionable review feedback and `retry_failed_checks` are present, prioritize review feedback first; a new commit will retrigger CI, so avoid rerunning flaky checks on the old SHA unless you intentionally defer the review change.\n10. On every loop, verify mergeability / merge-conflict status (for example via `gh pr view`) in addition to CI and review state.\n11. After any push or rerun action, immediately return to step 1 and continue polling on the updated SHA/state.\n12. If you had been using `--watch` before pausing to patch/commit/push, relaunch `--watch` yourself in the same turn immediately after the push (do not wait for the user to re-invoke the skill).\n13. Repeat polling until the PR is green + review-clean + mergeable, `stop_pr_closed` appears, or a user-help-required blocker is reached.\n14. Maintain terminal/session ownership: while babysitting is active, keep consuming watcher output in the same turn; do not leave a detached `--watch` process running and then end the turn as if monitoring were complete.\n\n## Commands\n\n### One-shot snapshot\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --once\n```\n\n### Continuous watch (JSONL)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --watch\n```\n\n### Trigger flaky retry cycle (only when watcher indicates)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --retry-failed-now\n```\n\n### Explicit PR target\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr <number-or-url> --once\n```\n\n## CI Failure Classification\nUse `gh` commands to inspect failed runs before deciding to rerun.\n\n- `gh run view <run-id> --json jobs,name,workflowName,conclusion,status,url,headSha`\n- `gh run view <run-id> --log-failed`\n\nPrefer treating failures as branch-related when logs point to changed code (compile/test/lint/typecheck/snapshots/static analysis in touched areas).\n\nPrefer treating failures as flaky/unrelated when logs show transient infra/external issues (timeouts, runner provisioning failures, registry/network outages, GitHub Actions infra errors).\n\nIf classification is ambiguous, perform one manual diagnosis attempt before choosing rerun.\n\nRead `.codex/skills/babysit-pr/references/heuristics.md` for a concise checklist.\n\n## Review Comment Handling\nThe watcher surfaces review items from:\n\n- PR issue comments\n- Inline review comments\n- Review submissions (COMMENT / APPROVED / CHANGES_REQUESTED)\n\nIt intentionally surfaces Codex reviewer bot feedback (for example comments/reviews from `chatgpt-codex-connector[bot]`) in addition to human reviewer feedback. Most unrelated bot noise should still be ignored.\nFor safety, the watcher only auto-surfaces trusted human review authors (for example repo OWNER/MEMBER/COLLABORATOR, plus the authenticated operator) and approved review bots such as Codex.\nOn a fresh watcher state file, existing pending review feedback may be surfaced immediately (not only comments that arrive after monitoring starts). This is intentional so already-open review comments are not missed.\n\nWhen you agree with a comment and it is actionable:\n\n1. Patch code locally.\n2. Commit with `codex: address PR review feedback (#<n>)`.\n3. Push to the PR head branch.\n4. Resume watching on the new SHA immediately (do not stop after reporting the push).\n5. If monitoring was running in `--watch` mode, restart `--watch` immediately after the push in the same turn; do not wait for the user to ask again.\n\nIf you disagree or the comment is non-actionable/already addressed, record it as handled by continuing the watcher loop (the script de-duplicates surfaced items via state after surfacing them).\nIf a code review comment/thread is already marked as resolved in GitHub, treat it as non-actionable and safely ignore it unless new unresolved follow-up feedback appears.\n\n## Git Safety Rules\n\n- Work only on the PR head branch.\n- Avoid destructive git commands.\n- Do not switch branches unless necessary to recover context.\n- Before editing, check for unrelated uncommitted changes. If present, stop and ask the user.\n- After each successful fix, commit and `git push`, then re-run the watcher.\n- If you interrupted a live `--watch` session to make the fix, restart `--watch` immediately after the push in the same turn.\n- Do not run multiple concurrent `--watch` processes for the same PR/state file; keep one watcher session active and reuse it until it stops or you intentionally restart it.\n- A push is not a terminal outcome; continue the monitoring loop unless a strict stop condition is met.\n\nCommit message defaults:\n\n- `codex: fix CI failure on PR #<n>`\n- `codex: address PR review feedback (#<n>)`\n\n## Monitoring Loop Pattern\nUse this loop in a live Codex session:\n\n1. Run `--once`.\n2. Read `actions`.\n3. First check whether the PR is now merged or otherwise closed; if so, report that terminal state and stop polling immediately.\n4. Check CI summary, new review items, and mergeability/conflict status.\n5. Diagnose CI failures and classify branch-related vs flaky/unrelated.\n6. Process actionable review comments before flaky reruns when both are present; if a review fix requires a commit, push it and skip rerunning failed checks on the old SHA.\n7. Retry failed checks only when `retry_failed_checks` is present and you are not about to replace the current SHA with a review/CI fix commit.\n8. If you pushed a commit or triggered a rerun, report the action briefly and continue polling (do not stop).\n9. After a review-fix push, proactively restart continuous monitoring (`--watch`) in the same turn unless a strict stop condition has already been reached.\n10. If everything is passing, mergeable, not blocked on required review approval, and there are no unaddressed review items, report success and stop.\n11. If blocked on a user-help-required issue (infra outage, exhausted flaky retries, unclear reviewer request, permissions), report the blocker and stop.\n12. Otherwise sleep according to the polling cadence below and repeat.\n\nWhen the user explicitly asks to monitor/watch/babysit a PR, prefer `--watch` so polling continues autonomously in one command. Use repeated `--once` snapshots only for debugging, local testing, or when the user explicitly asks for a one-shot check.\nDo not stop to ask the user whether to continue polling; continue autonomously until a strict stop condition is met or the user explicitly interrupts.\nDo not hand control back to the user after a review-fix push just because a new SHA was created; restarting the watcher and re-entering the poll loop is part of the same babysitting task.\nIf a `--watch` process is still running and no strict stop condition has been reached, the babysitting task is still in progress; keep streaming/consuming watcher output instead of ending the turn.\n\n## Polling Cadence\nUse adaptive polling and continue monitoring even after CI turns green:\n\n- While CI is not green (pending/running/queued or failing): poll every 1 minute.\n- After CI turns green: start at every 1 minute, then back off exponentially when there is no change (for example 1m, 2m, 4m, 8m, 16m, 32m), capping at every 1 hour.\n- Reset the green-state polling interval back to 1 minute whenever anything changes (new commit/SHA, check status changes, new review comments, mergeability changes, review decision changes).\n- If CI stops being green again (new commit, rerun, or regression): return to 1-minute polling.\n- If any poll shows the PR is merged or otherwise closed: stop polling immediately and report the terminal state.\n\n## Stop Conditions (Strict)\nStop only when one of the following is true:\n\n- PR merged or closed (stop as soon as a poll/snapshot confirms this).\n- PR is ready to merge: CI succeeded, no surfaced unaddressed review comments, not blocked on required review approval, and no merge conflict risk.\n- User intervention is required and Codex cannot safely proceed alone.\n\nKeep polling when:\n\n- `actions` contains only `idle` but checks are still pending.\n- CI is still running/queued.\n- Review state is quiet but CI is not terminal.\n- CI is green but mergeability is unknown/pending.\n- CI is green and mergeable, but the PR is still open and you are waiting for possible new review comments or merge-conflict changes per the green-state cadence.\n- The PR is green but blocked on review approval (`REVIEW_REQUIRED` / similar); continue polling on the green-state cadence and surface any new review comments without asking for confirmation to keep watching.\n\n## Output Expectations\nProvide concise progress updates while monitoring and a final summary that includes:\n\n- During long unchanged monitoring periods, avoid emitting a full update on every poll; summarize only status changes plus occasional heartbeat updates.\n- Treat push confirmations, intermediate CI snapshots, and review-action updates as progress updates only; do not emit the final summary or end the babysitting session unless a strict stop condition is met.\n- A user request to \"monitor\" is not satisfied by a couple of sample polls; remain in the loop until a strict stop condition or an explicit user interruption.\n- A review-fix commit + push is not a completion event; immediately resume live monitoring (`--watch`) in the same turn and continue reporting progress updates.\n- When CI first transitions to all green for the current SHA, emit a one-time celebratory progress update (do not repeat it on every green poll). Preferred style: `🚀 CI is all green! 33/33 passed. Still on watch for review approval.`\n- Do not send the final summary while a watcher terminal is still running unless the watcher has emitted/confirmed a strict stop condition; otherwise continue with progress updates.\n\n- Final PR SHA\n- CI status summary\n- Mergeability / conflict status\n- Fixes pushed\n- Flaky retry cycles used\n- Remaining unresolved failures or review comments\n\n## References\n\n- Heuristics and decision tree: `.codex/skills/babysit-pr/references/heuristics.md`\n- GitHub CLI/API details used by the watcher: `.codex/skills/babysit-pr/references/github-api-notes.md`\n"},"lastSynced":"2026-03-07T13:06:21.935Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Integration Agents requiring automated PR monitoring and conflict resolution capabilities.","zh":"适用于需要自动化 PR 监控和冲突解决能力的 GitHub 集成代理。","ja":"GitHub の統合エージェントに自動化された PR 監視とコンフリクト解決機能を必要とする場合に最適です。","ko":"자동화된 PR 모니터링 및 충돌 해결 기능이 필요한 GitHub 통합 에이전트에 적합합니다.","es":"Ideal para Agentes de Integración de GitHub que requieren monitoreo de PR automatizado y capacidades de resolución de conflictos.","fr":"Idéal pour les Agents d''intégration GitHub nécessitant un moniteur de PR automatisé et des capacités de résolution de conflits.","de":"Ideal für GitHub-Integration-Agents, die automatisierte PR-Überwachung und Konfliktlösungsfähigkeiten erfordern.","pt":"Ideal para Agentes de Integração do GitHub que exigem monitoramento de PR automatizado e capacidades de resolução de conflitos.","ru":"Идеально для агентов интеграции GitHub, требующих автоматического мониторинга PR и возможностей разрешения конфликтов.","ar":"مثالي لعميل تكنولوجيا المعلومات الذي يحتاج إلى مراقبة طلبات السحب و إمكانيات حل النزاعات تلقائيًا."},"recommendation":{"en":"Empowers agents to persistently track PRs until merge, closure, or user intervention is required, leveraging CI success checks, review comment analysis, and merge conflict detection via GitHub APIs and webhooks.","zh":"赋予代理持续跟踪 PR 直到合并、关闭或需要用户干预，利用 CI 成功检查、审查评论分析和通过 GitHub API 和 webhook 的合并冲突检测。","ja":"CI 成功チェック、レビューコメントの分析、GitHub API および Webhook 経由のマージコンフリクトの検出を利用して、エージェントが PR をマージ、クローズ、またはユーザーが介入するまでずっと追跡できるようにします。","ko":"CI 성공 확인, 리뷰 댓글 분석, GitHub API 및 webhook를 통해 merge 충돌 감지를 활용하여 에이전트가 PR을 merge, 닫기 또는 사용자 개입이 필요한 때까지 지속적으로 추적할 수 있도록 합니다.","es":"Habilita a los agentes a realizar un seguimiento persistente de las PR hasta la combinación, cierre o intervención del usuario, aprovechando las comprobaciones de éxito de CI, el análisis de comentarios de revisión y la detección de conflictos de combinación a través de GitHub APIs y webhooks.","fr":"Permet aux agents de suivre de manière persistante les PR jusqu''à la fusion, la fermeture ou l''intervention de l''utilisateur, en exploitant les vérifications de réussite de CI, l''analyse des commentaires de révision et la détection des conflits de fusion via les GitHub APIs et les webhooks.","de":"Ermächtigt die Agenten, PRs bis zum Merge, Schließen oder Benutzereingriff persistent zu verfolgen, indem sie CI-Erfolgskontrollen, Review-Kommentar-Analyse und Merge-Konflikt-Erkennung über GitHub-APIs und Webhooks nutzen.","pt":"Habilita os agentes a acompanhar persistentemente os PRs até a mesclagem, fechamento ou intervenção do usuário seja necessária, aproveitando verificações de sucesso de CI, análise de comentários de revisão e detecção de conflitos de mesclagem via GitHub APIs e webhooks.","ru":"Позволяет агентам постоянно отслеживать PR до слияния, закрытия или когда требуется вмешательство пользователя, используя проверки успешности CI, анализ комментариев к обзору и обнаружение конфликтов слияния через GitHub API и веб-хуки.","ar":"يمنح الوكلاء القدرة على متابعة طلبات السحب بانتظام حتى يتم دمجها أو إغلاقها أو متى تتطلب تدخل المستخدم، مستفيدًا من التحقق من نجاح CI وتحليل تعليقات المراجعة وكشف النزاعات في الدمج عبر واجهات برمجة تطبيقات GitHub ورسائل الويب."},"useCases":{"en":["Automating PR monitoring for timely merge or closure","Debugging CI failures and flaky tests to prevent PR bottlenecks","Resolving merge conflicts and addressing review comments for seamless integration"],"zh":["自动化 PR 监控以实现及时合并或关闭","调试 CI 故障和不稳定的测试以防止 PR 瓶颈","解决合并冲突和解决审查评论以实现无缝集成"],"ja":["タイムリーなマージまたはクローズを実現するために PR の監視を自動化する","PR ボトルネックを防ぐために CI の故障と不安定なテストをデバッグする","シームレスな統合を実現するためにマージコンフリクトを解決し、レビューコメントに応答する"],"ko":["적절한 병합 또는 닫기를 위한 PR 모니터링 자동화","PR 병목 현상을 방지하기 위한 CI 오류 및 불안정한 테스트 디버깅","무결점 통합을 위한 병합 충돌 해결 및 리뷰 댓글 처리"],"es":["Automatizar el monitoreo de PR para una combinación o cierre oportuno","Depurar fallos de CI y pruebas inestables para prevenir cuellos de botella de PR","Resolver conflictos de combinación y abordar comentarios de revisión para una integración sin problemas"],"fr":["Automatiser le suivi des PR pour une fusion ou une fermeture en temps opportun","Déboguer les échecs de CI et les tests instables pour éviter les goulots d''étranglement des PR","Résoudre les conflits de fusion et traiter les commentaires de révision pour une intégration sans problème"],"de":["Automatisieren des PR-Monitorings für rechtzeitigen Merge oder Schließen","Fehler in CI und flüchtigen Tests debuggen, um PR-Engpässe zu vermeiden","Auflösung von Merge-Konflikten und Bearbeitung von Review-Kommentaren für eine reibungslose Integration"],"pt":["Automatizar o monitoramento de PR para mesclagem ou fechamento oportuno","Depurar falhas de CI e testes instáveis para evitar gargalos de PR","Resolver conflitos de mesclagem e abordar comentários de revisão para integração sem problemas"],"ru":["Автоматизировать мониторинг PR для своевременного слияния или закрытия","Отлаживать неисправности CI и нестабильные тесты, чтобы предотвратить заторы PR","Разрешать конфликты слияния и решать комментарии к обзору для бесперебойной интеграции"],"ar":["توفير مراقبة تلقائية لطلبات السحب من أجل دمج أو إغلاق في الوقت المناسب","تصحيح أخطاء CI والاختبارات غير المستقرة لمنع انسداد طلبات السحب","حل النزاعات في الدمج ومعالجة تعليقات المراجعة من أجل دمج بدون مشاكل"]},"limitations":{"en":["Requires GitHub API access and authentication","Limited to GitHub PRs, not compatible with other version control systems"],"zh":["需要 GitHub API 访问和身份验证","仅限 GitHub PR，不能与其他版本控制系统兼容"],"ja":["GitHub API アクセスと認証が必要","GitHub の PR のみに限定され、他のバージョン管理システムとは互換性がない"],"ko":["GitHub API 액세스 및 인증이 필요","GitHub PR만 해당되며 다른 버전 관리 시스템과 호환되지 않음"],"es":["Requiere acceso y autenticación a la API de GitHub","Limitado a PR de GitHub, no compatible con otros sistemas de control de versiones"],"fr":["Nécessite un accès et une authentification à l''API GitHub","Limité aux PR GitHub, non compatible avec d''autres systèmes de contrôle de version"],"de":["Benötigt Zugriff und Authentifizierung auf die GitHub-API","Begrenzt auf GitHub-PR, nicht kompatibel mit anderen Versionskontrollsystemen"],"pt":["Exige acesso e autenticação à API do GitHub","Limitado a PRs do GitHub, não compatível com outros sistemas de controle de versão"],"ru":["Требует доступа и аутентификации к API GitHub","Ограничен PR GitHub, несовместим с другими системами контроля версий"],"ar":["يتطلب الوصول والمصادقة على واجهة برمجة تطبيقات GitHub","محدود لطلبات السحب على GitHub، غير متوافق مع أنظمة التحكم في الإصدار الأخرى"]},"version":4},"contentHash":"165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5","qualityScore":60}');
