INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getkawai/kawai-code/babysit-pr', 'babysit-pr', 'getkawai', 'kawai-code', 'community', 'babysit-pr getkawai kawai-code community The babysit-pr skill automates PR monitoring, ensuring persistent tracking until a PR is merged, closed, or requires user help, benefiting developers and GitHub users. It handles CI success, review comments, and merge conflicts. babysit-pr 是一个自动化 PR 审核和合并的工具，帮助开发者提高效率 babysit-pr は PR の自動化とマージを実現するツールで、開発者の効率を向上させます babysit-pr은 PR 자동화 및 병합을 도와주는 도구로 개발자 효율성을 높여줍니다 babysit-pr es una herramienta de automatización que supervisa las solicitudes de extracción en GitHub hasta que se cumple una de las condiciones de finalización. Permite a los desarrolladores ahorrar tiempo y aumentar la productividad. babysit-pr est un outil d''automatisation qui surveille les demandes de tirage sur GitHub jusqu''à ce que l''une des conditions de fin soit remplie. Il permet aux développeurs de gagner du temps et d''augmenter la productivité. babysit-pr ist ein Automatisierungstool, das Pull-Requests auf GitHub überwacht, bis eine der Beendigungsbedingungen erfüllt ist. Es ermöglicht Entwicklern, Zeit zu sparen und die Produktivität zu steigern. O babysit-pr é uma ferramenta que automatiza a vigilância de pull requests até que seja mesclado ou fechado, melhorando a eficiência do fluxo de trabalho de desenvolvimento babysit-pr - это инструмент, который автоматизирует надзор за pull request до тех пор, пока он не будет слит или закрыт, улучшая эффективность рабочего процесса разработки babysit-pr هو أداة تلقيم مراقبة الطلبات السحب حتى يتم دمجها أو إغلاقها، مما يحسن كفاءة سير عمل التطوير how to use babysit-pr babysit-pr setup guide what is babysit-pr babysit-pr alternative babysit-pr vs github actions babysit-pr install automated pr monitoring github pr workflow ci/cd pipeline optimization babysit-pr AIエージェント PR 自动化 代码审查 CI/CD 自动化工具 开发效率 代码管理 Monitors PRs until merge or closure Checks for CI success and addresses unmet review comments Verifies required review approval and potential merge conflicts Identifies situations requiring user help, such as CI infrastructure issues Ensures PRs are mergeable and do not report conflict risks Handles repeated flaky failures after retry budget exhaustion babysit-pr is a GitHub PR monitoring tool that persistently tracks pull requests until terminal outcomes occur, such as merge, closure, or the need for user intervention.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thiansit/LuPang/awaken', 'community', 'thiansit', 'LuPang', 'thiansit/LuPang', 'awaken', 0, 0, 60, '2026-02-28T07:13:18Z', '2026-03-07T03:50:59.493Z', '760d0aa98b85d16005f084ef9cf2bf0eaf915b0332bdeb9509758c7eef54abb1', '{"id":"thiansit/LuPang/awaken","name":"awaken","description":{"en":"The awaken skill guides developers through an 8-step ritual to set up LuPang''s Oracle AI Brain, transforming an empty repo into a fully awakened Oracle. This skill is designed for developers working with AI agents.","zh":"Awaken 是 LuPang Oracle AI Brain 的一种设置方式，通过 8 步引导仪式快速设置","ja":"Awaken は Oracle AIエージェントの設定方法であり、8 步ガイドを使用して設定します","ko":"Awaken은 LuPang Oracle AI Brain의 설정 방법으로 8단계 가이드를 통해 설정합니다","es":"Awaken es un ritual de despertar de Oracle AI que te guía a través de un proceso de 8 pasos para crear un entorno de desarrollo desde cero","fr":"Awaken est un rituel d''éveil d''Oracle AI qui vous guide à travers un processus de 8 étapes pour créer un environnement de développement depuis zéro","de":"Awaken ist ein Erweckungsritus von Oracle AI, der Sie durch einen 8-Schritte-Prozess führt, um ein Entwicklungsumgebung von Grund auf zu erstellen","pt":"O Awaken é uma ferramenta de agente de inteligência artificial que fornece um ritual de 8 etapas para guiar você da criação de um repositório vazio até a ativação do Oracle","ru":"Awaken - это инструмент ИИ Агентов, который предоставляет 8-этапный ритуал для指导 вас от создания пустого репозитория до активации Oracle","ar":"Awaken هو أداة وكلاء الذكاء الاصطناعي التي توفر طقوسًا من 8 خطوات لتوجيهك من إنشاء مستودع فارغ إلى تفعيل برنامج Oracle"},"seo":{"title":{"en":"awaken: 8-Step Oracle AI Brain Setup Guide | AI Agent Skill","zh":"Awaken Setup Guide - 了解 LuPang Oracle AI Brain","ja":"Awaken セットアップガイド - Oracle AIエージェントの使い方","ko":"Awaken 설정 가이드 - LuPang Oracle AI Brain 이해","es":"Gu