INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thiansit/LuPang/awaken', 'awaken', 'thiansit', 'LuPang', 'community', 'awaken thiansit LuPang community The awaken skill guides developers through an 8-step ritual to set up LuPang''s Oracle AI Brain, transforming an empty repo into a fully awakened Oracle. This skill is designed for developers working with AI agents. Awaken 是 LuPang Oracle AI Brain 的一种设置方式，通过 8 步引导仪式快速设置 Awaken は Oracle AIエージェントの設定方法であり、8 步ガイドを使用して設定します Awaken은 LuPang Oracle AI Brain의 설정 방법으로 8단계 가이드를 통해 설정합니다 Awaken es un ritual de despertar de Oracle AI que te guía a través de un proceso de 8 pasos para crear un entorno de desarrollo desde cero Awaken est un rituel d''éveil d''Oracle AI qui vous guide à travers un processus de 8 étapes pour créer un environnement de développement depuis zéro Awaken ist ein Erweckungsritus von Oracle AI, der Sie durch einen 8-Schritte-Prozess führt, um ein Entwicklungsumgebung von Grund auf zu erstellen O Awaken é uma ferramenta de agente de inteligência artificial que fornece um ritual de 8 etapas para guiar você da criação de um repositório vazio até a ativação do Oracle Awaken - это инструмент ИИ Агентов, который предоставляет 8-этапный ритуал для指导 вас от создания пустого репозитория до активации Oracle Awaken هو أداة وكلاء الذكاء الاصطناعي التي توفر طقوسًا من 8 خطوات لتوجيهك من إنشاء مستودع فارغ إلى تفعيل برنامج Oracle how to use awaken awaken setup guide what is awaken awaken alternative awaken vs oracle-v2 awaken install luPang oracle ai brain ai agent setup guided ritual for ai agents Awaken 设置 LuPang Oracle AI Brain AI 代理设置 Git 仓库设置 CLI 命令 Oracle AI 代理 AI 工具设置 AI 代理设置指南 Starts the awakening ritual with the `/awaken` command Guides users through an 8-step process to awaken the Oracle Requires a fresh git repository for setup Ignores deprecated `awaken.md` files from oracle-v2 Completes the awakening process in approximately 15 minutes Utilizes the `awaken.md` file for the guided ritual awaken is a guided ritual for setting up LuPang''s Oracle AI Brain, consisting of an 8-step process that awakens the Oracle in an empty git repository.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NehaTanti-afk/Neha-Notes/figma-analyze', 'community', 'NehaTanti-afk', 'Neha-Notes', 'NehaTanti-afk/Neha-Notes', 'figma-analyze', 0, 0, 60, '2026-02-22T20:37:06Z', '2026-03-07T03:53:41.290Z', '4e3600172f3c10aeff8af7de6a5fb1630dfa171fe38550400b7bf80bc91be08d', '{"id":"NehaTanti-afk/Neha-Notes/figma-analyze","name":"figma-analyze","description":{"en":"The figma-analyze skill analyzes Figma components against Nexus conventions, validating design-code parity, token usage, and AI readability. It benefits developers and designers by providing a focused issues list with fixes.","zh":"Figma Analyze 是一个检查 Figma 设计与代码一致性的工具，确保设计代码的正确性和可读性","ja":"Figma Analyze は、Figma デザインとコードの整合性をチェックするツールで、設計コードの正しさと可読性を確保します","ko":"피그마 분석 도구는 피그마 디자인과 코드의 일관성을 확인하는 도구로 디자인 코드의 정확성과 가독성을 보장합니다","es":"Figma Analyze es una herramienta que valida la paridad entre diseño y código, y ofrece un informe detallado de problemas y soluciones.","fr":"Figma Analyze est un outil qui valide la parité entre conception et code, et fournit un rapport détaillé des problèmes et des solutions.","de":"Figma Analyze ist ein Tool, das die Übereinstimmung zwischen Design und Code überprüft und einen detaillierten Bericht über Probleme und Lösungen bietet.","pt":"O Figma Analyze é uma ferramenta que analisa componentes do Figma contra convenções do Nexus, validando a paridade de design e código","ru":"Figma Analyze - это инструмент, который анализирует компоненты Figma против конвенций Nexus, проверяя соответствие дизайна и кода","ar":"Figma Analyze هو أداة تحليل مكونات Figma ضد التطبيقات المتوافقة مع Nexus، والتحقق من توافق التصميم والكود"},"seo":{"title":{"en":"figma-analyze: Figma Component Analysis for AI Agents | A...","zh":"Figma 设计分析工具 - 代码设计一致性检查","ja":"Figma Analyze AIエージェント - デザインとコードの整合性を確保する","ko":"피그마 분석 도구 - 디자인 코드 상통성 검사","es":"Guía de configuración de Figma Analyze para desarrolladores","fr":"Configurer Figma Analyze pour les développeurs : meilleur...","de":"Einrichtung von Figma Analyze für Entwickler: Leitfaden","pt":"Guia de Configuração do Figma Analyze: Ferramenta de Anál...","ru":"Настройка Figma Analyze: ИИ Агент для Анализа Конвенций","ar":"دليل إعداد Figma Analyze: أداة تحليل التطبيقات"},"description":{"en":"Unlock design-code parity with figma-analyze. Get a focused issues list and fixes for your Figma components. Learn how to set up and use figma-analyze today!","zh":"使用 Figma Analyze 检查设计与代码的一致性，确保设计代码的正确性和可读性","ja":"Figma Analyze AIエージェントを使用して、デザインとコードの整合性をチェックし、設計コードの正しさと可読性を確保する","ko":"피그마 분석 도구를 사용하여 디자인과 코드의 일관성을 확인하고 디자인 코드의 정확성과 가독성을 보장합니다","es":"Aprende a utilizar Figma Analyze para validar la paridad entre diseño y código, tokens y legibilidad de IA. Mejora tu flujo de trabajo de desarrollo con nues...","fr":"Découvrez comment utiliser Figma Analyze pour valider la parité entre conception et code, les jetons et la lisibilité de l''IA. Améliorez votre flux de travai...","de":"Erfahren Sie, wie Sie Figma Analyze verwenden, um die Übereinstimmung zwischen Design und Code, Token und IA-Lesbarkeit zu überprüfen. Verbessern Sie Ihren E...","pt":"Aprenda a configurar o Figma Analyze para validar a paridade de design e código, uso de tokens e legibilidade de IA","ru":"Узнайте, как настроить Figma Analyze для проверки соответствия конвенциям, использования токенов и читаемости ИИ","ar":"تعرف على كيفية إعداد Figma Analyze للتحقق من توافق التصميم والكود واستخدام الرموز وقراءة الذكاء الاصطناعي"},"definition":{"en":"figma-analyze is a skill that analyzes existing Figma components against Nexus conventions, validating design-code parity, token usage, and AI readability.","zh":"Figma Analyze 是一个 AI 工具，用于检查 Figma 设计与代码的一致性","ja":"Figma Analyze は、Figma デザインとコードの整合性をチェックする AI エージェントです","ko":"피그마 분석 도구는 피그마 디자인과 코드의 일관성을 확인하는 AI 도구입니다","es":"Figma Analyze es una herramienta de análisis de componentes de Figma que verifica la paridad entre diseño y código.","fr":"Figma Analyze est un outil d''analyse de composants Figma qui vérifie la parité entre conception et code.","de":"Figma Analyze ist ein Analyse-Tool für Figma-Komponenten, das die Übereinstimmung zwischen Design und Code überprüft.","pt":"Figma Analyze é uma ferramenta de análise que verifica a conformidade de componentes do Figma com as convenções do Nexus","ru":"Figma Analyze - это инструмент анализа, который проверяет соответствие компонентов Figma конвенциям Nexus","ar":"Figma Analyze هو أداة تحليل تقوم بالتحقق من مطابقة مكونات Figma للتطبيقات المتوافقة مع Nexus"},"features":{"en":["Validates design-code parity against Nexus conventions","Checks token usage in Figma components","Analyzes AI readability of Figma designs","Outputs a focused issues list with fixes","Supports input via Figma URL with node-id parameter","Generates reports on design-code inconsistencies"],"zh":["设计代码一致性检查","Nexus 约定的验证","令牌使用情况检查","AI 可读性检查","输出问题列表和解决方案"],"ja":["デザインとコードの整合性チェック","Nexus 约定的検証","トークンの使用状況チェック","AI 可読性チェック","問題リストと解決策の出力"],"ko":["디자인 코드 일관성 확인","Nexus 규약의 유효성 검사","토큰 사용情况 확인","AI 가독성 확인","문제 목록과 해결책 출력"],"es":["Validación de paridad entre diseño y código","Análisis de tokens y legibilidad de IA","Informe detallado de problemas y soluciones","Compatibilidad con URLs de Figma","Detección de problemas de diseño y código"],"fr":["Validation de la parité entre conception et code","Analyse des jetons et de la lisibilité de l''IA","Rapport détaillé des problèmes et des solutions","Compatibilité avec les URL de Figma","Détection des problèmes de conception et de code"],"de":["Überprüfung der Übereinstimmung zwischen Design und Code","Analyse von Token und IA-Lesbarkeit","Detaillierter Bericht über Probleme und Lösungen","Kompatibilität mit Figma-URLs","Erkennung von Design- und Code-Problemen"],"pt":["Validação de paridade de design e código","Verificação de uso de tokens","Análise de legibilidade de IA","Saída de lista de problemas com soluções","Integração com Figma URL"],"ru":["Проверка соответствия дизайна и кода","Проверка использования токенов","Анализ читаемости ИИ","Выходная список проблем с решениями","Интеграция с Figma URL"],"ar":["التحقق من توافق التصميم والكود","التحقق من استخدام الرموز","تحليل قراءة الذكاء الاصطناعي","إخراج قائمة المشاكل مع الحلول","التكامل مع Figma URL"]},"keywords":{"en":["how to use figma-analyze","figma-analyze setup guide","figma component analysis","design-code parity validation","figma-analyze alternative","figma-analyze vs design system tools","figma-analyze install","nexus conventions for figma","ai readability in figma designs"],"zh":["Figma 设计分析","代码设计一致性检查","AI 设计工具","Nexus 约定","令牌使用情况检查","AI 可读性检查"],"ja":["Figma デザイン分析","デザインとコードの整合性チェック","AI エージェント","Nexus 约定","トークンの使用状況チェック","AI 可読性チェック"],"ko":["피그마 디자인 분석","디자인 코드 일관성 확인","AI 도구","Nexus 규약","토큰 사용情况 확인","AI 가독성 확인"],"es":["Figma Analyze","herramientas de desarrollo","diseño y código","tokens y legibilidad de IA","informe de problemas y soluciones","compatibilidad con Figma","análisis de componentes de Figma"],"fr":["Figma Analyze","outils de développement","conception et code","jetons et lisibilité de l''IA","rapport de problèmes et de solutions","compatibilité avec Figma","analyse de composants Figma"],"de":["Figma Analyze","Entwicklungstools","Design und Code","Token und IA-Lesbarkeit","Bericht über Probleme und Lösungen","Kompatibilität mit Figma","Analyse von Figma-Komponenten"],"pt":["Figma Analyze","análise de convenções","paridade de design e código","uso de tokens","legibilidade de IA","Figma URL","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Figma Analyze","анализ конвенций","соответствие дизайна и кода","использование токенов","читаемость ИИ","Figma URL","разработка программного обеспечения","инструменты разработки"],"ar":["Figma Analyze","تحليل التطبيقات","توافق التصميم والكود","استخدام الرموز","قراءة الذكاء الاصطناعي","Figma URL","تطوير البرمجيات","أدوات التطوير"]}},"owner":"NehaTanti-afk","repo":"Neha-Notes","repoPath":"NehaTanti-afk/Neha-Notes","stars":0,"forks":0,"updatedAt":"2026-02-22T20:37:06Z","topics":[],"category":"community","skillMd":{"name":"figma-analyze","description":"Analyze Figma designs for code implementation readiness and design-code parity. Use when working with Figma URLs, analyzing component designs, or checking token consistency.","bodyPreview":"# Figma Analyze\n\n## Purpose\n\nAnalyze an existing Figma component against Nexus conventions. Validates design-code parity, token usage, and AI readability. Outputs a focused issues list with fixes.\n\n## Input\n\n| Format               | Example                                                       | Detection   |\n| -------------------- | ------------------------------------------------------------- | ----------- |\n| Figma URL            | `https://figma.com/design/:fileKey/:fileName?node-id=123-456`","body":"# Figma Analyze\n\n## Purpose\n\nAnalyze an existing Figma component against Nexus conventions. Validates design-code parity, token usage, and AI readability. Outputs a focused issues list with fixes.\n\n## Input\n\n| Format               | Example                                                       | Detection   |\n| -------------------- | ------------------------------------------------------------- | ----------- |\n| Figma URL            | `https://figma.com/design/:fileKey/:fileName?node-id=123-456` | URL pattern |\n| Component name + URL | `Button https://figma.com/...`                                | Name + URL  |\n\nExtract from URL:\n\n- `fileKey` — from path segment after `/design/`\n- `nodeId` — from `node-id` param, convert `123-456` → `123:456`\n\n## Data Sources\n\n### Figma (via MCP)\n\n```\nmcp__figma__get_design_context(fileKey, nodeId)  → Props, structure, generated code\nmcp__figma__get_variable_defs(fileKey, nodeId)   → Tokens/variables used\nmcp__figma__get_metadata(fileKey, nodeId)        → Frame names, hierarchy\nmcp__figma__get_screenshot(fileKey, nodeId)      → Visual reference (optional)\n```\n\n### Nexus Token System\n\n```\nRead: packages/tailwind/nexus.css           → Semantic tokens (source of truth)\nRead: .claude/rules/shadcn-divergences.md   → shadcn → Nexus mapping rules\n```\n\n### shadcn Reference (if applicable)\n\n```\nWebFetch: https://ui.shadcn.com/r/styles/default/{component}.json\n```\n\n---\n\n## Workflow\n\n### Phase 1: Gather All Context\n\n**In parallel:**\n\n1. **Figma Design** — Call MCP tools to get:\n   - Component properties (names, types, values)\n   - Variables/tokens used\n   - Frame names and layer hierarchy\n\n2. **Nexus Tokens** — Read:\n   - `packages/tailwind/nexus.css` — actual semantic tokens available\n   - `.claude/rules/shadcn-divergences.md` — divergence rules\n\n3. **shadcn Reference** (if base component identified):\n   - Fetch from registry to compare props/variants\n\n### Phase 2: Run All Checks\n\nAnalyze Figma against Nexus conventions. Check each category and **only note issues**.\n\n#### Check Categories\n\n| Category               | What to Check                                                        |\n| ---------------------- | -------------------------------------------------------------------- |\n| **Property Names**     | Match code props exactly (`variant` not `Style`, `size` not `Scale`) |\n| **Property Values**    | Lowercase (`sm`, `md` not `Small`, `Medium`)                         |\n| **Boolean Props**      | Use `has*`/`is*` prefix (`hasLeadingIcon` not `showIcon`)            |\n| **Layer Names**        | Standard names (`Label`, `LeadingIcon`, `TrailingIcon`, `Spinner`)   |\n| **Token Usage**        | Semantic Nexus tokens, no hardcoded values or primitives             |\n| **Token Naming**       | Follows Nexus patterns (see divergence checks below)                 |\n| **States**             | Component includes hover, focus, active, disabled states as needed   |\n| **Description**        | Component has AI-readable description                                |\n| **Compound Structure** | Frame names match code exports (PascalCase, no spaces)               |\n\n#### Divergence-Specific Checks\n\nCross-reference Figma variables against `shadcn-divergences.md`:\n\n| Figma Uses              | Should Be                     | Rule                          |\n| ----------------------- | ----------------------------- | ----------------------------- |\n| `destructive/*`         | `error/*`                     | Nexus uses `error` naming     |\n| `accent/*`              | `background-hover` or `muted` | Accent removed in Nexus       |\n| `card/*`                | `container/*`                 | Renamed in Nexus              |\n| `primary` (no suffix)   | `primary-background`          | Explicit `-background` suffix |\n| `hover:*/90` or opacity | `*-background-hover`          | Semantic hover tokens         |\n| `border-input`          | `border-default`              | Renamed in Nexus              |\n\n#### Token Existence Check\n\nFor each Figma variable, verify it exists in `nexus.css`:\n\n```\nFigma: color/primary-background → Check: --color-primary-background exists? ✓\nFigma: color/accent-hover → Check: --color-accent-hover exists? ✗ (use background-hover)\n```\n\n### Phase 3: Generate Report\n\nOutput a focused report with issues grouped by severity.\n\n---\n\n## Output Format\n\n```markdown\n## Figma Analysis: {ComponentName}\n\n**Base:** {shadcn component or \"Custom\"}\n**Type:** {Simple | Compound}\n**Verdict:** {Ready | Needs Updates | Blocked}\n\n---\n\n### Issues\n\n#### Blocking (Must Fix)\n\n{If none: \"None\"}\n\n1. **{Issue Title}**\n   - Location: `{property/layer/token name}`\n   - Current: `{what Figma has}`\n   - Expected: `{what it should be}`\n   - Why: {brief reason}\n\n#### Should Fix\n\n{If none: \"None\"}\n\n1. **{Issue Title}**\n   - Location: `{property/layer/token name}`\n   - Current: `{what Figma has}`\n   - Expected: `{what it should be}`\n\n---\n\n### Token Mapping\n\n{Only show if there are token issues or divergences}\n\n| Figma Variable  | Nexus Equivalent | Status |\n| --------------- | ---------------- | ------ | --- | --- |\n| `{figma token}` | `{nexus token}`  | {✅    | ❌  | ⚠️} |\n\n---\n\n### Custom Additions\n\n{Only show if component has props/variants beyond shadcn base}\n\n| Addition | Type                | Convention | Notes |\n| -------- | ------------------- | ---------- | ----- | ------------ |\n| `{name}` | {Prop/Variant/Slot} | {✅        | ❌}   | {brief note} |\n\n---\n\n### Checklist\n\n- [{x| }] Property names match code\n- [{x| }] Property values lowercase\n- [{x| }] Layer names standard\n- [{x| }] Tokens exist in Nexus\n- [{x| }] No divergence violations\n- [{x| }] States defined (hover, focus, active, disabled)\n- [{x| }] Has component description\n```\n\n---\n\n## Severity Guidelines\n\n### Blocking\n\nIssues that **break code generation or cause runtime errors**:\n\n- Property name doesn''t match code prop (case-sensitive)\n- Token doesn''t exist in Nexus (will fail compilation)\n- Compound frame name doesn''t match export\n- Required prop missing\n\n### Should Fix\n\nIssues that **degrade quality but don''t break builds**:\n\n- Non-standard layer names (affects AI readability)\n- Missing description\n- Using deprecated token names (still works but inconsistent)\n\n---\n\n## Examples\n\n### Clean Report (No Issues)\n\n```markdown\n## Figma Analysis: Button\n\n**Base:** shadcn/button\n**Type:** Simple\n**Verdict:** Ready\n\n---\n\n### Issues\n\n#### Blocking (Must Fix)\n\nNone\n\n#### Should Fix\n\nNone\n\n---\n\n### Checklist\n\n- [x] Property names match code\n- [x] Property values lowercase\n- [x] Layer names standard\n- [x] Tokens exist in Nexus\n- [x] No divergence violations\n- [x] States defined (hover, focus, active, disabled)\n- [x] Has component description\n```\n\n### Report with Issues\n\n```markdown\n## Figma Analysis: Button\n\n**Base:** shadcn/button\n**Type:** Simple\n**Verdict:** Needs Updates\n\n---\n\n### Issues\n\n#### Blocking (Must Fix)\n\n1. **Invalid token reference**\n   - Location: `color/destructive-background`\n   - Current: `destructive-background`\n   - Expected: `error-background`\n   - Why: Nexus uses `error` naming, `destructive` tokens don''t exist\n\n2. **Property name mismatch**\n   - Location: Property `Size`\n   - Current: `Size` (PascalCase)\n   - Expected: `size` (lowercase)\n   - Why: Code prop is `size`, case-sensitive matching required\n\n#### Should Fix\n\n1. **Non-standard layer name**\n   - Location: Layer `Button Text`\n   - Current: `Button Text`\n   - Expected: `Label`\n\n2. **Missing component description**\n   - Location: Component description field\n   - Current: (empty)\n   - Expected: Description following format: \"{What} — {Use case}. Variants: {list}.\"\n\n---\n\n### Token Mapping\n\n| Figma Variable                 | Nexus Equivalent             | Status    |\n| ------------------------------ | ---------------------------- | --------- |\n| `color/destructive-background` | `--color-error-background`   | ❌ Rename |\n| `color/destructive-foreground` | `--color-error-foreground`   | ❌ Rename |\n| `color/accent-hover`           | `--color-background-hover`   | ❌ Rename |\n| `color/primary-background`     | `--color-primary-background` | ✅        |\n\n---\n\n### Checklist\n\n- [ ] Property names match code\n- [x] Property values lowercase\n- [ ] Layer names standard\n- [ ] Tokens exist in Nexus\n- [ ] No divergence violations\n- [ ] Has component description\n```\n\n---\n\n## Error Handling\n\n| Error                            | Action                                        |\n| -------------------------------- | --------------------------------------------- |\n| Figma MCP fails                  | Ask user to verify connection and permissions |\n| Component not in shadcn registry | Treat as custom, check conventions only       |\n| No variables used                | Flag as blocking — must use Figma variables   |\n| Can''t identify base component    | Ask user to specify                           |\n\n---\n\n## Key References\n\n| Reference                             | Purpose                              |\n| ------------------------------------- | ------------------------------------ |\n| `packages/tailwind/nexus.css`         | Source of truth for available tokens |\n| `.claude/rules/shadcn-divergences.md` | shadcn → Nexus mapping rules         |\n| `.claude/rules/figma.md`              | Figma-code parity conventions        |\n| `.claude/rules/components.md`         | Component structure requirements     |\n"},"lastSynced":"2026-03-07T03:53:41.290Z","agentAnalysis":{"suitability":{"en":"Perfect for Design Analysis Agents needing advanced Figma component validation and Nexus convention compliance.","zh":"适用于需要高级Figma组件验证和Nexus约定合规性的设计分析代理。","ja":"Figmaコンポーネントの高度な検証とNexus規約のコンプライアンスが必要な設計分析エージェントに適しています。","ko":"고급 Figma 컴포넌트 검증 및 Nexus 규약 준수에 필요한 설계 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de diseño que necesitan una validación avanzada de componentes de Figma y cumplimiento de convenciones de Nexus.","fr":"Parfait pour les agents d''analyse de conception nécessitant une validation avancée des composants Figma et le respect des conventions Nexus.","de":"Perfekt für Designanalyse-Agents, die eine erweiterte Figma-Komponenten-Validierung und Nexus-Konventions-Konformität benötigen.","pt":"Perfeito para Agentes de Análise de Design que necessitam de validação avançada de componentes Figma e conformidade com convenções Nexus.","ru":"Идеально подходит для агентов анализа дизайна, которым необходима продвинутая проверка компонентов Figma и соблюдение конвенций Nexus.","ar":"مثالي للوكلاء الذين يحتاجون إلى تحقق متقدم من مكونات Figma وامتثال لاتفاقيات Nexus."},"recommendation":{"en":"Empowers agents to validate design-code parity, token usage, and AI readability in Figma components, providing a focused issues list with fixes using Figma URLs and Nexus conventions.","zh":"赋予代理验证Figma组件的设计代码一致性、令牌使用和AI可读性，并提供一个使用Figma URL和Nexus约定进行修复的专注问题列表。","ja":"Figmaコンポーネントの設計コードの一貫性、トークンの使用、AIの可読性を検証するエージェントを可能にし、Figma URLとNexus規約を使用して修復するための焦点のある問題リストを提供します。","ko":"Figma 컴포넌트의 디자인 코드 일관성, 토큰 사용 및 AI 가독성을 검증하는 에이전트를 가능하게 하며 Figma URL 및 Nexus 규약을 사용하여 수정하는 데 중점을 둔 문제 목록을 제공합니다.","es":"Habilita a los agentes a validar la paridad entre diseño y código, el uso de tokens y la legibilidad de la IA en los componentes de Figma, proporcionando una lista de problemas enfocada con soluciones que utilizan URL de Figma y convenciones de Nexus.","fr":"Permet aux agents de valider la parité conception-code, l''utilisation de jetons et la lisibilité de l''IA dans les composants Figma, en fournissant une liste ciblée de problèmes avec des correctifs utilisant des URL Figma et des conventions Nexus.","de":"Ermächtigt Agents, die Design-Code-Parität, Token-Nutzung und KI-Lesbarkeit in Figma-Komponenten zu validieren, und bietet eine fokussierte Problemliste mit Lösungen, die Figma-URLs und Nexus-Konventionen nutzen.","pt":"Habilita os agentes a validar a paridade de design-código, uso de token e legibilidade de IA em componentes Figma, fornecendo uma lista de problemas focada com soluções usando URLs do Figma e convenções Nexus.","ru":"Позволяет агентам проверять паритет дизайна-кода, использование токенов и читаемость ИИ в компонентах Figma, предоставляя сосредоточенный список проблем с исправлениями, используя URL-адреса Figma и конвенции Nexus.","ar":"تمكّن الوكلاء من التحقق من تطابق التصميم-البرمجي، واستخدام الرموز، وقراءة الذكاء الاصطناعي في مكونات Figma، وتوفير قائمة محددة من المشكلات مع إصلاحات باستخدام عناوين URL من Figma واتفاقيات Nexus."},"useCases":{"en":["Validating Figma components against Nexus conventions","Analyzing design-code parity for consistency","Debugging token usage and AI readability issues in Figma designs"],"zh":["验证Figma组件是否符合Nexus约定","分析设计代码的一致性","在Figma设计中调试令牌使用和AI可读性问题"],"ja":["FigmaコンポーネントをNexus規約に従って検証する","設計コードの一貫性を分析する","Figmaデザインでのトークンの使用とAIの可読性の問題をデバッグする"],"ko":["Figma 컴포넌트를 Nexus 규약에 따라 검증する","디자인 코드의 일관성을 분석하는","Figma 디자인에서 토큰 사용 및 AI 가독성 문제를 디버깅하는"],"es":["Validar componentes de Figma frente a convenciones de Nexus","Analizar la paridad entre diseño y código para la coherencia","Depurar problemas de uso de tokens y legibilidad de la IA en diseños de Figma"],"fr":["Valider les composants Figma par rapport aux conventions Nexus","Analyser la parité conception-code pour la cohérence","Déboguer les problèmes d''utilisation de jetons et de lisibilité de l''IA dans les conceptions Figma"],"de":["Figma-Komponenten gegen Nexus-Konventionen validieren","Design-Code-Parität für Konsistenz analysieren","Token-Nutzungs- und KI-Lesbarkeitsprobleme in Figma-Designs debuggen"],"pt":["Validar componentes Figma contra convenções Nexus","Analizar a paridade de design-código para consistência","Depurar problemas de uso de token e legibilidade de IA em designs Figma"],"ru":["Проверка компонентов Figma на соответствие конвенциям Nexus","Анализ паритета дизайна-кода для последовательности","Отладка проблем использования токенов и читаемости ИИ в дизайнах Figma"],"ar":["التحقق من مكونات Figma مقابل اتفاقيات Nexus","تحليل تطابق التصميم-البرمجي من أجل الاتساق","تصحيح مشكلات استخدام الرموز وقراءة الذكاء الاصطناعي في تصميمات Figma"]},"limitations":{"en":["Requires Figma URL with node-id","Limited to Nexus conventions and Figma components"],"zh":["需要带有node-id的Figma URL","仅限于Nexus约定和Figma组件"],"ja":["node-idを含むFigma URLが必要","Nexus規約とFigmaコンポーネントに限定される"],"ko":["node-id를 포함하는 Figma URL이 필요","Nexus 규약 및 Figma 컴포넌트로 제한됨"],"es":["Requiere URL de Figma con node-id","Limitado a convenciones de Nexus y componentes de Figma"],"fr":["Nécessite une URL Figma avec un node-id","Limité aux conventions Nexus et aux composants Figma"],"de":["Benötigt Figma-URL mit node-id","Begrenzt auf Nexus-Konventionen und Figma-Komponenten"],"pt":["Exige URL do Figma com node-id","Limitado a convenções Nexus e componentes Figma"],"ru":["Требует URL-адреса Figma с node-id","Ограничен конвенциями Nexus и компонентами Figma"],"ar":["يتطلب عنوان URL من Figma مع node-id","محدود باتفاقيات Nexus ومكونات Figma"]},"version":4},"contentHash":"4e3600172f3c10aeff8af7de6a5fb1630dfa171fe38550400b7bf80bc91be08d","qualityScore":60}');
