INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mashharuki/Mistral-Worldwide-Hackathon/flask-api-development', 'flask-api-development', 'mashharuki', 'Mistral-Worldwide-Hackathon', 'community', 'flask-api-development mashharuki Mistral-Worldwide-Hackathon community The flask-api-development skill creates efficient Flask APIs with blueprints, SQLAlchemy, and JWT authentication, benefiting developers building RESTful APIs and microservices. 使用Flask构建高效的API，采用Blueprints进行模块化组织，SQLAlchemy进行ORM，JWT身份验证和错误处理 Flask API開発のためのガイド - Blueprint、SQLAlchemy、JWT認証を使用してRESTful APIを作成する Flask API 개발을 위한 가이드 - Blueprint, SQLAlchemy, JWT 인증을 사용하여 효율적인 API를 생성 Desarrolla APIs eficientes con Flask utilizando blueprints para una organización modular, SQLAlchemy para ORM y autenticación JWT. Créez des APIs efficaces avec Flask en utilisant des blueprints pour une organisation modulaire, SQLAlchemy pour ORM et l''authentification JWT. Erstellen Sie effiziente APIs mit Flask, indem Sie Blueprints für eine modulare Organisation, SQLAlchemy für ORM und JWT-Authentifizierung verwenden. Desenvolvimento de API Flask é uma habilidade que permite criar APIs eficientes com blueprints e SQLAlchemy. Aprenda a implementar autenticação JWT e validação de solicitação. Разработка API Flask - это навык, который позволяет создавать эффективные API с помощью blueprints и SQLAlchemy. Узнайте, как реализовать аутентификацию JWT и валидацию запросов с ИИ Агентами. تطوير واجهة برمجة تطبيقات Flask هو مهارة تسمح بإنشاء واجهات برمجة تطبيقات الكفء مع مخططات و SQLAlchemy. تعلم كيفية تنفيذ توثيق JWT والتحقق من الطلبات مع أدوات الذكاء الاصطناعي. how to use flask-api-development flask-api-development setup guide flask-api-development vs Django flask-api-development install what is flask-api-development flask-api-development tutorial flask-api-development alternative flask-api-development RESTful API flask-api-development JWT authentication Flask API开发 RESTful API Blueprints SQLAlchemy JWT身份验证 错误处理 AI工具 Python开发 Creates Flask APIs with blueprints for modular organization Utilizes SQLAlchemy for Object-Relational Mapping (ORM) Implements JWT authentication for secure API access Provides comprehensive error handling and request validation Follows REST principles for building efficient API endpoints flask-api-development is a skill for building efficient Flask APIs with modular organization, ORM, and authentication, following REST principles.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chicanoandres702/SentientAIBrowser/bats-testing-patterns', 'community', 'chicanoandres702', 'SentientAIBrowser', 'chicanoandres702/SentientAIBrowser', 'bats-testing-patterns', 0, 0, 60, '2026-03-07T03:42:47Z', '2026-03-07T13:07:19.906Z', 'bbf2ab75641bf998873c2a25e408a7a800a8e727d876ce1c56b20b889772ac78', '{"id":"chicanoandres702/SentientAIBrowser/bats-testing-patterns","name":"bats-testing-patterns","description":{"en":"bats-testing-patterns provides comprehensive guidance for writing unit tests for shell scripts using Bats. It benefits developers implementing test-driven development and automated testing.","zh":"Bats 测试模式提供了编写 shell 脚本单元测试的综合指南，包括测试模式、固定装置和生产级别 shell 测试的最佳实践","ja":"Bats テスティング パターンは、シェル スクリプトのユニット テストを記述するための包括的なガイドを提供します。テスト パターン、フィクスチャ、および生产レベルのシェル テストのベスト プラクティスが含まれます","ko":"Bats 테스트 패턴은 쉘 스크립트 단위 테스트를 작성하기 위한 포괄적인 가이드를 제공합니다. 테스트 패턴, 고정 장치 및 생산급 쉘 테스트의 모범 사례가 포함됩니다","es":"Bats Testing Patterns ofrece una guía completa para escribir pruebas unitarias para scripts de shell. Aprende a implementar TDD y a configurar pruebas automatizadas en pipelines de CI/CD","fr":"Bats Testing Patterns propose un guide complet pour écrire des tests unitaires pour les scripts shell. Découvrez comment implémenter le TDD et configurer des tests automatisés dans les pipelines de CI/CD","de":"Bats-Testmuster bietet eine umfassende Anleitung zum Schreiben von Unit-Tests für Shell-Skripte. Erfahren Sie, wie Sie TDD implementieren und automatisierte Tests in CI/CD-Pipelines konfigurieren","pt":"Bats Testing Patterns fornece orientação abrangente para escrita de testes unitários para scripts shell. Inclui padrões de teste, fixtures e boas práticas.","ru":"Шаблоны тестирования Bats предоставляют комплексное руководство по написанию unit-тестов для скриптов shell. Включают шаблоны тестирования, фикстуры и лучшие практики.","ar":"أنماط اختبار Bats توفر إرشادات شاملة لكتابة الاختبارات الوحدوية للبرامج النصية. تشمل أنماط الاختبار، الإعدادات الثابتة وأفضل الممارسات."},"seo":{"title":{"en":"bats-testing-patterns: Comprehensive Shell Testing Setup ...","zh":"Bats 测试模式设置指南 - Shell 脚本自动化测试","ja":"Bats テスティング パターン設定ガイド - Bash Automated Testing System","ko":"Bats 테스트 패턴 설정 가이드 - 쉘 스크립트 자동화 테스트","es":"Guía de configuración para Bats Testing Patterns","fr":"Guide de mise en place des modèles de test Bats","de":"Einrichtungsleitfaden für Bats-Testmuster","pt":"Guia de Configuração para Bats Testing Patterns","ru":"Настройка шаблонов тестирования Bats: ИИ Агенты","ar":"دليل إعداد أنماط اختبار Bats"},"description":{"en":"Unlock robust shell testing with bats-testing-patterns. Discover how to write unit tests, implement TDD, and automate testing in CI/CD pipelines. Get started...","zh":"使用 Bats 测试模式为您的 shell 脚本创建全面单元测试，包括测试模式、固定装置和生产级别 shell 测试的最佳实践","ja":"Bats テスティング パターンを使用して、シェル スクリプトの包括的なユニット テストを作成します。テスト パターン、フィクスチャ、および生产レベルのシェル テストのベスト プラクティスが含まれます","ko":"Bats 테스트 패턴을 사용하여 쉘 스크립트에 대한 포괄적인 단위 테스트를 생성합니다. 테스트 패턴, 고정 장치 및 생산급 쉘 테스트의 모범 사례가 포함됩니다","es":"Aprende a escribir pruebas unitarias exhaustivas para scripts de shell con Bats. Mejora tus habilidades en pruebas automatizadas y TDD","fr":"Découvrez comment écrire des tests unitaires complets pour les scripts shell avec Bats. Améliorez vos compétences en tests automatisés et TDD","de":"Erfahren Sie, wie Sie umfassende Unit-Tests für Shell-Skripte mit Bats schreiben. Verbessern Sie Ihre Fähigkeiten im Bereich automatisierter Tests und TDD","pt":"Aprenda a escrever testes unitários para scripts shell com Bats. Confira as melhores práticas e padrões de teste para produção.","ru":"Изучите шаблоны тестирования Bats для скриптов shell. Узнайте о лучших практиках и тестировании в производстве с ИИ Агентами.","ar":"تعلم كيفية كتابة الاختبارات الوحدوية للبرامج النصية باستخدام Bats. استكشف أفضل الممارسات وأنماط الاختبار للإنتاج."},"definition":{"en":"bats-testing-patterns is a comprehensive testing framework for shell scripts, providing guidance on test patterns, fixtures, and best practices for production-grade testing.","zh":"Bats 测试模式是一种用于为 shell 脚本创建单元测试的方法，包括测试模式、固定装置和生产级别 shell 测试的最佳实践","ja":"Bats テスティング パターンは、シェル スクリプトのユニット テストを作成するための方法であり、テスト パターン、フィクスチャ、および生产レベルのシェル テストのベスト プラクティスが含まれます","ko":"Bats 테스트 패턴은 쉘 스크립트에 대한 단위 테스트를 생성하기 위한 방법으로, 테스트 패턴, 고정 장치 및 생산급 쉘 테스트의 모범 사례가 포함됩니다","es":"Bats Testing Patterns es un conjunto de patrones de prueba para scripts de shell que utiliza Bats, el sistema de prueba automático de Bash","fr":"Bats Testing Patterns est un ensemble de modèles de test pour les scripts shell qui utilise Bats, le système de test automatisé de Bash","de":"Bats-Testmuster ist eine Sammlung von Testmustern für Shell-Skripte, die Bats, das automatisierte Testsystem von Bash, verwendet","pt":"Bats Testing Patterns é uma abordagem para testar scripts shell de forma automatizada.","ru":"Шаблоны тестирования Bats - это подход к автоматизированному тестированию скриптов shell.","ar":"أنماط اختبار Bats هي طريقة لاختبار البرامج النصية بشكل تلقائي."},"features":{"en":["Provides comprehensive guidance for writing unit tests for shell scripts using Bats","Supports test-driven development (TDD) for scripts","Enables automated testing in CI/CD pipelines","Facilitates testing edge cases and error conditions","Validates behavior across different shell environments"],"zh":["支持 shell 脚本单元测试","包括测试模式和固定装置","提供生产级别 shell 测试的最佳实践","支持测试驱动开发（TDD）","支持 CI/CD 流水线中的自动化测试"],"ja":["シェル スクリプトのユニット テストをサポート","テスト パターンとフィクスチャを含む","生产レベルのシェル テストのベスト プラクティスを提供","テスト駆動開発（TDD）をサポート","CI/CD パイプラインでの自動化テストをサポート"],"ko":["쉘 스크립트 단위 테스트 지원","테스트 패턴과 고정 장치 포함","생산급 쉘 테스트의 모범 사례 제공","테스트 주도 개발（TDD）지원","CI/CD 파이프라인에서의 자동화 테스트 지원"],"es":["Patrones de prueba para scripts de shell","Implementación de TDD para scripts","Configuración de pruebas automatizadas en pipelines de CI/CD","Pruebas de casos límite y condiciones de error","Validación de comportamiento en diferentes shells"],"fr":["Modèles de test pour les scripts shell","Implémentation du TDD pour les scripts","Configuration des tests automatisés dans les pipelines de CI/CD","Tests de cas limites et conditions d''erreur","Validation du comportement sur différents shells"],"de":["Testmuster für Shell-Skripte","Implementierung von TDD für Skripte","Konfiguration von automatisierten Tests in CI/CD-Pipelines","Tests von Randfällen und Fehlerbedingungen","Validierung von Verhalten auf unterschiedlichen Shells"],"pt":["Testes unitários para scripts shell","Padrões de teste para produção","Fixtures para testes","Implementação de TDD para scripts","Testes automatizados em pipelines CI/CD"],"ru":["Unit-тесты для скриптов shell","Шаблоны тестирования для производства","Фикстуры для тестов","Реализация TDD для скриптов","Автоматизированное тестирование в конвейерах CI/CD"],"ar":["الاختبارات الوحدوية للبرامج النصية","أنماط الاختبار للإنتاج","الإعدادات الثابتة للاختبارات","تنفيذ التطوير القائم على الاختبار للاسครبتات","الاختبارات الآلية في خطوط أنابيب CI/CD"]},"keywords":{"en":["how to use bats-testing-patterns","bats-testing-patterns tutorial","bats-testing-patterns alternative","bats-testing-patterns vs bash unit testing","bats-testing-patterns install","bats-testing-patterns setup guide","shell script testing best practices","automated shell testing"],"zh":["Bats 测试模式","shell 脚本单元测试","测试驱动开发","CI/CD 自动化测试","生产级别 shell 测试","Bash Automated Testing System"],"ja":["Bats テスティング パターン","シェル スクリプトのユニット テスト","テスト駆動開発","CI/CD 自動化テスト","生产レベルのシェル テスト","Bash Automated Testing System"],"ko":["Bats 테스트 패턴","쉘 스크립트 단위 테스트","테스트 주도 개발","CI/CD 자동화 테스트","생산급 쉘 테스트","Bash Automated Testing System"],"es":["Bats Testing Patterns","pruebas unitarias para scripts de shell","TDD para scripts","pruebas automatizadas en CI/CD","patrones de prueba para shell","herramientas de prueba para Bash"],"fr":["Bats Testing Patterns","tests unitaires pour les scripts shell","TDD pour les scripts","tests automatisés dans les pipelines de CI/CD","modèles de test pour les scripts shell","outils de test pour Bash"],"de":["Bats-Testmuster","Unit-Tests für Shell-Skripte","TDD für Skripte","automatisierte Tests in CI/CD-Pipelines","Testmuster für Shell-Skripte","Testtools für Bash"],"pt":["bats testing patterns","testes unitários para scripts shell","tdd para scripts","testes automatizados em ci/cd","padrões de teste para produção","fixturess para testes"],"ru":["шаблоны тестирования bats","unit-тесты для скриптов shell","tdd для скриптов","автоматизированное тестирование в ci/cd","шаблоны тестирования для производства","фикстуры для тестов"],"ar":["أنماط اختبار bats","الاختبارات الوحدوية للبرامج النصية","تطوير قائم على الاختبار للاسكربتات","الاختبارات الآلية في خطوط أنابيب ci/cd","أنماط الاختبار للإنتاج","الإعدادات الثابتة للاختبارات"]}},"owner":"chicanoandres702","repo":"SentientAIBrowser","repoPath":"chicanoandres702/SentientAIBrowser","stars":0,"forks":0,"updatedAt":"2026-03-07T03:42:47Z","topics":[],"category":"community","skillMd":{"name":"bats-testing-patterns","description":"Master Bash Automated Testing System (Bats) for comprehensive shell script testing. Use when writing tests for shell scripts, CI/CD pipelines, or requiring test-driven development of shell utilities.","bodyPreview":"# Bats Testing Patterns\n\nComprehensive guidance for writing comprehensive unit tests for shell scripts using Bats (Bash Automated Testing System), including test patterns, fixtures, and best practices for production-grade shell testing.\n\n## When to Use This Skill\n\n- Writing unit tests for shell scripts\n- Implementing test-driven development (TDD) for scripts\n- Setting up automated testing in CI/CD pipelines\n- Testing edge cases and error conditions\n- Validating behavior across different shell en","body":"# Bats Testing Patterns\n\nComprehensive guidance for writing comprehensive unit tests for shell scripts using Bats (Bash Automated Testing System), including test patterns, fixtures, and best practices for production-grade shell testing.\n\n## When to Use This Skill\n\n- Writing unit tests for shell scripts\n- Implementing test-driven development (TDD) for scripts\n- Setting up automated testing in CI/CD pipelines\n- Testing edge cases and error conditions\n- Validating behavior across different shell environments\n- Building maintainable test suites for scripts\n- Creating fixtures for complex test scenarios\n- Testing multiple shell dialects (bash, sh, dash)\n\n## Bats Fundamentals\n\n### What is Bats?\n\nBats (Bash Automated Testing System) is a TAP (Test Anything Protocol) compliant testing framework for shell scripts that provides:\n- Simple, natural test syntax\n- TAP output format compatible with CI systems\n- Fixtures and setup/teardown support\n- Assertion helpers\n- Parallel test execution\n\n### Installation\n\n```bash\n# macOS with Homebrew\nbrew install bats-core\n\n# Ubuntu/Debian\ngit clone https://github.com/bats-core/bats-core.git\ncd bats-core\n./install.sh /usr/local\n\n# From npm (Node.js)\nnpm install --global bats\n\n# Verify installation\nbats --version\n```\n\n### File Structure\n\n```\nproject/\n├── bin/\n│   ├── script.sh\n│   └── helper.sh\n├── tests/\n│   ├── test_script.bats\n│   ├── test_helper.sh\n│   ├── fixtures/\n│   │   ├── input.txt\n│   │   └── expected_output.txt\n│   └── helpers/\n│       └── mocks.bash\n└── README.md\n```\n\n## Basic Test Structure\n\n### Simple Test File\n\n```bash\n#!/usr/bin/env bats\n\n# Load test helper if present\nload test_helper\n\n# Setup runs before each test\nsetup() {\n    export TMPDIR=$(mktemp -d)\n}\n\n# Teardown runs after each test\nteardown() {\n    rm -rf \"$TMPDIR\"\n}\n\n# Test: simple assertion\n@test \"Function returns 0 on success\" {\n    run my_function \"input\"\n    [ \"$status\" -eq 0 ]\n}\n\n# Test: output verification\n@test \"Function outputs correct result\" {\n    run my_function \"test\"\n    [ \"$output\" = \"expected output\" ]\n}\n\n# Test: error handling\n@test \"Function returns 1 on missing argument\" {\n    run my_function\n    [ \"$status\" -eq 1 ]\n}\n```\n\n## Assertion Patterns\n\n### Exit Code Assertions\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Command succeeds\" {\n    run true\n    [ \"$status\" -eq 0 ]\n}\n\n@test \"Command fails as expected\" {\n    run false\n    [ \"$status\" -ne 0 ]\n}\n\n@test \"Command returns specific exit code\" {\n    run my_function --invalid\n    [ \"$status\" -eq 127 ]\n}\n\n@test \"Can capture command result\" {\n    run echo \"hello\"\n    [ $status -eq 0 ]\n    [ \"$output\" = \"hello\" ]\n}\n```\n\n### Output Assertions\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Output matches string\" {\n    result=$(echo \"hello world\")\n    [ \"$result\" = \"hello world\" ]\n}\n\n@test \"Output contains substring\" {\n    result=$(echo \"hello world\")\n    [[ \"$result\" == *\"world\"* ]]\n}\n\n@test \"Output matches pattern\" {\n    result=$(date +%Y)\n    [[ \"$result\" =~ ^[0-9]{4}$ ]]\n}\n\n@test \"Multi-line output\" {\n    run printf \"line1\\nline2\\nline3\"\n    [ \"$output\" = \"line1\nline2\nline3\" ]\n}\n\n@test \"Lines variable contains output\" {\n    run printf \"line1\\nline2\\nline3\"\n    [ \"${lines[0]}\" = \"line1\" ]\n    [ \"${lines[1]}\" = \"line2\" ]\n    [ \"${lines[2]}\" = \"line3\" ]\n}\n```\n\n### File Assertions\n\n```bash\n#!/usr/bin/env bats\n\n@test \"File is created\" {\n    [ ! -f \"$TMPDIR/output.txt\" ]\n    my_function > \"$TMPDIR/output.txt\"\n    [ -f \"$TMPDIR/output.txt\" ]\n}\n\n@test \"File contents match expected\" {\n    my_function > \"$TMPDIR/output.txt\"\n    [ \"$(cat \"$TMPDIR/output.txt\")\" = \"expected content\" ]\n}\n\n@test \"File is readable\" {\n    touch \"$TMPDIR/test.txt\"\n    [ -r \"$TMPDIR/test.txt\" ]\n}\n\n@test \"File has correct permissions\" {\n    touch \"$TMPDIR/test.txt\"\n    chmod 644 \"$TMPDIR/test.txt\"\n    [ \"$(stat -f %OLp \"$TMPDIR/test.txt\")\" = \"644\" ]\n}\n\n@test \"File size is correct\" {\n    echo -n \"12345\" > \"$TMPDIR/test.txt\"\n    [ \"$(wc -c < \"$TMPDIR/test.txt\")\" -eq 5 ]\n}\n```\n\n## Setup and Teardown Patterns\n\n### Basic Setup and Teardown\n\n```bash\n#!/usr/bin/env bats\n\nsetup() {\n    # Create test directory\n    TEST_DIR=$(mktemp -d)\n    export TEST_DIR\n\n    # Source script under test\n    source \"${BATS_TEST_DIRNAME}/../bin/script.sh\"\n}\n\nteardown() {\n    # Clean up temporary directory\n    rm -rf \"$TEST_DIR\"\n}\n\n@test \"Test using TEST_DIR\" {\n    touch \"$TEST_DIR/file.txt\"\n    [ -f \"$TEST_DIR/file.txt\" ]\n}\n```\n\n### Setup with Resources\n\n```bash\n#!/usr/bin/env bats\n\nsetup() {\n    # Create directory structure\n    mkdir -p \"$TMPDIR/data/input\"\n    mkdir -p \"$TMPDIR/data/output\"\n\n    # Create test fixtures\n    echo \"line1\" > \"$TMPDIR/data/input/file1.txt\"\n    echo \"line2\" > \"$TMPDIR/data/input/file2.txt\"\n\n    # Initialize environment\n    export DATA_DIR=\"$TMPDIR/data\"\n    export INPUT_DIR=\"$DATA_DIR/input\"\n    export OUTPUT_DIR=\"$DATA_DIR/output\"\n}\n\nteardown() {\n    rm -rf \"$TMPDIR/data\"\n}\n\n@test \"Processes input files\" {\n    run my_process_script \"$INPUT_DIR\" \"$OUTPUT_DIR\"\n    [ \"$status\" -eq 0 ]\n    [ -f \"$OUTPUT_DIR/file1.txt\" ]\n}\n```\n\n### Global Setup/Teardown\n\n```bash\n#!/usr/bin/env bats\n\n# Load shared setup from test_helper.sh\nload test_helper\n\n# setup_file runs once before all tests\nsetup_file() {\n    export SHARED_RESOURCE=$(mktemp -d)\n    echo \"Expensive setup\" > \"$SHARED_RESOURCE/data.txt\"\n}\n\n# teardown_file runs once after all tests\nteardown_file() {\n    rm -rf \"$SHARED_RESOURCE\"\n}\n\n@test \"First test uses shared resource\" {\n    [ -f \"$SHARED_RESOURCE/data.txt\" ]\n}\n\n@test \"Second test uses shared resource\" {\n    [ -d \"$SHARED_RESOURCE\" ]\n}\n```\n\n## Mocking and Stubbing Patterns\n\n### Function Mocking\n\n```bash\n#!/usr/bin/env bats\n\n# Mock external command\nmy_external_tool() {\n    echo \"mocked output\"\n    return 0\n}\n\n@test \"Function uses mocked tool\" {\n    export -f my_external_tool\n    run my_function\n    [[ \"$output\" == *\"mocked output\"* ]]\n}\n```\n\n### Command Stubbing\n\n```bash\n#!/usr/bin/env bats\n\nsetup() {\n    # Create stub directory\n    STUBS_DIR=\"$TMPDIR/stubs\"\n    mkdir -p \"$STUBS_DIR\"\n\n    # Add to PATH\n    export PATH=\"$STUBS_DIR:$PATH\"\n}\n\ncreate_stub() {\n    local cmd=\"$1\"\n    local output=\"$2\"\n    local code=\"${3:-0}\"\n\n    cat > \"$STUBS_DIR/$cmd\" <<EOF\n#!/bin/bash\necho \"$output\"\nexit $code\nEOF\n    chmod +x \"$STUBS_DIR/$cmd\"\n}\n\n@test \"Function works with stubbed curl\" {\n    create_stub curl \"{ \\\"status\\\": \\\"ok\\\" }\" 0\n    run my_api_function\n    [ \"$status\" -eq 0 ]\n}\n```\n\n### Variable Stubbing\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Function handles environment override\" {\n    export MY_SETTING=\"override_value\"\n    run my_function\n    [ \"$status\" -eq 0 ]\n    [[ \"$output\" == *\"override_value\"* ]]\n}\n\n@test \"Function uses default when var unset\" {\n    unset MY_SETTING\n    run my_function\n    [ \"$status\" -eq 0 ]\n    [[ \"$output\" == *\"default\"* ]]\n}\n```\n\n## Fixture Management\n\n### Using Fixture Files\n\n```bash\n#!/usr/bin/env bats\n\n# Fixture directory: tests/fixtures/\n\nsetup() {\n    FIXTURES_DIR=\"${BATS_TEST_DIRNAME}/fixtures\"\n    WORK_DIR=$(mktemp -d)\n    export WORK_DIR\n}\n\nteardown() {\n    rm -rf \"$WORK_DIR\"\n}\n\n@test \"Process fixture file\" {\n    # Copy fixture to work directory\n    cp \"$FIXTURES_DIR/input.txt\" \"$WORK_DIR/input.txt\"\n\n    # Run function\n    run my_process_function \"$WORK_DIR/input.txt\"\n\n    # Compare output\n    diff \"$WORK_DIR/output.txt\" \"$FIXTURES_DIR/expected_output.txt\"\n}\n```\n\n### Dynamic Fixture Generation\n\n```bash\n#!/usr/bin/env bats\n\ngenerate_fixture() {\n    local lines=\"$1\"\n    local file=\"$2\"\n\n    for i in $(seq 1 \"$lines\"); do\n        echo \"Line $i content\" >> \"$file\"\n    done\n}\n\n@test \"Handle large input file\" {\n    generate_fixture 1000 \"$TMPDIR/large.txt\"\n    run my_function \"$TMPDIR/large.txt\"\n    [ \"$status\" -eq 0 ]\n    [ \"$(wc -l < \"$TMPDIR/large.txt\")\" -eq 1000 ]\n}\n```\n\n## Advanced Patterns\n\n### Testing Error Conditions\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Function fails with missing file\" {\n    run my_function \"/nonexistent/file.txt\"\n    [ \"$status\" -ne 0 ]\n    [[ \"$output\" == *\"not found\"* ]]\n}\n\n@test \"Function fails with invalid input\" {\n    run my_function \"\"\n    [ \"$status\" -ne 0 ]\n}\n\n@test \"Function fails with permission denied\" {\n    touch \"$TMPDIR/readonly.txt\"\n    chmod 000 \"$TMPDIR/readonly.txt\"\n    run my_function \"$TMPDIR/readonly.txt\"\n    [ \"$status\" -ne 0 ]\n    chmod 644 \"$TMPDIR/readonly.txt\"  # Cleanup\n}\n\n@test \"Function provides helpful error message\" {\n    run my_function --invalid-option\n    [ \"$status\" -ne 0 ]\n    [[ \"$output\" == *\"Usage:\"* ]]\n}\n```\n\n### Testing with Dependencies\n\n```bash\n#!/usr/bin/env bats\n\nsetup() {\n    # Check for required tools\n    if ! command -v jq &>/dev/null; then\n        skip \"jq is not installed\"\n    fi\n\n    export SCRIPT=\"${BATS_TEST_DIRNAME}/../bin/script.sh\"\n}\n\n@test \"JSON parsing works\" {\n    skip_if ! command -v jq &>/dev/null\n    run my_json_parser ''{\"key\": \"value\"}''\n    [ \"$status\" -eq 0 ]\n}\n```\n\n### Testing Shell Compatibility\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Script works in bash\" {\n    bash \"${BATS_TEST_DIRNAME}/../bin/script.sh\" arg1\n}\n\n@test \"Script works in sh (POSIX)\" {\n    sh \"${BATS_TEST_DIRNAME}/../bin/script.sh\" arg1\n}\n\n@test \"Script works in dash\" {\n    if command -v dash &>/dev/null; then\n        dash \"${BATS_TEST_DIRNAME}/../bin/script.sh\" arg1\n    else\n        skip \"dash not installed\"\n    fi\n}\n```\n\n### Parallel Execution\n\n```bash\n#!/usr/bin/env bats\n\n@test \"Multiple independent operations\" {\n    run bash -c ''for i in {1..10}; do\n        my_operation \"$i\" &\n    done\n    wait''\n    [ \"$status\" -eq 0 ]\n}\n\n@test \"Concurrent file operations\" {\n    for i in {1..5}; do\n        my_function \"$TMPDIR/file$i\" &\n    done\n    wait\n    [ -f \"$TMPDIR/file1\" ]\n    [ -f \"$TMPDIR/file5\" ]\n}\n```\n\n## Test Helper Pattern\n\n### test_helper.sh\n\n```bash\n#!/usr/bin/env bash\n\n# Source script under test\nexport SCRIPT_DIR=\"${BATS_TEST_DIRNAME%/*}/bin\"\n\n# Common test utilities\nassert_file_exists() {\n    if [ ! -f \"$1\" ]; then\n        echo \"Expected file to exist: $1\"\n        return 1\n    fi\n}\n\nassert_file_equals() {\n    local file=\"$1\"\n    local expected=\"$2\"\n\n    if [ ! -f \"$file\" ]; then\n        echo \"File does not exist: $file\"\n        return 1\n    fi\n\n    local actual=$(cat \"$file\")\n    if [ \"$actual\" != \"$expected\" ]; then\n        echo \"File contents do not match\"\n        echo \"Expected: $expected\"\n        echo \"Actual: $actual\"\n        return 1\n    fi\n}\n\n# Create temporary test directory\nsetup_test_dir() {\n    export TEST_DIR=$(mktemp -d)\n}\n\ncleanup_test_dir() {\n    rm -rf \"$TEST_DIR\"\n}\n```\n\n## Integration with CI/CD\n\n### GitHub Actions Workflow\n\n```yaml\nname: Tests\n\non: [push, pull_request]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n\n    steps:\n      - uses: actions/checkout@v3\n\n      - name: Install Bats\n        run: |\n          npm install --global bats\n\n      - name: Run Tests\n        run: |\n          bats tests/*.bats\n\n      - name: Run Tests with Tap Reporter\n        run: |\n          bats tests/*.bats --tap | tee test_output.tap\n```\n\n### Makefile Integration\n\n```makefile\n.PHONY: test test-verbose test-tap\n\ntest:\n\tbats tests/*.bats\n\ntest-verbose:\n\tbats tests/*.bats --verbose\n\ntest-tap:\n\tbats tests/*.bats --tap\n\ntest-parallel:\n\tbats tests/*.bats --parallel 4\n\ncoverage: test\n\t# Optional: Generate coverage reports\n```\n\n## Best Practices\n\n1. **Test one thing per test** - Single responsibility principle\n2. **Use descriptive test names** - Clearly states what is being tested\n3. **Clean up after tests** - Always remove temporary files in teardown\n4. **Test both success and failure paths** - Don''t just test happy path\n5. **Mock external dependencies** - Isolate unit under test\n6. **Use fixtures for complex data** - Makes tests more readable\n7. **Run tests in CI/CD** - Catch regressions early\n8. **Test across shell dialects** - Ensure portability\n9. **Keep tests fast** - Run in parallel when possible\n10. **Document complex test setup** - Explain unusual patterns\n\n## Resources\n\n- **Bats GitHub**: https://github.com/bats-core/bats-core\n- **Bats Documentation**: https://bats-core.readthedocs.io/\n- **TAP Protocol**: https://testanything.org/\n- **Test-Driven Development**: https://en.wikipedia.org/wiki/Test-driven_development\n"},"lastSynced":"2026-03-07T13:07:19.906Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing comprehensive shell script testing using Bats","zh":"适合需要使用Bats进行全面shell脚本测试的自动化代理","ja":"Batsを使用した包括的なシェルスクリプトテストが必要な自動化エージェントに適しています","ko":"Bats를 사용하여 포괄적인 셸 스크립트 테스트가 필요한 자동화 에이전트에 적합합니다","es":"Perfecto para Agentes de Automatización que necesitan pruebas de scripts de shell exhaustivas utilizando Bats","fr":"Parfait pour les Agents d''Automatisation ayant besoin d''un test de script shell complet utilisant Bats","de":"Perfekt für Automatisierungsagenten, die umfassende Shell-Skript-Tests mit Bats benötigen","pt":"Perfeito para Agentes de Automação que precisam de testes abrangentes de scripts de shell usando Bats","ru":"Идеально подходит для агентов автоматизации, которым необходимы полные тесты shell-скриптов с использованием Bats","ar":"مثالي لعميل التutomatiوn الذين يحتاجون إلى اختبارات شاملة لبرامج النص البرمجي للshell باستخدام Bats"},"recommendation":{"en":"Empowers agents to write unit tests for shell scripts using Bats, including test patterns, fixtures, and best practices for production-grade shell testing, leveraging Bash Automated Testing System for automated testing in CI/CD pipelines","zh":"赋予代理编写使用Bats的shell脚本单元测试的能力，包括测试模式、固定装置和生产级shell测试的最佳实践，利用Bash Automated Testing System在CI/CD管道中进行自动化测试","ja":"Batsを使用してシェルスクリプトのユニットテストを記述するエージェントを可能にし、テストパターン、フィクスチャ、生产級のシェルテストのベストプラクティスを含み、CI/CDパイプラインでの自動テストのためのBash Automated Testing Systemを利用する","ko":"Bats를 사용하여 셸 스크립트의 단위 테스트를 작성할 수 있는 에이전트를 강화하고, 테스트 패턴, 고정 장치, 생산급 셸 테스트의 최선의 실践을 포함하며, CI/CD 파이프라인에서 자동 테스트를 위한 Bash Automated Testing System을 활용함","es":"Habilita a los agentes a escribir pruebas unitarias para scripts de shell utilizando Bats, incluyendo patrones de prueba, fixtures y mejores prácticas para pruebas de shell de grado de producción, aprovechando el Sistema de Pruebas Automatizadas de Bash para pruebas automatizadas en tuberías de CI/CD","fr":"Permet aux agents d''écrire des tests unitaires pour les scripts shell en utilisant Bats, y compris les modèles de test, les fixtures et les meilleures pratiques pour les tests shell de niveau production, en exploitant le Système de Test Automatisé Bash pour les tests automatisés dans les pipelines CI/CD","de":"Ermächtigt Agenten, Unit-Tests für Shell-Skripte unter Verwendung von Bats zu schreiben, einschließlich Testmustern, Fixtures und Best Practices für Produktions-Shell-Tests, indem es das Bash-Automated-Testing-System für automatisierte Tests in CI/CD-Pipelines nutzt","pt":"Habilita os agentes a escrever testes unitários para scripts de shell usando Bats, incluindo padrões de teste, fixtures e as melhores práticas para testes de shell de nível de produção, aproveitando o Bash Automated Testing System para testes automatizados em pipelines de CI/CD","ru":"Наделяет агентов возможностью писать модульные тесты для shell-скриптов с использованием Bats, включая шаблоны тестирования, фикстуры и лучшие практики для тестирования shell-продукции, используя Bash Automated Testing System для автоматизированного тестирования в конвейерах CI/CD","ar":"يمنح الوكلاء khảية كتابة اختبارات الوحدة لبرامج النص البرمجي للshell باستخدام Bats، بما في ذلك أنماط الاختبار والإصلاحات وأفضل الممارسات لاختبارات shell من الدرجة الإنتاجية، واستخدام نظام اختبار تلقائي Bash للاختبارات الآلية في خطوط أنابيب CI/CD"},"useCases":{"en":["Writing unit tests for shell scripts","Implementing test-driven development for scripts","Testing edge cases and error conditions in shell scripts"],"zh":["编写shell脚本的单元测试","为脚本实现测试驱动开发","测试shell脚本的边缘情况和错误条件"],"ja":["シェルスクリプトのユニットテストを記述する","スクリプトのためのテスト駆動開発を実装する","シェルスクリプトのエッジケースとエラーコンディションをテストする"],"ko":["셸 스크립트의 단위 테스트를 작성하기","스크립트를 위한 테스트 주도 개발을 구현하기","셸 스크립트의 에지 케이스와 오류 조건을 테스트하기"],"es":["Escritura de pruebas unitarias para scripts de shell","Implementación de desarrollo impulsado por pruebas para scripts","Pruebas de casos límite y condiciones de error en scripts de shell"],"fr":["Écriture de tests unitaires pour les scripts shell","Mise en œuvre du développement piloté par les tests pour les scripts","Tests de cas limites et de conditions d''erreur dans les scripts shell"],"de":["Schreiben von Unit-Tests für Shell-Skripte","Implementierung von testgetriebenem Entwicklung für Skripte","Testen von Randfällen und Fehlerbedingungen in Shell-Skripten"],"pt":["Escrever testes unitários para scripts de shell","Implementar desenvolvimento orientado a testes para scripts","Testar casos de bordo e condições de erro em scripts de shell"],"ru":["Написание модульных тестов для shell-скриптов","Реализация разработки, ориентированной на тестирование, для скриптов","Тестирование граничных случаев и условий ошибки в shell-скриптах"],"ar":["كتابة اختبارات الوحدة لبرامج النص البرمجي للshell","تنفيذ التطوير الموجه للاختبار لبرامج النص البرمجي","اختبار الحالات الحدودية وشروط الخطأ في برامج النص البرمجي للshell"]},"limitations":{"en":["Requires Bats installation","Limited to shell script testing","Bash environment required"],"zh":["需要Bats安装","仅限shell脚本测试","需要Bash环境"],"ja":["Batsのインストールが必要","シェルスクリプトテストに限定される","Bash環境が必要"],"ko":["Bats 설치가 필요함","셸 스크립트 테스트에만 제한됨","Bash 환경이 필요함"],"es":["Requiere instalación de Bats","Limitado a pruebas de scripts de shell","Entorno de Bash requerido"],"fr":["Nécessite l''installation de Bats","Limité aux tests de scripts shell","Environnement Bash requis"],"de":["Benötigt Bats-Installation","Begrenzt auf Shell-Skript-Tests","Bash-Umgebung erforderlich"],"pt":["Requer instalação do Bats","Limitado a testes de scripts de shell","Ambiente Bash necessário"],"ru":["Требуется установка Bats","Ограничен тестированием shell-скриптов","Требуется среда Bash"],"ar":["يتطلب تثبيت Bats","محدود باختبارات برامج النص البرمجي للshell","يتطلب بيئة Bash"]},"version":4},"contentHash":"bbf2ab75641bf998873c2a25e408a7a800a8e727d876ce1c56b20b889772ac78","qualityScore":60}');
