INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chicanoandres702/SentientAIBrowser/bats-testing-patterns', 'bats-testing-patterns', 'chicanoandres702', 'SentientAIBrowser', 'community', 'bats-testing-patterns chicanoandres702 SentientAIBrowser community bats-testing-patterns provides comprehensive guidance for writing unit tests for shell scripts using Bats. It benefits developers implementing test-driven development and automated testing. Bats 测试模式提供了编写 shell 脚本单元测试的综合指南，包括测试模式、固定装置和生产级别 shell 测试的最佳实践 Bats テスティング パターンは、シェル スクリプトのユニット テストを記述するための包括的なガイドを提供します。テスト パターン、フィクスチャ、および生产レベルのシェル テストのベスト プラクティスが含まれます Bats 테스트 패턴은 쉘 스크립트 단위 테스트를 작성하기 위한 포괄적인 가이드를 제공합니다. 테스트 패턴, 고정 장치 및 생산급 쉘 테스트의 모범 사례가 포함됩니다 Bats Testing Patterns ofrece una guía completa para escribir pruebas unitarias para scripts de shell. Aprende a implementar TDD y a configurar pruebas automatizadas en pipelines de CI/CD Bats Testing Patterns propose un guide complet pour écrire des tests unitaires pour les scripts shell. Découvrez comment implémenter le TDD et configurer des tests automatisés dans les pipelines de CI/CD Bats-Testmuster bietet eine umfassende Anleitung zum Schreiben von Unit-Tests für Shell-Skripte. Erfahren Sie, wie Sie TDD implementieren und automatisierte Tests in CI/CD-Pipelines konfigurieren Bats Testing Patterns fornece orientação abrangente para escrita de testes unitários para scripts shell. Inclui padrões de teste, fixtures e boas práticas. Шаблоны тестирования Bats предоставляют комплексное руководство по написанию unit-тестов для скриптов shell. Включают шаблоны тестирования, фикстуры и лучшие практики. أنماط اختبار Bats توفر إرشادات شاملة لكتابة الاختبارات الوحدوية للبرامج النصية. تشمل أنماط الاختبار، الإعدادات الثابتة وأفضل الممارسات. how to use bats-testing-patterns bats-testing-patterns tutorial bats-testing-patterns alternative bats-testing-patterns vs bash unit testing bats-testing-patterns install bats-testing-patterns setup guide shell script testing best practices automated shell testing Bats 测试模式 shell 脚本单元测试 测试驱动开发 CI/CD 自动化测试 生产级别 shell 测试 Bash Automated Testing System Provides comprehensive guidance for writing unit tests for shell scripts using Bats Supports test-driven development (TDD) for scripts Enables automated testing in CI/CD pipelines Facilitates testing edge cases and error conditions Validates behavior across different shell environments bats-testing-patterns is a comprehensive testing framework for shell scripts, providing guidance on test patterns, fixtures, and best practices for production-grade testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marvinbiss/servicesartisans/supabase-audit-tables-list', 'community', 'marvinbiss', 'servicesartisans', 'marvinbiss/servicesartisans', 'supabase-audit-tables-list', 0, 0, 60, '2026-03-06T12:56:32Z', '2026-03-07T03:58:20.953Z', '9bb41b6c3ec884acfdfb5846ebf5e205456737cc822da3f70f24f1cea72f9904', '{"id":"marvinbiss/servicesartisans/supabase-audit-tables-list","name":"supabase-audit-tables-list","description":{"en":"The supabase-audit-tables-list skill enables AI agents to list exposed tables while progressively updating context files and logging actions for secure auditing, benefiting developers and security teams.","zh":"Supabase 审计表列表功能要求进行实时文件更新和日志记录，确保技能在中断或崩溃时保留所有发现结果","ja":"Supabase オーディットテーブルリスト機能は、進行的なファイル更新とログ記録を必要とし、スキルが中断またはクラッシュした場合にすべての発見結果を保持する","ko":"Supabase 감사 테이블 목록 기능은 진행적인 파일 업데이트와 로깅을 요구하며, 스킬이 중단되거나 충돌할 경우 모든 발견 결과를 유지","es":"El agente de AI supabase-audit-tables-list permite la auditoría de tablas expuestas en Supabase, mejorando la seguridad de tus datos.","fr":"L''agent d''IA supabase-audit-tables-list permet l''audit des tables exposées dans Supabase, améliorant ainsi la sécurité de vos données","de":"Der KI-Agent supabase-audit-tables-list ermöglicht die Überprüfung von exponierten Tabellen in Supabase, wodurch die Datensicherheit verbessert wird","pt":"O supabase-audit-tables-list é uma ferramenta de auditoria que exige atualizações progressivas de arquivos para garantir a segurança dos dados","ru":"ИИ Агенты supabase-audit-tables-list - это инструмент аудита, который требует прогрессивных обновлений файлов для обеспечения безопасности данных","ar":"supabase-audit-tables-list هو أداة تدقيق تتطلب تحديثات متتالية للملفات لضمان أمان البيانات"},"seo":{"title":{"en":"supabase-audit-tables-list: Progressive Audit Table Listi...","zh":"Supabase 审计表列表设置指南","ja":"Supabase オーディットテーブルリストのベストプ