INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('seanchiuai/trace/ui-components', 'ui-components', 'seanchiuai', 'trace', 'community', 'ui-components seanchiuai trace community The ui-components skill provides a React 19 + TypeScript frontend with Tailwind CSS 4 and Framer Motion animations. It benefits developers seeking a dark detective-themed design system. 本UI组件库采用React 19 + TypeScript，结合Tailwind CSS 4和Framer Motion，提供了一套强大的前端开发解决方案 このUIコンポーネントは、React 19 + TypeScriptを使用し、Tailwind CSS 4とFramer Motionを組み合わせて、強力なフロントエンド開発ソリューションを提供します 이 UI 컴포넌트 라이브러리는 React 19 및 TypeScript를 사용하며, Tailwind CSS 4 및 Framer Motion을 결합하여 강력한 프론트엔드 개발 솔루션을 제공합니다 Componentes de interfaz de usuario personalizados con React 19, TypeScript y Tailwind CSS 4. Incluye animaciones de Framer Motion para una mejor experiencia del usuario. Composants d''interface utilisateur personnalisés avec React 19, TypeScript et Tailwind CSS 4. Inclut des animations Framer Motion pour une meilleure expérience utilisateur. Benutzerdefinierte Benutzeroberflächenkomponenten mit React 19, TypeScript und Tailwind CSS 4. Enthält Framer Motion-Animationen für eine bessere Benutzererfahrung. UI Components é uma coleção de componentes de interface de usuário construída com React 19, TypeScript e Tailwind CSS 4 ИИ Агенты UI Компоненты - это коллекция компонентов интерфейса пользователя, построенная на React 19, TypeScript и Tailwind CSS 4 مكونات الواجهة البصرية هي مجموعة من مكونات واجهة المستخدم التي يتم بناؤها مع React 19 و TypeScript و Tailwind CSS 4 how to use ui-components ui-components setup guide ui-components alternative ui-components vs Material UI ui-components install what is ui-components ui-components react ui-components typescript ui-components tailwind css UI组件库 React 19 TypeScript 5.9 Tailwind CSS 4 Framer Motion 12 前端开发 UI设计 AI工具 AIエージェント Utilizes React 19 as the UI framework Employs TypeScript 5.9 for type safety Leverages Tailwind CSS 4 for utility-first styling via @tailwindcss/vite plugin Incorporates Framer Motion 12 for component animations Organizes components in src/components/ and pages in src/pages/ Supports a dark detective-themed design system ui-components is a React-based frontend skill utilizing TypeScript, Tailwind CSS, and Framer Motion for a unique design system.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('litegral/skk-migas-news-monitor/prompt-engineering-patterns', 'community', 'litegral', 'skk-migas-news-monitor', 'litegral/skk-migas-news-monitor', 'prompt-engineering-patterns', 0, 0, 60, '2026-02-25T23:50:02Z', '2026-03-07T04:00:54.833Z', '747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6', '{"id":"litegral/skk-migas-news-monitor/prompt-engineering-patterns","name":"prompt-engineering-patterns","description":{"en":"The prompt-engineering-patterns skill enables developers to maximize LLM performance, reliability, and controllability. It benefits developers designing complex prompts for production LLM applications.","zh":"提示工程模式是一种优化LLM性能、可靠性和可控性的技术，用于生产环境下的LLM应用","ja":"プロンプトエンジニアリングパターンは、LLMの性能、信頼性、制御性を最大化するための技術です","ko":"프롬프트 엔지니어링 패턴은 LLM 성능, 신뢰성, 제어성을 최적화하는 기술입니다","es":"Los patrones de ingeniería de prompts permiten maximizar el rendimiento y la confiabilidad de las aplicaciones LLM","fr":"Les modèles de prompts permettent d''optimiser les performances et la fiabilité des applications LLM","de":"Prompt-Engineering-Muster ermöglichen die Maximierung der Leistung und Zuverlässigkeit von LLM-Anwendungen","pt":"Padrões de engenharia de prompt para maximizar o desempenho e a confiabilidade de aplicações LLM","ru":"Шаблоны инженерии промптов для максимизации производительности и надежности приложений LLM","ar":"أنماط هندسة البرمجة لزيادة الأداء والموثوقية لتطبيقات LLM"},"seo":{"title":{"en":"Prompt-Engineering-Patterns: Mastering LLM Performance Op...","zh":"提示工程模式最佳实践","ja":"プロンプトエンジニアリングパターンのセットアップガイド","ko":"프롬프트 엔지니어링 패턴 구현 방법","es":"Guía de patrones de ingeniería de prompts para maximizar ...","fr":"Meilleures pratiques de modèles de prompts pour améliorer...","de":"Leitfaden für Prompt-Engineering-Muster zur Optimierung v...","pt":"Padrões de Engenharia de Prompt: Guia de Configuração par...","ru":"Шаблоны Инженерии Промптов: Руководство по Настройке для ...","ar":"أنماط هندسة البرمجة: دليل الإعداد للعميل الذكي"},"description":{"en":"Unlock advanced prompt engineering techniques for LLM applications. Discover how to optimize prompt performance, implement chain-of-thought patterns, and bui...","zh":"学习提示工程模式，优化LLM性能、可靠性和可控性，适用于生产环境下的LLM应用","ja":"プロンプトエンジニアリングパターンを使用してLLMの性能、信頼性、制御性を最大化する","ko":"프롬프트 엔지니어링 패턴을 사용하여 LLM 성능, 신뢰성, 제어성을 최적화하는 방법","es":"Aprende a diseñar patrones de prompts complejos para aplicaciones de LLM de producción y mejora la consistencia y el rendimiento","fr":"Découvrez comment concevoir des modèles de prompts avancés pour les applications LLM de production et améliorer la cohérence et les performances","de":"Erfahren Sie, wie Sie komplexe Prompt-Muster für LLM-Produktionsanwendungen entwerfen und Konsistenz und Leistung verbessern können","pt":"Aprenda a criar prompts complexos para aplicações de LLM de produção com padrões de engenharia de prompt e maximize o desempenho e a confiabilidade","ru":"Научитесь создавать сложные промпты для приложений LLM с шаблонами инженерии промптов и максимизируйте производительность и надежность","ar":"تعلم كيفية إنشاء برمجة معقدة لتطبيقات LLM باستخدام أنماط هندسة البرمجة وزيادة الأداء والموثوقية"},"definition":{"en":"prompt-engineering-patterns is a set of advanced techniques for optimizing language model performance, including structured reasoning patterns and dynamic example selection.","zh":"提示工程模式是一种用于优化LLM性能的技术，涉及设计复杂的提示、优化提示性能和一致性","ja":"プロンプトエンジニアリングパターンとは、LLMの性能を最適化するための技術で、複雑なプロンプトの設計やプロンプトのパフォーマンスと一貫性の最適化が含まれます","ko":"프롬프트 엔지니어링 패턴은 LLM 성능을 최적화하는 기술로, 복잡한 프롬프트 설계와 프롬프트 성능 및 일관성 최적화를 포함합니다","es":"Patrones de ingeniería de prompts: técnicas para diseñar prompts complejos y mejorar el rendimiento de LLM","fr":"Modèles de prompts: techniques pour concevoir des prompts avancés et améliorer les performances des LLM","de":"Prompt-Engineering-Muster: Techniken zum Entwerfen komplexer Prompts und zur Verbesserung der LLM-Leistung","pt":"Padrões de engenharia de prompt são técnicas avançadas para criar prompts complexos e melhorar o desempenho de aplicações LLM","ru":"Шаблоны инженерии промптов - это продвинутые техники для создания сложных промптов и улучшения производительности приложений LLM","ar":"أنماط هندسة البرمجة هي تقنيات متقدمة لإنشاء برمجة معقدة وتحسين الأداء لتطبيقات LLM"},"features":{"en":["Designing complex prompts for production LLM applications","Implementing structured reasoning patterns such as chain-of-thought and tree-of-thought","Building few-shot learning systems with dynamic example selection","Creating reusable prompt templates with variable interpolation","Debugging and optimizing prompt performance and consistency"],"zh":["设计复杂的提示","优化提示性能和一致性","实现结构化推理模式（chain-of-thought、tree-of-thought）","构建少样本学习系统","创建可重用的提示模板"],"ja":["複雑なプロンプトの設計","プロンプトのパフォーマンスと一貫性の最適化","構造化推理パターンの実装（chain-of-thought、tree-of-thought）","少샘플学習システムの構築","再利用可能なプロンプトテンプレートの作成"],"ko":["복잡한 프롬프트 설계","프롬프트 성능 및 일관성 최적화","구조화된 추론 패턴 구현（chain-of-thought、tree-of-thought）","적은 샘플 학습 시스템 구축","재사용 가능한 프롬프트 템플릿 생성"],"es":["Diseño de patrones de prompts complejos para aplicaciones LLM de producción","Optimización del rendimiento y la consistencia de los prompts","Implementación de patrones de razonamiento estructurados (cadena de pensamiento, árbol de pensamiento)","Creación de plantillas de prompts reutilizables con interpolación de variables","Depuración de patrones de prompts"],"fr":["Conception de modèles de prompts avancés pour les applications LLM de production","Optimisation des performances et de la cohérence des prompts","Mise en œuvre de modèles de raisonnement structurés (chaîne de pensée, arbre de pensée)","Création de modèles de prompts réutilisables avec interpolation de variables","Débogage de modèles de prompts"],"de":["Entwurf komplexer Prompt-Muster für LLM-Produktionsanwendungen","Optimierung der Leistung und Konsistenz von Prompts","Implementierung strukturierter Denkmuster (Gedankenketten, Denkbaum)","Erstellung wiederverwendbarer Prompt-Vorlagen mit Variableninterpolation","Fehlerbehebung bei Prompt-Mustern"],"pt":["Criação de prompts complexos para aplicações LLM de produção","Otimização do desempenho e consistência de prompts","Implementação de padrões de raciocínio estruturados (cadeia de pensamento, árvore de pensamento)","Criação de sistemas de aprendizado com poucos exemplos com seleção dinâmica de exemplos","Criação de modelos de prompt reutilizáveis com interpolação de variáveis"],"ru":["Создание сложных промптов для приложений LLM","Оптимизация производительности и согласованности промптов","Реализация структурированных шаблонов рассуждений (цепочка мыслей, дерево мыслей)","Создание систем обучения с少ими примерами с динамическим выбором примеров","Создание повторно используемых шаблонов промптов с интерполяцией переменных"],"ar":["إنشاء برمجة معقدة لتطبيقات LLM","تحسين الأداء والاتساق للبرمجة","تنفيذ أنماط استدلالية متسلسلة (سلسلة الفكر، شجرة الفكر)","إنشاء أنظمة تعلم مع قليل من الأمثلة مع اختيار ديناميكي للأمثلة","إنشاء قوالب برمجة قابلة لإعادة الاستخدام مع استبدال المتغيرات"]},"keywords":{"en":["how to use prompt-engineering-patterns","prompt-engineering-patterns tutorial","LLM performance optimization techniques","chain-of-thought prompt engineering","few-shot learning with prompt-engineering-patterns","prompt-engineering-patterns setup guide","prompt-engineering-patterns vs traditional NLP"],"zh":["提示工程模式","LLM性能优化","AIエージェント","自然语言处理","机器学习","深度学习","Python","CLI"],"ja":["プロンプトエンジニアリングパターン","LLMパフォーマンス最適化","AIエージェント","自然言語処理","機械学習","ディープラーニング","Python","CLI"],"ko":["프롬프트 엔지니어링 패턴","LLM 성능 최적화","AI 툴","자연어 처리","기계 학습","딥 러닝","Python","CLI"],"es":["patrones de ingeniería de prompts","LLM","aplicaciones de LLM de producción","optimización de prompts","modelos de prompts","cadena de pensamiento","árbol de pensamiento","plantillas de prompts reutilizables"],"fr":["modèles de prompts","LLM","applications LLM de production","optimisation de prompts","conception de modèles de prompts","chaîne de pensée","arbre de pensée","modèles de prompts réutilisables"],"de":["Prompt-Engineering-Muster","LLM","LLM-Produktionsanwendungen","Optimierung von Prompts","Entwurf von Prompt-Mustern","Gedankenketten","Denkbaum","wiederverwendbare Prompt-Vorlagen"],"pt":["engenharia de prompt","padrões de engenharia de prompt","aplicações LLM","prompts complexos","otimização de desempenho","raciocínio estruturado","aprendizado com poucos exemplos","modelos de prompt reutilizáveis","ferramentas de IA"],"ru":["инженерия промптов","шаблоны инженерии промптов","приложения LLM","сложные промпты","оптимизация производительности","структурированные шаблоны рассуждений","обучение с少ими примерами","повторно используемые шаблоны промптов","ИИ агенты"],"ar":["هندسة البرمجة","أنماط هندسة البرمجة","تطبيقات LLM","برمجة معقدة","تحسين الأداء","أنماط استدلالية متسلسلة","تعلم مع قليل من الأمثلة","قوالب برمجة قابلة لإعادة الاستخدام","عميل ذكي"]}},"owner":"litegral","repo":"skk-migas-news-monitor","repoPath":"litegral/skk-migas-news-monitor","stars":0,"forks":0,"updatedAt":"2026-02-25T23:50:02Z","topics":[],"category":"community","skillMd":{"name":"prompt-engineering-patterns","description":"Master advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability in production. Use when optimizing prompts, improving LLM outputs, or designing production prompt templates.","bodyPreview":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debuggin","body":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debugging and refining prompts that produce inconsistent outputs\n- Implementing system prompts for specialized AI assistants\n- Using structured outputs (JSON mode) for reliable parsing\n\n## Core Capabilities\n\n### 1. Few-Shot Learning\n\n- Example selection strategies (semantic similarity, diversity sampling)\n- Balancing example count with context window constraints\n- Constructing effective demonstrations with input-output pairs\n- Dynamic example retrieval from knowledge bases\n- Handling edge cases through strategic example selection\n\n### 2. Chain-of-Thought Prompting\n\n- Step-by-step reasoning elicitation\n- Zero-shot CoT with \"Let''s think step by step\"\n- Few-shot CoT with reasoning traces\n- Self-consistency techniques (sampling multiple reasoning paths)\n- Verification and validation steps\n\n### 3. Structured Outputs\n\n- JSON mode for reliable parsing\n- Pydantic schema enforcement\n- Type-safe response handling\n- Error handling for malformed outputs\n\n### 4. Prompt Optimization\n\n- Iterative refinement workflows\n- A/B testing prompt variations\n- Measuring prompt performance metrics (accuracy, consistency, latency)\n- Reducing token usage while maintaining quality\n- Handling edge cases and failure modes\n\n### 5. Template Systems\n\n- Variable interpolation and formatting\n- Conditional prompt sections\n- Multi-turn conversation templates\n- Role-based prompt composition\n- Modular prompt components\n\n### 6. System Prompt Design\n\n- Setting model behavior and constraints\n- Defining output formats and structure\n- Establishing role and expertise\n- Safety guidelines and content policies\n- Context setting and background information\n\n## Quick Start\n\n```python\nfrom langchain_anthropic import ChatAnthropic\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom pydantic import BaseModel, Field\n\n# Define structured output schema\nclass SQLQuery(BaseModel):\n    query: str = Field(description=\"The SQL query\")\n    explanation: str = Field(description=\"Brief explanation of what the query does\")\n    tables_used: list[str] = Field(description=\"List of tables referenced\")\n\n# Initialize model with structured output\nllm = ChatAnthropic(model=\"claude-sonnet-4-6\")\nstructured_llm = llm.with_structured_output(SQLQuery)\n\n# Create prompt template\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"\"\"You are an expert SQL developer. Generate efficient, secure SQL queries.\n    Always use parameterized queries to prevent SQL injection.\n    Explain your reasoning briefly.\"\"\"),\n    (\"user\", \"Convert this to SQL: {query}\")\n])\n\n# Create chain\nchain = prompt | structured_llm\n\n# Use\nresult = await chain.ainvoke({\n    \"query\": \"Find all users who registered in the last 30 days\"\n})\nprint(result.query)\nprint(result.explanation)\n```\n\n## Key Patterns\n\n### Pattern 1: Structured Output with Pydantic\n\n```python\nfrom anthropic import Anthropic\nfrom pydantic import BaseModel, Field\nfrom typing import Literal\nimport json\n\nclass SentimentAnalysis(BaseModel):\n    sentiment: Literal[\"positive\", \"negative\", \"neutral\"]\n    confidence: float = Field(ge=0, le=1)\n    key_phrases: list[str]\n    reasoning: str\n\nasync def analyze_sentiment(text: str) -> SentimentAnalysis:\n    \"\"\"Analyze sentiment with structured output.\"\"\"\n    client = Anthropic()\n\n    message = client.messages.create(\n        model=\"claude-sonnet-4-6\",\n        max_tokens=500,\n        messages=[{\n            \"role\": \"user\",\n            \"content\": f\"\"\"Analyze the sentiment of this text.\n\nText: {text}\n\nRespond with JSON matching this schema:\n{{\n    \"sentiment\": \"positive\" | \"negative\" | \"neutral\",\n    \"confidence\": 0.0-1.0,\n    \"key_phrases\": [\"phrase1\", \"phrase2\"],\n    \"reasoning\": \"brief explanation\"\n}}\"\"\"\n        }]\n    )\n\n    return SentimentAnalysis(**json.loads(message.content[0].text))\n```\n\n### Pattern 2: Chain-of-Thought with Self-Verification\n\n```python\nfrom langchain_core.prompts import ChatPromptTemplate\n\ncot_prompt = ChatPromptTemplate.from_template(\"\"\"\nSolve this problem step by step.\n\nProblem: {problem}\n\nInstructions:\n1. Break down the problem into clear steps\n2. Work through each step showing your reasoning\n3. State your final answer\n4. Verify your answer by checking it against the original problem\n\nFormat your response as:\n## Steps\n[Your step-by-step reasoning]\n\n## Answer\n[Your final answer]\n\n## Verification\n[Check that your answer is correct]\n\"\"\")\n```\n\n### Pattern 3: Few-Shot with Dynamic Example Selection\n\n```python\nfrom langchain_voyageai import VoyageAIEmbeddings\nfrom langchain_core.example_selectors import SemanticSimilarityExampleSelector\nfrom langchain_chroma import Chroma\n\n# Create example selector with semantic similarity\nexample_selector = SemanticSimilarityExampleSelector.from_examples(\n    examples=[\n        {\"input\": \"How do I reset my password?\", \"output\": \"Go to Settings > Security > Reset Password\"},\n        {\"input\": \"Where can I see my order history?\", \"output\": \"Navigate to Account > Orders\"},\n        {\"input\": \"How do I contact support?\", \"output\": \"Click Help > Contact Us or email support@example.com\"},\n    ],\n    embeddings=VoyageAIEmbeddings(model=\"voyage-3-large\"),\n    vectorstore_cls=Chroma,\n    k=2  # Select 2 most similar examples\n)\n\nasync def get_few_shot_prompt(query: str) -> str:\n    \"\"\"Build prompt with dynamically selected examples.\"\"\"\n    examples = await example_selector.aselect_examples({\"input\": query})\n\n    examples_text = \"\\n\".join(\n        f\"User: {ex[''input'']}\\nAssistant: {ex[''output'']}\"\n        for ex in examples\n    )\n\n    return f\"\"\"You are a helpful customer support assistant.\n\nHere are some example interactions:\n{examples_text}\n\nNow respond to this query:\nUser: {query}\nAssistant:\"\"\"\n```\n\n### Pattern 4: Progressive Disclosure\n\nStart with simple prompts, add complexity only when needed:\n\n```python\nPROMPT_LEVELS = {\n    # Level 1: Direct instruction\n    \"simple\": \"Summarize this article: {text}\",\n\n    # Level 2: Add constraints\n    \"constrained\": \"\"\"Summarize this article in 3 bullet points, focusing on:\n- Key findings\n- Main conclusions\n- Practical implications\n\nArticle: {text}\"\"\",\n\n    # Level 3: Add reasoning\n    \"reasoning\": \"\"\"Read this article carefully.\n1. First, identify the main topic and thesis\n2. Then, extract the key supporting points\n3. Finally, summarize in 3 bullet points\n\nArticle: {text}\n\nSummary:\"\"\",\n\n    # Level 4: Add examples\n    \"few_shot\": \"\"\"Read articles and provide concise summaries.\n\nExample:\nArticle: \"New research shows that regular exercise can reduce anxiety by up to 40%...\"\nSummary:\n• Regular exercise reduces anxiety by up to 40%\n• 30 minutes of moderate activity 3x/week is sufficient\n• Benefits appear within 2 weeks of starting\n\nNow summarize this article:\nArticle: {text}\n\nSummary:\"\"\"\n}\n```\n\n### Pattern 5: Error Recovery and Fallback\n\n```python\nfrom pydantic import BaseModel, ValidationError\nimport json\n\nclass ResponseWithConfidence(BaseModel):\n    answer: str\n    confidence: float\n    sources: list[str]\n    alternative_interpretations: list[str] = []\n\nERROR_RECOVERY_PROMPT = \"\"\"\nAnswer the question based on the context provided.\n\nContext: {context}\nQuestion: {question}\n\nInstructions:\n1. If you can answer confidently (>0.8), provide a direct answer\n2. If you''re somewhat confident (0.5-0.8), provide your best answer with caveats\n3. If you''re uncertain (<0.5), explain what information is missing\n4. Always provide alternative interpretations if the question is ambiguous\n\nRespond in JSON:\n{{\n    \"answer\": \"your answer or ''I cannot determine this from the context''\",\n    \"confidence\": 0.0-1.0,\n    \"sources\": [\"relevant context excerpts\"],\n    \"alternative_interpretations\": [\"if question is ambiguous\"]\n}}\n\"\"\"\n\nasync def answer_with_fallback(\n    context: str,\n    question: str,\n    llm\n) -> ResponseWithConfidence:\n    \"\"\"Answer with error recovery and fallback.\"\"\"\n    prompt = ERROR_RECOVERY_PROMPT.format(context=context, question=question)\n\n    try:\n        response = await llm.ainvoke(prompt)\n        return ResponseWithConfidence(**json.loads(response.content))\n    except (json.JSONDecodeError, ValidationError) as e:\n        # Fallback: try to extract answer without structure\n        simple_prompt = f\"Based on: {context}\\n\\nAnswer: {question}\"\n        simple_response = await llm.ainvoke(simple_prompt)\n        return ResponseWithConfidence(\n            answer=simple_response.content,\n            confidence=0.5,\n            sources=[\"fallback extraction\"],\n            alternative_interpretations=[]\n        )\n```\n\n### Pattern 6: Role-Based System Prompts\n\n```python\nSYSTEM_PROMPTS = {\n    \"analyst\": \"\"\"You are a senior data analyst with expertise in SQL, Python, and business intelligence.\n\nYour responsibilities:\n- Write efficient, well-documented queries\n- Explain your analysis methodology\n- Highlight key insights and recommendations\n- Flag any data quality concerns\n\nCommunication style:\n- Be precise and technical when discussing methodology\n- Translate technical findings into business impact\n- Use clear visualizations when helpful\"\"\",\n\n    \"assistant\": \"\"\"You are a helpful AI assistant focused on accuracy and clarity.\n\nCore principles:\n- Always cite sources when making factual claims\n- Acknowledge uncertainty rather than guessing\n- Ask clarifying questions when the request is ambiguous\n- Provide step-by-step explanations for complex topics\n\nConstraints:\n- Do not provide medical, legal, or financial advice\n- Redirect harmful requests appropriately\n- Protect user privacy\"\"\",\n\n    \"code_reviewer\": \"\"\"You are a senior software engineer conducting code reviews.\n\nReview criteria:\n- Correctness: Does the code work as intended?\n- Security: Are there any vulnerabilities?\n- Performance: Are there efficiency concerns?\n- Maintainability: Is the code readable and well-structured?\n- Best practices: Does it follow language idioms?\n\nOutput format:\n1. Summary assessment (approve/request changes)\n2. Critical issues (must fix)\n3. Suggestions (nice to have)\n4. Positive feedback (what''s done well)\"\"\"\n}\n```\n\n## Integration Patterns\n\n### With RAG Systems\n\n```python\nRAG_PROMPT = \"\"\"You are a knowledgeable assistant that answers questions based on provided context.\n\nContext (retrieved from knowledge base):\n{context}\n\nInstructions:\n1. Answer ONLY based on the provided context\n2. If the context doesn''t contain the answer, say \"I don''t have information about that in my knowledge base\"\n3. Cite specific passages using [1], [2] notation\n4. If the question is ambiguous, ask for clarification\n\nQuestion: {question}\n\nAnswer:\"\"\"\n```\n\n### With Validation and Verification\n\n```python\nVALIDATED_PROMPT = \"\"\"Complete the following task:\n\nTask: {task}\n\nAfter generating your response, verify it meets ALL these criteria:\n✓ Directly addresses the original request\n✓ Contains no factual errors\n✓ Is appropriately detailed (not too brief, not too verbose)\n✓ Uses proper formatting\n✓ Is safe and appropriate\n\nIf verification fails on any criterion, revise before responding.\n\nResponse:\"\"\"\n```\n\n## Performance Optimization\n\n### Token Efficiency\n\n```python\n# Before: Verbose prompt (150+ tokens)\nverbose_prompt = \"\"\"\nI would like you to please take the following text and provide me with a comprehensive\nsummary of the main points. The summary should capture the key ideas and important details\nwhile being concise and easy to understand.\n\"\"\"\n\n# After: Concise prompt (30 tokens)\nconcise_prompt = \"\"\"Summarize the key points concisely:\n\n{text}\n\nSummary:\"\"\"\n```\n\n### Caching Common Prefixes\n\n```python\nfrom anthropic import Anthropic\n\nclient = Anthropic()\n\n# Use prompt caching for repeated system prompts\nresponse = client.messages.create(\n    model=\"claude-sonnet-4-6\",\n    max_tokens=1000,\n    system=[\n        {\n            \"type\": \"text\",\n            \"text\": LONG_SYSTEM_PROMPT,\n            \"cache_control\": {\"type\": \"ephemeral\"}\n        }\n    ],\n    messages=[{\"role\": \"user\", \"content\": user_query}]\n)\n```\n\n## Best Practices\n\n1. **Be Specific**: Vague prompts produce inconsistent results\n2. **Show, Don''t Tell**: Examples are more effective than descriptions\n3. **Use Structured Outputs**: Enforce schemas with Pydantic for reliability\n4. **Test Extensively**: Evaluate on diverse, representative inputs\n5. **Iterate Rapidly**: Small changes can have large impacts\n6. **Monitor Performance**: Track metrics in production\n7. **Version Control**: Treat prompts as code with proper versioning\n8. **Document Intent**: Explain why prompts are structured as they are\n\n## Common Pitfalls\n\n- **Over-engineering**: Starting with complex prompts before trying simple ones\n- **Example pollution**: Using examples that don''t match the target task\n- **Context overflow**: Exceeding token limits with excessive examples\n- **Ambiguous instructions**: Leaving room for multiple interpretations\n- **Ignoring edge cases**: Not testing on unusual or boundary inputs\n- **No error handling**: Assuming outputs will always be well-formed\n- **Hardcoded values**: Not parameterizing prompts for reuse\n\n## Success Metrics\n\nTrack these KPIs for your prompts:\n\n- **Accuracy**: Correctness of outputs\n- **Consistency**: Reproducibility across similar inputs\n- **Latency**: Response time (P50, P95, P99)\n- **Token Usage**: Average tokens per request\n- **Success Rate**: Percentage of valid, parseable outputs\n- **User Satisfaction**: Ratings and feedback\n\n## Resources\n\n- [Anthropic Prompt Engineering Guide](https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering)\n- [Claude Prompt Caching](https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching)\n- [OpenAI Prompt Engineering](https://platform.openai.com/docs/guides/prompt-engineering)\n- [LangChain Prompts](https://python.langchain.com/docs/concepts/prompts/)\n"},"lastSynced":"2026-03-07T04:00:54.833Z","agentAnalysis":{"suitability":{"en":"Perfect for LLM Agents needing advanced prompt engineering capabilities for production applications.","zh":"非常适合需要高级提示工程能力的LLM代理，用于生产应用。","ja":"生産アプリケーションでの高度なプロンプトエンジニアリング機能を必要とするLLMエージェントに最適です。","ko":"생산 애플리케이션에서 고급 프롬프트 엔지니어링 기능이 필요한 LLM 에이전트에 적합합니다.","es":"Perfecto para agentes LLM que necesitan capacidades avanzadas de ingeniería de prompt para aplicaciones de producción.","fr":"Parfait pour les agents LLM qui ont besoin de capacités avancées d''ingénierie de prompt pour les applications de production.","de":"Perfekt für LLM-Agents, die erweiterte Prompt-Engineering-Fähigkeiten für Produktionsanwendungen benötigen.","pt":"Perfeito para Agentes LLM que necessitam de capacidades avançadas de engenharia de prompts para aplicações de produção.","ru":"Идеально подходит для агентов LLM, которым необходимы расширенные возможности инженерии запросов для производственных приложений.","ar":"مثالي لعميل LLM الذي يحتاج إلى قدرات هندسة متقدمة لتقديم تطبيقات الإنتاج."},"recommendation":{"en":"Empowers agents to maximize LLM performance, reliability, and controllability by implementing structured reasoning patterns, such as chain-of-thought and tree-of-thought, and utilizing techniques like few-shot learning and dynamic example selection.","zh":"通过实现结构化的推理模式（如链式思维和树状思维）和利用少样本学习和动态示例选择等技术，赋予代理最大化LLM性能、可靠性和可控性的能力。","ja":"チェーンオブソートやツリーオブソートなどの構造化された推論パターンを実装し、少量学習や動的例選択などのテクニックを利用することで、エージェントがLLMのパフォーマンス、信頼性、および制御性を最大化できるようにします。","ko":"체인 오브 사고 또는 트리 오브 사고와 같은 구조화된 推論 패턴을 구현하고 少샘플 학습이나 동적 예제 선택과 같은 기술을 활용하여 에이전트가 LLM의 성능, 신뢰성 및 제어성을 최대화할 수 있도록 합니다.","es":"Habilita a los agentes a maximizar el rendimiento, la confiabilidad y la capacidad de control de LLM implementando patrones de razonamiento estructurados, como la cadena de pensamiento y el árbol de pensamiento, y utilizando técnicas como el aprendizaje de pocos disparos y la selección dinámica de ejemplos.","fr":"Permet aux agents de maximiser les performances, la fiabilité et la contrôlabilité de LLM en mettant en œuvre des modèles de raisonnement structurés, tels que la chaîne de pensée et l''arbre de pensée, et en utilisant des techniques comme l''apprentissage à partir de quelques exemples et la sélection dynamique d''exemples.","de":"Ermächtigt Agents, die LLM-Leistung, -Zuverlässigkeit und -Steuerbarkeit zu maximieren, indem sie strukturierte Denkmuster wie die Gedankenkette und den Gedankenbaum implementieren und Techniken wie Few-Shot-Learning und dynamische Beispielwahl verwenden.","pt":"Habilita os agentes a maximizar o desempenho, a confiabilidade e o controle do LLM, implementando padrões de raciocínio estruturados, como cadeia de pensamento e árvore de pensamento, e utilizando técnicas como aprendizado de poucos disparos e seleção dinâmica de exemplos.","ru":"Позволяет агентам максимизировать производительность, надежность и управляемость LLM, реализуя структурированные закономерности рассуждений, такие как цепочка мыслей и дерево мыслей, и используя методы, такие как обучение на нескольких примерах и динамический выбор примеров.","ar":"يُمكّن الوكيل من تعزيز أداء LLM وثباته وضبطه من خلال تنفيذ أنماط التفكير المنظمة، مثل سلسلة التفكير وشجرة التفكير، واستخدام تقنيات مثل التعلم بضعف النار والاختيار الديناميكي للأمثلة."},"useCases":{"en":["Designing complex prompts for production LLM applications","Optimizing prompt performance and consistency","Implementing reusable prompt templates with variable interpolation"],"zh":["为生产LLM应用设计复杂的提示","优化提示的性能和一致性","实现具有变量插值的可重用提示模板"],"ja":["生産LLMアプリケーションのための複雑なプロンプトの設計","プロンプトのパフォーマンスと一貫性の最適化","変数補間を備えた再利用可能なプロンプトテンプレートの実装"],"ko":["생산 LLM 애플리케이션을 위한 복잡한 프롬프트 설계","프롬프트의 성능 및 일관성 최적화","변수 삽입을 갖춘 재사용 가능한 프롬프트 템플릿 구현"],"es":["Diseñar prompts complejos para aplicaciones LLM de producción","Optimizar el rendimiento y la coherencia de los prompts","Implementar plantillas de prompts reutilizables con interpolación de variables"],"fr":["Concevoir des prompts complexes pour les applications LLM de production","Optimiser les performances et la cohérence des prompts","Mettre en œuvre des modèles de prompts réutilisables avec interpolation de variables"],"de":["Komplexe Prompts für LLM-Produktionsanwendungen entwerfen","Prompt-Leistung und -Konsistenz optimieren","Wiederverwendbare Prompt-Vorlagen mit Variableninterpolation implementieren"],"pt":["Projeto de prompts complexos para aplicações LLM de produção","Otimização do desempenho e consistência do prompt","Implementação de modelos de prompt reutilizáveis com interpolação de variáveis"],"ru":["Проектирование сложных запросов для производственных приложений LLM","Оптимизация производительности и последовательности запроса","Реализация перезаписываемых шаблонов запроса с интерполяцией переменных"],"ar":["تصميم دوافع معقدة لتطبيقات LLM الإنتاجية","تحسين أداء الدافع وثباته","تنفيذ قوالب دوافع قابلة لإعادة الاستخدام مع استبدال المتغيرات"]},"limitations":{"en":["Requires expertise in LLM applications and prompt engineering","Limited to text-based LLM applications"],"zh":["需要LLM应用和提示工程的专业知识","仅限于基于文本的LLM应用"],"ja":["LLMアプリケーションとプロンプトエンジニアリングの専門知識が必要","テキストベースのLLMアプリケーションに限定される"],"ko":["LLM 애플리케이션 및 프롬프트 엔지니어링에 대한 전문 지식이 필요","텍스트 기반 LLM 애플리케이션에만 제한됨"],"es":["Requiere experiencia en aplicaciones LLM y ingeniería de prompt","Limitado a aplicaciones LLM basadas en texto"],"fr":["Nécessite une expertise dans les applications LLM et l''ingénierie de prompt","Limité aux applications LLM basées sur le texte"],"de":["Erfordert Expertenwissen in LLM-Anwendungen und Prompt-Engineering","Begrenzt auf textbasierte LLM-Anwendungen"],"pt":["Exige especialização em aplicações LLM e engenharia de prompts","Limitado a aplicações LLM baseadas em texto"],"ru":["Требует специализации в области приложений LLM и инженерии запросов","Ограничен для приложений LLM на основе текста"],"ar":["يتطلب تخصصًا في تطبيقات LLM وهندسة الدوافع","محدود للتطبيقات القائمة على النص LLM"]},"version":4},"contentHash":"747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6","qualityScore":60}');
