INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('litegral/skk-migas-news-monitor/prompt-engineering-patterns', 'prompt-engineering-patterns', 'litegral', 'skk-migas-news-monitor', 'community', 'prompt-engineering-patterns litegral skk-migas-news-monitor community The prompt-engineering-patterns skill enables developers to maximize LLM performance, reliability, and controllability. It benefits developers designing complex prompts for production LLM applications. 提示工程模式是一种优化LLM性能、可靠性和可控性的技术，用于生产环境下的LLM应用 プロンプトエンジニアリングパターンは、LLMの性能、信頼性、制御性を最大化するための技術です 프롬프트 엔지니어링 패턴은 LLM 성능, 신뢰성, 제어성을 최적화하는 기술입니다 Los patrones de ingeniería de prompts permiten maximizar el rendimiento y la confiabilidad de las aplicaciones LLM Les modèles de prompts permettent d''optimiser les performances et la fiabilité des applications LLM Prompt-Engineering-Muster ermöglichen die Maximierung der Leistung und Zuverlässigkeit von LLM-Anwendungen Padrões de engenharia de prompt para maximizar o desempenho e a confiabilidade de aplicações LLM Шаблоны инженерии промптов для максимизации производительности и надежности приложений LLM أنماط هندسة البرمجة لزيادة الأداء والموثوقية لتطبيقات LLM how to use prompt-engineering-patterns prompt-engineering-patterns tutorial LLM performance optimization techniques chain-of-thought prompt engineering few-shot learning with prompt-engineering-patterns prompt-engineering-patterns setup guide prompt-engineering-patterns vs traditional NLP 提示工程模式 LLM性能优化 AIエージェント 自然语言处理 机器学习 深度学习 Python CLI Designing complex prompts for production LLM applications Implementing structured reasoning patterns such as chain-of-thought and tree-of-thought Building few-shot learning systems with dynamic example selection Creating reusable prompt templates with variable interpolation Debugging and optimizing prompt performance and consistency prompt-engineering-patterns is a set of advanced techniques for optimizing language model performance, including structured reasoning patterns and dynamic example selection.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('prulloac/git-blame-vsc/feature-summary', 'community', 'prulloac', 'git-blame-vsc', 'prulloac/git-blame-vsc', 'feature-summary', 0, 0, 60, '2026-02-24T00:33:08Z', '2026-03-07T04:01:48.375Z', 'c62b6903f190733fbb871982f2629346d589fdf6e0cbaef916f75971d90e8b1e', '{"id":"prulloac/git-blame-vsc/feature-summary","name":"feature-summary","description":{"en":"The feature-summary skill transforms detailed feature breakdowns into accessible summaries for multiple audiences, including stakeholders, users, and developers. It focuses on feature documentation and communication.","zh":"Feature Summary是一个轻量级的Git Blame可视化插件，用于创建和管理特性文档","ja":"Feature Summaryは軽量級のGit Blame可視化プラグインであり、特性ドキュメントの作成と管理に使用されます","ko":"Feature Summary는 가벼운 Git Blame 플러그인으로서 특성 문서의 생성과 관리에 사용됩니다","es":"El resumen de características es una habilidad que permite transformar desgloses detallados en resúmenes accesibles y completos para múltiples audiencias. Se utiliza para crear documentación de usuario y catálogos de funciones.","fr":"Le résumé de fonctionnalités est une compétence qui permet de transformer les décompositions détaillées en résumés accessibles et complets pour plusieurs publics. Il est utilisé pour créer une documentation utilisateur et des catalogues de fonctionnalités.","de":"Die Funktionszusammenfassung ist eine Fähigkeit, die es ermöglicht, detaillierte Aufschlüsselungen in zugängliche und vollständige Zusammenfassungen für mehrere Zielgruppen umzuwandeln. Sie wird verwendet, um Benutzerdokumentation und Funktionskataloge zu erstellen.","pt":"O feature-summary é um plugin leve para Git que ajuda a documentar e comunicar recursos para desenvolvedores e stakeholders","ru":"Фич-саммари - это лёгкий плагин для Git, помогающий документировать и коммуницировать фичи для разработчиков и заинтересованных сторон","ar":"ميزة feature-summary هي إضافة خفيفة لمنصة Git تساعد على توثيق وتبادل الميزات مع المطورين وأصحاب المصلحة"},"seo":{"title":{"en":"feature-summary: Lightweight Git Blame Plugin Setup Guide...","zh":"Feature Summary Setup Guide: AIエージェント for Git Blame","ja":"Feature Summary ベストプラクティス: AIエージェントによるGit Blameの可視化","ko":"Feature Summary 구축 가이드: AI 에이전트를 활용한 Git Blame 플러그인","es":"Guía de configuración de resumen de características para ...","fr":"Guide de mise en place du résumé de fonctionnalités pour ...","de":"Einrichtungsleitfaden für Funktionszusammenfassung zur Fu...","pt":"Guia de Configuração do feature-summary: Documentação de ...","ru":"ИИ Агенты: Настройка feature-summary для Коммуникации Фич","ar":"دليل إعداد feature-summary: توثيق الميزات لمنصة Git"},"description":{"en":"Discover how feature-summary simplifies feature documentation and communication for stakeholders, users, and developers. Get started with this lightweight Gi...","zh":"使用Feature Summary AIエージェント轻松创建Git Blame的可视化插件，提高开发效率","ja":"Feature Summary AIエージェントを使用してGit Blameの可視化プラグインを作成し、開発効率を向上させる","ko":"Feature Summary AI 에이전트를 사용하여 Git Blame 플러그인을 구축하고 개발 효율성을 높여보세요","es":"Aprende a implementar el resumen de características para mejorar la documentación y comunicación de funciones en tu proyecto con esta herramienta de document...","fr":"Découvrez comment mettre en œuvre le résumé de fonctionnalités pour améliorer la documentation et la communication des fonctionnalités dans votre projet avec...","de":"Erfahren Sie, wie Sie die Funktionszusammenfassung implementieren, um die Dokumentation und Kommunikation von Funktionen in Ihrem Projekt mit diesem Code-Dok...","pt":"Aprenda a configurar o plugin feature-summary para Visual Studio e melhore a documentação de recursos para desenvolvedores e stakeholders","ru":"Узнайте, как настроить плагин feature-summary для Visual Studio и улучшить коммуникацию фич для разработчиков и заинтересованных сторон","ar":"تعرف على كيفية إعداد ميزة feature-summary لمنصة Git وتحسين توثيق الميزات للمطورين وأصحاب المصلحة"},"definition":{"en":"feature-summary is a skill that enables the creation of comprehensive feature documentation and communication, serving multiple audiences through accessible summaries.","zh":"Feature Summary是指使用AIエージェント创建和管理特性文档的技术","ja":"Feature Summaryとは、AIエージェントを使用して特性ドキュメントを作成し管理する技術である","ko":"Feature Summary는 AI 에이전트를 사용하여 특성 문서를 생성하고 관리하는 기술을 의미합니다","es":"El resumen de características es una habilidad que se utiliza para documentar y comunicar funciones a partes interesadas, usuarios y desarrolladores","fr":"Le résumé de fonctionnalités est une compétence qui est utilisée pour documenter et communiquer des fonctionnalités aux parties prenantes, utilisateurs et développeurs","de":"Die Funktionszusammenfassung ist eine Fähigkeit, die zur Dokumentation und Kommunikation von Funktionen an Interessenten, Benutzer und Entwickler verwendet wird","pt":"O feature-summary é uma habilidade que transforma quebras detalhadas em resumos acessíveis e abrangentes para múltiplos públicos","ru":"Фич-саммари - это навык, превращающий детальные разбивки в доступные и полные резюме для нескольких аудиторий","ar":"ميزة feature-summary هي مهارة تتحول إلى ملخصات سهلة الوصول وشاملة لمختلف الجماهير"},"features":{"en":["Generates comprehensive user-facing documentation","Builds a feature catalog for stakeholders and developers","Transforms detailed breakdowns into accessible summaries","Supports feature documentation and communication for multiple audiences","Creates summaries for completed features or detailed feature breakdowns","Enables the creation of a feature catalog"],"zh":["轻量级Git Blame可视化","特性文档的创建和管理","支持多种开发环境","易于使用的界面","提高开发效率","支持AIエージェント集成"],"ja":["軽量級Git Blame可視化","特性ドキュメントの作成と管理","複数の開発環境をサポート","使いやすいインターフェース","開発効率の向上","AIエージェントとの連携をサポート"],"ko":["가벼운 Git Blame 플러그인","특성 문서의 생성과 관리","다양한 개발 환경 지원","사용하기 쉬운 인터페이스","개발 효율성 향상","AI 에이전트와의 통합 지원"],"es":["Transformación de desgloses detallados en resúmenes accesibles","Creación de documentación de usuario comprehensiva","Generación de catálogos de funciones","Mejora de la comunicación de funciones a partes interesadas y desarrolladores","Integración con herramientas de documentación de código","Compatibilidad con plugins de Visual Studio"],"fr":["Transformation de décompositions détaillées en résumés accessibles","Création de documentation utilisateur complète","Génération de catalogues de fonctionnalités","Amélioration de la communication de fonctionnalités aux parties prenantes et développeurs","Intégration avec des outils de documentation de code","Compatibilité avec les plugins de Visual Studio"],"de":["Umwandlung von detaillierten Aufschlüsselungen in zugängliche Zusammenfassungen","Erstellung von umfassender Benutzerdokumentation","Generierung von Funktionskatalogen","Verbesserung der Kommunikation von Funktionen an Interessenten und Entwickler","Integration mit Code-Dokumentations-Tools","Kompatibilität mit Visual Studio-Plugins"],"pt":["Cria documentação abrangente para usuários","Constroi um catálogo de recursos","Transforma quebras detalhadas em resumos acessíveis","Melhora a comunicação entre desenvolvedores e stakeholders","Integração com o Visual Studio"],"ru":["Создаёт полную документацию для пользователей","Строит каталог фич","Превращает детальные разбивки в доступные резюме","Улучшает коммуникацию между разработчиками и заинтересованными сторонами","Интеграция с Visual Studio"],"ar":["إنشاء توثيق شامل للمستخدمين","بناء فهرس للميزات","تحويل التجزئة التفصيلية إلى ملخصات سهلة الوصول","تحسين التواصل بين المطورين وأصحاب المصلحة","التكامل مع منصة Git"]},"keywords":{"en":["how to use feature-summary","what is feature-summary","feature-summary alternative","feature-summary vs git blame","feature-summary install","feature-summary setup guide","feature documentation best practices","git blame visual studio plugin"],"zh":["Feature Summary","AIエージェント","Git Blame","可视化插件","特性文档","开发效率","轻量级","开发环境","AI工具"],"ja":["Feature Summary","AIエージェント","Git Blame","可視化プラグイン","特性ドキュメント","開発効率","軽量級","開発環境","AIツール"],"ko":["Feature Summary","AI 에이전트","Git Blame","플러그인","특성 문서","개발 효율성","가벼운","개발 환경","AI 도구"],"es":["resumen de características","documentación de funciones","comunicación de funciones","herramientas de documentación de código","plugins de Visual Studio","catálogos de funciones","documentación de usuario","desarrollo de software","gestión de proyectos"],"fr":["résumé de fonctionnalités","documentation de fonctionnalités","communication de fonctionnalités","outils de documentation de code","plugins de Visual Studio","catalogues de fonctionnalités","documentation utilisateur","développement de logiciels","gestion de projets"],"de":["Funktionszusammenfassung","Funktionsdokumentation","Funktionenkommunikation","Code-Dokumentations-Tools","Visual Studio-Plugins","Funktionskataloge","Benutzerdokumentation","Softwareentwicklung","Projektmanagement"],"pt":["feature-summary","documentação de recursos","comunicação de fiche","Visual Studio","Git","desenvolvedores","stakeholders","plugin leve","tutorial de configuração"],"ru":["фич-саммари","документация фич","коммуникация фич","Visual Studio","Git","разработчики","заинтересованные стороны","лёгкий плагин","руководство по настройке"],"ar":["ميزة feature-summary","توثيق الميزات","تبادل الميزات","منصة Git","المطورين","أصحاب المصلحة","إضافة خفيفة","دليل الإعداد"]}},"owner":"prulloac","repo":"git-blame-vsc","repoPath":"prulloac/git-blame-vsc","stars":0,"forks":0,"updatedAt":"2026-02-24T00:33:08Z","topics":[],"category":"community","skillMd":{"name":"feature-summary","description":"Create comprehensive feature documentation summaries that describe current and future capabilities. Use after feature-breakdown to document what a feature does, its business value, technical implementation, and roadmap. Ideal for creating user-facing documentation and feature catalogs in `docs/features/<feature-name>/` format.","bodyPreview":"# Feature Summary Skill\n\n**Answers the question: How do we DOCUMENT and COMMUNICATE a feature to stakeholders, users, and developers?**\n\nThis skill focuses on **feature documentation and communication**, transforming detailed breakdowns into accessible, comprehensive summaries that serve multiple audiences.\n\n## When to Use\n\nUse this skill when you have a **completed feature** (or a detailed feature breakdown) and need to:\n- Create comprehensive user-facing documentation\n- Build a feature catalog","body":"# Feature Summary Skill\n\n**Answers the question: How do we DOCUMENT and COMMUNICATE a feature to stakeholders, users, and developers?**\n\nThis skill focuses on **feature documentation and communication**, transforming detailed breakdowns into accessible, comprehensive summaries that serve multiple audiences.\n\n## When to Use\n\nUse this skill when you have a **completed feature** (or a detailed feature breakdown) and need to:\n- Create comprehensive user-facing documentation\n- Build a feature catalog or knowledge base\n- Document business features for stakeholder communication\n- Explain technical implementation to developers\n- Create feature roadmaps and status tracking\n- Document current and future capabilities\n- Classify features by type (core, customization, performance, accessibility, UX)\n\n**Key indicator**: You''re asking \"How do we document and communicate this feature?\" or \"What should users know about this capability?\"\n\n**Works best with**: This skill complements `feature-breakdown` (provides the detailed task list) and `feature-planning` (provides the execution sequence)\n\n## When NOT to Use\n\n- You only have a feature idea/spec without breakdown details → Use `feature-breakdown` first\n- You need to determine task execution order → Use `feature-planning` instead\n- You need to track real-time implementation progress → Use `execution-tracking` instead\n\n## Prerequisites\n\nRecommended (but not strictly required):\n\n1. **Feature breakdown** (`docs/features/[feature-name]/breakdown.md`)\n   - Provides detailed task list and component architecture\n   - Helps identify all feature aspects to document\n   \n2. **Feature implementation** (completed or well-understood)\n   - Access to working code or specifications\n   - Understanding of current status\n\n3. **Audience understanding**\n   - Who will read this documentation?\n   - What do they need to know?\n\n## Inputs\n\n- **Feature specification or implemented feature** (required)\n- **Feature breakdown document** (recommended): `docs/features/[feature-name]/breakdown.md`\n- **Source code access** (optional but helpful): For accurate implementation details\n- **Usage examples** (optional): For user documentation\n\n## Directory Structure\n\nAll feature-summary output must follow this structure:\n\n```\ndocs/features/[feature-name]/\n├── breakdown.md              (created by feature-breakdown skill)\n├── summary.md                (created by this skill - PRIMARY OUTPUT)\n├── configuration.md          (optional - created by this skill)\n├── reference.md              (optional - created by this skill)\n└── implementation-progress.md (created by execution-tracking skill during implementation)\n```\n\n## Outputs\n\n**MANDATORY FILE ORGANIZATION**: All feature documentation must be in `docs/features/<feature-name>/` subdirectory.\n\nWhen this skill completes, it creates:\n\n1. **Primary Output: Feature Summary** (`docs/features/[feature-name]/summary.md`)\n   - Comprehensive feature documentation\n   - 150-250 lines covering all major aspects\n   - Serves multiple audiences (users, developers, stakeholders)\n   - Includes feature type classification\n   - **Example**: `docs/features/git-blame-overlay/summary.md`\n\n2. **Optional: Configuration Reference** (`docs/features/[feature-name]/configuration.md`)\n   - Detailed configuration options and examples\n   - For features with significant customization\n   \n3. **Optional: Reference Guide** (`docs/features/[feature-name]/reference.md`)\n   - Technical implementation details for developers\n   - Architecture decisions and patterns\n   \n4. **Supporting Structure**:\n   - `docs/features/[feature-name]/breakdown.md` - Implementation tasks (created by feature-breakdown skill)\n   - `docs/features/[feature-name]/implementation-progress.md` - Tracking file (created by execution-tracking skill)\n\n## Workflow Overview\n\nThe feature summary process transforms a feature concept into comprehensive documentation:\n\n```\nFeature Input (Breakdown or Implementation)\n    ↓\nAnalyze Feature Aspects\n    ↓\nIdentify Audiences & Use Cases\n    ↓\nClassify Feature Type\n    ↓\nCreate Executive Summary\n    ↓\nDocument Configuration & Options\n    ↓\nExplain Technical Implementation\n    ↓\nDefine Status & Version Info\n    ↓\nIdentify Limitations & Future Enhancements\n    ↓\nWrite Output Files\n    ↓\nComprehensive Feature Documentation\n```\n\n## Core Workflow\n\n### Phase 1: Analyze Feature Scope\n\n**Input**: Feature specification, breakdown, or implementation\n\n1. **Identify feature aspects**:\n   - What does it do? (Core functionality)\n   - Why is it valuable? (Business value)\n   - How do users interact with it? (User experience)\n   - What are the key capabilities? (Feature list)\n   - What are the limitations? (Edge cases and constraints)\n\n2. **Extract technical details**:\n   - How is it implemented? (Architecture, components)\n   - What are the technical requirements? (Dependencies, prerequisites)\n   - Where is the code located? (Source file references)\n   - What patterns or technologies are used?\n\n3. **Understand current state**:\n   - Version number and release status\n   - When was it introduced?\n   - What improvements or fixes have been made?\n   - Is it production-ready?\n\n### Phase 2: Classify Feature Type\n\nAssign the feature to one or more categories:\n\n| Category | Description | Examples |\n|----------|-------------|----------|\n| **Core Functionality** | Essential feature defining the product''s primary purpose | Git blame overlay, authentication system |\n| **Customization** | Allows users to personalize behavior and appearance | Output patterns, color customization |\n| **User Experience** | Improves usability, visual integration, and workflow | Theme adaptation, command palette |\n| **Accessibility** | Supports users with different abilities and needs | Color options, keyboard shortcuts, ARIA labels |\n| **Performance** | Optimizes speed and resource usage | Caching, lazy loading, pagination |\n| **Extended Functionality** | Non-essential features that enhance core capability | Advanced filtering, export options |\n| **Developer Experience** | Improves developer productivity and experience | Debugging tools, API documentation |\n\n## Output Format\n\nFeature summaries include these key sections (in order):\n\n1. **Feature Header** - Name, overview, status, version, feature type\n2. **Business Value** - Why it matters, specific benefits\n3. **What It Does** - Core functionality with user experience and examples\n4. **Key Features** - Capabilities and extended functionality\n5. **Configuration** (if applicable) - Options and examples\n6. **Technical Implementation** - Code references and architecture\n7. **User Interactions** - Workflows and commands\n8. **Status and Roadmap** - Current status, limitations, future enhancements\n9. **Related Features** - Cross-references to related features\n\n**For a complete template with examples and detailed guidelines**, see:\n- [`assets/documentation-template.md`](assets/documentation-template.md) - Blank template for creating new features\n- [`examples/example-feature-summary-core.md`](examples/example-feature-summary-core.md) - Core functionality example\n- [`examples/example-feature-summary-customization.md`](examples/example-feature-summary-customization.md) - Customization example\n- [`examples/example-feature-summary-performance.md`](examples/example-feature-summary-performance.md) - Performance example\n\n## Feature Type Classification\n\nEvery feature should be classified with a primary type and optional secondary types. This helps users understand:\n- **What is this feature?** (Its purpose)\n- **Is it essential?** (Core vs. optional)\n- **How does it relate to other features?** (Ecosystem awareness)\n\n### Quick Reference\n\n| Type | Icon | Purpose | Example |\n|------|------|---------|---------|\n| **Core Functionality** | ⭐ | Essential, defines product purpose | Git blame overlay |\n| **Customization** | 🎨 | Personalization & preferences | Output patterns |\n| **User Experience** | 👥 | Usability & visual integration | Theme-aware styling |\n| **Accessibility** | ♿ | Support for diverse users | Color options |\n| **Performance** | 🚀 | Speed & resource optimization | Caching system |\n| **Extended Functionality** | ➕ | Optional enhancements | Export options |\n| **Developer Experience** | 🛠️ | Developer productivity | API docs |\n\n**For detailed guidance on each type**, see [`references/feature-type-reference.md`](references/feature-type-reference.md)\n\n## Guidelines\n\n### Writing for Multiple Audiences\n\n**For Users**:\n- Use clear, non-technical language\n- Explain benefits and use cases\n- Provide concrete examples\n- Include configuration examples\n\n**For Developers**:\n- Include code references and file paths\n- Explain architecture and design decisions\n- Document patterns and conventions\n- Link to technical documentation\n\n**For Stakeholders**:\n- Lead with business value\n- Emphasize impact and ROI\n- Focus on status and roadmap\n- Quantify benefits where possible\n\n### Feature Classification\n\nWhen assigning feature types:\n\n1. **Identify primary category**: What is this feature''s main purpose?\n2. **Note secondary categories**: Can it serve multiple purposes?\n3. **Explain classification**: Why does this categorization make sense?\n4. **Consider user perception**: How do users think about this feature?\n\n### Technical Accuracy\n\n- Reference actual source code paths\n- Include line numbers for specific implementations\n- Verify all code examples work correctly\n- Document technical constraints accurately\n\n### Keeping Documentation Current\n\n- Update status section when feature versions change\n- Add to limitations if new constraints are discovered\n- Move items from \"Future Enhancements\" when implemented\n- Update configuration examples if options change\n\n## Common Pitfalls to Avoid\n\n❌ **Too technical for users**: Remember non-technical readers; explain technical concepts\n❌ **Too vague for developers**: Provide specific code references and implementation details\n❌ **Incomplete feature classification**: Always explain why a feature fits its category\n❌ **Missing examples**: Concrete examples are crucial for understanding\n❌ **Outdated information**: Keep status and version info current\n❌ **Poor cross-linking**: Reference related features; help readers understand relationships\n❌ **Missing technical details**: Developers need code references and architecture info\n\n## Integration with Other Skills\n\nThe feature-summary skill works as part of a larger feature documentation ecosystem. For detailed integration workflows and examples:\n\n- **Overview of the skill ecosystem**: [`references/ecosystem-diagram.md`](references/ecosystem-diagram.md)\n- **Practical integration workflows**: [`references/workflow-integration-guide.md`](references/workflow-integration-guide.md)\n- **Quick navigation**: [`references/integration-guide.md`](references/integration-guide.md)\n\n### Recommended Skill Sequence\n\n1. **feature-breakdown** (1-2 hrs) - Decompose feature into tasks and acceptance criteria\n2. **feature-summary** (1-2 hrs) - Create user-facing documentation\n3. **feature-planning** (1-2 hrs) - Sequence tasks for execution\n4. **execution-tracking** (ongoing) - Monitor implementation progress\n\n### Key Concepts\n\n**feature-breakdown creates** (`docs/features/[name]/breakdown.md`):\n- Internal task list\n- Component architecture\n- Acceptance criteria\n- Validation plan\n\n**feature-summary creates** (`docs/features/[name]/summary.md`):\n- User-facing documentation\n- Business value explanation\n- Configuration examples\n- Roadmap and future enhancements\n\n## Quality Checklist\n\nBefore finalizing feature documentation:\n\n- [ ] Feature type classification is clear and explained\n- [ ] Business value section explains \"why\" not just \"what\"\n- [ ] Examples show real-world usage\n- [ ] Technical details are accurate with code references\n- [ ] Configuration options are clearly documented\n- [ ] Status and version info are current\n- [ ] Known limitations are honestly documented\n- [ ] Future enhancements are realistic and categorized\n- [ ] Cross-references to related features are accurate\n- [ ] Documentation is accessible to intended audiences\n- [ ] Language is clear and concise\n- [ ] All file paths and code references are accurate\n\n## Example Output\n\nFor a real example of how feature documentation should look, see the example feature summaries:\n\n- Reference: `examples/example-feature-summary-core.md` (Core functionality example)\n- Reference: `examples/example-feature-summary-customization.md` (Customization example)\n- Reference: `examples/example-feature-summary-performance.md` (Performance feature example)\n\n## See Also\n\n- `feature-breakdown` - Decompose features into tasks\n- `feature-planning` - Sequence tasks for execution\n- `execution-tracking` - Monitor feature implementation progress\n- `readme-updater` - Keep project README in sync with features\n"},"lastSynced":"2026-03-07T04:01:48.375Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing to create comprehensive feature documentation for stakeholders, users, and developers.","zh":"非常适合需要为利益相关者、用户和开发人员创建全面功能文档的技术写作代理。","ja":"ステークホルダー、ユーザー、開発者向けに包括的な機能ドキュメントを作成する必要があるテクニカルライティングエージェントに最適です。","ko":"스테이크홀더, 사용자 및 개발자를 위한 포괄적인 기능 문서를 작성해야 하는 기술 작성 에이전트에 적합합니다.","es":"Perfecto para agentes de redacción técnica que necesitan crear documentación de características comprehensiva para partes interesadas, usuarios y desarrolladores.","fr":"Parfait pour les agents de rédaction technique ayant besoin de créer une documentation de fonctionnalités complète pour les parties prenantes, les utilisateurs et les développeurs.","de":"Perfekt für technische Schreibagenten, die umfassende Funktionsdokumentationen für Stakeholder, Benutzer und Entwickler erstellen müssen.","pt":"Perfeito para Agentes de Redação Técnica que precisam criar documentação de recurso abrangente para partes interessadas, usuários e desenvolvedores.","ru":"Идеально подходит для агентов технической документации, которым необходимо создавать всестороннюю документацию по функциям для заинтересованных сторон, пользователей и разработчиков.","ar":"مثالي لعميل الكتابة الفنية الذين يحتاجون إلى إنشاء توثيق ميزة شامل لجميع أصحاب المصلحة والمستخدمين والمطورين."},"recommendation":{"en":"Empowers agents to transform detailed feature breakdowns into accessible summaries using feature documentation and communication protocols, supporting multiple audiences and formats such as user-facing documentation and feature catalogs.","zh":"赋予代理人使用功能文档和通信协议将详细的功能细分转化为可访问的摘要的能力，支持多个受众和格式，例如用户面向的文档和功能目录。","ja":"機能ドキュメントとコミュニケーションプロトコルを使用して、詳細な機能ブレークダウンをアクセス可能なサマリーに変換するエージェントの能力を提供し、ユーザー向けのドキュメントや機能カタログなどの複数のオーディエンスや形式をサポートします。","ko":"세부 기능 분해를 사용 가능한 요약으로 변환하기 위한 기능 문서 및 통신 프로토콜을 사용하여 에이전트의 능력을 부여하며, 여러 사용자 및 형식(예: 사용자向け 문서 및 기능 카탈로그)을 지원합니다.","es":"Permite a los agentes transformar desgloses detallados de características en resúmenes accesibles utilizando documentación de características y protocolos de comunicación, y soporta múltiples audiencias y formatos como documentación orientada al usuario y catálogos de características.","fr":"Permet aux agents de transformer des analyses détaillées de fonctionnalités en résumés accessibles en utilisant la documentation de fonctionnalités et les protocoles de communication, et prend en charge plusieurs publics et formats tels que la documentation orientée utilisateur et les catalogues de fonctionnalités.","de":"Ermächtigt Agenten, detaillierte Funktionsanalysen in zugängliche Zusammenfassungen umzuwandeln, indem sie Funktionsdokumentation und Kommunikationsprotokolle verwenden, und unterstützt mehrere Zielgruppen und Formate wie benutzerorientierte Dokumentation und Funktionskataloge.","pt":"Habilita os agentes a transformar quebras detalhadas de recursos em resumos acessíveis usando documentação de recursos e protocolos de comunicação, suportando vários públicos e formatos, como documentação voltada para o usuário e catálogos de recursos.","ru":"Наделяет агентов возможностью преобразовывать подробный анализ функций в доступные резюме с помощью документации функций и протоколов связи, поддерживая различные аудитории и форматы, такие как документация, ориентированная на пользователя, и каталоги функций.","ar":"يمنح الوكلاء القدرة على تحويل تحليل مفصل للميزات إلى ملخصات يمكن الوصول إليها باستخدام توثيق الميزات وبروتوكولات الاتصال، لدعم جمهور متنوع وتنسيقات مثل توثيق المستخدم ومجموعات الميزات."},"useCases":{"en":["Generating comprehensive user-facing documentation","Building feature catalogs for stakeholders","Creating accessible summaries for developers"],"zh":["生成全面用户面向的文档","为利益相关者构建功能目录","为开发人员创建可访问的摘要"],"ja":["包括的なユーザー向けドキュメントを生成する","ステークホルダー向けの機能カタログを構築する","開発者向けのアクセス可能なサマリーを作成する"],"ko":["포괄적인 사용자向け 문서 생성","스테이크홀더를 위한 기능 카탈로그 구축","개발자를 위한 접근 가능한 요약 생성"],"es":["Generación de documentación completa orientada al usuario","Creación de catálogos de características para partes interesadas","Creación de resúmenes accesibles para desarrolladores"],"fr":["Génération de documentation complète orientée utilisateur","Création de catalogues de fonctionnalités pour les parties prenantes","Création de résumés accessibles pour les développeurs"],"de":["Erstellung umfassender benutzerorientierter Dokumentation","Erstellung von Funktionskatalogen für Stakeholder","Erstellung zugänglicher Zusammenfassungen für Entwickler"],"pt":["Geração de documentação abrangente voltada para o usuário","Construção de catálogos de recursos para partes interessadas","Criação de resumos acessíveis para desenvolvedores"],"ru":["Генерация всесторонней документации, ориентированной на пользователя","Создание каталогов функций для заинтересованных сторон","Создание доступных резюме для разработчиков"],"ar":["إنتاج توثيق شامل موجه للمستخدم","بناء فهرس الميزات لأصحاب المصلحة","إنشاء ملخصات يمكن الوصول إليها للمطورين"]},"limitations":{"en":["Requires completed feature or detailed feature breakdown","Focuses on feature documentation and communication only"],"zh":["需要完成的功能或详细功能细分","仅关注功能文档和通信"],"ja":["完了した機能または詳細な機能ブレークダウンが必要","機能ドキュメントとコミュニケーションのみに焦点を当てている"],"ko":["완료된 기능 또는 세부 기능 분해가 필요","기능 문서 및 통신에만 중점을 둠"],"es":["Requiere una característica o desglose de característica completado","Se centra solo en documentación y comunicación de características"],"fr":["Nécessite une fonctionnalité ou une analyse de fonctionnalité complète","Se concentre uniquement sur la documentation et la communication de fonctionnalités"],"de":["Benötigt eine abgeschlossene Funktion oder detaillierte Funktionsanalyse","Konzentriert sich ausschließlich auf Funktionsdokumentation und -kommunikation"],"pt":["Exige recurso concluído ou quebra detalhada de recurso","Concentra-se apenas na documentação e comunicação de recursos"],"ru":["Требует завершенного функционала или подробного анализа функций","Сосредоточен только на документации и связи функций"],"ar":["يتطلب ميزة مكتملة أو تحليل مفصل للميزة","يركز فقط على توثيق الميزات وبروتوكول الاتصال"]},"version":4},"contentHash":"c62b6903f190733fbb871982f2629346d589fdf6e0cbaef916f75971d90e8b1e","qualityScore":60}');
