INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('prulloac/git-blame-vsc/feature-summary', 'feature-summary', 'prulloac', 'git-blame-vsc', 'community', 'feature-summary prulloac git-blame-vsc community The feature-summary skill transforms detailed feature breakdowns into accessible summaries for multiple audiences, including stakeholders, users, and developers. It focuses on feature documentation and communication. Feature Summary是一个轻量级的Git Blame可视化插件，用于创建和管理特性文档 Feature Summaryは軽量級のGit Blame可視化プラグインであり、特性ドキュメントの作成と管理に使用されます Feature Summary는 가벼운 Git Blame 플러그인으로서 특성 문서의 생성과 관리에 사용됩니다 El resumen de características es una habilidad que permite transformar desgloses detallados en resúmenes accesibles y completos para múltiples audiencias. Se utiliza para crear documentación de usuario y catálogos de funciones. Le résumé de fonctionnalités est une compétence qui permet de transformer les décompositions détaillées en résumés accessibles et complets pour plusieurs publics. Il est utilisé pour créer une documentation utilisateur et des catalogues de fonctionnalités. Die Funktionszusammenfassung ist eine Fähigkeit, die es ermöglicht, detaillierte Aufschlüsselungen in zugängliche und vollständige Zusammenfassungen für mehrere Zielgruppen umzuwandeln. Sie wird verwendet, um Benutzerdokumentation und Funktionskataloge zu erstellen. O feature-summary é um plugin leve para Git que ajuda a documentar e comunicar recursos para desenvolvedores e stakeholders Фич-саммари - это лёгкий плагин для Git, помогающий документировать и коммуницировать фичи для разработчиков и заинтересованных сторон ميزة feature-summary هي إضافة خفيفة لمنصة Git تساعد على توثيق وتبادل الميزات مع المطورين وأصحاب المصلحة how to use feature-summary what is feature-summary feature-summary alternative feature-summary vs git blame feature-summary install feature-summary setup guide feature documentation best practices git blame visual studio plugin Feature Summary AIエージェント Git Blame 可视化插件 特性文档 开发效率 轻量级 开发环境 AI工具 Generates comprehensive user-facing documentation Builds a feature catalog for stakeholders and developers Transforms detailed breakdowns into accessible summaries Supports feature documentation and communication for multiple audiences Creates summaries for completed features or detailed feature breakdowns Enables the creation of a feature catalog feature-summary is a skill that enables the creation of comprehensive feature documentation and communication, serving multiple audiences through accessible summaries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TharushaKula/AI-video-editor/video-processing-editing', 'community', 'TharushaKula', 'AI-video-editor', 'TharushaKula/AI-video-editor', 'video-processing-editing', 0, 0, 60, '2026-02-22T07:08:03Z', '2026-03-07T04:03:42.103Z', '90390179df5f83bd86b72ddaf03867bae61ae25fecb1db0a914b7fd2519e6c59', '{"id":"TharushaKula/AI-video-editor/video-processing-editing","name":"video-processing-editing","description":{"en":"The video-processing-editing skill provides expert-level FFmpeg-based video editing and processing automation for modern content creation workflows, benefiting developers and content creators alike.","zh":"本视频处理编辑技能专注于FFmpeg基于的视频编辑、处理自动化和导出优化","ja":"このビデオ編集＆処理スキルは、FFmpegベースのビデオ編集、処理自動化、エクスポート最適化に特化","ko":"이 비디오 처리 편집 스킬은 FFmpeg 기반의 비디오 편집, 처리 자동화, xuất 최적화에 특화","es":"El procesamiento y la edición de video con FFmpeg permiten la automatización de pipelines de edición y la optimización de flujos de trabajo","fr":"Le traitement et l''édition vidéo avec FFmpeg permettent l''automatisation des pipelines de montage et l''optimisation des flux de travail","de":"Die Videoverarbeitung und -bearbeitung mit FFmpeg ermöglichen die Automatisierung von Bearbeitungspipelines und die Optimierung von Arbeitsflüssen","pt":"Edição de vídeo automatizada com FFmpeg para criação de conteúdo moderno","ru":"Автоматизация видеообработки и редактирования для современных рабочих процессов создания контента","ar":"تعديل الفيديو التلقائي باستخدام تقنيات ذكاء اصطناعي لزيادة الإنتاجية"},"seo":{"title":{"en":"Video-Processing-Editing: FFmpeg-Based Workflow Optimizat...","zh":"视频处理编辑最佳实践：FFmpeg自动化","ja":"ビデオ編集＆処理のためのAIエージェント：FFmpegベースの自動化","ko":"비디오 처리 편집 가이드: FFmpeg 기반 자동화","es":"Guía de configuración de procesamiento y edición de video...","fr":"Guide de mise en place du traitement et de l''édition vidé...","de":"Einrichtungsleitfaden für Videoverarbeitung und -bearbeit...","pt":"Guia de Configuração de Edição de Vídeo com FFmpeg","ru":"Настройка видеообработки и редактирования с помощью ИИ Аг...","ar":"دليل إعداد وتعديل الفيديو باستخدام تقنيات ذكاء اصطناعي"},"description":{"en":"Unlock efficient video editing pipelines with FFmpeg-based automation, export optimization, and more. Learn how to leverage video-processing-editing for your...","zh":"使用AI驱动的视频处理编辑工具，自动化您的视频编辑流程，实现高效的内容创作","ja":"AIエージェントによるビデオ編集＆処理を自動化し、効率的なコンテンツ創作を実現","ko":"AI 기반 비디오 처리 편집 툴을 사용하여 비디오 편집 프로세스를 자동화하고 효율적인 콘텐츠 제작을 실현","es":"Aprende a automatizar pipelines de edición de video con FFmpeg y optimiza tus flujos de trabajo de creación de contenido","fr":"Découvrez comment automatiser les pipelines de montage vidéo avec FFmpeg et optimisez vos flux de travail de création de contenu","de":"Erfahren Sie, wie Sie Video-Bearbeitungspipelines mit FFmpeg automatisieren und Ihre Inhalts-Erstellungs-Workflows optimieren","pt":"Aprenda a automatizar pipelines de edição de vídeo com FFmpeg e otimize a exportação para plataformas modernas","ru":"Автоматизируйте видеообработку и редактирование с помощью ИИ Агентов и оптимизируйте экспорт для современных платформ","ar":"تعلم كيفية توفير وقتك باستخدام تقنيات ذكاء اصطناعي لتعديل الفيديو وتحسين الإنتاجية"},"definition":{"en":"Video-processing-editing is a skill that expertly utilizes FFmpeg for automated video editing, processing, and export optimization in content creation workflows.","zh":"视频处理编辑是指使用AI驱动的工具自动化视频编辑、处理和优化的过程","ja":"ビデオ編集＆処理とは、AIエージェントを使用してビデオ編集、処理、最適化を自動化するプロセス","ko":"비디오 처리 편집은 AI 기반 도구를 사용하여 비디오 편집, 처리, 최적화를 자동화하는 과정","es":"El procesamiento y la edición de video es la capacidad de automatizar tareas de edición y optimizar la exportación de videos","fr":"Le traitement et l''édition vidéo est la capacité d''automatiser les tâches de montage et d''optimiser l''exportation de vidéos","de":"Die Videoverarbeitung und -bearbeitung ist die Fähigkeit, Bearbeitungsaufgaben zu automatisieren und die Exportierung von Videos zu optimieren","pt":"Edição de vídeo é o processo de manipulação de vídeos para criar conteúdo de mídia","ru":"Видеоредактирование - это процесс обработки видео для создания мультимедийного контента","ar":"تعديل الفيديو هو عملية تحرير وتعديل الفيديوهات لإنشاء محتوى إعلامي"},"features":{"en":["Automated video editing pipelines using script-to-video functionality","Clip cutting, trimming, and concatenation with transition and effect additions","Audio mixing and normalization for optimized sound quality","Subtitle and caption handling for accessible video content","Export optimization for various platforms using FFmpeg"],"zh":["FFmpeg基于的视频编辑","自动化视频编辑流程","剪切、修剪、连接片段","添加过渡、特效、覆盖层","音频混音和归一化","字幕/标题处理"],"ja":["FFmpegベースのビデオ編集","ビデオ編集プロセスの自動化","クリップのカット、トリミング、連結","トランジション、エフェクト、オーバーレイの追加","オーディオミキシングと正規化","字幕/キャプションの処理"],"ko":["FFmpeg 기반의 비디오 편집","비디오 편집 프로세스의 자동화","클립의 컷, 트리밍, 연결","트랜지션, 이펙트, 오버레이의 추가","오디오 믹싱과 정규화","자막/캡션의 처리"],"es":["Automatización de pipelines de edición de video con script-to-video","Corte, recorte y concatenación de clips de video","Adición de transiciones, efectos y superposiciones","Mezcla y normalización de audio","Manipulación de subtítulos y leyendas"],"fr":["Automatisation des pipelines de montage vidéo avec script-to-video","Coupe, décalage et concaténation de clips vidéo","Ajout de transitions, d''effets et de superpositions","Mixage et normalisation audio","Manipulation de sous-titres et de légendes"],"de":["Automatisierung von Video-Bearbeitungspipelines mit script-to-video","Schnitt, Trimmen und Verkettung von Videoclips","Hinzufügen von Übergängen, Effekten und Überlagerungen","Audio-Mischung und -Normalisierung","Manipulation von Untertiteln und Legenden"],"pt":["Edição de vídeo automatizada com FFmpeg","Corte, corte e concatenação de cliques","Adição de transições, efeitos e sobreposições","Mistura e normalização de áudio","Manipulação de legendas e legendas"],"ru":["Автоматизированное видеообработка с помощью FFmpeg","Обрезка, обрезка и соединение клипов","Добавление переходов, эффектов и наложений","Смешивание и нормализация аудио","Обработка субтитров и титров"],"ar":["تعديل الفيديو التلقائي باستخدام FFmpeg","قص وتركيب الفيديوهات","إضافة انتقالات وآثار وطبقات","مزج الصوت وتعديله","تعامل مع الترجمات والتعليقات"]},"keywords":{"en":["how to use video-processing-editing","video-processing-editing alternative","FFmpeg video editing tutorial","video-processing-editing setup guide","video editing pipeline optimization","automated video processing with FFmpeg","what is video-processing-editing","video-processing-editing vs Adobe Premiere","video-processing-editing install"],"zh":["视频处理编辑","FFmpeg","自动化视频编辑","视频编辑工具","AI驱动的视频处理","内容创作","视频导出优化"],"ja":["ビデオ編集＆処理","FFmpeg","ビデオ編集の自動化","ビデオ編集ツール","AIエージェントによるビデオ処理","コンテンツ創作","ビデオエクスポート最適化"],"ko":["비디오 처리 편집","FFmpeg","비디오 편집 자동화","비디오 편집 툴","AI 기반 비디오 처리","콘텐츠 제작","비디오 xuất 최적화"],"es":["procesamiento de video","edición de video","FFmpeg","automatización de pipelines","script-to-video","mejora de la exportación de video","herramientas de edición de video","tecnologías de video","desarrollo de video"],"fr":["traitement vidéo","édition vidéo","FFmpeg","automatisation des pipelines","script-to-video","amélioration de l''exportation de vidéo","outils de montage vidéo","technologies vidéo","développement de vidéo"],"de":["Videoverarbeitung","Videobearbeitung","FFmpeg","Automatisierung von Bearbeitungspipelines","script-to-video","Optimierung der Video-Exportierung","Video-Bearbeitungstools","Videotechnologien","Videorentwicklung"],"pt":["edição de vídeo","FFmpeg","automatização de pipelines","otimização de exportação","criação de conteúdo","vídeo processing","edição de vídeo automatizada"],"ru":["видеоредактирование","ИИ Агенты","автоматизация видеообработки","оптимизация экспорта","создание контента","видеообработка","автоматизированное видеоредактирование"],"ar":["تعديل الفيديو","تقنيات ذكاء اصطناعي","توفير وقت","زيادة الإنتاجية","إنشاء محتوى","معالجة الفيديو","تعديل الفيديو التلقائي"]}},"owner":"TharushaKula","repo":"AI-video-editor","repoPath":"TharushaKula/AI-video-editor","stars":0,"forks":0,"updatedAt":"2026-02-22T07:08:03Z","topics":[],"category":"community","skillMd":{"name":"video-processing-editing","description":"FFmpeg automation for cutting, trimming, concatenating videos. Audio mixing, timeline editing, transitions, effects. Export optimization for YouTube, social media. Subtitle handling, color grading, batch processing. Use for videogen projects, content creation, automated video production. Activate on video editing, FFmpeg, trim video, concatenate, transitions, export optimization. NOT for real-time video editing UI, 3D compositing, or motion graphics.","bodyPreview":"# Video Processing & Editing\n\nExpert in FFmpeg-based video editing, processing automation, and export optimization for modern content creation workflows.\n\n## When to Use\n\n✅ **Use for**:\n- Automated video editing pipelines (script-to-video)\n- Cutting, trimming, concatenating clips\n- Adding transitions, effects, overlays\n- Audio mixing and normalization\n- Subtitle/caption handling\n- Export optimization for platforms\n- Batch video processing\n- Color grading and correction\n\n❌ **NOT for**:\n- Real-tim","body":"# Video Processing & Editing\n\nExpert in FFmpeg-based video editing, processing automation, and export optimization for modern content creation workflows.\n\n## When to Use\n\n✅ **Use for**:\n- Automated video editing pipelines (script-to-video)\n- Cutting, trimming, concatenating clips\n- Adding transitions, effects, overlays\n- Audio mixing and normalization\n- Subtitle/caption handling\n- Export optimization for platforms\n- Batch video processing\n- Color grading and correction\n\n❌ **NOT for**:\n- Real-time video editing UI (use DaVinci Resolve/Premiere)\n- 3D compositing (use After Effects/Blender)\n- Motion graphics animation (use After Effects)\n- Basic screen recording (use OBS)\n\n---\n\n## Technology Selection\n\n### Video Editing Tools\n\n| Tool | Speed | Features | Use Case |\n|------|-------|----------|----------|\n| FFmpeg | Very Fast | CLI automation | Production pipelines |\n| MoviePy | Medium | Python API | Programmatic editing |\n| PyAV | Fast | Low-level control | Custom processing |\n| DaVinci Resolve | Slow | Full NLE | Manual editing |\n\n**Decision tree**:\n```\nNeed automation? → FFmpeg\nNeed Python API? → MoviePy\nNeed frame-level control? → PyAV\nNeed manual editing? → DaVinci Resolve\n```\n\n---\n\n## Common Anti-Patterns\n\n### Anti-Pattern 1: Not Using Keyframe-Aligned Cuts\n\n**Novice thinking**: \"Just cut the video at any timestamp\"\n\n**Problem**: Causes artifacts, black frames, and playback issues.\n\n**Wrong approach**:\n```bash\n# ❌ Cut at arbitrary timestamp (not keyframe-aligned)\nffmpeg -i input.mp4 -ss 00:01:23.456 -to 00:02:45.678 -c copy output.mp4\n\n# Result: Black frames, artifacts, sync issues\n```\n\n**Why wrong**:\n- Video codecs use keyframes (I-frames) every 2-10 seconds\n- Non-keyframe cuts require re-encoding\n- Using `-c copy` (stream copy) without keyframe alignment breaks playback\n- GOP (Group of Pictures) structure depends on keyframes\n\n**Correct approach 1**: Re-encode for precise cuts\n```bash\n# ✅ Re-encode for frame-accurate cutting\nffmpeg -i input.mp4 -ss 00:01:23.456 -to 00:02:45.678 \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a aac -b:a 192k \\\n  output.mp4\n\n# Frame-accurate, but slower (re-encoding)\n```\n\n**Correct approach 2**: Keyframe-aligned stream copy\n```bash\n# ✅ Fast cutting with keyframe alignment\n# Step 1: Find keyframes near cut points\nffprobe -select_streams v -show_frames -show_entries frame=pkt_pts_time,key_frame \\\n  -of csv input.mp4 | grep \",1$\" | awk -F'','' ''{print $2}''\n\n# Step 2: Cut at nearest keyframes (fast, no re-encoding)\nffmpeg -i input.mp4 -ss 00:01:22.000 -to 00:02:46.000 -c copy output.mp4\n\n# Blazing fast, no quality loss, but not frame-accurate\n```\n\n**Correct approach 3**: Two-pass for best of both worlds\n```bash\n# ✅ Fast seek + precise cut\nffmpeg -ss 00:01:20.000 -i input.mp4 \\\n  -ss 00:00:03.456 -to 00:01:25.678 \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a aac -b:a 192k \\\n  output.mp4\n\n# -ss BEFORE -i: Fast seek to keyframe (no decode)\n# -ss AFTER -i: Precise trim (only decode needed portion)\n```\n\n**Performance comparison**:\n| Method | Time (1-hour video) | Accuracy | Quality |\n|--------|---------------------|----------|---------|\n| Stream copy (arbitrary) | 2s | ❌ Broken | ❌ Artifacts |\n| Stream copy (keyframe) | 2s | ±2s | ✅ Perfect |\n| Re-encode (simple) | 15min | ✅ Frame | ⚠️ Quality loss |\n| Two-pass (optimal) | 3min | ✅ Frame | ✅ Perfect |\n\n**Timeline context**:\n- 2010: FFmpeg required full re-encoding for cuts\n- 2015: `-c copy` added for stream copying\n- 2020: Two-pass cutting became best practice\n- 2024: Hardware acceleration (NVENC) makes re-encoding viable\n\n---\n\n### Anti-Pattern 2: Re-encoding Unnecessarily\n\n**Novice thinking**: \"Apply all edits in one FFmpeg command\"\n\n**Problem**: Multiple re-encodings cause cumulative quality loss.\n\n**Wrong approach**:\n```bash\n# ❌ Re-encode for each operation (quality degradation)\n# Operation 1: Trim\nffmpeg -i input.mp4 -ss 00:01:00 -to 00:05:00 \\\n  -c:v libx264 -crf 23 temp1.mp4\n\n# Operation 2: Add audio\nffmpeg -i temp1.mp4 -i audio.mp3 -c:v libx264 -crf 23 \\\n  -map 0:v -map 1:a temp2.mp4\n\n# Operation 3: Add subtitles\nffmpeg -i temp2.mp4 -vf subtitles=subs.srt \\\n  -c:v libx264 -crf 23 output.mp4\n\n# Result: 3x re-encoding = significant quality loss\n```\n\n**Why wrong**:\n- Each re-encode is lossy (even with high CRF)\n- Cumulative quality loss (generation loss)\n- 3x encoding time\n- Wasted disk I/O\n\n**Correct approach 1**: Chain operations in single command\n```bash\n# ✅ Single-pass encoding with all operations\nffmpeg -ss 00:01:00 -i input.mp4 -i audio.mp3 \\\n  -to 00:04:00 \\\n  -vf \"subtitles=subs.srt\" \\\n  -map 0:v -map 1:a \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a aac -b:a 192k \\\n  output.mp4\n\n# Single re-encode, all operations applied at once\n```\n\n**Correct approach 2**: Use stream copy when possible\n```bash\n# ✅ Lossless operations with stream copy\n# Trim (stream copy)\nffmpeg -i input.mp4 -ss 00:01:00 -to 00:05:00 -c copy temp.mp4\n\n# Add audio (stream copy video, encode audio)\nffmpeg -i temp.mp4 -i audio.mp3 \\\n  -map 0:v -map 1:a \\\n  -c:v copy -c:a aac -b:a 192k \\\n  temp2.mp4\n\n# Burn subtitles (must re-encode video)\nffmpeg -i temp2.mp4 -vf subtitles=subs.srt \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a copy \\\n  output.mp4\n\n# Only 1 video re-encode (for subtitles)\n```\n\n**Quality comparison**:\n| Method | Encoding Passes | Quality (VMAF) | Time |\n|--------|-----------------|----------------|------|\n| 3x re-encode (CRF 23) | 3 | 82/100 | 45min |\n| Single pass (CRF 23) | 1 | 91/100 | 15min |\n| Stream copy + 1 encode | 1 | 95/100 | 18min |\n| All stream copy | 0 | 100/100 | 30s |\n\n---\n\n### Anti-Pattern 3: Ignoring Color Space Conversions\n\n**Novice thinking**: \"Just concatenate videos together\"\n\n**Problem**: Color shifts, mismatched brightness, broken playback.\n\n**Wrong approach**:\n```bash\n# ❌ Concatenate videos with different color spaces\n# clip1.mp4: BT.709 (HD), yuv420p\n# clip2.mp4: BT.601 (SD), yuvj420p (full range)\n# clip3.mp4: BT.2020 (HDR), yuv420p10le\n\n# Create concat list\necho \"file ''clip1.mp4''\" > list.txt\necho \"file ''clip2.mp4''\" >> list.txt\necho \"file ''clip3.mp4''\" >> list.txt\n\n# Concatenate without color normalization\nffmpeg -f concat -safe 0 -i list.txt -c copy output.mp4\n\n# Result: Color shifts between clips, broken HDR metadata\n```\n\n**Why wrong**:\n- Different color spaces (BT.601 vs BT.709 vs BT.2020)\n- Different pixel formats (yuv420p vs yuvj420p)\n- Different color ranges (limited vs full)\n- Metadata conflicts\n\n**Correct approach**:\n```bash\n# ✅ Normalize color space before concatenation\n\n# Step 1: Analyze color space of each clip\nffprobe -v error -select_streams v:0 \\\n  -show_entries stream=color_space,color_transfer,color_primaries,pix_fmt \\\n  -of default=noprint_wrappers=1 clip1.mp4\n\n# Step 2: Normalize all clips to common color space\n# Target: BT.709 (HD), yuv420p, limited range\n\n# Normalize clip1 (already BT.709)\nffmpeg -i clip1.mp4 -c copy clip1_normalized.mp4\n\n# Normalize clip2 (BT.601 SD → BT.709 HD)\nffmpeg -i clip2.mp4 \\\n  -vf \"scale=in_range=full:out_range=limited,colorspace=bt709:iall=bt601:fast=1\" \\\n  -color_primaries bt709 \\\n  -color_trc bt709 \\\n  -colorspace bt709 \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a copy \\\n  clip2_normalized.mp4\n\n# Normalize clip3 (BT.2020 HDR → BT.709 SDR)\nffmpeg -i clip3.mp4 \\\n  -vf \"zscale=t=linear:npl=100,format=gbrpf32le,zscale=p=bt709,tonemap=hable:desat=0,zscale=t=bt709:m=bt709:r=limited,format=yuv420p\" \\\n  -color_primaries bt709 \\\n  -color_trc bt709 \\\n  -colorspace bt709 \\\n  -c:v libx264 -crf 18 -preset medium \\\n  -c:a copy \\\n  clip3_normalized.mp4\n\n# Step 3: Concatenate normalized clips\necho \"file ''clip1_normalized.mp4''\" > list.txt\necho \"file ''clip2_normalized.mp4''\" >> list.txt\necho \"file ''clip3_normalized.mp4''\" >> list.txt\n\nffmpeg -f concat -safe 0 -i list.txt -c copy output.mp4\n```\n\n**Color space guide**:\n| Standard | Color Space | Transfer | Primaries | Use Case |\n|----------|-------------|----------|-----------|----------|\n| BT.601 | SD | bt470bg | bt470bg | Old SD content |\n| BT.709 | HD | bt709 | bt709 | Modern HD/FHD |\n| BT.2020 | UHD/HDR | smpte2084 | bt2020 | 4K HDR |\n| sRGB | Web | iec61966-2-1 | bt709 | Web delivery |\n\n---\n\n### Anti-Pattern 4: Poor Audio Sync\n\n**Novice thinking**: \"Video and audio are separate, just overlay them\"\n\n**Problem**: Lip sync issues, audio drift, broken playback.\n\n**Wrong approach**:\n```bash\n# ❌ Replace audio without sync consideration\nffmpeg -i video.mp4 -i audio.mp3 \\\n  -map 0:v -map 1:a \\\n  -c:v copy -c:a copy \\\n  output.mp4\n\n# Problems:\n# - Audio duration ≠ video duration\n# - No audio stretching/compression\n# - Drift over time\n```\n\n**Why wrong**:\n- Audio and video have different durations\n- No timebase synchronization\n- No drift correction\n- Ignores original audio sync\n\n**Correct approach 1**: Stretch/compress audio to match video\n```bash\n# ✅ Adjust audio speed to match video duration\n\n# Get durations\nVIDEO_DUR=$(ffprobe -v error -show_entries format=duration \\\n  -of default=noprint_wrappers=1:nokey=1 video.mp4)\nAUDIO_DUR=$(ffprobe -v error -show_entries format=duration \\\n  -of default=noprint_wrappers=1:nokey=1 audio.mp3)\n\n# Calculate speed ratio\nRATIO=$(echo \"$VIDEO_DUR / $AUDIO_DUR\" | bc -l)\n\n# Stretch audio to match video (with pitch correction)\nffmpeg -i video.mp4 -i audio.mp3 \\\n  -filter_complex \"[1:a]atempo=${RATIO}[a]\" \\\n  -map 0:v -map \"[a]\" \\\n  -c:v copy -c:a aac -b:a 192k \\\n  output.mp4\n```\n\n**Correct approach 2**: Precise offset and trim\n```bash\n# ✅ Sync audio with offset and trim\n\n# Audio starts 0.5s late, trim to match video\nffmpeg -i video.mp4 -itsoffset 0.5 -i audio.mp3 \\\n  -map 0:v -map 1:a \\\n  -shortest \\\n  -c:v copy -c:a aac -b:a 192k \\\n  output.mp4\n\n# -itsoffset: Delay audio by 0.5s\n# -shortest: Trim to shortest stream\n```\n\n**Correct approach 3**: Mix multiple audio tracks with sync\n```bash\n# ✅ Mix dialogue, music, effects with precise timing\n\nffmpeg -i video.mp4 -i dialogue.wav -i music.mp3 -i sfx.wav \\\n  -filter_complex \"\n    [1:a]adelay=0|0[dlg];\n    [2:a]volume=0.3,adelay=500|500[mus];\n    [3:a]adelay=1200|1200[sfx];\n    [dlg][mus][sfx]amix=inputs=3:duration=first[a]\n  \" \\\n  -map 0:v -map \"[a]\" \\\n  -c:v copy -c:a aac -b:a 256k \\\n  output.mp4\n\n# adelay: Precise millisecond timing\n# amix: Mix multiple audio streams\n# volume: Normalize levels\n```\n\n**Audio sync checklist**:\n```\n□ Verify video and audio durations match\n□ Use -shortest to prevent excess audio\n□ Apply adelay for precise timing offsets\n□ Use atempo for speed adjustment (maintains pitch)\n□ Set audio bitrate appropriately (128k-256k)\n□ Test lip sync at beginning, middle, end\n```\n\n---\n\n### Anti-Pattern 5: Wrong Codec/Bitrate for Platform\n\n**Novice thinking**: \"One export settings for everything\"\n\n**Problem**: Wasted bandwidth, poor quality, rejected uploads, compatibility issues.\n\n**Wrong approach**:\n```bash\n# ❌ Export everything at 4K 50 Mbps\nffmpeg -i input.mp4 \\\n  -c:v libx264 -b:v 50M -s 3840x2160 \\\n  -c:a aac -b:a 320k \\\n  output.mp4\n\n# For Instagram story: 2 GB file, rejected (max 100 MB)\n# For YouTube: Could use 10 Mbps and look identical\n# For Twitter: Exceeds bitrate limits\n```\n\n**Why wrong**:\n- Platform-specific size/bitrate limits\n- Over-encoding wastes bandwidth\n- Wrong resolution for platform\n- Incompatible codecs\n\n**Correct approach**: Platform-optimized exports\n\n**YouTube (recommended settings)**:\n```bash\n# ✅ YouTube 1080p upload\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset slow -crf 18 \\\n  -s 1920x1080 -r 30 \\\n  -pix_fmt yuv420p \\\n  -color_primaries bt709 -color_trc bt709 -colorspace bt709 \\\n  -movflags +faststart \\\n  -c:a aac -b:a 192k -ar 48000 \\\n  youtube_1080p.mp4\n\n# YouTube 4K upload\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset slow -crf 18 \\\n  -s 3840x2160 -r 60 \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 256k -ar 48000 \\\n  youtube_4k.mp4\n```\n\n**Instagram (Stories, Reels, Feed)**:\n```bash\n# ✅ Instagram Story (9:16, max 100 MB, 15s)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1080x1920 -r 30 -t 15 \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k \\\n  instagram_story.mp4\n\n# ✅ Instagram Reel (9:16, max 90s)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1080x1920 -r 30 -t 90 \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k \\\n  instagram_reel.mp4\n\n# ✅ Instagram Feed (1:1 or 4:5)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1080x1080 -r 30 \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k \\\n  instagram_feed.mp4\n```\n\n**Twitter/X**:\n```bash\n# ✅ Twitter video (max 512 MB, 2:20)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1280x720 -r 30 -t 140 \\\n  -maxrate 5000k -bufsize 10000k \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k \\\n  twitter.mp4\n```\n\n**TikTok**:\n```bash\n# ✅ TikTok (9:16, max 287 MB, 10 min)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1080x1920 -r 30 -t 600 \\\n  -pix_fmt yuv420p \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k \\\n  tiktok.mp4\n```\n\n**Web (HTML5 video)**:\n```bash\n# ✅ Web optimized (fast load, broad compatibility)\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset medium -crf 23 \\\n  -s 1920x1080 -r 30 \\\n  -pix_fmt yuv420p \\\n  -profile:v baseline -level 3.0 \\\n  -movflags +faststart \\\n  -c:a aac -b:a 128k -ar 48000 \\\n  web.mp4\n```\n\n**Platform specs table**:\n| Platform | Max Size | Max Duration | Resolution | FPS | Bitrate | Codec |\n|----------|----------|--------------|------------|-----|---------|-------|\n| YouTube | Unlimited | Unlimited | 8K | 60 | Auto | H.264/VP9 |\n| Instagram Story | 100 MB | 15s | 1080x1920 | 30 | ~5 Mbps | H.264 |\n| Instagram Reel | 1 GB | 90s | 1080x1920 | 30 | ~8 Mbps | H.264 |\n| Twitter | 512 MB | 2:20 | 1920x1080 | 60 | 5 Mbps | H.264 |\n| TikTok | 287 MB | 10min | 1080x1920 | 30 | ~4 Mbps | H.264 |\n| LinkedIn | 5 GB | 10min | 1920x1080 | 30 | 5 Mbps | H.264 |\n| Web | Varies | Varies | 1920x1080 | 30 | 2-5 Mbps | H.264 |\n\n**Export optimization checklist**:\n```\n□ Use -movflags +faststart for web (progressive download)\n□ Use -pix_fmt yuv420p for broad compatibility\n□ Set -r 30 for most platforms (avoid variable framerate)\n□ Use -preset slow for final exports (better quality)\n□ Use -preset ultrafast for drafts\n□ Apply -maxrate and -bufsize for streaming\n□ Test playback on target platform before bulk export\n```\n\n---\n\n## Production Checklist\n\n```\n□ Align cuts to keyframes (or two-pass seek)\n□ Chain operations in single FFmpeg command\n□ Normalize color spaces before concatenating\n□ Verify audio/video sync (test at multiple points)\n□ Use platform-specific export presets\n□ Apply -movflags +faststart for web delivery\n□ Set proper color metadata (bt709 for HD)\n□ Test output file on target platform\n□ Keep lossless intermediate files (ProRes, FFV1)\n□ Use hardware acceleration for batch jobs (NVENC, VideoToolbox)\n```\n\n---\n\n## When to Use vs Avoid\n\n| Scenario | Appropriate? |\n|----------|--------------|\n| Automated video pipeline (script → video) | ✅ Yes - FFmpeg automation |\n| Batch process 100 videos | ✅ Yes - parallel FFmpeg jobs |\n| Trim/cut clips programmatically | ✅ Yes - precise cutting |\n| Add subtitles to videos | ✅ Yes - burn or soft subs |\n| Color grade footage | ⚠️ Limited - basic only |\n| Multi-cam editing | ❌ No - use DaVinci Resolve |\n| Motion graphics | ❌ No - use After Effects |\n| Real-time preview editing | ❌ No - use Premiere/Resolve |\n\n---\n\n## References\n\n- `/references/ffmpeg-guide.md` - Complete FFmpeg command reference\n- `/references/timeline-editing.md` - Timeline concepts, multi-track editing\n- `/references/export-optimization.md` - Platform-specific export settings\n\n## Scripts\n\n- `scripts/video_editor.py` - Cut, trim, concatenate, transitions, effects\n- `scripts/batch_processor.py` - Parallel batch video processing\n\n---\n\n**This skill guides**: Video editing | FFmpeg | Timeline editing | Transitions | Export optimization | Audio mixing | Color grading | Automated video production\n"},"lastSynced":"2026-03-07T04:03:42.103Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Processing Agents needing advanced FFmpeg-based video editing and automation capabilities.","zh":"非常适合需要高级FFmpeg基于视频编辑和自动化能力的媒体处理代理。","ja":"メディア処理エージェントが高度なFFmpegベースのビデオ編集および自動化機能を必要とする場合に最適です。","ko":"고급 FFmpeg 기반 비디오 편집 및 자동화 기능이 필요한 미디어 처리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Procesamiento de Medios que necesitan capacidades avanzadas de edición y automatización de video basadas en FFmpeg.","fr":"Parfait pour les Agents de Traitement des Médias nécessitant des capacités avancées d''édition et d''automatisation de la vidéo basées sur FFmpeg.","de":"Perfekt für Media-Processing-Agents, die erweiterte FFmpeg-basierte Video-Bearbeitungs- und Automatisierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Processamento de Mídia que precisam de capacidades avançadas de edição e automação de vídeo baseadas em FFmpeg.","ru":"Идеально подходит для агентов обработки медиа, которым требуются продвинутые возможности редактирования и автоматизации видео на основе FFmpeg.","ar":"مثالي لعميل معالجة الوسائط التي تحتاج إلى قدرات متقدمة لتحرير الفيديو وأتمتة القائم على FFmpeg."},"recommendation":{"en":"Empowers agents to automate video editing pipelines with FFmpeg, enabling efficient cutting, trimming, and concatenating of clips, as well as adding transitions, effects, and overlays, with support for audio mixing, subtitle handling, and export optimization for various platforms.","zh":"赋予代理自动化视频编辑管道的能力，使用FFmpeg实现高效的剪切、修剪和连接片段，以及添加过渡、特效和叠加层，支持音频混合、字幕处理和针对各个平台的导出优化。","ja":"FFmpegを使用してビデオ編集パイプラインの自動化をエージェントに可能にし、効率的なクリッピング、トリミング、クリップの接続、および遷移、エフェクト、オーバーレイの追加、およびオーディオミックス、字幕処理、およびさまざまなプラットフォームのエクスポート最適化をサポートします。","ko":"FFmpeg를 사용하여 비디오 편집 파이프라인을 자동화할 수 있도록 에이전트를 능력화하여 클립핑, 트리밍, 클립 연결 등을 효율적으로 수행하고, 전환, 효과, 오버레이 추가 및 오디오 믹싱, 자막 처리 및 다양한 플랫폼을 위한 내보내기 최적화를 지원합니다.","es":"Habilita a los agentes a automatizar las tuberías de edición de video con FFmpeg, lo que permite un corte, recorte y concatenación eficientes de clips, así como agregar transiciones, efectos y superposiciones, con soporte para mezcla de audio, manejo de subtítulos y optimización de exportación para varias plataformas.","fr":"Permet aux agents d''automatiser les pipelines d''édition de vidéos avec FFmpeg, permettant un découpage, un rognage et une concaténation efficaces des clips, ainsi que l''ajout de transitions, d''effets et de superpositions, avec une prise en charge du mixage audio, de la gestion des sous-titres et de l''optimisation de l''exportation pour différentes plateformes.","de":"Ermöglicht es Agenten, Video-Bearbeitungspipelines mit FFmpeg zu automatisieren, wodurch effizientes Schneiden, Beschneiden und Verketten von Clips ermöglicht wird, sowie das Hinzufügen von Übergängen, Effekten und Überlagerungen, mit Unterstützung für Audio-Mixing, Untertitel-Handhabung und Export-Optimierung für verschiedene Plattformen.","pt":"Habilita os agentes a automatizar pipelines de edição de vídeo com FFmpeg, permitindo corte eficiente, corte, concatenação de cliques, bem como adicionar transições, efeitos e sobreposições, com suporte para mistura de áudio, manipulação de legendas e otimização de exportação para várias plataformas.","ru":"Наделяет агентов возможностью автоматизировать видеоредакторские конвейеры с помощью FFmpeg, обеспечивая эффективное обрезание, обрезку и объединение клипов, а также добавление переходов, эффектов и наложений, с поддержкой аудиосмешивания, обработки субтитров и оптимизации экспорта для различных платформ.","ar":"يُمنح الوكيل القدرة على أتمتة خطوط أنابيب تحرير الفيديو مع FFmpeg، وتمكين القص والتقليم والتحويل الرقمي للفيلم، بالإضافة إلى إضافة الانتقالات والأffects والتعليقات التوضيحية، مع دعم لمزج الصوت ومعالجة الترجمة والتحسين التصديري للمنصات المختلفة."},"useCases":{"en":["Automating video editing pipelines for script-to-video workflows","Batch processing videos for color grading and correction","Optimizing video exports for social media and online platforms"],"zh":["为脚本到视频工作流自动化视频编辑管道","批量处理视频进行色彩分级和更正","优化视频导出以适应社交媒体和在线平台"],"ja":["スクリプトからビデオのワークフロー用にビデオ編集パイプラインを自動化する","カラーグレーディングと修正のためのビデオのバッチ処理","ソーシャルメディアおよびオンラインプラットフォーム用にビデオエクスポートを最適化する"],"ko":["스크립트에서 비디오 워크플로우를 위한 비디오 편집 파이프라인 자동화","색상 그레이딩 및 보정을 위한 비디오 배치 처리","소셜 미디어 및 온라인 플랫폼을 위한 비디오 내보내기 최적화"],"es":["Automatizar las tuberías de edición de video para flujos de trabajo de script a video","Procesamiento por lotes de videos para gradación y corrección de color","Optimizar las exportaciones de video para redes sociales y plataformas en línea"],"fr":["Automatiser les pipelines d''édition de vidéos pour les flux de travail de script à vidéo","Traitement par lots de vidéos pour le gradation et la correction de la couleur","Optimiser les exportations de vidéos pour les réseaux sociaux et les plateformes en ligne"],"de":["Automatisieren von Video-Bearbeitungspipelines für Script-to-Video-Arbeitsabläufe","Batch-Verarbeitung von Videos für Farbgradierung und -korrektur","Optimieren von Video-Exporten für soziale Medien und Online-Plattformen"],"pt":["Automatizar pipelines de edição de vídeo para fluxos de trabalho de script para vídeo","Processamento em lote de vídeos para graduação e correção de cores","Otimizar exportações de vídeo para mídias sociais e plataformas online"],"ru":["Автоматизация видеоредакторских конвейеров для рабочих процессов от сценария к видео","Пакетная обработка видео для цветокоррекции и градации","Оптимизация видеоэкспорта для социальных сетей и онлайн-платформ"],"ar":["أتمتة خطوط أنابيب تحرير الفيديو لأعمال من سيناريو إلى فيديو","معالجة المجموعة من الفيديوهات لدرجات الألوان وتصحيحها","تحسين تصدير الفيديو إلى منصات التواصل الاجتماعي والمنصات عبر الإنترنت"]},"limitations":{"en":["Not suitable for real-time video processing","Requires FFmpeg installation and configuration"],"zh":["不适合实时视频处理","需要FFmpeg安装和配置"],"ja":["リアルタイムビデオ処理には不向き","FFmpegのインストールと設定が必要"],"ko":["실시간 비디오 처리에는 적합하지 않음","FFmpeg 설치 및 구성이 필요"],"es":["No apto para el procesamiento de video en tiempo real","Requiere instalación y configuración de FFmpeg"],"fr":["Non adapté pour le traitement de la vidéo en temps réel","Nécessite l''installation et la configuration de FFmpeg"],"de":["Nicht geeignet für Echtzeit-Videoverarbeitung","Benötigt FFmpeg-Installation und -Konfiguration"],"pt":["Não é adequado para processamento de vídeo em tempo real","Requer instalação e configuração do FFmpeg"],"ru":["Не подходит для обработки видео в режиме реального времени","Требует установки и настройки FFmpeg"],"ar":["غير مناسب للمعالجة الفورية للفيديو","يتطلب تثبيت وتكوين FFmpeg"]},"version":4},"contentHash":"90390179df5f83bd86b72ddaf03867bae61ae25fecb1db0a914b7fd2519e6c59","qualityScore":60}');
