INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TharushaKula/AI-video-editor/video-processing-editing', 'video-processing-editing', 'TharushaKula', 'AI-video-editor', 'community', 'video-processing-editing TharushaKula AI-video-editor community The video-processing-editing skill provides expert-level FFmpeg-based video editing and processing automation for modern content creation workflows, benefiting developers and content creators alike. 本视频处理编辑技能专注于FFmpeg基于的视频编辑、处理自动化和导出优化 このビデオ編集＆処理スキルは、FFmpegベースのビデオ編集、処理自動化、エクスポート最適化に特化 이 비디오 처리 편집 스킬은 FFmpeg 기반의 비디오 편집, 처리 자동화, xuất 최적화에 특화 El procesamiento y la edición de video con FFmpeg permiten la automatización de pipelines de edición y la optimización de flujos de trabajo Le traitement et l''édition vidéo avec FFmpeg permettent l''automatisation des pipelines de montage et l''optimisation des flux de travail Die Videoverarbeitung und -bearbeitung mit FFmpeg ermöglichen die Automatisierung von Bearbeitungspipelines und die Optimierung von Arbeitsflüssen Edição de vídeo automatizada com FFmpeg para criação de conteúdo moderno Автоматизация видеообработки и редактирования для современных рабочих процессов создания контента تعديل الفيديو التلقائي باستخدام تقنيات ذكاء اصطناعي لزيادة الإنتاجية how to use video-processing-editing video-processing-editing alternative FFmpeg video editing tutorial video-processing-editing setup guide video editing pipeline optimization automated video processing with FFmpeg what is video-processing-editing video-processing-editing vs Adobe Premiere video-processing-editing install 视频处理编辑 FFmpeg 自动化视频编辑 视频编辑工具 AI驱动的视频处理 内容创作 视频导出优化 Automated video editing pipelines using script-to-video functionality Clip cutting, trimming, and concatenation with transition and effect additions Audio mixing and normalization for optimized sound quality Subtitle and caption handling for accessible video content Export optimization for various platforms using FFmpeg Video-processing-editing is a skill that expertly utilizes FFmpeg for automated video editing, processing, and export optimization in content creation workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('prulloac/vibe-coding-template/feature-summary', 'community', 'prulloac', 'vibe-coding-template', 'prulloac/vibe-coding-template', 'feature-summary', 0, 0, 60, '2026-02-23T15:05:13Z', '2026-03-07T13:09:31.653Z', 'c62b6903f190733fbb871982f2629346d589fdf6e0cbaef916f75971d90e8b1e', '{"id":"prulloac/vibe-coding-template/feature-summary","name":"feature-summary","description":{"en":"The feature-summary skill transforms detailed feature breakdowns into comprehensive summaries for multiple audiences, including stakeholders, users, and developers. It facilitates the creation of user-facing documentation and feature catalogs.","zh":"功能摘要AI工具，用于创建用户文档和功能目录，支持多种受众","ja":"機能サマリAIエージェントは、ユーザー向けドキュメントと機能カタログを作成するために使用され、複数の受け手をサポートする","ko":"기능 요약 AI 에이전트는 사용자 문서와 기능 카탈로그를 생성하기 위해 사용되며 여러 受众을 지원합니다","es":"El resumen de características es una habilidad que se centra en la documentación y comunicación de características, transformando desgloses detallados en resúmenes accesibles","fr":"Le résumé de fonctionnalités est une compétence qui se concentre sur la documentation et la communication de fonctionnalités, transformant les décompositions détaillées en résumés accessibles","de":"Die Funktionszusammenfassung ist eine Fähigkeit, die sich auf die Dokumentation und Kommunikation von Funktionen konzentriert, indem sie detaillierte Aufschlüsselungen in zugängliche Zusammenfassungen umwandelt","pt":"O skill de resumo de recursos transforma descrições detalhadas em resumos acessíveis e abrangentes para stakeholders, usuários e desenvolvedores","ru":"Навык сводки функций преобразует подробные описания в доступные и всесторонние сводки для заинтересованных сторон, пользователей и разработчиков","ar":"مهارة ملخص الميزات تحول الوصف المفصل إلى ملخصات شاملة وقابلة للوصول لمختلف الأطراف المعنية"},"seo":{"title":{"en":"Feature-Summary: Comprehensive Documentation Setup Guide ...","zh":"AI工具：功能摘要设置指南","ja":"AIエージェント：機能サマリのベストプラクティス","ko":"AI 에이전트: 기능 요약 가이드","es":"Guía de configuración de resumen de características para ...","fr":"Guide de mise en place du résumé de fonctionnalités pour ...","de":"Einrichtungsleitfaden für Funktionszusammenfassung für En...","pt":"Guia de Configuração de Resumo de Recursos para Desenvolv...","ru":"Настройка ИИ Агентов: Руководство по Созданию Сводок Функций","ar":"دليل إعداد ملخص الميزات للبرمجيين"},"description":{"en":"Unlock efficient feature documentation and communication with feature-summary. Learn how to create accessible summaries for stakeholders, users, and develope...","zh":"了解功能摘要AI工具的优势，创建全面用户文档和功能目录","ja":"機能サマリAIエージェントを使用して、包括的なユーザー向けドキュメントと機能カタログを作成する","ko":"기능 요약 AI 에이전트를 사용하여 완전한 사용자 문서와 기능 카탈로그를 생성하는 방법","es":"Aprende a documentar y comunicar características a partes interesadas, usuarios y desarrolladores con nuestro resumen de características de AI Agent","fr":"Découvrez comment documenter et communiquer des fonctionnalités aux parties prenantes, utilisateurs et développeurs avec notre résumé de fonctionnalités d''ou...","de":"Erfahren Sie, wie Sie Funktionen an Interessenten, Benutzer und Entwickler mit unserem Funktionszusammenfassung von KI-Tools dokumentieren und kommunizieren","pt":"Aprenda a criar resumos de recursos acessíveis e abrangentes para stakeholders, usuários e desenvolvedores com o skill de resumo de recursos","ru":"ИИ Агенты для создания сводок функций: узнайте, как создавать доступные и всесторонние описания функций для заинтересованных сторон, пользователей и разработ...","ar":"تعرف على كيفية إنشاء ملخصات ميزات شاملة وقابلة للوصول لمختلف الأطراف المعنية باستخدام مهارة ملخص الميزات"},"definition":{"en":"Feature-summary is a skill that focuses on feature documentation and communication, providing accessible summaries for various stakeholders.","zh":"功能摘要AI工具：一种创建功能文档和目录的技术，支持用户和开发者","ja":"機能サマリAIエージェント：機能ドキュメントとカタログを作成する技術、ユーザーと開発者向け","ko":"기능 요약 AI 에이전트: 기능 문서와 카탈로그를 생성하는 기술, 사용자와 개발자를 위한","es":"El resumen de características es una habilidad de AI Agent que permite documentar y comunicar características de manera efectiva","fr":"Le résumé de fonctionnalités est une compétence d''outils d''IA qui permet de documenter et de communiquer des fonctionnalités de manière efficace","de":"Die Funktionszusammenfassung ist eine Fähigkeit von KI-Tools, die es ermöglicht, Funktionen effektiv zu dokumentieren und zu kommunizieren","pt":"O que é resumo de recursos? É uma habilidade que cria resumos acessíveis e abrangentes de recursos para stakeholders, usuários e desenvolvedores","ru":"Что такое сводка функций? Это навык, создающий доступные и всесторонние сводки функций для заинтересованных сторон, пользователей и разработчиков","ar":"ما هي مهارة ملخص الميزات؟ هي القدرة على إنشاء ملخصات ميزات شاملة وقابلة للوصول لمختلف الأطراف المعنية"},"features":{"en":["Transforms detailed feature breakdowns into comprehensive summaries","Creates user-facing documentation for completed features","Builds feature catalogs for multiple audiences","Serves stakeholders, users, and developers with accessible information","Facilitates communication among different groups with feature summaries","Supports the creation of documentation for completed features"],"zh":["创建全面用户文档","生成功能目录","支持多种受众","功能文档和目录的自动化","提高团队协作效率"],"ja":["包括的なユーザー向けドキュメントを作成する","機能カタログを生成する","複数の受け手をサポートする","機能ドキュメントとカタログの自動化","チームコラボレーションの効率化"],"ko":["완전한 사용자 문서 생성","기능 카탈로그 생성","여러 受众 지원","기능 문서와 카탈로그의 자동화","팀 협업 효율성 향상"],"es":["Crear documentación completa para usuarios","Generar catálogos de características","Transformar desgloses detallados en resúmenes accesibles","Comunicar características a partes interesadas y desarrolladores","Utilizar la habilidad cuando se tiene una característica completada o un desglose detallado"],"fr":["Créer une documentation complète pour les utilisateurs","Générer des catalogues de fonctionnalités","Transformer les décompositions détaillées en résumés accessibles","Communiquer des fonctionnalités aux parties prenantes et développeurs","Utiliser la compétence lorsqu''une fonctionnalité est terminée ou qu''un détail décomposé est disponible"],"de":["Erstellen Sie umfassende Benutzerdokumentation","Generieren Sie Funktionskataloge","Wandeln Sie detaillierte Aufschlüsselungen in zugängliche Zusammenfassungen um","Kommunizieren Sie Funktionen an Interessenten und Entwickler","Verwenden Sie die Fähigkeit, wenn eine Funktion abgeschlossen ist oder wenn eine detaillierte Aufschlüsselung verfügbar ist"],"pt":["Criação de documentação abrangente para usuários","Desenvolvimento de catálogos de recursos","Transformação de descrições detalhadas em resumos acessíveis","Comunicação eficaz com stakeholders e desenvolvedores","Suporte à criação de documentação para múltiplos públicos"],"ru":["Создание всесторонней документации для пользователей","Разработка каталогов функций","Преобразование подробных описаний в доступные сводки","Эффективная коммуникация с заинтересованными сторонами и разработчиками","Поддержка создания документации для нескольких аудиторий"],"ar":["إنشاء وثائق شاملة للمستخدمين","تطوير فهرس الميزات","تحويل الوصف المفصل إلى ملخصات شاملة","التواصل الفعّال مع الأطراف المعنية والبرمجيين","دعم إنشاء الوثائق للجماهير المتعددة"]},"keywords":{"en":["how to use feature-summary","what is feature-summary","feature-summary alternative","feature-summary vs documentation tools","feature-summary setup guide","feature-summary install for AI agents","creating feature catalogs with feature-summary","feature documentation best practices","feature-summary for developers and stakeholders"],"zh":["AI工具","功能摘要","用户文档","功能目录","技术文档","开发者工具","AIエージェント","功能サマリ","ユーザー向けドキュメント"],"ja":["AIエージェント","機能サマリ","ユーザー向けドキュメント","機能カタログ","技術ドキュメント","開発者ツール","AI工具","機能摘要","用户文档"],"ko":["AI 에이전트","기능 요약","사용자 문서","기능 카탈로그","기술 문서","개발자 도구","AI工具","功能サマリ","ユーザー向けドキュメント"],"es":["resumen de características","documentación de características","comunicación de características","AI Agent","herramientas de IA","desarrollo de software","documentación técnica","catalogo de características"],"fr":["résumé de fonctionnalités","documentation de fonctionnalités","communication de fonctionnalités","outils d''IA","développement de logiciels","documentation technique","catalogue de fonctionnalités"],"de":["Funktionszusammenfassung","Dokumentation von Funktionen","Kommunikation von Funktionen","KI-Tools","Software-Entwicklung","technische Dokumentation","Funktionskatalog"],"pt":["resumo de recursos","documentação de recursos","comunicação de recursos","catálogo de recursos","desenvolvimento de software","skill de resumo de recursos","criação de documentação","transformação de descrições"],"ru":["сводка функций","документация функций","коммуникация функций","каталог функций","разработка программного обеспечения","навык сводки функций","создание документации","преобразование описаний"],"ar":["ملخص الميزات","توثيق الميزات","تواصل الميزات","فهرس الميزات","تطوير البرمجيات","مهارة ملخص الميزات","إنشاء الوثائق","تحويل الوصف"]}},"owner":"prulloac","repo":"vibe-coding-template","repoPath":"prulloac/vibe-coding-template","stars":0,"forks":0,"updatedAt":"2026-02-23T15:05:13Z","topics":[],"category":"community","skillMd":{"name":"feature-summary","description":"Create comprehensive feature documentation summaries that describe current and future capabilities. Use after feature-breakdown to document what a feature does, its business value, technical implementation, and roadmap. Ideal for creating user-facing documentation and feature catalogs in `docs/features/<feature-name>/` format.","bodyPreview":"# Feature Summary Skill\n\n**Answers the question: How do we DOCUMENT and COMMUNICATE a feature to stakeholders, users, and developers?**\n\nThis skill focuses on **feature documentation and communication**, transforming detailed breakdowns into accessible, comprehensive summaries that serve multiple audiences.\n\n## When to Use\n\nUse this skill when you have a **completed feature** (or a detailed feature breakdown) and need to:\n- Create comprehensive user-facing documentation\n- Build a feature catalog","body":"# Feature Summary Skill\n\n**Answers the question: How do we DOCUMENT and COMMUNICATE a feature to stakeholders, users, and developers?**\n\nThis skill focuses on **feature documentation and communication**, transforming detailed breakdowns into accessible, comprehensive summaries that serve multiple audiences.\n\n## When to Use\n\nUse this skill when you have a **completed feature** (or a detailed feature breakdown) and need to:\n- Create comprehensive user-facing documentation\n- Build a feature catalog or knowledge base\n- Document business features for stakeholder communication\n- Explain technical implementation to developers\n- Create feature roadmaps and status tracking\n- Document current and future capabilities\n- Classify features by type (core, customization, performance, accessibility, UX)\n\n**Key indicator**: You''re asking \"How do we document and communicate this feature?\" or \"What should users know about this capability?\"\n\n**Works best with**: This skill complements `feature-breakdown` (provides the detailed task list) and `feature-planning` (provides the execution sequence)\n\n## When NOT to Use\n\n- You only have a feature idea/spec without breakdown details → Use `feature-breakdown` first\n- You need to determine task execution order → Use `feature-planning` instead\n- You need to track real-time implementation progress → Use `execution-tracking` instead\n\n## Prerequisites\n\nRecommended (but not strictly required):\n\n1. **Feature breakdown** (`docs/features/[feature-name]/breakdown.md`)\n   - Provides detailed task list and component architecture\n   - Helps identify all feature aspects to document\n   \n2. **Feature implementation** (completed or well-understood)\n   - Access to working code or specifications\n   - Understanding of current status\n\n3. **Audience understanding**\n   - Who will read this documentation?\n   - What do they need to know?\n\n## Inputs\n\n- **Feature specification or implemented feature** (required)\n- **Feature breakdown document** (recommended): `docs/features/[feature-name]/breakdown.md`\n- **Source code access** (optional but helpful): For accurate implementation details\n- **Usage examples** (optional): For user documentation\n\n## Directory Structure\n\nAll feature-summary output must follow this structure:\n\n```\ndocs/features/[feature-name]/\n├── breakdown.md              (created by feature-breakdown skill)\n├── summary.md                (created by this skill - PRIMARY OUTPUT)\n├── configuration.md          (optional - created by this skill)\n├── reference.md              (optional - created by this skill)\n└── implementation-progress.md (created by execution-tracking skill during implementation)\n```\n\n## Outputs\n\n**MANDATORY FILE ORGANIZATION**: All feature documentation must be in `docs/features/<feature-name>/` subdirectory.\n\nWhen this skill completes, it creates:\n\n1. **Primary Output: Feature Summary** (`docs/features/[feature-name]/summary.md`)\n   - Comprehensive feature documentation\n   - 150-250 lines covering all major aspects\n   - Serves multiple audiences (users, developers, stakeholders)\n   - Includes feature type classification\n   - **Example**: `docs/features/git-blame-overlay/summary.md`\n\n2. **Optional: Configuration Reference** (`docs/features/[feature-name]/configuration.md`)\n   - Detailed configuration options and examples\n   - For features with significant customization\n   \n3. **Optional: Reference Guide** (`docs/features/[feature-name]/reference.md`)\n   - Technical implementation details for developers\n   - Architecture decisions and patterns\n   \n4. **Supporting Structure**:\n   - `docs/features/[feature-name]/breakdown.md` - Implementation tasks (created by feature-breakdown skill)\n   - `docs/features/[feature-name]/implementation-progress.md` - Tracking file (created by execution-tracking skill)\n\n## Workflow Overview\n\nThe feature summary process transforms a feature concept into comprehensive documentation:\n\n```\nFeature Input (Breakdown or Implementation)\n    ↓\nAnalyze Feature Aspects\n    ↓\nIdentify Audiences & Use Cases\n    ↓\nClassify Feature Type\n    ↓\nCreate Executive Summary\n    ↓\nDocument Configuration & Options\n    ↓\nExplain Technical Implementation\n    ↓\nDefine Status & Version Info\n    ↓\nIdentify Limitations & Future Enhancements\n    ↓\nWrite Output Files\n    ↓\nComprehensive Feature Documentation\n```\n\n## Core Workflow\n\n### Phase 1: Analyze Feature Scope\n\n**Input**: Feature specification, breakdown, or implementation\n\n1. **Identify feature aspects**:\n   - What does it do? (Core functionality)\n   - Why is it valuable? (Business value)\n   - How do users interact with it? (User experience)\n   - What are the key capabilities? (Feature list)\n   - What are the limitations? (Edge cases and constraints)\n\n2. **Extract technical details**:\n   - How is it implemented? (Architecture, components)\n   - What are the technical requirements? (Dependencies, prerequisites)\n   - Where is the code located? (Source file references)\n   - What patterns or technologies are used?\n\n3. **Understand current state**:\n   - Version number and release status\n   - When was it introduced?\n   - What improvements or fixes have been made?\n   - Is it production-ready?\n\n### Phase 2: Classify Feature Type\n\nAssign the feature to one or more categories:\n\n| Category | Description | Examples |\n|----------|-------------|----------|\n| **Core Functionality** | Essential feature defining the product''s primary purpose | Git blame overlay, authentication system |\n| **Customization** | Allows users to personalize behavior and appearance | Output patterns, color customization |\n| **User Experience** | Improves usability, visual integration, and workflow | Theme adaptation, command palette |\n| **Accessibility** | Supports users with different abilities and needs | Color options, keyboard shortcuts, ARIA labels |\n| **Performance** | Optimizes speed and resource usage | Caching, lazy loading, pagination |\n| **Extended Functionality** | Non-essential features that enhance core capability | Advanced filtering, export options |\n| **Developer Experience** | Improves developer productivity and experience | Debugging tools, API documentation |\n\n## Output Format\n\nFeature summaries include these key sections (in order):\n\n1. **Feature Header** - Name, overview, status, version, feature type\n2. **Business Value** - Why it matters, specific benefits\n3. **What It Does** - Core functionality with user experience and examples\n4. **Key Features** - Capabilities and extended functionality\n5. **Configuration** (if applicable) - Options and examples\n6. **Technical Implementation** - Code references and architecture\n7. **User Interactions** - Workflows and commands\n8. **Status and Roadmap** - Current status, limitations, future enhancements\n9. **Related Features** - Cross-references to related features\n\n**For a complete template with examples and detailed guidelines**, see:\n- [`assets/documentation-template.md`](assets/documentation-template.md) - Blank template for creating new features\n- [`examples/example-feature-summary-core.md`](examples/example-feature-summary-core.md) - Core functionality example\n- [`examples/example-feature-summary-customization.md`](examples/example-feature-summary-customization.md) - Customization example\n- [`examples/example-feature-summary-performance.md`](examples/example-feature-summary-performance.md) - Performance example\n\n## Feature Type Classification\n\nEvery feature should be classified with a primary type and optional secondary types. This helps users understand:\n- **What is this feature?** (Its purpose)\n- **Is it essential?** (Core vs. optional)\n- **How does it relate to other features?** (Ecosystem awareness)\n\n### Quick Reference\n\n| Type | Icon | Purpose | Example |\n|------|------|---------|---------|\n| **Core Functionality** | ⭐ | Essential, defines product purpose | Git blame overlay |\n| **Customization** | 🎨 | Personalization & preferences | Output patterns |\n| **User Experience** | 👥 | Usability & visual integration | Theme-aware styling |\n| **Accessibility** | ♿ | Support for diverse users | Color options |\n| **Performance** | 🚀 | Speed & resource optimization | Caching system |\n| **Extended Functionality** | ➕ | Optional enhancements | Export options |\n| **Developer Experience** | 🛠️ | Developer productivity | API docs |\n\n**For detailed guidance on each type**, see [`references/feature-type-reference.md`](references/feature-type-reference.md)\n\n## Guidelines\n\n### Writing for Multiple Audiences\n\n**For Users**:\n- Use clear, non-technical language\n- Explain benefits and use cases\n- Provide concrete examples\n- Include configuration examples\n\n**For Developers**:\n- Include code references and file paths\n- Explain architecture and design decisions\n- Document patterns and conventions\n- Link to technical documentation\n\n**For Stakeholders**:\n- Lead with business value\n- Emphasize impact and ROI\n- Focus on status and roadmap\n- Quantify benefits where possible\n\n### Feature Classification\n\nWhen assigning feature types:\n\n1. **Identify primary category**: What is this feature''s main purpose?\n2. **Note secondary categories**: Can it serve multiple purposes?\n3. **Explain classification**: Why does this categorization make sense?\n4. **Consider user perception**: How do users think about this feature?\n\n### Technical Accuracy\n\n- Reference actual source code paths\n- Include line numbers for specific implementations\n- Verify all code examples work correctly\n- Document technical constraints accurately\n\n### Keeping Documentation Current\n\n- Update status section when feature versions change\n- Add to limitations if new constraints are discovered\n- Move items from \"Future Enhancements\" when implemented\n- Update configuration examples if options change\n\n## Common Pitfalls to Avoid\n\n❌ **Too technical for users**: Remember non-technical readers; explain technical concepts\n❌ **Too vague for developers**: Provide specific code references and implementation details\n❌ **Incomplete feature classification**: Always explain why a feature fits its category\n❌ **Missing examples**: Concrete examples are crucial for understanding\n❌ **Outdated information**: Keep status and version info current\n❌ **Poor cross-linking**: Reference related features; help readers understand relationships\n❌ **Missing technical details**: Developers need code references and architecture info\n\n## Integration with Other Skills\n\nThe feature-summary skill works as part of a larger feature documentation ecosystem. For detailed integration workflows and examples:\n\n- **Overview of the skill ecosystem**: [`references/ecosystem-diagram.md`](references/ecosystem-diagram.md)\n- **Practical integration workflows**: [`references/workflow-integration-guide.md`](references/workflow-integration-guide.md)\n- **Quick navigation**: [`references/integration-guide.md`](references/integration-guide.md)\n\n### Recommended Skill Sequence\n\n1. **feature-breakdown** (1-2 hrs) - Decompose feature into tasks and acceptance criteria\n2. **feature-summary** (1-2 hrs) - Create user-facing documentation\n3. **feature-planning** (1-2 hrs) - Sequence tasks for execution\n4. **execution-tracking** (ongoing) - Monitor implementation progress\n\n### Key Concepts\n\n**feature-breakdown creates** (`docs/features/[name]/breakdown.md`):\n- Internal task list\n- Component architecture\n- Acceptance criteria\n- Validation plan\n\n**feature-summary creates** (`docs/features/[name]/summary.md`):\n- User-facing documentation\n- Business value explanation\n- Configuration examples\n- Roadmap and future enhancements\n\n## Quality Checklist\n\nBefore finalizing feature documentation:\n\n- [ ] Feature type classification is clear and explained\n- [ ] Business value section explains \"why\" not just \"what\"\n- [ ] Examples show real-world usage\n- [ ] Technical details are accurate with code references\n- [ ] Configuration options are clearly documented\n- [ ] Status and version info are current\n- [ ] Known limitations are honestly documented\n- [ ] Future enhancements are realistic and categorized\n- [ ] Cross-references to related features are accurate\n- [ ] Documentation is accessible to intended audiences\n- [ ] Language is clear and concise\n- [ ] All file paths and code references are accurate\n\n## Example Output\n\nFor a real example of how feature documentation should look, see the example feature summaries:\n\n- Reference: `examples/example-feature-summary-core.md` (Core functionality example)\n- Reference: `examples/example-feature-summary-customization.md` (Customization example)\n- Reference: `examples/example-feature-summary-performance.md` (Performance feature example)\n\n## See Also\n\n- `feature-breakdown` - Decompose features into tasks\n- `feature-planning` - Sequence tasks for execution\n- `execution-tracking` - Monitor feature implementation progress\n- `readme-updater` - Keep project README in sync with features\n"},"lastSynced":"2026-03-07T13:09:31.653Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents needing to create comprehensive feature documentation for stakeholders, users, and developers.","zh":"非常适合需要为利益相关者、用户和开发人员创建全面特性文档的技术写作代理。","ja":"ステークホルダー、ユーザー、開発者向けの包括的な機能ドキュメントを作成する必要があるテクニカルライティングエージェントに最適です。","ko":"스테이크홀더, 사용자, 개발자를 위한 포괄적인 기능 문서를 작성해야 하는 기술 작성을 위한 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Escritura Técnica que necesitan crear documentación de características completa para partes interesadas, usuarios y desarrolladores.","fr":"Parfait pour les agents de rédaction technique ayant besoin de créer une documentation de fonctionnalités complète pour les parties prenantes, les utilisateurs et les développeurs.","de":"Perfekt für technische Schreiber-Agenten, die umfassende Funktionsdokumentationen für Stakeholder, Benutzer und Entwickler erstellen müssen.","pt":"Perfeito para Agentes de Escrita Técnica que necessitam criar documentação de recursos abrangente para partes interessadas, usuários e desenvolvedores.","ru":"Идеально подходит для агентов технического письма, которым необходимо создавать комплексную документацию по функциям для заинтересованных сторон, пользователей и разработчиков.","ar":"เหมาะ للوكلاء النصيين الفنيين الذين يحتاجون إلى إنشاء توثيق ميزات شامل لمستثمري الأطراف، والمستخدمين، والمطورين."},"recommendation":{"en":"Empowers agents to transform detailed feature breakdowns into accessible, comprehensive summaries using feature documentation and communication protocols, facilitating the creation of user-facing documentation and feature catalogs in formats like Markdown or HTML.","zh":"赋予代理人将详细的功能细分转化为易于理解的综合摘要的能力，使用功能文档和通信协议，促进用户可面向的文档和功能目录的创建，以Markdown或HTML等格式。","ja":"エージェントが詳細な機能のブレークダウンをアクセスしやすい包括的なサマリーに変換することを可能にし、機能ドキュメントとコミュニケーションプロトコルを使用して、ユーザー向けのドキュメントと機能カタログの作成を促進する、マークダウンやHTMLなどの形式で。","ko":"에이전트가 자세한 기능 세부 정보를 쉽게 이해할 수 있는 포괄적인 요약으로 변환할 수 있도록 해주며, 기능 문서와 통신 규약을 사용하여 사용자에게 제공되는 문서와 기능 카탈로그의 작성이 마크다운 또는 HTML과 같은 형식으로 용이하게 진행될 수 있도록 합니다.","es":"Habilita a los agentes a transformar desgloses detallados de características en resúmenes accesibles y completos utilizando documentación de características y protocolos de comunicación, facilitando la creación de documentación orientada al usuario y catálogos de características en formatos como Markdown o HTML.","fr":"Permet aux agents de transformer des décompositions détaillées de fonctionnalités en résumés accessibles et complets en utilisant la documentation de fonctionnalités et les protocoles de communication, facilitant la création de documentation orientée utilisateur et de catalogues de fonctionnalités dans des formats tels que Markdown ou HTML.","de":"Ermöglicht es Agenten, detaillierte Funktionszerlegungen in zugängliche und umfassende Zusammenfassungen mithilfe von Funktionsdokumentation und Kommunikationsprotokollen umzuwandeln, wodurch die Erstellung von benutzerorientierter Dokumentation und Funktionskatalogen in Formaten wie Markdown oder HTML erleichtert wird.","pt":"Habilita os agentes a transformar desmembramentos detalhados de recursos em resumos acessíveis e abrangentes usando documentação de recursos e protocolos de comunicação, facilitando a criação de documentação voltada para o usuário e catálogos de recursos em formatos como Markdown ou HTML.","ru":"Позволяет агентам преобразовывать подробные описания функций в доступные и комплексные резюме, используя документацию функций и протоколы связи, что облегчает создание документации, ориентированной на пользователя, и каталогов функций в форматах, таких как Markdown или HTML.","ar":"تمكن الوكلاء من تحويل تفصيل ميزات مفصل إلى ملخصات يمكن الوصول إليها وشاملة باستخدام توثيق الميزات وبروتوكولات الاتصال، مما يسهل إنشاء توثيق موجه للمستخدم وقوائم الميزات بالتنسيقات مثل Markdown أو HTML."},"useCases":{"en":["Generating user-facing documentation for new features","Building feature catalogs for product launches","Creating comprehensive summaries for stakeholder reports"],"zh":["为新功能生成用户可面向的文档","为产品发布构建功能目录","为利益相关者报告创建综合摘要"],"ja":["新しい機能のユーザー向けドキュメントを生成する","製品のローンチのための機能カタログを構築する","ステークホルダーのレポートのための包括的なサマリーを作成する"],"ko":["새로운 기능을 위한 사용자에게 제공되는 문서 생성","제품 출시를 위한 기능 카탈로그 구축","스테이크홀더 보고서를 위한 포괄적인 요약 생성"],"es":["Generación de documentación orientada al usuario para nuevas características","Creación de catálogos de características para lanzamientos de productos","Creación de resúmenes completos para informes de partes interesadas"],"fr":["Génération de documentation orientée utilisateur pour les nouvelles fonctionnalités","Création de catalogues de fonctionnalités pour les lancements de produits","Création de résumés complets pour les rapports de parties prenantes"],"de":["Erstellung von benutzerorientierter Dokumentation für neue Funktionen","Erstellung von Funktionskatalogen für Produktstarts","Erstellung von umfassenden Zusammenfassungen für Stakeholder-Berichte"],"pt":["Geração de documentação voltada para o usuário para novos recursos","Construção de catálogos de recursos para lançamentos de produtos","Criação de resumos abrangentes para relatórios de partes interessadas"],"ru":["Генерация документации, ориентированной на пользователя, для новых функций","Создание каталогов функций для запуска продуктов","Создание комплексных резюме для отчетов заинтересованных сторон"],"ar":["إنشاء توثيق موجه للمستخدم لميزات جديدة","بناء قوائم الميزات لإطلاق المنتجات","إنشاء ملخصات شاملة لتقرير مستثمري الأطراف"]},"limitations":{"en":["Requires completed feature or detailed feature breakdown","Limited to text-based documentation formats"],"zh":["需要完成的功能或详细的功能细分","仅限于基于文本的文档格式"],"ja":["完了した機能または詳細な機能のブレークダウンが必要","テキストベースのドキュメント形式に限定される"],"ko":["완료된 기능 또는 자세한 기능 세부 정보가 필요","텍스트 기반 문서 형식으로만 제한됨"],"es":["Requiere una característica completa o un desglose detallado de la característica","Limitado a formatos de documentación basados en texto"],"fr":["Nécessite une fonctionnalité complète ou une décomposition détaillée de la fonctionnalité","Limité aux formats de documentation basés sur le texte"],"de":["Erfordert eine abgeschlossene Funktion oder eine detaillierte Funktionszerlegung","Begrenzt auf textbasierte Dokumentationsformate"],"pt":["Requer recurso concluído ou desmembramento detalhado do recurso","Limitado a formatos de documentação baseados em texto"],"ru":["Требуется завершенный функционал или подробное описание функции","Ограничен форматами документации на основе текста"],"ar":["يتطلب ميزة مكتملة أو تفصيل مفصل للميزة","محدود بالتنسيقات القائمة على النص لتوثيق"]},"version":4},"contentHash":"c62b6903f190733fbb871982f2629346d589fdf6e0cbaef916f75971d90e8b1e","qualityScore":60}');
