INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('prulloac/vibe-coding-template/feature-summary', 'feature-summary', 'prulloac', 'vibe-coding-template', 'community', 'feature-summary prulloac vibe-coding-template community The feature-summary skill transforms detailed feature breakdowns into comprehensive summaries for multiple audiences, including stakeholders, users, and developers. It facilitates the creation of user-facing documentation and feature catalogs. 功能摘要AI工具，用于创建用户文档和功能目录，支持多种受众 機能サマリAIエージェントは、ユーザー向けドキュメントと機能カタログを作成するために使用され、複数の受け手をサポートする 기능 요약 AI 에이전트는 사용자 문서와 기능 카탈로그를 생성하기 위해 사용되며 여러 受众을 지원합니다 El resumen de características es una habilidad que se centra en la documentación y comunicación de características, transformando desgloses detallados en resúmenes accesibles Le résumé de fonctionnalités est une compétence qui se concentre sur la documentation et la communication de fonctionnalités, transformant les décompositions détaillées en résumés accessibles Die Funktionszusammenfassung ist eine Fähigkeit, die sich auf die Dokumentation und Kommunikation von Funktionen konzentriert, indem sie detaillierte Aufschlüsselungen in zugängliche Zusammenfassungen umwandelt O skill de resumo de recursos transforma descrições detalhadas em resumos acessíveis e abrangentes para stakeholders, usuários e desenvolvedores Навык сводки функций преобразует подробные описания в доступные и всесторонние сводки для заинтересованных сторон, пользователей и разработчиков مهارة ملخص الميزات تحول الوصف المفصل إلى ملخصات شاملة وقابلة للوصول لمختلف الأطراف المعنية how to use feature-summary what is feature-summary feature-summary alternative feature-summary vs documentation tools feature-summary setup guide feature-summary install for AI agents creating feature catalogs with feature-summary feature documentation best practices feature-summary for developers and stakeholders AI工具 功能摘要 用户文档 功能目录 技术文档 开发者工具 AIエージェント 功能サマリ ユーザー向けドキュメント Transforms detailed feature breakdowns into comprehensive summaries Creates user-facing documentation for completed features Builds feature catalogs for multiple audiences Serves stakeholders, users, and developers with accessible information Facilitates communication among different groups with feature summaries Supports the creation of documentation for completed features Feature-summary is a skill that focuses on feature documentation and communication, providing accessible summaries for various stakeholders.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vibbs/company-os/token-cost-ledger', 'community', 'vibbs', 'company-os', 'vibbs/company-os', 'token-cost-ledger', 0, 0, 60, '2026-03-01T16:05:33Z', '2026-03-07T04:05:28.074Z', 'c46e60347cddd824f7c30f55460831c1dea6ca57279fe081e01defb5e52203e2', '{"id":"vibbs/company-os/token-cost-ledger","name":"token-cost-ledger","description":{"en":"The token-cost-ledger skill tracks AI token consumption and costs, providing ledger entries and summaries for Ops & Risk and Orchestrator Agents. It utilizes company.config.yaml for configuration.","zh":"Token Cost Ledger 是一个用于跟踪 AI 令牌消费和成本的工具，帮助您优化 SaaS 产品的成本","ja":"Token Cost Ledger は、AI 令牌の使用状況とコストを追跡するために設計されたツールで、SaaS 製品のコスト最適化を支援","ko":"Token Cost Ledger 는 AI 에이전트의 비용을 추적하고 최적화하여 SaaS 제품의 비용을 효율적으로 관리","es":"Token Cost Ledger es una funcionalidad para rastrear el consumo y costos de tokens AI con Claude Code, proporcionando un registro detallado en `cogs/ai-ledger/entries.jsonl`","fr":"Le Token Cost Ledger est une fonctionnalité pour suivre la consommation et les coûts des tokens AI avec Claude Code, fournissant un registre détaillé dans `cogs/ai-ledger/entries.jsonl`","de":"Token Cost Ledger ist eine Funktionalität zur Nachverfolgung von KI-Token-Verbrauch und -kosten mit Claude Code, die ein detailliertes Protokoll in `cogs/ai-ledger/entries.jsonl` bereitstellt","pt":"O Token Cost Ledger é uma ferramenta para rastrear o consumo de tokens de IA e calcular os custos","ru":"Счетчик Стоимости Токенов - это инструмент для отслеживания потребления токенов ИИ и расчета затрат","ar":"سجل تكلفة Token هو أداة لتتبع استهلاك رموز الوكيل الذكي وحساب التكاليف"},"seo":{"title":{"en":"token-cost-ledger: AI Token Consumption Tracking Setup Gu...","zh":"Token Cost Ledger 设置指南 - AIエージェント成本跟踪","ja":"Token Cost Ledger のベストプラクティス - AIエージェントのコスト管理","ko":"Token Cost Ledger 사용자 가이드 - AI 에이전트 비용 추적","es":"Guía de configuración de Token Cost Ledger para agente AI","fr":"Paramétrer le Token Cost Ledger pour les outils AI","de":"Einrichtungsanleitung für Token Cost Ledger mit KI-Agenten","pt":"Guia de Configuração do Token Cost Ledger para Ferramenta...","ru":"Настройка Счетчика Стоимости Токенов для ИИ Агентов","ar":"دليل إعداد سجل تكلفة Token للوكلاء الذكية"},"description":{"en":"Discover how to monitor AI token costs with token-cost-ledger. Learn to track consumption, set budgets, and receive alerts with this comprehensive guide.","zh":"了解 Token Cost Ledger 如何帮助您跟踪 AI 令牌消费和成本，优化您的 SaaS 产品","ja":"Token Cost Ledger を使用して AI 令牌の使用状況とコストを追跡し、SaaS 製品の最適化を実現","ko":"Token Cost Ledger 를 사용하여 AI 에이전트의 비용을 추적하고 최적화하여 SaaS 제품의 효율성을 향상","es":"Aprende a configurar Token Cost Ledger para rastrear el consumo y costos de tokens AI con Claude Code","fr":"Découvrez comment paramétrer le Token Cost Ledger pour suivre la consommation et les coûts des tokens AI avec Claude Code","de":"Erfahren Sie, wie Sie Token Cost Ledger für die Nachverfolgung von KI-Token-Verbrauch und -kosten mit Claude Code einrichten","pt":"Aprenda a configurar o Token Cost Ledger para otimizar o consumo de tokens de IA e reduzir custos","ru":"Узнайте, как настроить Счетчик Стоимости Токенов для оптимизации потребления токенов ИИ и снижения затрат","ar":"تعرف على كيفية إعداد سجل تكلفة Token لتحسين استهلاك رموز الوكيل الذكي وتقليل التكاليف"},"definition":{"en":"token-cost-ledger is a skill for tracking AI token consumption and costs, generating ledger entries in JSONL and summary reports in Markdown.","zh":"Token Cost Ledger 是一种 AI 令牌成本跟踪系统，用于记录和管理 AI 令牌的使用情况","ja":"Token Cost Ledger は、AI 令牌の使用状況とコストを追跡するためのシステム","ko":"Token Cost Ledger 는 AI 에이전트의 비용을 추적하고 관리하는 시스템","es":"Token Cost Ledger es una funcionalidad de agente AI que registra el consumo y costos de tokens","fr":"Le Token Cost Ledger est une fonctionnalité d''agent AI qui enregistre la consommation et les coûts des tokens","de":"Token Cost Ledger ist eine Funktionalität von KI-Agenten, die den Verbrauch und die Kosten von Token registriert","pt":"O Token Cost Ledger é um recurso de IA que registra e calcula os custos de tokens consumidos","ru":"Счетчик Стоимости Токенов - это функция ИИ, которая регистрирует и рассчитывает затраты на потребленные токены","ar":"سجل تكلفة Token هو ميزة من ميزات الوكيل الذكي التي تسجل وتحسب تكاليف الرموز المستهلكة"},"features":{"en":["Tracks AI token usage data and costs","Utilizes company.config.yaml for configuration, including ai.cost_budget_monthly and ai.cost_alert_threshold_percent","Generates ledger entries in cogs/ai-ledger/entries.jsonl","Produces summary reports in cogs/ai-ledger/summary.md","Used by Ops & Risk Agent and Orchestrator Agent for post-ship advisory","Includes tool script ./tools/ops/token-ledger.sh for automation"],"zh":["支持 token 使用数据跟踪","集成 company.config.yaml 配置文件","输出 ledger 条目和汇总报告","使用 Ops & Risk Agent 和 Orchestrator Agent","提供工具脚本 ./tools/ops/token-ledger.sh"],"ja":["トークンの使用状況データの追跡をサポート","company.config.yaml 構成ファイルの統合","レジャー エントリとサマリー レポートの出力","Ops & Risk Agent と Orchestrator Agent の使用","ツール スクリプト ./tools/ops/token-ledger.sh の提供"],"ko":["토큰 사용 데이터 추적 지원","company.config.yaml 구성 파일 통합","레저 엔트리 및 요약 보고서 출력","Ops & Risk Agent 및 Orchestrator Agent 사용","도구 스크립트 ./tools/ops/token-ledger.sh 제공"],"es":["Registro detallado de consumo de tokens en `cogs/ai-ledger/entries.jsonl`","Resumen de costos en `cogs/ai-ledger/summary.md`","Compatibilidad con company.config.yaml para configurar ai.cost_budget_monthly y ai.cost_tracking_enabled","Uso de herramientas de línea de comandos como `./tools/ops/token-ledger.sh`","Integración con agente Ops & Risk y Orchestrator Agent","Seguimiento de umbrales de alerta de costos con ai.cost_alert_threshold_percent"],"fr":["Registre détaillé de la consommation de tokens dans `cogs/ai-ledger/entries.jsonl`","Résumé des coûts dans `cogs/ai-ledger/summary.md`","Compatibilité avec company.config.yaml pour configurer ai.cost_budget_monthly et ai.cost_tracking_enabled","Utilisation d''outils de ligne de commande tels que `./tools/ops/token-ledger.sh`","Intégration avec l''agent Ops & Risk et l''agent Orchestrator","Suivi des seuils d''alerte de coûts avec ai.cost_alert_threshold_percent"],"de":["Detailliertes Protokoll des Token-Verbrauchs in `cogs/ai-ledger/entries.jsonl`","Kostenzusammenfassung in `cogs/ai-ledger/summary.md`","Kompatibilität mit company.config.yaml zur Konfiguration von ai.cost_budget_monthly und ai.cost_tracking_enabled","Verwendung von Kommandozeilen-Tools wie `./tools/ops/token-ledger.sh`","Integration mit dem Ops & Risk-Agent und dem Orchestrator-Agent","Überwachung von Kosten-Schwellenwerten mit ai.cost_alert_threshold_percent"],"pt":["Rastreamento do consumo de tokens de IA","Cálculo dos custos de tokens consumidos","Integração com a ferramenta de configuração company.config.yaml","Saída de dados em formato JSONL e Markdown","Utilizado pelo Agente de Operações e Risco e pelo Agente Orchestrador"],"ru":["Отслеживание потребления токенов ИИ","Расчет затрат на потребленные токены","Интеграция с инструментом конфигурации company.config.yaml","Вывод данных в форматах JSONL и Markdown","Используется агентами по операциям и риску и агентом-оркестратором"],"ar":["تتبع استهلاك رموز الوكيل الذكي","حساب تكاليف الرموز المستهلكة","التكامل مع أداة التكوين company.config.yaml","إخراج البيانات في صيغ JSONL و Markdown","يستخدمه وكلاء العمليات والمخاطر والوكيل المنسق"]},"keywords":{"en":["how to use token-cost-ledger","token-cost-ledger setup guide","AI token consumption tracking","token-cost-ledger alternative","token-cost-ledger vs other AI cost tracking tools","install token-cost-ledger","token-cost-ledger for Ops & Risk Agents","what is token-cost-ledger","token-cost-ledger documentation","token-cost-ledger tutorial"],"zh":["Token Cost Ledger","AI 令牌成本跟踪","SaaS 产品成本优化","AIエージェント成本管理","公司配置文件集成","ledger 条目输出","工具脚本"],"ja":["Token Cost Ledger","AI 令牌のコスト追跡","SaaS 製品のコスト最適化","AIエージェントのコスト管理","会社構成ファイルの統合","レジャー エントリの出力","ツール スクリプト"],"ko":["Token Cost Ledger","AI 에이전트 비용 추적","SaaS 제품 비용 최적화","AI 에이전트 비용 관리","회사 구성 파일 통합","레저 엔트리 출력","도구 스크립트"],"es":["agente AI","Token Cost Ledger","consumo de tokens","costos de tokens","Claude Code","company.config.yaml","ai.cost_budget_monthly","ai.cost_tracking_enabled","registro de tokens"],"fr":["agent AI","Token Cost Ledger","consommation de tokens","coûts de tokens","Claude Code","company.config.yaml","ai.cost_budget_monthly","ai.cost_tracking_enabled","registre de tokens"],"de":["KI-Agent","Token Cost Ledger","Token-Verbrauch","Token-Kosten","Claude Code","company.config.yaml","ai.cost_budget_monthly","ai.cost_tracking_enabled","Token-Protokoll"],"pt":["Token Cost Ledger","Ferramentas de IA","Consumo de tokens","Cálculo de custos","Company.config.yaml","Agente de Operações e Risco","Agente Orchestrador","JSONL","Markdown"],"ru":["Счетчик Стоимости Токенов","ИИ Агенты","Потребление токенов","Расчет затрат","Company.config.yaml","Агент по операциям и риску","Агент-оркестратор","JSONL","Markdown"],"ar":["سجل تكلفة Token","الوكلاء الذكية","استهلاك الرموز","حساب التكاليف","company.config.yaml","وكيل العمليات والمخاطر","الوكيل المنسق","JSONL","Markdown"]}},"owner":"vibbs","repo":"company-os","repoPath":"vibbs/company-os","stars":0,"forks":0,"updatedAt":"2026-03-01T16:05:33Z","topics":[],"category":"community","skillMd":{"name":"token-cost-ledger","description":"Tracks AI token usage and costs as COGS. Logs entries, generates reports, monitors budget, shows per-feature cost. Use when reviewing AI spend, logging session costs, or checking budget status.","bodyPreview":"# Token Cost Ledger\n\n## Reference\n- **ID**: S-OPS-08\n- **Category**: Ops & Risk\n- **Inputs**: token usage data, company.config.yaml (ai.cost_budget_monthly, ai.cost_tracking_enabled, ai.cost_alert_threshold_percent)\n- **Outputs**: ledger entries in `cogs/ai-ledger/entries.jsonl`, summary in `cogs/ai-ledger/summary.md`\n- **Used by**: Ops & Risk Agent, Orchestrator Agent (post-ship advisory)\n- **Tool scripts**: `./tools/ops/token-ledger.sh`\n\n## Purpose\n\nTrack AI token consumption and costs as Cost","body":"# Token Cost Ledger\n\n## Reference\n- **ID**: S-OPS-08\n- **Category**: Ops & Risk\n- **Inputs**: token usage data, company.config.yaml (ai.cost_budget_monthly, ai.cost_tracking_enabled, ai.cost_alert_threshold_percent)\n- **Outputs**: ledger entries in `cogs/ai-ledger/entries.jsonl`, summary in `cogs/ai-ledger/summary.md`\n- **Used by**: Ops & Risk Agent, Orchestrator Agent (post-ship advisory)\n- **Tool scripts**: `./tools/ops/token-ledger.sh`\n\n## Purpose\n\nTrack AI token consumption and costs as Cost of Goods Sold (COGS). Provides a lightweight, git-trackable cost accounting system for solo developers using AI agents. Supports logging individual entries, generating period summaries, showing per-feature cost breakdowns, monitoring budget health, and exporting data for financial reporting.\n\n## When to Use\n\n- After completing a ship flow or significant AI-assisted work session\n- When reviewing monthly AI spend against budget\n- When preparing investor updates or financial reports (feeds into pricing-unit-economics)\n- When deciding whether to use Opus vs Sonnet for a task (cost awareness)\n- When company.stage transitions (budgets should be reassessed)\n\n## Procedure\n\n### Step 1: Check Configuration\n\nRead `company.config.yaml` and extract:\n- `ai.cost_budget_monthly` — monthly spend cap\n- `ai.cost_tracking_enabled` — whether tracking is active (default: true if budget is set)\n- `ai.cost_alert_threshold_percent` — warning threshold (default: 80)\n\nIf `ai.cost_budget_monthly` is empty, suggest the user set a budget with guidance by stage:\n- **idea**: $25-50/month (exploration, light usage)\n- **mvp**: $50-200/month (active development, ship flows)\n- **growth**: $200-1000/month (multiple features, more agent usage)\n- **scale**: $1000+/month (heavy automation, multiple concurrent flows)\n\n### Step 2: Subcommand Routing\n\n#### Subcommand: `log`\n\nLog a token cost entry:\n\n```bash\n./tools/ops/token-ledger.sh log \\\n  --model \"claude-sonnet-4-20250514\" \\\n  --input-tokens 12500 \\\n  --output-tokens 3200 \\\n  --cache-read 8000 \\\n  --cache-write 1500 \\\n  --agent engineering \\\n  --category ship-flow \\\n  --feature PRD-001 \\\n  --session \"ship-user-auth-20260301\" \\\n  --notes \"RFC generation for user auth\"\n```\n\nIf the user provides raw numbers from their session, help them fill in the fields. Cost is auto-calculated from the model rates in `standards/ops/token-cost-tracking.md` when not provided via `--cost`.\n\nAfter logging, the tool shows budget impact:\n```\nEntry logged: $0.08\n  Budget: $13.82 / $100.00 (13.8%)\n```\n\n#### Subcommand: `report`\n\nGenerate a cost report:\n\n```bash\n./tools/ops/token-ledger.sh summary --period monthly\n```\n\nPresent the results with analysis:\n1. Total spend by category (ship-flow, agent-session, research, ad-hoc)\n2. Total spend by model (which models are costing the most)\n3. Total spend by agent (which agents are most expensive)\n4. Budget health with color coding\n\nAlso regenerates `cogs/ai-ledger/summary.md` for human review.\n\nIf the user has investor reporting set up, note that token costs feed into the infrastructure cost line item in `standards/ops/investor-reporting-template.md`.\n\n#### Subcommand: `budget-check`\n\nQuick budget health check:\n\n```bash\n./tools/ops/token-ledger.sh budget\n```\n\nPresent results:\n- Current month spend vs budget\n- Projected end-of-month spend (based on daily average)\n- Recommendation: stay the course / reduce usage / increase budget\n\n#### Subcommand: `feature-cost`\n\nShow total cost of building a specific feature:\n\n```bash\n./tools/ops/token-ledger.sh feature-cost PRD-001\n```\n\nPresent the feature cost report:\n- Total cost with entry count\n- Breakdown by agent (who spent what)\n- Breakdown by phase (ship-flow, research, etc.)\n- Timeline showing each entry chronologically\n\nThis is the key command for understanding \"how much did this feature cost to build?\"\n\n### Step 3: Cost Optimization Suggestions\n\nBased on the report data, suggest optimizations:\n- **Model downgrade**: If Opus is used for template-driven tasks, suggest Sonnet\n- **Cache utilization**: If cache_read_tokens is consistently 0, suggest enabling prompt caching\n- **Category rebalancing**: If research spend exceeds ship-flow spend, suggest more focused sessions\n- **Budget adjustment**: If consistently under 50% budget, suggest reducing to free up capital\n\nRefer to the full optimization playbook in `standards/ops/token-cost-tracking.md`.\n\n### Step 4: Cross-Reference with Unit Economics\n\nWhen generating reports, if artifacts exist in `artifacts/finance/`, note how AI COGS relates to:\n- Gross margin (AI costs reduce margin)\n- CAC (AI-assisted customer acquisition costs)\n- Infrastructure costs in the investor template\n\n### Typical Session Cost Estimates\n\nReference ranges for planning (based on Claude Opus/Sonnet pricing):\n\n| Flow | Typical Input Tokens | Typical Output Tokens | Estimated Cost |\n|------|---------------------|-----------------------|---------------|\n| `/ship` (full) | 150-300K | 30-60K | $3-8 |\n| `/prototype` | 50-100K | 15-30K | $1-3 |\n| `/code-review` | 30-80K | 10-20K | $0.50-2 |\n| `/status` | 10-30K | 5-10K | $0.20-0.50 |\n| Single skill | 20-50K | 5-15K | $0.30-1 |\n| Agent sub-delegation | 15-40K per agent | 5-10K per agent | $0.25-1 per agent |\n\nThese are estimates only. Actual costs depend on codebase size, artifact count, and conversation length.\n\n## Cross-References\n\n- **pricing-unit-economics** — consumes AI cost data for infrastructure cost calculations\n- **ship** — advisory integration at Step 7.5 (suggest logging session cost after release)\n- **investor-reporting-template** — AI COGS feeds into burn rate reporting\n\n## Quality Checklist\n\n- [ ] company.config.yaml was read for budget and tracking config\n- [ ] Ledger entry has all required fields (timestamp, model, tokens, cost, category)\n- [ ] Cost calculation matches model rate table (if auto-calculated)\n- [ ] Budget status uses color coding (green/yellow/red)\n- [ ] Summary report regenerates `cogs/ai-ledger/summary.md`\n- [ ] Empty ledger is handled gracefully\n- [ ] Feature ID is tagged when applicable (especially during ship flows)\n- [ ] Cross-reference to unit economics noted when applicable\n"},"lastSynced":"2026-03-07T04:05:28.074Z","agentAnalysis":{"suitability":{"en":"Ideal for Ops & Risk Agents and Orchestrator Agents requiring precise AI token consumption tracking and cost management.","zh":"适合于需要精确跟踪和管理 AI 令牌消费和成本的 Ops & Risk Agents 和 Orchestrator Agents。","ja":"Ops & Risk Agents および Orchestrator Agents が AI トークン消費とコストを正確に追跡して管理する必要がある場合に適しています。","ko":"정확한 AI 토큰 소비 및 비용 추적 및 관리가 필요한 Ops & Risk Agents 및 Orchestrator Agents 에 적합합니다.","es":"Ideal para agentes de Operaciones y Riesgo y agentes de Orquestador que requieren un seguimiento preciso del consumo de tokens de IA y gestión de costos.","fr":"Idéal pour les agents d''Opérations et de Risque et les agents d''Orchestrateur nécessitant un suivi précis de la consommation de jetons d''IA et une gestion des coûts.","de":"Ideal für Ops- und Risikoagenten und Orchestrierungsagenten, die eine präzise Nachverfolgung des AI-Token-Verbrauchs und eine Kostenverwaltung erfordern.","pt":"Ideal para agentes de Ops e Risco e agentes de Orquestrador que exigem rastreamento preciso de consumo de token de IA e gerenciamento de custos.","ru":"Идеально подходит для агентов Ops и Risk, а также агентов Оркестратора, требующих точного отслеживания потребления токенов ИИ и управления затратами.","ar":"مثالي لعميل العمليات والمخاطر وعميل الاوركسترا الذين يتطلبون تتبع دقيق لاستهلاك رمز ال IA وإدارة التكاليف."},"recommendation":{"en":"Empowers agents to track AI token consumption and costs utilizing company.config.yaml for configuration, generating ledger entries in JSONL format and summaries in Markdown, enabling data-driven decisions with ai.cost_budget_monthly, ai.cost_tracking_enabled, and ai.cost_alert_threshold_percent parameters.","zh":"使得代理能够使用 company.config.yaml 进行配置，生成 JSONL 格式的分类账条目和 Markdown 格式的摘要，通过 ai.cost_budget_monthly、ai.cost_tracking_enabled 和 ai.cost_alert_threshold_percent 参数实现数据驱动的决策。","ja":"エージェントが company.config.yaml を使用して構成し、JSONL 形式の台帳エントリと Markdown 形式のサマリーを生成し、ai.cost_budget_monthly、ai.cost_tracking_enabled、ai.cost_alert_threshold_percent パラメータを使用してデータ駆動型の意思決定を可能にします。","ko":"에이전트가 company.config.yaml을 사용하여 구성하고 JSONL 형식의 원장 항목과 Markdown 형식의 요약을 생성하여 ai.cost_budget_monthly, ai.cost_tracking_enabled 및 ai.cost_alert_threshold_percent 매개 변수를 통해 데이터 주도적인 의사 결정을 가능하게 합니다.","es":"Habilita a los agentes para realizar un seguimiento del consumo de tokens de IA y costos utilizando company.config.yaml para la configuración, generando entradas de registro en formato JSONL y resúmenes en Markdown, lo que permite tomar decisiones basadas en datos con los parámetros ai.cost_budget_monthly, ai.cost_tracking_enabled y ai.cost_alert_threshold_percent.","fr":"Permet aux agents de suivre la consommation de jetons d''IA et les coûts en utilisant company.config.yaml pour la configuration, en générant des entrées de journal au format JSONL et des résumés au format Markdown, permettant ainsi des décisions basées sur les données avec les paramètres ai.cost_budget_monthly, ai.cost_tracking_enabled et ai.cost_alert_threshold_percent.","de":"Ermöglicht es den Agenten, den Verbrauch von AI-Tokens und Kosten unter Verwendung von company.config.yaml für die Konfiguration zu verfolgen, indem Registrierungseinträge im JSONL-Format und Zusammenfassungen im Markdown-Format generiert werden, wodurch datengetriebene Entscheidungen mit den Parametern ai.cost_budget_monthly, ai.cost_tracking_enabled und ai.cost_alert_threshold_percent ermöglicht werden.","pt":"Habilita os agentes a rastrear o consumo de token de IA e os custos, utilizando company.config.yaml para configuração, gerando entradas de ledger no formato JSONL e resumos em Markdown, permitindo decisões baseadas em dados com parâmetros ai.cost_budget_monthly, ai.cost_tracking_enabled e ai.cost_alert_threshold_percent.","ru":"Позволяет агентам отслеживать потребление токенов ИИ и затраты, используя company.config.yaml для конфигурации, генерируя записи в журнале в формате JSONL и сводки в Markdown, обеспечивающие принятие решений на основе данных с параметрами ai.cost_budget_monthly, ai.cost_tracking_enabled и ai.cost_alert_threshold_percent.","ar":"تمكين العملاء من تتبع استهلاك رمز ال IA والتكاليف، باستخدام company.config.yaml للتهيئة، وتوليد إدخالات دفتر الأستاذ بتنسيق JSONL والملخصات بتنسيق Markdown، وتمكين القرارات المستندة إلى البيانات مع 매개 ai.cost_budget_monthly و ai.cost_tracking_enabled و ai.cost_alert_threshold_percent."},"useCases":{"en":["Automating AI token cost tracking and reporting","Generating detailed ledger entries for cost analysis","Triggering alerts when AI costs exceed predefined thresholds"],"zh":["自动化 AI 令牌成本跟踪和报告","生成详细的分类账条目以进行成本分析","当 AI 成本超过预定义阈值时触发警报"],"ja":["AI トークンコストの追跡と報告を自動化する","コスト分析のための詳細な台帳エントリを生成する","AI コストが定義されたしきい値を超えたときにアラートをトリガーする"],"ko":["AI 토큰 비용 추적 및 보고 자동화","비용 분석을 위한 세부적인 원장 항목 생성","AI 비용이 정의된 임계값을 초과할 때 경고를 트리거합니다"],"es":["Automatizar el seguimiento y la generación de informes de costos de tokens de IA","Generar entradas de registro detalladas para el análisis de costos","Activar alertas cuando los costos de IA superan los umbrales predefinidos"],"fr":["Automatiser le suivi et la génération de rapports de coûts de jetons d''IA","Générer des entrées de journal détaillées pour l''analyse des coûts","Déclencher des alertes lorsque les coûts d''IA dépassent les seuils prédéfinis"],"de":["Automatisieren der Nachverfolgung und Berichterstellung der AI-Token-Kosten","Erstellen detaillierter Registrierungseinträge für die Kostenanalyse","Auslösen von Warnungen, wenn die AI-Kosten die vordefinierten Schwellenwerte überschreiten"],"pt":["Automatizar o rastreamento e relatórios de custos de token de IA","Gerar entradas de ledger detalhadas para análise de custos","Disparar alertas quando os custos de IA excedem limiares predefinidos"],"ru":["Автоматизировать отслеживание и отчетность о затратах на токены ИИ","Генерировать подробные записи в журнале для анализа затрат","Срабатывать при превышении затрат на ИИ предустановленных порогов"],"ar":["تأتمتة تتبع وتقرير تكاليف رمز ال IA","توليد إدخالات دفتر الأستاذ المفصلة لتحليل التكاليف","تشغيل التنبيهات عندما يتجاوز استهلاك رمز ال IA العوائق المحددة مسبقا"]},"limitations":{"en":["Requires access to company.config.yaml for configuration","Dependent on tool scripts like ./tools/ops/token-ledger.sh","Limited to tracking AI token consumption and costs"],"zh":["需要访问 company.config.yaml 进行配置","依赖于工具脚本，如 ./tools/ops/token-ledger.sh","仅限于跟踪 AI 令牌消费和成本"],"ja":["構成のために company.config.yaml へのアクセスが必要","ツールスクリプト (例: ./tools/ops/token-ledger.sh) への依存","AI トークン消費とコストの追跡のみ"],"ko":["구성하기 위해 company.config.yaml에 대한 액세스가 필요합니다","도구 스크립트(예: ./tools/ops/token-ledger.sh)에 대한 의존","AI 토큰 소비 및 비용 추적만"],"es":["Requiere acceso a company.config.yaml para la configuración","Depende de scripts de herramientas como ./tools/ops/token-ledger.sh","Limitado al seguimiento del consumo de tokens de IA y costos"],"fr":["Nécessite un accès à company.config.yaml pour la configuration","Dépend de scripts d''outils tels que ./tools/ops/token-ledger.sh","Limité au suivi de la consommation de jetons d''IA et des coûts"],"de":["Benötigt Zugriff auf company.config.yaml für die Konfiguration","Hängt von Toolskripten wie ./tools/ops/token-ledger.sh ab","Begrenzt auf die Nachverfolgung des AI-Token-Verbrauchs und der Kosten"],"pt":["Exige acesso ao company.config.yaml para configuração","Dependente de scripts de ferramentas como ./tools/ops/token-ledger.sh","Limitado ao rastreamento de consumo de token de IA e custos"],"ru":["Требует доступа к company.config.yaml для конфигурации","Зависит от скриптов инструментов, таких как ./tools/ops/token-ledger.sh","Ограничен отслеживанием потребления токенов ИИ и затрат"],"ar":["يتطلب الوصول إلى company.config.yaml للتهيئة","يعتمد على سكريبتات أدوات مثل ./tools/ops/token-ledger.sh","محدود لتتبع استهلاك رمز ال IA والتكاليف"]},"version":4},"contentHash":"c46e60347cddd824f7c30f55460831c1dea6ca57279fe081e01defb5e52203e2","qualityScore":60}');
